-- Build 032 reload safety: restore any previous transaction-firewall wrappers
-- before caching Cherax's real native/service/global dispatch functions.
do
    local previous = rawget(_G, "__HUSTLEMETER_TX_FIREWALL")
    if type(previous) == "table" and previous.installed == true then
        pcall(function()
            if Natives then
                if previous.invokeVoid then Natives.InvokeVoid = previous.invokeVoid end
                if previous.invokeBool then Natives.InvokeBool = previous.invokeBool end
            end
            if GTA then
                if previous.beginService then GTA.BeginService = previous.beginService end
                if previous.checkoutStart then GTA.CheckoutStart = previous.checkoutStart end
            end
            if ScriptGlobal and previous.scriptGlobalSetInt then
                ScriptGlobal.SetInt = previous.scriptGlobalSetInt
            end
            if type(previous.moneyFunctions) == "table" and type(_G.MONEY) == "table" then
                for name, fn in pairs(previous.moneyFunctions) do
                    if type(fn) == "function" then _G.MONEY[name] = fn end
                end
            end
            if type(previous.globalEarnFunctions) == "table" then
                for name, fn in pairs(previous.globalEarnFunctions) do
                    if type(fn) == "function" then _G[name] = fn end
                end
            end
        end)
        previous.installed = false
    end
end

