-- ═══════════════════════════════════════════════════════════════════════════════════
-- small utility kit
-- note: general helpers stay grouped so feature logic below reads cleaner.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.now()
    if Time and Time.GetEpocheMs then
        local value = Time.GetEpocheMs()
        if value then return tonumber(value) or math.floor(os.clock() * 1000) end
    end
    return math.floor(os.clock() * 1000)
end

function hustle_meter.clamp_float(v, minv, maxv)
    v = tonumber(v) or minv
    if v < minv then return minv end
    if v > maxv then return maxv end
    return v
end

function hustle_meter.clamp_int(v, minv, maxv)
    v = math.floor(tonumber(v) or minv)
    if v < minv then return minv end
    if v > maxv then return maxv end
    return v
end

function hustle_meter.hash(key)
    if Utils and Utils.Joaat then
        local result = Utils.Joaat(script_prefix .. tostring(key))
        if result then return result end
    end
    local hash = 0
    local text = script_prefix .. tostring(key)
    for i = 1, #text do
        hash = (hash * 31 + string.byte(text, i)) % 2147483647
    end
    return hash
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- file system helpers
-- note: directory and migration helpers avoid deleting old MoneyCheck backups.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.ensure_dir()
    if FileMgr and FileMgr.CreateDir then
        FileMgr.CreateDir(hustle_meter.RootDir)
        FileMgr.CreateDir(hustle_meter.AccountRootDir)
        FileMgr.CreateDir(hustle_meter.BackupRootDir)
        if hustle_meter.PublicUrinalIconDir then FileMgr.CreateDir(hustle_meter.PublicUrinalIconDir) end
        if hustle_meter.DebugDir then FileMgr.CreateDir(hustle_meter.DebugDir) end
    end
end

function hustle_meter.file_exists(path)
    local f = io.open(tostring(path or ""), "r")
    if f then f:close(); return true end
    return false
end

function hustle_meter.read_file(path)
    local f = io.open(tostring(path or ""), "r")
    if not f then return nil end
    local content = f:read("*a")
    f:close()
    return content
end

function hustle_meter.copy_file_if_missing(newPath, oldPath)
    if hustle_meter.file_exists(newPath) then return false end
    if not hustle_meter.file_exists(oldPath) then return false end
    local content = hustle_meter.read_file(oldPath)
    if not content or content == "" then return false end
    return hustle_meter.try_write_file(newPath, content)
end

function hustle_meter.migrate_legacy_storage()
    -- HustleMeter saves under Cherax\Lua\hustle_meter.
    -- Existing MoneyCheck data is copied forward safely without deleting old backups.
    hustle_meter.ensure_dir()
    hustle_meter.copy_file_if_missing(hustle_meter.ConfigFile, hustle_meter.LegacyMoneyCheckLuaConfigFile)
    hustle_meter.copy_file_if_missing(hustle_meter.SharedHistoryFile, hustle_meter.LegacyMoneyCheckLuaHistoryFile)
    hustle_meter.copy_file_if_missing(hustle_meter.ConfigFile, hustle_meter.LegacyConfigFile)
    hustle_meter.copy_file_if_missing(hustle_meter.SharedHistoryFile, hustle_meter.LegacyHistoryFile)
end

function hustle_meter.trim(text)
    text = tostring(text or "")
    text = text:gsub("^%s+", ""):gsub("%s+$", "")
    return text
end

function hustle_meter.copy_to_clipboard(text)
    text = tostring(text or "")
    if text == "" then return false end

    if Utils and Utils.SetClipBoardText then
        local ok = pcall(function() Utils.SetClipBoardText(text, "") end)
        if ok then return true end
    end
    if Utils and Utils.SetClipboardText then
        local ok = pcall(function() Utils.SetClipboardText(text) end)
        if ok then return true end
    end
    if ImGui and ImGui.SetClipboardText then
        local ok = pcall(function() ImGui.SetClipboardText(text) end)
        if ok then return true end
    end
    return false
end

function hustle_meter.copy_support_folder_path()
    local path = tostring(hustle_meter.RootDir or "")
    if hustle_meter.copy_to_clipboard(path) then
        hustle_meter.toast("HustleMeter support folder path copied.", 4000)
        return true
    end
    hustle_meter.toast("Support folder: " .. path, 6000)
    return false
end

-- Creates a standards-compliant ZIP using the STORE method (no external programs required).
-- Cherax exposes FileMgr.Unzip but no matching Zip API, so support packaging stays self-contained.
function hustle_meter.get_support_discord_link()
    local direct = tostring(hustle_meter.SupportDiscordLink or "")
    if direct ~= "" then return direct, true end
    return tostring(hustle_meter.DiscordLink or ""), false
end

function hustle_meter.open_url(url)
    url = tostring(url or "")
    if url == "" then return false end
    if Utils and Utils.OpenURL then return Utils.OpenURL(url) ~= false end
    if Utils and Utils.OpenUrl then return Utils.OpenUrl(url) ~= false end
    if GUI and GUI.OpenURL then return GUI.OpenURL(url) ~= false end
    return false
end

function hustle_meter.copy_support_zip_path()
    local copied = hustle_meter.copy_to_clipboard(hustle_meter.SupportZipPath)
    hustle_meter.toast(copied and "Support ZIP path copied." or "Could not copy support ZIP path.", 3500)
    return copied
end

function hustle_meter.copy_and_open_support_discord()
    local url, dedicated = hustle_meter.get_support_discord_link()
    if url == "" then
        hustle_meter.toast("No support Discord link is configured yet.", 4000)
        return false, false
    end

    local copied = hustle_meter.copy_to_clipboard(url)
    local opened = hustle_meter.open_url(url)
    local name = dedicated and tostring(hustle_meter.SupportDiscordName or "Support") or "community Discord"

    if opened and copied then
        hustle_meter.toast(name .. " opened and link copied.", 4000)
    elseif copied then
        hustle_meter.toast(name .. " link copied.", 3500)
    elseif opened then
        hustle_meter.toast(name .. " opened.", 3500)
    else
        hustle_meter.toast("Could not open or copy the support Discord link.", 4500)
    end
    return copied, opened
end

function hustle_meter.write_support_upload_instructions()
    local supportUrl, dedicated = hustle_meter.get_support_discord_link()
    local channelLine
    if dedicated then
        channelLine = tostring(hustle_meter.SupportDiscordName or "Support") .. ": " .. tostring(supportUrl)
    else
        channelLine = "Dedicated HustleMeter support channel: not configured yet.\nCommunity Discord fallback: " .. tostring(supportUrl)
    end

    local lines = {
        "HUSTLEMETER SUPPORT UPLOAD",
        "==========================",
        "",
        "1. In HustleMeter > Config > Files & Support, click Create Support ZIP.",
        "2. Wait for the ZIP status to show it was created.",
        "3. Click Open Support Discord.",
        "4. Upload HustleMeter_Support.zip and briefly describe what happened.",
        "",
        "Support ZIP: " .. tostring(hustle_meter.SupportZipPath or ""),
        channelLine,
        "",
        "Cherax.log included when present: " .. tostring(hustle_meter.file_exists(hustle_meter.CheraxLogPath)),
        "Cherax.log path: " .. tostring(hustle_meter.CheraxLogPath or ""),
        "",
        "PRIVACY NOTE",
        "Cherax.log can contain player names, Rockstar IDs, IP addresses, local file paths,",
        "and other session/debug information. Share the support ZIP only in a trusted",
        "support channel or directly with someone you trust to review diagnostics.",
        "",
        "Version: " .. tostring(hustle_meter.Version or "Unknown"),
        "Build: " .. tostring(hustle_meter.Build or "Unknown"),
        "Game edition: " .. tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        "Cherax edition: " .. tostring(hustle_meter.S.currentCheraxEdition or "Unknown")
    }
    return hustle_meter.try_write_file(
        hustle_meter.SupportUploadInfoFile,
        table.concat(lines, "\n") .. "\n"
    )
end

-- v1.0.5 uses the streaming CRC/STORE writer below. The old in-memory
-- pure-Lua DEFLATE implementation was removed for production because large
-- Cherax.log and forensic files could take several minutes to compress.

function hustle_meter.zip_dos_datetime(epoch)
    local t = os.date("*t", tonumber(epoch or os.time()) or os.time())
    local year = math.max(1980, math.min(2107, tonumber(t.year or 1980) or 1980))
    local month = math.max(1, math.min(12, tonumber(t.month or 1) or 1))
    local day = math.max(1, math.min(31, tonumber(t.day or 1) or 1))
    local hour = math.max(0, math.min(23, tonumber(t.hour or 0) or 0))
    local min = math.max(0, math.min(59, tonumber(t.min or 0) or 0))
    local sec = math.max(0, math.min(59, tonumber(t.sec or 0) or 0))
    local dosTime = ((hour & 0x1F) << 11) | ((min & 0x3F) << 5) | ((math.floor(sec / 2)) & 0x1F)
    local dosDate = (((year - 1980) & 0x7F) << 9) | ((month & 0x0F) << 5) | (day & 0x1F)
    return dosTime, dosDate
end

function hustle_meter.support_relative_path(path)
    local normalized = tostring(path or ""):gsub("/", "\\"):lower()
    local cheraxLog = tostring(hustle_meter.CheraxLogPath or ""):gsub("/", "\\"):lower()
    if cheraxLog ~= "" and normalized == cheraxLog then
        return "Cherax/Cherax.log"
    end

    local root = tostring(hustle_meter.RootDir or ""):gsub("\\", "/"):gsub("/+$", "")
    local full = tostring(path or ""):gsub("\\", "/")
    local rootLower = root:lower()
    local fullLower = full:lower()
    local rel = full
    if fullLower:sub(1, #rootLower) == rootLower then
        rel = full:sub(#root + 1):gsub("^/+", "")
    end
    if rel == "" then rel = "unknown" end
    return "HustleMeter/" .. rel
end

function hustle_meter.collect_support_files()
    local found, seen = {}, {}
    local function add(path)
        path = tostring(path or "")
        if path == "" then return end
        local key = path:gsub("/", "\\"):lower()
        if seen[key] then return end
        if key == tostring(hustle_meter.SupportZipPath or ""):gsub("/", "\\"):lower() then return end
        if key == tostring(hustle_meter.SupportZipTempPath or ""):gsub("/", "\\"):lower() then return end
        local f = io.open(path, "rb")
        if not f then return end
        f:close()
        seen[key] = true
        found[#found + 1] = path
    end
    local files = {
        hustle_meter.ConfigFile, hustle_meter.AccountsFile, hustle_meter.DiagnosticsFile,
        hustle_meter.SupportInfoFile, hustle_meter.SharedHistoryFile, hustle_meter.HistoryFile,
        hustle_meter.ScannerTraceFile, hustle_meter.ScannerTraceFile .. ".1",
        hustle_meter.TransitionEventsFile, hustle_meter.TransitionEventsFile .. ".1",
        hustle_meter.LastTransitionFile, hustle_meter.SuspiciousFile,
        hustle_meter.SupportUploadInfoFile, hustle_meter.CheraxLogPath
    }
    for _, path in ipairs(files) do add(path) end
    table.sort(found, function(a,b) return tostring(a):lower() < tostring(b):lower() end)
    return found
end

function hustle_meter.copy_file_streaming(sourcePath, destinationPath)
    local input = io.open(tostring(sourcePath or ""), "rb")
    if not input then return false, "source unavailable" end

    local output, openErr = io.open(tostring(destinationPath or ""), "wb")
    if not output then
        input:close()
        return false, tostring(openErr or "destination unavailable")
    end

    local ok, err = pcall(function()
        while true do
            local chunk = input:read(262144)
            if not chunk or #chunk == 0 then break end
            output:write(chunk)
            if Script and Script.Yield then Script.Yield(0) end
        end
    end)

    input:close()
    output:close()
    if not ok then
        pcall(os.remove, destinationPath)
        return false, tostring(err)
    end
    return true
end

function hustle_meter.preserve_previous_build028_forensics()
    if hustle_meter.file_exists(hustle_meter.Build028RecoveryMarkerFile) then return false end

    local candidates = {
        hustle_meter.ForensicTraceFile,
        hustle_meter.ForensicTraceFile .. ".1",
        hustle_meter.ForensicTraceFile .. ".2",
        hustle_meter.ForensicTraceFile .. ".3",
        hustle_meter.ForensicEventsFile,
        hustle_meter.ForensicEventsFile .. ".1",
        hustle_meter.ForensicEventsFile .. ".2",
        hustle_meter.ForensicEventsFile .. ".3",
        hustle_meter.ForensicSummaryFile,
        hustle_meter.ForensicReadmeFile,
        hustle_meter.ScannerTraceFile,
        hustle_meter.ScannerTraceFile .. ".1",
        hustle_meter.ScannerTraceFile .. ".2",
        hustle_meter.ScannerTraceFile .. ".3",
        hustle_meter.TransitionEventsFile,
        hustle_meter.TransitionEventsFile .. ".1",
        hustle_meter.TransitionEventsFile .. ".2",
        hustle_meter.TransitionEventsFile .. ".3",
        hustle_meter.LastTransitionFile,
        hustle_meter.SuspiciousFile,
        hustle_meter.DiagnosticsFile,
        hustle_meter.SupportInfoFile,
        hustle_meter.HistoryFile
    }

    local existing = {}
    for _, path in ipairs(candidates) do
        if hustle_meter.file_exists(path) then existing[#existing + 1] = path end
    end
    if #existing == 0 then return false end

    pcall(function() FileMgr.CreateDir(hustle_meter.RecoveryDir) end)
    local stamp = os.date("%Y%m%d_%H%M%S") or tostring(os.time())
    local backupDir = hustle_meter.RecoveryDir .. "\\pre_build029_" .. stamp
    pcall(function() FileMgr.CreateDir(backupDir) end)

    local copied = 0
    for _, source in ipairs(existing) do
        local filename = tostring(source):gsub("/", "\\"):match("([^\\]+)$") or ("file_" .. tostring(copied + 1))
        local destination = backupDir .. "\\" .. filename
        local ok = hustle_meter.copy_file_streaming(source, destination)
        if ok then copied = copied + 1 end
    end

    if copied > 0 then
        hustle_meter.S.previousForensicBackupDir = backupDir
        hustle_meter.try_write_file(
            hustle_meter.Build028RecoveryMarkerFile,
            "return " .. hustle_meter.serialize({
                build = hustle_meter.Build,
                preservedAt = os.time(),
                backupDir = backupDir,
                copiedFiles = copied
            }, "") .. "\n"
        )
        hustle_meter.toast("Previous Build 028 forensic evidence preserved.", 5000)
        return true
    end
    return false
end

function hustle_meter.ensure_zip_crc_table()
    if type(hustle_meter._ZipCrcTable) == "table" then return hustle_meter._ZipCrcTable end
    local tbl = {}
    for i = 0, 255 do
        local c = i
        for _ = 1, 8 do
            if (c & 1) ~= 0 then
                c = (0xEDB88320 ~ (c >> 1)) & 0xFFFFFFFF
            else
                c = (c >> 1) & 0xFFFFFFFF
            end
        end
        tbl[i] = c
    end
    hustle_meter._ZipCrcTable = tbl
    return tbl
end

function hustle_meter.zip_crc32_update(crc, data)
    local tbl = hustle_meter.ensure_zip_crc_table()
    crc = tonumber(crc or 0xFFFFFFFF) or 0xFFFFFFFF
    for i = 1, #data do
        crc = (tbl[(crc ~ data:byte(i)) & 0xFF] ~ (crc >> 8)) & 0xFFFFFFFF
    end
    return crc
end

function hustle_meter.scan_support_file(path)
    local f, openErr = io.open(tostring(path or ""), "rb")
    if not f then return nil, nil, tostring(openErr or "open failed") end

    local crc = 0xFFFFFFFF
    local size = 0
    local ok, err = pcall(function()
        while true do
            local chunk = f:read(262144)
            if not chunk or #chunk == 0 then break end
            size = size + #chunk
            if size > 0xFFFFFFFF then error("file exceeds ZIP32 limit") end
            crc = hustle_meter.zip_crc32_update(crc, chunk)
            if Script and Script.Yield then Script.Yield(0) end
        end
    end)
    f:close()

    if not ok then return nil, nil, tostring(err) end
    return ((~crc) & 0xFFFFFFFF), size, nil
end

function hustle_meter.stream_file_into_zip(out, path, exactBytes)
    local f, openErr = io.open(tostring(path or ""), "rb")
    if not f then return false, tostring(openErr or "open failed") end

    local remaining = tonumber(exactBytes)
    if remaining ~= nil then remaining = math.max(0, math.floor(remaining)) end

    local ok, err = pcall(function()
        if remaining ~= nil then
            while remaining > 0 do
                local want = math.min(262144, remaining)
                local chunk = f:read(want)
                if not chunk or #chunk == 0 then
                    error("source changed/truncated while ZIP snapshot was being streamed")
                end
                out:write(chunk)
                remaining = remaining - #chunk
                if Script and Script.Yield then Script.Yield(0) end
            end
        else
            while true do
                local chunk = f:read(262144)
                if not chunk or #chunk == 0 then break end
                out:write(chunk)
                if Script and Script.Yield then Script.Yield(0) end
            end
        end
    end)

    f:close()
    return ok, ok and nil or tostring(err)
end

function hustle_meter.validate_support_zip_file(path)
    local f = io.open(tostring(path or ""), "rb")
    if not f then return false, "archive unavailable" end
    local size = f:seek("end") or 0
    if size < 22 then
        f:close()
        return false, "archive is too small"
    end

    f:seek("set", 0)
    local first = f:read(4)
    f:seek("set", math.max(0, size - 22))
    local ending = f:read(4)
    f:close()

    if first ~= "PK\003\004" then return false, "missing local ZIP header" end
    if ending ~= "PK\005\006" then return false, "missing ZIP end record" end
    return true
end

function hustle_meter.create_support_zip()
    if hustle_meter.S.supportZipBusy == true then
        hustle_meter.toast("Support ZIP is already being created.", 3000)
        return false
    end

    hustle_meter.S.supportZipQueued = false
    hustle_meter.S.supportZipBusy = true
    hustle_meter.S.supportZipProgress = 0
    hustle_meter.S.supportZipCurrentFile = ""
    hustle_meter.S.supportZipStatus = "Preparing diagnostics..."

    local function finish(success, message)
        hustle_meter.S.supportZipBusy = false
        hustle_meter.S.supportZipQueued = false
        hustle_meter.S.supportZipCurrentFile = ""
        hustle_meter.S.supportZipStatus = tostring(message or (success and "Support ZIP created." or "Support ZIP failed."))
        if message and message ~= "" then hustle_meter.toast(message, success and 8000 or 9000) end
        return success
    end

    local ok, err = pcall(function()
        hustle_meter.PendingForensicEnd = false
        if hustle_meter.Forensic and hustle_meter.Forensic.testActive == true then
            hustle_meter.forensic_mark_test_end("support-zip-auto")
        end

        hustle_meter.forensic_write_summary("support-zip-created")
        hustle_meter.forensic_write_readme()
        hustle_meter.save_diagnostics("support-zip-created")
        hustle_meter.write_support_info("support-zip-created")
        hustle_meter.write_support_upload_instructions()

        local files = hustle_meter.collect_support_files()
        if #files == 0 then error("No HustleMeter support files were found.") end
        if #files > 65535 then error("Too many support files for ZIP32.") end

        hustle_meter.S.supportZipTotalFiles = #files
        hustle_meter.debug_event("SUPPORT_ZIP_STARTED",
            "files=" .. tostring(#files) .. " mode=STORE-streaming path=" .. tostring(hustle_meter.SupportZipPath))

        pcall(os.remove, hustle_meter.SupportZipTempPath)
        local out = assert(io.open(hustle_meter.SupportZipTempPath, "wb"))
        local entries = {}
        local offset = 0
        local totalInputBytes = 0
        local dosTime, dosDate = hustle_meter.zip_dos_datetime(os.time())

        for index, path in ipairs(files) do
            local name = hustle_meter.support_relative_path(path):gsub("\\", "/")
            hustle_meter.S.supportZipProgress = index
            hustle_meter.S.supportZipCurrentFile = name
            hustle_meter.S.supportZipStatus =
                ("Scanning %d/%d: %s"):format(index, #files, name)

            local crc, size, scanErr = hustle_meter.scan_support_file(path)
            if crc ~= nil and size ~= nil then
                totalInputBytes = totalInputBytes + size
                hustle_meter.S.supportZipStatus =
                    ("Adding %d/%d: %s"):format(index, #files, name)

                -- STORE method: no pure-Lua compression. This is intentionally larger
                -- but dramatically faster and reliable for Cherax.log/forensic traces.
                local localHeader = string.pack("<I4I2I2I2I2I2I4I4I4I2I2",
                    0x04034B50, 20, 0x0800, 0, dosTime, dosDate,
                    crc, size, size, #name, 0)
                out:write(localHeader, name)

                -- IMPORTANT: stream exactly the byte count used for the CRC/header.
                -- Diagnostic logs can keep growing while the ZIP is being built; reading
                -- to a later EOF corrupts all following ZIP offsets.
                local wrote, writeErr = hustle_meter.stream_file_into_zip(out, path, size)
                if not wrote then
                    out:close()
                    error("Could not add " .. name .. ": " .. tostring(writeErr))
                end

                entries[#entries + 1] = {
                    name = name,
                    crc = crc,
                    size = size,
                    compressedSize = size,
                    method = 0,
                    offset = offset
                }
                offset = offset + #localHeader + #name + size
            else
                hustle_meter.debug_event("SUPPORT_FILE_SKIPPED",
                    "path=" .. tostring(path) .. " reason=" .. tostring(scanErr or "unreadable"))
            end

            if Script and Script.Yield then Script.Yield(0) end
        end

        if #entries == 0 then
            out:close()
            pcall(os.remove, hustle_meter.SupportZipTempPath)
            error("No readable files were available for the support ZIP.")
        end

        hustle_meter.S.supportZipStatus = "Finalizing ZIP directory..."
        local centralOffset = offset
        local centralSize = 0
        for _, entry in ipairs(entries) do
            local name = entry.name
            local centralHeader = string.pack("<I4I2I2I2I2I2I2I4I4I4I2I2I2I2I2I4I4",
                0x02014B50, 20, 20, 0x0800, 0, dosTime, dosDate,
                entry.crc, entry.size, entry.size,
                #name, 0, 0, 0, 0, 0, entry.offset)
            out:write(centralHeader, name)
            centralSize = centralSize + #centralHeader + #name
        end

        local count = #entries
        out:write(string.pack("<I4I2I2I2I2I4I4I2",
            0x06054B50, 0, 0, count, count, centralSize, centralOffset, 0))
        out:close()

        local valid, validationErr = hustle_meter.validate_support_zip_file(hustle_meter.SupportZipTempPath)
        if not valid then
            pcall(os.remove, hustle_meter.SupportZipTempPath)
            error("ZIP validation failed: " .. tostring(validationErr))
        end

        -- Preserve the previous known-good ZIP until the new archive is validated.
        local previousPath = hustle_meter.SupportZipPath .. ".previous"
        pcall(os.remove, previousPath)
        if hustle_meter.file_exists(hustle_meter.SupportZipPath) then
            local movedOld = os.rename(hustle_meter.SupportZipPath, previousPath)
            if not movedOld then
                pcall(os.remove, hustle_meter.SupportZipPath)
            end
        end

        local renamed, renameErr = os.rename(hustle_meter.SupportZipTempPath, hustle_meter.SupportZipPath)
        if not renamed then
            if hustle_meter.file_exists(previousPath) then
                pcall(os.rename, previousPath, hustle_meter.SupportZipPath)
            end
            error("Could not finalize support ZIP: " .. tostring(renameErr or "rename failed"))
        end
        pcall(os.remove, previousPath)

        hustle_meter.S.lastSupportZipPath = hustle_meter.SupportZipPath
        hustle_meter.S.lastSupportZipFileCount = count
        hustle_meter.S.lastSupportZipBytes = hustle_meter.debug_file_size(hustle_meter.SupportZipPath)
        hustle_meter.S.lastSupportZipAt = os.time()
        hustle_meter.S.supportZipProgress = count

        local copied = hustle_meter.copy_to_clipboard(hustle_meter.SupportZipPath)
        hustle_meter.debug_event("SUPPORT_ZIP_CREATED",
            "files=" .. tostring(count) ..
            " archiveBytes=" .. tostring(hustle_meter.S.lastSupportZipBytes or 0) ..
            " sourceBytes=" .. tostring(totalInputBytes) ..
            " mode=STORE-streaming path=" .. tostring(hustle_meter.SupportZipPath))

        if copied then
            finish(true, "Support ZIP created! File path copied to clipboard.")
        else
            finish(true, "Support ZIP created! ZIP saved at: " .. tostring(hustle_meter.SupportZipPath))
        end
    end)

    if not ok then
        pcall(os.remove, hustle_meter.SupportZipTempPath)
        hustle_meter.debug_event("SUPPORT_ZIP_FAILED", tostring(err or "Unknown error"))
        finish(false, "Could not create support ZIP. " .. tostring(err or "Unknown error"))
        return false
    end
    return true
end

function hustle_meter.queue_support_zip()
    if hustle_meter.S.supportZipBusy == true or hustle_meter.S.supportZipQueued == true then
        hustle_meter.toast("Support ZIP is already queued or being created.", 3500)
        return
    end

    hustle_meter.S.supportZipQueued = true
    hustle_meter.S.supportZipStatus = "Queued: preparing fast support ZIP..."
    hustle_meter.toast("Creating fast support ZIP... Please wait.", 8000)

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            hustle_meter.create_support_zip()
        end)
    else
        hustle_meter.create_support_zip()
    end
end

function hustle_meter.is_valid_account_name(name)
    name = hustle_meter.trim(name)
    if name == "" then return false end
    local compact = name:gsub("[^%w]", ""):lower()
    if compact == "unknown" or compact == "detecting" or compact == "pending" or compact == "invalid" or compact == "null" then return false end
    if compact == "player" then return false end
    return true
end

function hustle_meter.sanitize_account_key(name)
    name = hustle_meter.trim(name)
    if name == "" then name = "unknown" end
    local key = name:gsub("[^%w_%-%.]", "_")
    key = key:gsub("_+", "_")
    key = key:gsub("^_+", ""):gsub("_+$", "")
    if key == "" then key = "unknown" end
    if #key > 48 then key = key:sub(1, 48) end
    return key
end

function hustle_meter.read_runtime_edition()
    local raw = "Unknown"
    if Cherax and Cherax.GetEdition then
        local ok, value = pcall(Cherax.GetEdition)
        if ok and value ~= nil and tostring(value) ~= "" then raw = tostring(value) end
    end
    local normalized = raw:upper():gsub("^%s+", ""):gsub("%s+$", "")
    normalized = normalized:gsub("BATTLEYE", "BE"):gsub("%s+", " ")
    if normalized == "LE" or normalized == "LE BE" then return "LE", raw end
    if normalized == "EE" or normalized == "EE BE" then return "EE", raw end
    return "Unknown", raw
end

function hustle_meter.refresh_runtime_metadata()
    local gameEdition, cheraxEdition = hustle_meter.read_runtime_edition()
    hustle_meter.S.currentGameEdition = gameEdition
    hustle_meter.S.currentCheraxEdition = cheraxEdition

    local version = "Unknown"
    if Cherax and Cherax.GetVersion then
        local ok, value = pcall(Cherax.GetVersion)
        if ok and value ~= nil then version = tostring(value) end
    end
    hustle_meter.S.currentCheraxVersion = version

    local build = 0
    if Cherax and Cherax.GetBuild then
        local ok, value = pcall(Cherax.GetBuild)
        if ok and tonumber(value) then build = tonumber(value) end
    end
    hustle_meter.S.currentCheraxBuild = build
    return gameEdition, cheraxEdition
end

function hustle_meter.build_account_key(accountName, gameEdition)
    local nameKey = hustle_meter.sanitize_account_key(accountName or "unknown")
    local editionKey = hustle_meter.sanitize_account_key(gameEdition or "Unknown")
    return hustle_meter.sanitize_account_key(nameKey .. "__" .. editionKey)
end

function hustle_meter.account_display_name(accountName, gameEdition)
    local name = tostring(accountName or "Unknown")
    local edition = tostring(gameEdition or "Unknown")
    return name .. " [" .. edition .. "]"
end

