    local source = hustle_meter.get_account_history_file(accountKey)
    if not hustle_meter.file_exists(source) then return nil, true end

    hustle_meter.ensure_account_backup_dir(accountKey)
    local backup = hustle_meter.get_zero_sample_import_repair_backup_file(accountKey)
    if hustle_meter.file_exists(backup) then return backup, true end

    local content = hustle_meter.read_file(source)
    if not content or content == "" then return nil, true end
    if hustle_meter.try_write_file(backup, content) then return backup, true end
    return nil, false
end

