        scriptVersion = hustle_meter.Version,
        scriptBuild = hustle_meter.Build,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
        accountKey = accountKey,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        backupFile = tostring(backupPath or "None - no edition-specific history existed"),
        baselineTotal = math.floor(tonumber(total or 0) or 0),
        baselineBank = math.floor(tonumber(bank or 0) or 0),
        baselineWallet = math.floor(tonumber(wallet or 0) or 0),
        baselineWallet0 = math.floor(tonumber(wallet0 or 0) or 0),
