function hustle_meter.perform_one_time_history_reset(total, bank, wallet, wallet0, wallet1)
    local accountKey = hustle_meter.sanitize_account_key(hustle_meter.S.currentAccountKey or "unknown")
    if accountKey == "unknown" or accountKey == "pending" or not hustle_meter.is_valid_account_name(hustle_meter.S.currentAccountName) then
        return false, "waiting-account"
    end
    if tostring(hustle_meter.S.currentGameEdition or "Unknown") == "Unknown" then
        return false, "waiting-edition"
    end

    hustle_meter.load_history()
    if hustle_meter.history_reset_marker_complete(accountKey) then
        if tostring(hustle_meter.Tracker.historyResetMigrationId or "") ~= tostring(hustle_meter.HistoryResetMigrationId) then
            hustle_meter.Tracker.historyResetMigrationId = hustle_meter.HistoryResetMigrationId
        end
        hustle_meter.S.historyResetMigrationId = hustle_meter.HistoryResetMigrationId
        hustle_meter.S.historyResetCompletedAt = tonumber(hustle_meter.Tracker.historyResetAt or hustle_meter.S.historyResetCompletedAt or 0) or 0
        hustle_meter.S.historyResetStatus = "Legacy history migration already complete for this account/edition."
        return false, "already-complete"
    end

    local backupPath, archiveOk = hustle_meter.archive_pre_reset_history(accountKey)
    if not archiveOk then
        hustle_meter.S.historyResetStatus = "Reset paused because the previous ledger could not be archived."
        hustle_meter.warn("One-time history reset aborted: failed to archive " .. tostring(hustle_meter.HistoryFile))
        return false, "archive-failed"
    end

    local nowSec = os.time()
    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet = math.floor(tonumber(wallet or 0) or 0)
    wallet0 = math.floor(tonumber(wallet0 or 0) or 0)
    wallet1 = math.floor(tonumber(wallet1 or 0) or 0)

    hustle_meter.Tracker.samples = {{
        t = nowSec,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
        accountKey = accountKey,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        total = total, bank = bank, wallet = wallet, wallet0 = wallet0, wallet1 = wallet1,
        balanceMode = hustle_meter.BalanceMode,
        migrationBaseline = true
    }}
    hustle_meter.Tracker.gains = {}
    hustle_meter.Tracker.lastTotal = total
    hustle_meter.Tracker.lastBank = bank
    hustle_meter.Tracker.lastWallet = wallet
    hustle_meter.Tracker.lastWallet0 = wallet0
    hustle_meter.Tracker.lastWallet1 = wallet1
    hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode
    hustle_meter.Tracker.historyResetMigrationId = hustle_meter.HistoryResetMigrationId
    hustle_meter.Tracker.historyResetAt = nowSec
    hustle_meter.Tracker.historyResetBackup = backupPath

    hustle_meter.S.lastBalance = total
    hustle_meter.S.lastBank = bank
    hustle_meter.S.lastWallet = wallet
    hustle_meter.S.past24h = 0
    hustle_meter.S.past168h = 0
    hustle_meter.S.gainCount = 0
    hustle_meter.S.sampleCount = 1
    hustle_meter.S.lastGainAmount = 0
    hustle_meter.S.lastGainTime = "None"
    hustle_meter.S.historyResetMigrationId = hustle_meter.HistoryResetMigrationId
    hustle_meter.S.historyResetCompletedAt = nowSec
    hustle_meter.S.historyResetStatus = "Previous rolling history archived; tracking restarted from the current balance."

    local scanner = hustle_meter.get_transaction_scanner and hustle_meter.get_transaction_scanner() or nil
    if type(scanner) == "table" then
        scanner.confirmedTotal = total
        scanner.confirmedBank = bank
        scanner.confirmedWallet = wallet
        scanner.confirmedWallet0 = wallet0
        scanner.confirmedWallet1 = wallet1
        scanner.initialized = true
        scanner.candidate = nil
        scanner.resumeCandidate = nil
    end

    if not hustle_meter.save_history() then
        -- Roll the in-memory tracker back to the still-existing pre-reset ledger so a
        -- failed disk write cannot mark the migration complete for this runtime.
        hustle_meter.Tracker.historyResetMigrationId = nil
        hustle_meter.Tracker.historyResetAt = nil
        hustle_meter.Tracker.historyResetBackup = nil
        hustle_meter.Tracker.loaded = false
        hustle_meter.Tracker.loadedFile = nil
        hustle_meter.load_history()
        hustle_meter.recalculate_windows()
        hustle_meter.S.historyResetMigrationId = ""
        hustle_meter.S.historyResetCompletedAt = 0
        hustle_meter.S.historyResetStatus = "Reset could not be saved; previous ledger backup was preserved and the reset will retry."
        hustle_meter.warn("One-time history reset failed while saving the clean ledger. Backup was preserved; migration will retry.")
        return false, "save-failed"
    end

    if not hustle_meter.write_history_reset_marker(accountKey, backupPath, total, bank, wallet, wallet0, wallet1) then
        -- The clean ledger itself also stores the migration ID, so a missing standalone
        -- marker cannot cause another reset on the next launch.
        hustle_meter.warn("History reset completed, but the standalone migration marker could not be written.")
    end

    hustle_meter.save_config(true)
    hustle_meter.debug_event("HISTORY_RESET_COMPLETE", "Legacy rolling-history migration completed.",
        ("baselineTotal=%s bank=%s wallet=%s w0=%s w1=%s backup=%s")
            :format(tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1), tostring(backupPath)))
    hustle_meter.toast("HustleMeter history migration complete. Previous rolling totals were archived due to a tracking issue; tracking now starts fresh from your current GTA$ balance.", 8000)
    return true, "reset-complete"
end

function hustle_meter.resolve_rockstar_username()
    -- Primary path: GTA native PLAYER_ID() + GET_PLAYER_NAME(Player).
    -- Fallbacks stay guarded with pcall so older/changed Cherax API tables cannot break loading.
    local name = nil

    local okNative, localPlayer = pcall(PLAYER_ID)
    if okNative and localPlayer ~= nil then
        local okName, nativeName = pcall(GET_PLAYER_NAME, localPlayer)
        if okName and hustle_meter.is_valid_account_name(nativeName) then
            name = hustle_meter.trim(nativeName)
        end
    end

    if not hustle_meter.is_valid_account_name(name) then
        local okName, nativeName = pcall(GET_PLAYER_NAME, -1)
        if okName and hustle_meter.is_valid_account_name(nativeName) then
            name = hustle_meter.trim(nativeName)
        end
    end

    if not hustle_meter.is_valid_account_name(name) then
        local candidates = {
            function()
                if PlayerMgr and PlayerMgr.GetLocalPlayer and PlayerMgr.GetPlayerName then
                    return PlayerMgr.GetPlayerName(PlayerMgr.GetLocalPlayer())
                end
            end,
            function()
                if Players and Players.GetLocalPlayer and Players.GetName then
                    return Players.GetName(Players.GetLocalPlayer())
                end
            end,
            function()
                if Players and Players.GetLocalName then return Players.GetLocalName() end
            end,
            function()
                if Player and Player.GetName then return Player.GetName() end
            end
        }
        for _, fn in ipairs(candidates) do
            local ok, result = pcall(fn)
            if ok and hustle_meter.is_valid_account_name(result) then
                name = hustle_meter.trim(result)
                break
            end
        end
    end

    if hustle_meter.is_valid_account_name(name) then return name end
    return nil
end

