function hustle_meter.legacy_dual_wallet_quarantine_matches(item, accountKey, trackedTotal)
    if type(item) ~= "table" then return false end
    accountKey = tostring(accountKey or "")
    if accountKey ~= "" and tostring(item.accountKey or "") ~= accountKey then return false end

    local reason = tostring(item.reason or "")
    local oldMismatchReason = string.find(reason, "active-total-does-not-match-bank-plus-wallet", 1, true) ~= nil
        or string.find(reason, "normal-money-source-mismatch", 1, true) ~= nil
    if not oldMismatchReason then return false end

    local total = math.floor(tonumber(item.total or 0) or 0)
    local bank = math.floor(tonumber(item.bank or 0) or 0)
    local wallet0 = math.floor(tonumber(item.wallet0 or 0) or 0)
    local wallet1 = math.floor(tonumber(item.wallet1 or 0) or 0)
    local preTotal = math.floor(tonumber(item.preTotal or 0) or 0)
    trackedTotal = math.floor(tonumber(trackedTotal or 0) or 0)

    if total <= 0 or trackedTotal <= 0 or preTotal ~= trackedTotal then return false end

    local oldMatch0 = total == (bank + wallet0)
    local oldMatch1 = total == (bank + wallet1)
    local combinedMatch = total == (bank + wallet0 + wallet1)

    -- This is the exact legacy bug signature: the old validator rejected both
    -- single-wallet equations even though both wallets together were exact.
    return combinedMatch and not oldMatch0 and not oldMatch1
end

function hustle_meter.find_legacy_dual_wallet_quarantine_evidence(accountKey, trackedTotal)
    accountKey = tostring(accountKey or hustle_meter.S.currentAccountKey or "")
    trackedTotal = math.floor(tonumber(trackedTotal or 0) or 0)

    local suspicious = hustle_meter.load_table(hustle_meter.SuspiciousFile)
    if type(suspicious) == "table" and type(suspicious.events) == "table" then
        for i = #suspicious.events, 1, -1 do
            local item = suspicious.events[i]
            if hustle_meter.legacy_dual_wallet_quarantine_matches(item, accountKey, trackedTotal) then
                return item, "suspicious-transactions"
            end
        end
    end

    -- Fallback for users whose suspicious history was pruned but whose latest
    -- structured transition snapshot still contains the rejected dual-wallet read.
    local lastTransition = hustle_meter.load_table(hustle_meter.LastTransitionFile)
    if type(lastTransition) == "table"
        and tostring(lastTransition.accountKey or "") == accountKey
        and tostring(lastTransition.stage or "") == "quarantined"
        and type(lastTransition.resumeCandidate) == "table" then

        local candidate = lastTransition.resumeCandidate
        local item = {
            accountKey = accountKey,
            reason = type(lastTransition.extra) == "table" and tostring(lastTransition.extra.reason or "") or "",
            preTotal = tonumber(lastTransition.preTransitionTotal or 0) or 0,
            total = tonumber(candidate.total or 0) or 0,
            bank = tonumber(candidate.bank or 0) or 0,
            wallet0 = tonumber(candidate.wallet0 or 0) or 0,
            wallet1 = tonumber(candidate.wallet1 or 0) or 0
        }
        if hustle_meter.legacy_dual_wallet_quarantine_matches(item, accountKey, trackedTotal) then
            return item, "last-transition"
        end
    end

    return nil, nil
end

function hustle_meter.perform_legacy_dual_wallet_recovery(total, bank, wallet, wallet0, wallet1)
    local accountKey = hustle_meter.sanitize_account_key(hustle_meter.S.currentAccountKey or "unknown")
    if accountKey == "unknown" or accountKey == "pending" then return false, "waiting-account" end

    local scanner = hustle_meter.get_transaction_scanner()
    if scanner.dualWalletRecoveryEvaluated == true then return false, "already-evaluated-runtime" end

    local consistency = hustle_meter.money_consistency(total, bank, wallet0, wallet1)
    if tostring(consistency.matchMode or "") ~= "bank+wallet0+wallet1" then
        -- Do not permanently mark runtime evaluation until both wallets genuinely
        -- contribute. The legacy bug only exists in this representation.
        return false, "not-combined-wallet-state"
    end

    if hustle_meter.dual_wallet_recovery_marker_complete(accountKey) then
        scanner.dualWalletRecoveryEvaluated = true
        hustle_meter.S.dualWalletRecoveryId = hustle_meter.DualWalletRecoveryId
        hustle_meter.S.dualWalletRecoveryCompletedAt = tonumber(hustle_meter.Tracker.dualWalletRecoveryAt or 0) or 0
        hustle_meter.S.dualWalletRecoveryStatus = "Legacy dual-wallet recovery already complete for this account/edition."
        return false, "already-complete"
    end

    hustle_meter.load_history()
    local trackedTotal = math.floor(tonumber(hustle_meter.Tracker.lastTotal or scanner.confirmedTotal or 0) or 0)
    local evidence, evidenceSource = hustle_meter.find_legacy_dual_wallet_quarantine_evidence(accountKey, trackedTotal)
    scanner.dualWalletRecoveryEvaluated = true

    if not evidence then
        hustle_meter.S.dualWalletRecoveryStatus = "No matching legacy dual-wallet quarantine evidence found; normal tracking preserved."
        return false, "no-proof"
    end

    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet = math.floor(tonumber(wallet or 0) or 0)
    wallet0 = math.floor(tonumber(wallet0 or 0) or 0)
    wallet1 = math.floor(tonumber(wallet1 or 0) or 0)

    local backupPath, archiveOk = hustle_meter.archive_pre_dual_wallet_recovery_history(accountKey)
    if not archiveOk then
        scanner.dualWalletRecoveryEvaluated = false
        hustle_meter.S.dualWalletRecoveryStatus = "Recovery paused because the previous ledger could not be archived."
        hustle_meter.warn("Dual-wallet recovery aborted: failed to archive " .. tostring(hustle_meter.HistoryFile))
        return false, "archive-failed"
    end

    local nowSec = os.time()

    -- Preserve every existing gain event. Only repair the stale comparison baseline.
    hustle_meter.Tracker.samples = hustle_meter.Tracker.samples or {}
    hustle_meter.Tracker.samples[#hustle_meter.Tracker.samples + 1] = {
        t = nowSec,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
        accountKey = accountKey,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        total = total,
        bank = bank,
        wallet = wallet,
        wallet0 = wallet0,
        wallet1 = wallet1,
        balanceMode = hustle_meter.BalanceMode,
        dualWalletRecoveryBaseline = true,
        previousTrackedTotal = trackedTotal
    }

    hustle_meter.Tracker.lastTotal = total
    hustle_meter.Tracker.lastBank = bank
    hustle_meter.Tracker.lastWallet = wallet
    hustle_meter.Tracker.lastWallet0 = wallet0
    hustle_meter.Tracker.lastWallet1 = wallet1
    hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode
    hustle_meter.Tracker.dualWalletRecoveryId = hustle_meter.DualWalletRecoveryId
    hustle_meter.Tracker.dualWalletRecoveryAt = nowSec
    hustle_meter.Tracker.dualWalletRecoveryBackup = backupPath
    hustle_meter.Tracker.dualWalletRecoveryFromTotal = trackedTotal

    scanner.confirmedTotal = total
    scanner.confirmedBank = bank
    scanner.confirmedWallet = wallet
    scanner.confirmedWallet0 = wallet0
    scanner.confirmedWallet1 = wallet1
    scanner.initialized = true
    scanner.candidate = nil
    scanner.resumeCandidate = nil

    hustle_meter.S.lastBalance = total
    hustle_meter.S.lastBank = bank
    hustle_meter.S.lastWallet = wallet
    hustle_meter.S.dualWalletRecoveryId = hustle_meter.DualWalletRecoveryId
    hustle_meter.S.dualWalletRecoveryCompletedAt = nowSec
    hustle_meter.S.dualWalletRecoveryStatus =
        "Recovered a legacy dual-wallet quarantine baseline without counting the historical gap as earnings."

    hustle_meter.recalculate_windows()

    if not hustle_meter.save_history() then
        -- Reload the untouched on-disk ledger. The archive remains available.
        hustle_meter.Tracker.loaded = false
        hustle_meter.Tracker.loadedFile = nil
        hustle_meter.load_history()
        hustle_meter.reset_transaction_scanner(accountKey)
        scanner = hustle_meter.get_transaction_scanner()
        scanner.dualWalletRecoveryEvaluated = false
        hustle_meter.S.lastBalance = tonumber(hustle_meter.Tracker.lastTotal or 0) or 0
        hustle_meter.S.lastBank = tonumber(hustle_meter.Tracker.lastBank or 0) or 0
        hustle_meter.S.lastWallet = tonumber(hustle_meter.Tracker.lastWallet or 0) or 0
        hustle_meter.S.dualWalletRecoveryId = ""
        hustle_meter.S.dualWalletRecoveryCompletedAt = 0
        hustle_meter.S.dualWalletRecoveryStatus = "Recovery could not be saved; previous ledger restored and recovery will retry."
        hustle_meter.warn("Dual-wallet recovery could not be saved. Previous ledger remains active.")
        return false, "save-failed"
    end

    if not hustle_meter.write_dual_wallet_recovery_marker(
        accountKey, backupPath, trackedTotal, total, bank, wallet, wallet0, wallet1, evidenceSource
    ) then
        -- The ledger also stores the recovery ID, so marker failure cannot repeat
        -- the rebaseline on the next launch.
        hustle_meter.warn("Dual-wallet recovery completed, but its standalone marker could not be written.")
    end

    scanner.dirty = false
    hustle_meter.debug_event(
        "LEGACY_DUAL_WALLET_RECOVERY",
        "Older combined-wallet quarantine baseline repaired; historical gap intentionally counted as $0 earned.",
        ("from=%s to=%s bank=%s wallet=%s w0=%s w1=%s evidence=%s backup=%s")
            :format(tostring(trackedTotal), tostring(total), tostring(bank), tostring(wallet),
                tostring(wallet0), tostring(wallet1), tostring(evidenceSource), tostring(backupPath))
    )
    hustle_meter.save_diagnostics("dual-wallet-recovery")
    hustle_meter.toast(
        "HustleMeter repaired an older dual-wallet tracking baseline. The old untracked balance gap was not counted as new earnings; future payouts will track normally.",
        9000
    )
    return true, "recovered"
end

function hustle_meter.reset_tracker_for_account(accountName, accountKey)
    accountName = hustle_meter.trim(accountName or "Unknown")
    accountKey = hustle_meter.sanitize_account_key(accountKey or accountName)
    hustle_meter.Tracker = {
        samples = {}, gains = {}, loaded = false, loadedFile = nil, importedLegacy = false,
        lastSaveMs = 0, lastTotal = nil, lastBank = nil, lastWallet = nil,
        lastWallet0 = nil, lastWallet1 = nil, balanceMode = nil,
        historyResetMigrationId = nil, historyResetAt = nil, historyResetBackup = nil,
        dualWalletRecoveryId = nil, dualWalletRecoveryAt = nil, dualWalletRecoveryBackup = nil,
        dualWalletRecoveryFromTotal = nil,
        accountName = accountName, accountKey = accountKey,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        cheraxVersion = tostring(hustle_meter.S.currentCheraxVersion or "Unknown"),
        cheraxBuild = tonumber(hustle_meter.S.currentCheraxBuild or 0) or 0
    }
    hustle_meter.HistoryFile = hustle_meter.get_account_history_file(accountKey)
    hustle_meter.S.currentAccountName = accountName
    hustle_meter.S.currentAccountKey = accountKey
    hustle_meter.S.past24h = 0
    hustle_meter.S.past168h = 0
    hustle_meter.S.gainCount = 0
    hustle_meter.S.sampleCount = 0
    hustle_meter.S.historyResetMigrationId = ""
    hustle_meter.S.historyResetCompletedAt = 0
    hustle_meter.S.historyResetStatus = "Pending legacy history migration for this account/edition."
    hustle_meter.S.dualWalletRecoveryId = ""
    hustle_meter.S.dualWalletRecoveryCompletedAt = 0
    hustle_meter.S.dualWalletRecoveryStatus = "Not yet evaluated for legacy dual-wallet quarantine recovery."
    if hustle_meter.reset_transaction_scanner then
        hustle_meter.reset_transaction_scanner(accountKey)
    end
end

function hustle_meter.load_account_registry()
    local data = hustle_meter.load_table(hustle_meter.AccountsFile)
    if type(data) ~= "table" then data = {} end
    if type(data.accounts) ~= "table" then data.accounts = {} end
    data.version = data.version or hustle_meter.Version
    return data
end

function hustle_meter.save_account_registry(data)
    if type(data) ~= "table" then data = { accounts = {} } end
    if type(data.accounts) ~= "table" then data.accounts = {} end
    data.version = hustle_meter.Version
    data.updatedAt = os.time()
    return hustle_meter.try_write_file(hustle_meter.AccountsFile, "return " .. hustle_meter.serialize(data, "") .. "\n")
end

function hustle_meter.register_account(accountName, accountKey)
    accountName = hustle_meter.trim(accountName or hustle_meter.S.currentAccountName or "Unknown")
    accountKey = hustle_meter.sanitize_account_key(accountKey or accountName)
    if not hustle_meter.is_valid_account_name(accountName) then return false end
    local data = hustle_meter.load_account_registry()
    local existing = data.accounts[accountKey] or {}
    data.accounts[accountKey] = {
        key = accountKey, name = accountName,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or existing.gameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or existing.cheraxEdition or "Unknown"),
        cheraxVersion = tostring(hustle_meter.S.currentCheraxVersion or existing.cheraxVersion or "Unknown"),
        cheraxBuild = tonumber(hustle_meter.S.currentCheraxBuild or existing.cheraxBuild or 0) or 0,
        firstSeen = tonumber(existing.firstSeen or os.time()) or os.time(),
        lastSeen = os.time(),
        lastTotal = tonumber(hustle_meter.S.lastBalance or existing.lastTotal or 0) or 0,
        lastBank = tonumber(hustle_meter.S.lastBank or existing.lastBank or 0) or 0,
        lastWallet = tonumber(hustle_meter.S.lastWallet or existing.lastWallet or 0) or 0,
        past24h = tonumber(hustle_meter.S.past24h or existing.past24h or 0) or 0,
        past168h = tonumber(hustle_meter.S.past168h or existing.past168h or 0) or 0,
        historyFile = hustle_meter.get_account_history_file(accountKey)
    }
    data.lastAccountKey = accountKey
    return hustle_meter.save_account_registry(data)
end

function hustle_meter.activate_account(accountName)
    accountName = hustle_meter.trim(accountName or "Unknown")
    if not hustle_meter.is_valid_account_name(accountName) then return false end
    local gameEdition = hustle_meter.refresh_runtime_metadata()
    local accountKey = hustle_meter.build_account_key(accountName, gameEdition)
    local previousKey = tostring(hustle_meter.S.currentAccountKey or "pending")
    if hustle_meter.Tracker and hustle_meter.Tracker.loaded and hustle_meter.S.currentAccountKey and hustle_meter.S.currentAccountKey ~= accountKey then
        hustle_meter.save_history()
    end
    if hustle_meter.S.currentAccountKey ~= accountKey or hustle_meter.Tracker.accountKey ~= accountKey then
        if hustle_meter.debug_event then
            hustle_meter.debug_event("ACCOUNT_LEDGER_SWITCH", "Rockstar/edition ledger changed.",
                "from=" .. tostring(previousKey) .. " to=" .. tostring(accountKey) .. " user=" .. tostring(accountName) .. " edition=" .. tostring(gameEdition))
        end
        hustle_meter.reset_tracker_for_account(accountName, accountKey)
        hustle_meter.ensure_account_dir(accountKey)
        hustle_meter.S.accountModeStatus = "Tracking " .. hustle_meter.account_display_name(accountName, gameEdition)
        hustle_meter.save_config(true)
    end
    hustle_meter.HistoryFile = hustle_meter.get_account_history_file(accountKey)
    hustle_meter.ensure_account_dir(accountKey)
    hustle_meter.register_account(accountName, accountKey)
    return true
end

function hustle_meter.ensure_current_account(force)
    hustle_meter.refresh_runtime_metadata()
    local now = hustle_meter.now()
    if not force and (now - (tonumber(hustle_meter.S.lastAccountCheckMs or 0) or 0)) < 3000 and hustle_meter.is_valid_account_name(hustle_meter.S.currentAccountName) then
        return true
    end
    hustle_meter.S.lastAccountCheckMs = now
    local accountName = hustle_meter.resolve_rockstar_username()
    if not hustle_meter.is_valid_account_name(accountName) then
        hustle_meter.S.accountModeStatus = "Waiting for Rockstar username. Ledger not switched yet."
        return false
    end
    return hustle_meter.activate_account(accountName)
end

function hustle_meter.history_is_empty()
    return #(hustle_meter.Tracker.samples or {}) == 0 and #(hustle_meter.Tracker.gains or {}) == 0 and ((tonumber(hustle_meter.Tracker.lastTotal or 0) or 0) <= 0)
end

function hustle_meter.adopt_history_table(data, sourceLabel)
    if type(data) ~= "table" then return false end
    hustle_meter.Tracker.samples = type(data.samples) == "table" and data.samples or {}
    hustle_meter.Tracker.gains = type(data.gains) == "table" and data.gains or hustle_meter.import_gains_from_samples(hustle_meter.Tracker.samples)
    hustle_meter.Tracker.lastTotal = tonumber(data.lastTotal or data.lastBalance or data.total or 0)
    hustle_meter.Tracker.lastBank = tonumber(data.lastBank or data.bank or 0)
    hustle_meter.Tracker.lastWallet = tonumber(data.lastWallet or data.wallet or 0)
    hustle_meter.Tracker.lastWallet0 = tonumber(data.lastWallet0 or data.wallet0)
    hustle_meter.Tracker.lastWallet1 = tonumber(data.lastWallet1 or data.wallet1)
    hustle_meter.Tracker.balanceMode = tostring(data.balanceMode or "legacy-active-wallet")
    hustle_meter.Tracker.importedLegacy = true
    hustle_meter.sort_samples(); hustle_meter.sort_gains()
    hustle_meter.S.lastStatus = tostring(sourceLabel or "Imported old shared ledger.")
    hustle_meter.recalculate_windows(); hustle_meter.save_history()
    return true
end

function hustle_meter.try_import_shared_history_for_current_balance(total, bank, wallet, wallet0, wallet1)
    if not hustle_meter.history_is_empty() then return false end
    if not hustle_meter.file_exists(hustle_meter.SharedHistoryFile) then return false end
    if tostring(hustle_meter.HistoryFile or "") == tostring(hustle_meter.SharedHistoryFile or "") then return false end
    local data = hustle_meter.load_table(hustle_meter.SharedHistoryFile)
    if type(data) ~= "table" then return false end
    local legacyTotal = tonumber(data.lastTotal or data.lastBalance or data.total or 0) or 0
    local legacyBank = tonumber(data.lastBank or data.bank or 0) or 0
    local legacyWallet = tonumber(data.lastWallet or data.wallet or 0) or 0
    total = tonumber(total or 0) or 0; bank = tonumber(bank or 0) or 0; wallet = tonumber(wallet or 0) or 0
    wallet0 = tonumber(wallet0 or 0) or 0; wallet1 = tonumber(wallet1 or 0) or 0
    local legacySlot0Total = bank + wallet0
    local legacySlot1Total = bank + wallet1
    local totalsMatch = legacyTotal > 0 and (
        math.floor(legacyTotal) == math.floor(total)
        or math.floor(legacyTotal) == math.floor(legacySlot0Total)
        or math.floor(legacyTotal) == math.floor(legacySlot1Total)
    )
    local walletMatch = math.floor(legacyWallet) == math.floor(wallet)
        or math.floor(legacyWallet) == math.floor(wallet0)
        or math.floor(legacyWallet) == math.floor(wallet1)
    local bankWalletMatch = (legacyBank <= 0 and legacyWallet <= 0)
        or (math.floor(legacyBank) == math.floor(bank) and walletMatch)
    if totalsMatch and bankWalletMatch then
        return hustle_meter.adopt_history_table(data, "Imported old shared ledger into " .. tostring(hustle_meter.S.currentAccountName or "current account") .. ".")
    end
    return false
end

function hustle_meter.claim_shared_history_for_current_account()
    if not hustle_meter.is_valid_account_name(hustle_meter.S.currentAccountName) then hustle_meter.toast("Rockstar account not detected yet.", 2500); return false end
    if not hustle_meter.history_is_empty() then hustle_meter.toast("Current account already has a ledger.", 2500); return false end
    local data = hustle_meter.load_table(hustle_meter.SharedHistoryFile)
    if type(data) ~= "table" then hustle_meter.toast("No old shared ledger found.", 2500); return false end
    local ok = hustle_meter.adopt_history_table(data, "Manually claimed old shared ledger for " .. tostring(hustle_meter.S.currentAccountName or "current account") .. ".")
    if ok then hustle_meter.toast("Old shared ledger claimed for this account.", 3000) end
    return ok
end

function hustle_meter.calculate_window_gain_from_events(events, windowSeconds, nowSec)
    nowSec = tonumber(nowSec or os.time()) or os.time()
    local cutoff = nowSec - (tonumber(windowSeconds or 86400) or 86400)
    local gain = 0
    for _, event in ipairs(events or {}) do
        local t = tonumber(event.t or 0) or 0
        local amount = tonumber(event.amount or 0) or 0
        if t > cutoff and amount > 0 then gain = gain + amount end
    end
    return math.floor(gain)
end

function hustle_meter.read_account_summary(accountKey, registryEntry)
    accountKey = hustle_meter.sanitize_account_key(accountKey or (registryEntry and registryEntry.key) or "unknown")
    local accountName = (registryEntry and registryEntry.name) or accountKey
    local data = hustle_meter.load_table(hustle_meter.get_account_history_file(accountKey))
    local summary = {
        key = accountKey, name = accountName,
        gameEdition = tostring(registryEntry and registryEntry.gameEdition or "Unknown"),
        cheraxEdition = tostring(registryEntry and registryEntry.cheraxEdition or "Unknown"),
        lastTotal = tonumber(registryEntry and registryEntry.lastTotal or 0) or 0,
        past24h = tonumber(registryEntry and registryEntry.past24h or 0) or 0,
        past168h = tonumber(registryEntry and registryEntry.past168h or 0) or 0,
        updatedAt = tonumber(registryEntry and registryEntry.lastSeen or 0) or 0
    }
    if type(data) == "table" then
        local gains = type(data.gains) == "table" and data.gains or hustle_meter.import_gains_from_samples(data.samples or {})
        summary.name = tostring(data.accountName or summary.name)
        summary.gameEdition = tostring(data.gameEdition or summary.gameEdition or "Unknown")
        summary.cheraxEdition = tostring(data.cheraxEdition or summary.cheraxEdition or "Unknown")
        summary.lastTotal = tonumber(data.lastTotal or data.lastBalance or summary.lastTotal or 0) or 0
        summary.past24h = hustle_meter.calculate_window_gain_from_events(gains, 24 * 60 * 60, os.time())
        summary.past168h = hustle_meter.calculate_window_gain_from_events(gains, 168 * 60 * 60, os.time())
        summary.updatedAt = tonumber(data.updatedAt or summary.updatedAt or 0) or 0
    end
    return summary
end

function hustle_meter.get_account_summaries()
    local registry = hustle_meter.load_account_registry()
    local summaries = {}
    for key, entry in pairs(registry.accounts or {}) do summaries[#summaries + 1] = hustle_meter.read_account_summary(key, entry) end
    local currentKey = hustle_meter.S.currentAccountKey
    if currentKey and currentKey ~= "pending" then
        local found = false
        for _, item in ipairs(summaries) do if item.key == currentKey then found = true break end end
        if not found then summaries[#summaries + 1] = hustle_meter.read_account_summary(currentKey, { name = hustle_meter.S.currentAccountName, key = currentKey }) end
    end
    table.sort(summaries, function(a, b)
        if a.key == hustle_meter.S.currentAccountKey then return true end
        if b.key == hustle_meter.S.currentAccountKey then return false end
        return tostring(a.name or a.key):lower() < tostring(b.name or b.key):lower()
    end)
    return summaries
end

function hustle_meter.account_view_label(item)
    if not item then return "Current account" end
    local name = tostring(item.name or item.key or "Unknown")
    local edition = tostring(item.gameEdition or "Unknown")
    local label = hustle_meter.account_display_name(name, edition)
    if item.key == hustle_meter.S.currentAccountKey then
        return label .. " (current / HUD)"
    end
    return label .. " (view only)"
end

function hustle_meter.get_account_view_entries()
    local summaries = hustle_meter.get_account_summaries()
    local entries, seen = {}, {}
    for _, item in ipairs(summaries or {}) do
        local key = tostring(item.key or "")
        if key ~= "" and key ~= "pending" and not seen[key] then
            seen[key] = true
            entries[#entries + 1] = item
        end
    end

    local currentKey = tostring(hustle_meter.S.currentAccountKey or "")
    if currentKey ~= "" and currentKey ~= "pending" and not seen[currentKey] then
        entries[#entries + 1] = hustle_meter.read_account_summary(currentKey, { name = hustle_meter.S.currentAccountName, key = currentKey })
    end

    if #entries == 0 then
        entries[#entries + 1] = {
            key = currentKey ~= "" and currentKey or "pending",
            name = tostring(hustle_meter.S.currentAccountName or "Detecting..."),
            gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
            cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
            lastTotal = tonumber(hustle_meter.S.lastBalance or 0) or 0,
            past24h = tonumber(hustle_meter.S.past24h or 0) or 0,
            past168h = tonumber(hustle_meter.S.past168h or 0) or 0,
            updatedAt = os.time()
        }
    end

    for _, item in ipairs(entries) do
        if item.key == hustle_meter.S.currentAccountKey then
            item.name = tostring(hustle_meter.S.currentAccountName or item.name or item.key)
            item.gameEdition = tostring(hustle_meter.S.currentGameEdition or item.gameEdition or "Unknown")
            item.cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or item.cheraxEdition or "Unknown")
            item.lastTotal = tonumber(hustle_meter.S.lastBalance or item.lastTotal or 0) or 0
            item.past24h = tonumber(hustle_meter.S.past24h or item.past24h or 0) or 0
            item.past168h = tonumber(hustle_meter.S.past168h or item.past168h or 0) or 0
            item.updatedAt = os.time()
        end
    end

    return entries
end

function hustle_meter.refresh_account_view_combo(save)
    local entries = hustle_meter.get_account_view_entries()
    local names = {}
    local selectedKey = tostring(hustle_meter.S.viewAccountKey or "current")
    if selectedKey == "" or selectedKey == "current" or selectedKey == "pending" then
        selectedKey = tostring(hustle_meter.S.currentAccountKey or selectedKey)
    end

    local selectedIndex = 0
    local found = false
    for i, item in ipairs(entries) do
        names[i] = hustle_meter.account_view_label(item)
        if tostring(item.key or "") == selectedKey then
            selectedIndex = i - 1
            found = true
        end
    end

    if not found and entries[1] then
        selectedIndex = 0
        selectedKey = tostring(entries[1].key or selectedKey)
    end

    hustle_meter.S.viewAccountKey = selectedKey
    hustle_meter.S.viewAccountIndex = selectedIndex
    hustle_meter.AccountViewEntries = entries
    hustle_meter.AccountViewNames = names

    local feature = hustle_meter.Features and hustle_meter.Features.AccountView
    if feature and feature.SetList then feature:SetList(names) end
    if feature and feature.SetListIndex then
        hustle_meter.accountViewSyncing = true
        feature:SetListIndex(selectedIndex)
        hustle_meter.accountViewSyncing = false
    end

    if save then hustle_meter.save_config(true) end
    return entries[selectedIndex + 1]
end

function hustle_meter.get_selected_view_summary()
    local selected = hustle_meter.refresh_account_view_combo(false)
    if selected and selected.key == hustle_meter.S.currentAccountKey then
        selected.name = tostring(hustle_meter.S.currentAccountName or selected.name or selected.key)
        selected.lastTotal = tonumber(hustle_meter.S.lastBalance or selected.lastTotal or 0) or 0
        selected.past24h = tonumber(hustle_meter.S.past24h or selected.past24h or 0) or 0
        selected.past168h = tonumber(hustle_meter.S.past168h or selected.past168h or 0) or 0
        selected.updatedAt = os.time()
    end
    return selected or {
        key = tostring(hustle_meter.S.currentAccountKey or "pending"),
        name = tostring(hustle_meter.S.currentAccountName or "Detecting..."),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        lastTotal = tonumber(hustle_meter.S.lastBalance or 0) or 0,
        past24h = tonumber(hustle_meter.S.past24h or 0) or 0,
        past168h = tonumber(hustle_meter.S.past168h or 0) or 0,
        updatedAt = os.time()
    }
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- quiet release logging
-- note: normal logs are muted; red warnings/errors remain visible for troubleshooting.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.log(msg)
    -- Normal logs are intentionally muted for a clean release-style script.
    -- Errors still go through hustle_meter.warn in red.
end

function hustle_meter.warn(msg)
    local text = "[HustleMeter] " .. tostring(msg)
    if Logger and Logger.LogError then
        Logger.LogError(text)
    elseif Logger and Logger.Log then
        Logger.Log(eLogColor and eLogColor.RED or nil, "HustleMeter", text)
    elseif Logger and Logger.LogWarning then
        Logger.LogWarning(text)
    end
end

function hustle_meter.toast(msg, ms)
    -- Text-only toast path. Do not provide a title/logo string so Cherax
    -- only receives the message text from this script.
    if GUI and GUI.AddToast then
        GUI.AddToast("", tostring(msg), ms or 3000, eToastPos and eToastPos.TOP_RIGHT or nil)
    end
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- lua table persistence
-- note: config/history are saved as Lua-return tables for simple Cherax loading.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.serialize(value, indent)
    indent = indent or ""
    local t = type(value)
    if t == "number" then
        return tostring(value)
    elseif t == "boolean" then
        return tostring(value)
    elseif t == "string" then
        return string.format("%q", value)
    elseif t == "table" then
        local nextIndent = indent .. "    "
        local parts = {"{\n"}
        for k, v in pairs(value) do
            local key
            if type(k) == "string" and k:match("^[%a_][%w_]*$") then
                key = k
            else
                key = "[" .. hustle_meter.serialize(k, nextIndent) .. "]"
            end
            parts[#parts + 1] = nextIndent .. key .. " = " .. hustle_meter.serialize(v, nextIndent) .. ",\n"
        end
        parts[#parts + 1] = indent .. "}"
        return table.concat(parts)
    end
    return "nil"
end

function hustle_meter.try_write_file(path, content)
    hustle_meter.ensure_dir()
    local file = io.open(path, "w")
    if not file then return false end
    file:write(content)
    file:close()
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- forensic payout capture
-- note: lightweight automatic recording supports normal reports; an optional detailed
-- capture raises sampling frequency for exact payout reconstruction.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.forensic_clean(value)
    local s = tostring(value == nil and "nil" or value)
    return s:gsub("[\r\n]+", " "):gsub("|", "/")
end

function hustle_meter.rotate_forensic_file(path)
    if not path or path == "" then return end
    local maxBytes = math.max(4194304, math.floor(tonumber(hustle_meter.S.forensicMaxTraceBytes or 33554432) or 33554432))
    if hustle_meter.debug_file_size and hustle_meter.debug_file_size(path) < maxBytes then return end

    pcall(os.remove, path .. ".3")
    pcall(os.rename, path .. ".2", path .. ".3")
    pcall(os.rename, path .. ".1", path .. ".2")
    pcall(os.rename, path, path .. ".1")
end

function hustle_meter.append_forensic_line(path, line)
    if hustle_meter.S.forensicCaptureEnabled ~= true then return false end
    hustle_meter.ensure_debug_dir()
    hustle_meter.rotate_forensic_file(path)
    local f = io.open(tostring(path or ""), "a")
    if not f then
        hustle_meter.Forensic.writeFailures = (tonumber(hustle_meter.Forensic.writeFailures or 0) or 0) + 1
        hustle_meter.S.forensicStatus = "ERROR: could not write forensic log."
        return false
    end
    f:write(tostring(line or ""), "\n")
    f:close()
    return true
end

function hustle_meter.forensic_push_recent(listName, item, maxItems)
    local f = hustle_meter.Forensic
    f[listName] = type(f[listName]) == "table" and f[listName] or {}
    f[listName][#f[listName] + 1] = item
    maxItems = math.max(25, tonumber(maxItems or 250) or 250)
    while #f[listName] > maxItems do table.remove(f[listName], 1) end
end

function hustle_meter.forensic_current_snapshot(reason)
    local scanner = type(hustle_meter.Scanner) == "table" and hustle_meter.Scanner or {}
    return {
        t = os.time(),
        ms = hustle_meter.now(),
        reason = tostring(reason or "snapshot"),
        accountName = tostring(hustle_meter.S.currentAccountName or "Detecting..."),
        accountKey = tostring(hustle_meter.S.currentAccountKey or "pending"),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        scannerStatus = tostring(hustle_meter.S.scannerStatus or "Unknown"),
        onlineStatus = tostring(hustle_meter.S.onlineStatus or "Unknown"),
        confirmedTotal = tonumber(scanner.confirmedTotal or 0) or 0,
        confirmedBank = tonumber(scanner.confirmedBank or 0) or 0,
        confirmedWallet = tonumber(scanner.confirmedWallet or 0) or 0,
        confirmedWallet0 = tonumber(scanner.confirmedWallet0 or 0) or 0,
        confirmedWallet1 = tonumber(scanner.confirmedWallet1 or 0) or 0,
        trackerTotal = tonumber(hustle_meter.Tracker and hustle_meter.Tracker.lastTotal or 0) or 0,
        past24h = tonumber(hustle_meter.S.past24h or 0) or 0,
        past168h = tonumber(hustle_meter.S.past168h or 0) or 0,
        gainCount = tonumber(hustle_meter.S.gainCount or 0) or 0,
        lastGainAmount = tonumber(hustle_meter.S.lastGainAmount or 0) or 0,
        lastGainTime = tostring(hustle_meter.S.lastGainTime or "None"),
        inTransition = scanner.inTransition == true,
        transitionId = tonumber(scanner.transitionId or 0) or 0,
        anchorActive = scanner.anchorActive == true,
        anchorTotal = tonumber(scanner.anchorTotal or 0) or 0,
        anchorCreditedAbove = tonumber(scanner.anchorCreditedAbove or 0) or 0
    }
end

function hustle_meter.forensic_event(kind, message, extra)
    if hustle_meter.S.forensicCaptureEnabled ~= true then return end
    local f = hustle_meter.Forensic
    f.sequence = (tonumber(f.sequence or 0) or 0) + 1
    local nowMs = hustle_meter.now()
    local line = ("%s | elapsedMs=%s | seq=%s | kind=%s | account=%s | edition=%s/%s | message=%s | extra=%s")
        :format(
            os.date("%Y-%m-%d %H:%M:%S"),
            tostring(nowMs - (tonumber(f.startedMs or nowMs) or nowMs)),
            tostring(f.sequence),
            hustle_meter.forensic_clean(kind or "EVENT"),
            hustle_meter.forensic_clean(hustle_meter.S.currentAccountKey or "pending"),
            hustle_meter.forensic_clean(hustle_meter.S.currentGameEdition or "Unknown"),
            hustle_meter.forensic_clean(hustle_meter.S.currentCheraxEdition or "Unknown"),
            hustle_meter.forensic_clean(message or ""),
            hustle_meter.forensic_clean(extra or "")
        )
    hustle_meter.append_forensic_line(hustle_meter.ForensicEventsFile, line)
    hustle_meter.forensic_push_recent("recentEvents", {
        t = os.time(), ms = nowMs, kind = tostring(kind or "EVENT"),
        message = tostring(message or ""), extra = tostring(extra or "")
    }, 300)
end

function hustle_meter.forensic_capture_money_snapshot(stage, nowMs, total, bank, wallet, wallet0, wallet1, flags, consistency, details)
    if hustle_meter.S.forensicCaptureEnabled ~= true then return end

    local f = hustle_meter.Forensic
    local scanner = hustle_meter.get_transaction_scanner()
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()
    flags = type(flags) == "table" and flags or hustle_meter.capture_session_flags()
    consistency = type(consistency) == "table" and consistency or hustle_meter.money_consistency(total, bank, wallet0, wallet1)

    local same =
        tonumber(f.lastRawTotal) == tonumber(total)
        and tonumber(f.lastRawBank) == tonumber(bank)
        and tonumber(f.lastRawWallet) == tonumber(wallet)
        and tonumber(f.lastRawWallet0) == tonumber(wallet0)
        and tonumber(f.lastRawWallet1) == tonumber(wallet1)

    local configuredInterval
    if f.testActive == true then
        configuredInterval = hustle_meter.S.forensicOneShotSnapshotIntervalMs or 100
    else
        configuredInterval = hustle_meter.S.forensicSnapshotIntervalMs or 1000
    end
    local interval = math.max(25, math.floor(tonumber(configuredInterval) or 1000))
    local hot = scanner.inTransition == true or scanner.anchorActive == true
    local shouldLog = (not same) or hot or (nowMs - (tonumber(f.lastLoggedMs or 0) or 0) >= interval)
    if not shouldLog then return end

    local prevTotal = tonumber(f.lastRawTotal)
    local prevBank = tonumber(f.lastRawBank)
    local prevWallet0 = tonumber(f.lastRawWallet0)
    local prevWallet1 = tonumber(f.lastRawWallet1)

    local rawDelta = prevTotal ~= nil and (tonumber(total or 0) - prevTotal) or 0
    local bankDelta = prevBank ~= nil and (tonumber(bank or 0) - prevBank) or 0
    local wallet0Delta = prevWallet0 ~= nil and (tonumber(wallet0 or 0) - prevWallet0) or 0
    local wallet1Delta = prevWallet1 ~= nil and (tonumber(wallet1 or 0) - prevWallet1) or 0

    f.sequence = (tonumber(f.sequence or 0) or 0) + 1
    f.rawReadCount = (tonumber(f.rawReadCount or 0) or 0) + 1
    f.lastLoggedMs = nowMs

    local changed = not same
    if changed and prevTotal ~= nil then
        f.rawChangeCount = (tonumber(f.rawChangeCount or 0) or 0) + 1
        if rawDelta > 0 then
            f.rawPositiveChangeTotal = (tonumber(f.rawPositiveChangeTotal or 0) or 0) + rawDelta
        elseif rawDelta < 0 then
            f.rawNegativeChangeTotal = (tonumber(f.rawNegativeChangeTotal or 0) or 0) + math.abs(rawDelta)
        end
        hustle_meter.forensic_push_recent("recentChanges", {
            t = os.time(), ms = nowMs, stage = tostring(stage or "scan"),
            total = total, bank = bank, wallet = wallet, wallet0 = wallet0, wallet1 = wallet1,
            rawDelta = rawDelta, bankDelta = bankDelta, wallet0Delta = wallet0Delta, wallet1Delta = wallet1Delta,
            confirmedTotal = tonumber(scanner.confirmedTotal or 0) or 0,
            trackerTotal = tonumber(hustle_meter.Tracker.lastTotal or 0) or 0,
            past24h = tonumber(hustle_meter.S.past24h or 0) or 0,
            past168h = tonumber(hustle_meter.S.past168h or 0) or 0
        }, 500)
    end

    local candidate = type(scanner.candidate) == "table" and scanner.candidate or {}
    local resume = type(scanner.resumeCandidate) == "table" and scanner.resumeCandidate or {}

    local line = table.concat({
        os.date("%Y-%m-%d %H:%M:%S"),
        "elapsedMs=" .. tostring(nowMs - (tonumber(f.startedMs or nowMs) or nowMs)),
        "seq=" .. tostring(f.sequence),
        "stage=" .. hustle_meter.forensic_clean(stage or "scan"),
        "account=" .. hustle_meter.forensic_clean(hustle_meter.S.currentAccountKey or "pending"),
        "edition=" .. hustle_meter.forensic_clean(hustle_meter.S.currentGameEdition or "Unknown") .. "/" .. hustle_meter.forensic_clean(hustle_meter.S.currentCheraxEdition or "Unknown"),
        "total=" .. hustle_meter.forensic_clean(total),
        "bank=" .. hustle_meter.forensic_clean(bank),
        "activeWallet=" .. hustle_meter.forensic_clean(wallet),
        "wallet0=" .. hustle_meter.forensic_clean(wallet0),
        "wallet1=" .. hustle_meter.forensic_clean(wallet1),
        "sum0=" .. hustle_meter.forensic_clean(consistency.sum0),
        "sum1=" .. hustle_meter.forensic_clean(consistency.sum1),
        "sumCombined=" .. hustle_meter.forensic_clean(consistency.sumCombined),
        "diff0=" .. hustle_meter.forensic_clean(consistency.diff0),
        "diff1=" .. hustle_meter.forensic_clean(consistency.diff1),
        "diffCombined=" .. hustle_meter.forensic_clean(consistency.diffCombined),
        "matchMode=" .. hustle_meter.forensic_clean(consistency.matchMode),
        "consistent=" .. tostring(consistency.consistent == true),
        "rawDelta=" .. tostring(rawDelta),
        "bankDelta=" .. tostring(bankDelta),
        "wallet0Delta=" .. tostring(wallet0Delta),
        "wallet1Delta=" .. tostring(wallet1Delta),
        "confirmedTotal=" .. hustle_meter.forensic_clean(scanner.confirmedTotal),
        "confirmedBank=" .. hustle_meter.forensic_clean(scanner.confirmedBank),
        "confirmedWallet0=" .. hustle_meter.forensic_clean(scanner.confirmedWallet0),
        "confirmedWallet1=" .. hustle_meter.forensic_clean(scanner.confirmedWallet1),
        "trackerTotal=" .. hustle_meter.forensic_clean(hustle_meter.Tracker.lastTotal),
        "past24=" .. hustle_meter.forensic_clean(hustle_meter.S.past24h),
        "past168=" .. hustle_meter.forensic_clean(hustle_meter.S.past168h),
        "gainCount=" .. hustle_meter.forensic_clean(hustle_meter.S.gainCount),
        "lastGain=" .. hustle_meter.forensic_clean(hustle_meter.S.lastGainAmount),
        "inTransition=" .. tostring(scanner.inTransition == true),
        "transitionId=" .. hustle_meter.forensic_clean(scanner.transitionId),
        "anchorActive=" .. tostring(scanner.anchorActive == true),
        "anchorTotal=" .. hustle_meter.forensic_clean(scanner.anchorTotal),
        "anchorCredited=" .. hustle_meter.forensic_clean(scanner.anchorCreditedAbove),
        "candidateTotal=" .. hustle_meter.forensic_clean(candidate.total),
        "candidateReads=" .. hustle_meter.forensic_clean(candidate.reads),
        "resumeTotal=" .. hustle_meter.forensic_clean(resume.total),
        "resumeReads=" .. hustle_meter.forensic_clean(resume.reads),
        "strongOnline=" .. tostring(scanner.lastStrongOnlineNow == true),
        "active=" .. tostring(flags.active == true),
        "inSession=" .. tostring(flags.inSession == true),
        "started=" .. tostring(flags.started == true),
        "signed=" .. tostring(flags.signedOnline == true),
        "playerOnline=" .. tostring(flags.playerOnline == true),
        "loading=" .. tostring(flags.loading == true),
        "playerSwitch=" .. tostring(flags.playerSwitch == true),
        "switchState=" .. hustle_meter.forensic_clean(flags.switchState),
        "faded=" .. tostring(flags.fadedOut == true),
        "fadingOut=" .. tostring(flags.fadingOut == true),
        "fadingIn=" .. tostring(flags.fadingIn == true),
        "historyReset=" .. hustle_meter.forensic_clean(hustle_meter.S.historyResetStatus),
        "dualRecovery=" .. hustle_meter.forensic_clean(hustle_meter.S.dualWalletRecoveryStatus),
        "scannerStatus=" .. hustle_meter.forensic_clean(hustle_meter.S.scannerStatus),
        "details=" .. hustle_meter.forensic_clean(details or "")
    }, " | ")

    hustle_meter.append_forensic_line(hustle_meter.ForensicTraceFile, line)

    f.lastRawTotal = total
    f.lastRawBank = bank
    f.lastRawWallet = wallet
    f.lastRawWallet0 = wallet0
    f.lastRawWallet1 = wallet1
end

function hustle_meter.forensic_record_gain(gain)
    if hustle_meter.S.forensicCaptureEnabled ~= true or type(gain) ~= "table" then return end
    local amount = math.floor(tonumber(gain.amount or 0) or 0)
    hustle_meter.Forensic.acceptedGainCount = (tonumber(hustle_meter.Forensic.acceptedGainCount or 0) or 0) + 1
    hustle_meter.Forensic.acceptedGainAmount = (tonumber(hustle_meter.Forensic.acceptedGainAmount or 0) or 0) + math.max(0, amount)
    hustle_meter.forensic_event(
        "LEDGER_GAIN_EVENT",
        "HustleMeter added a positive earnings event.",
        ("amount=%s before=%s after=%s source=%s bank=%s wallet=%s w0=%s w1=%s")
            :format(
                tostring(amount), tostring(gain.totalBefore or 0), tostring(gain.totalAfter or 0),
                tostring(gain.source or ""), tostring(gain.bank or 0), tostring(gain.wallet or 0),
                tostring(gain.wallet0 or 0), tostring(gain.wallet1 or 0)
            )
    )
end

function hustle_meter.forensic_test_snapshot(label)
    local total, bank, wallet, details, meta = hustle_meter.read_money_balance()
    local wallet0 = meta and tonumber(meta.wallet0 or 0) or 0
    local wallet1 = meta and tonumber(meta.wallet1 or 0) or 0
    local consistency = meta and meta.consistency or hustle_meter.money_consistency(total, bank, wallet0, wallet1)
    local scanner = hustle_meter.get_transaction_scanner()
    return {
        label = tostring(label or "marker"),
        t = os.time(),
        ms = hustle_meter.now(),
        total = tonumber(total or 0) or 0,
        bank = tonumber(bank or 0) or 0,
        wallet = tonumber(wallet or 0) or 0,
        wallet0 = wallet0,
        wallet1 = wallet1,
        consistency = consistency,
        confirmedTotal = tonumber(scanner.confirmedTotal or 0) or 0,
        trackerTotal = tonumber(hustle_meter.Tracker.lastTotal or 0) or 0,
        past24h = tonumber(hustle_meter.S.past24h or 0) or 0,
        past168h = tonumber(hustle_meter.S.past168h or 0) or 0,
        gainCount = tonumber(hustle_meter.S.gainCount or 0) or 0,
        lastGainAmount = tonumber(hustle_meter.S.lastGainAmount or 0) or 0,
        scannerStatus = tostring(hustle_meter.S.scannerStatus or ""),
        onlineStatus = tostring(hustle_meter.S.onlineStatus or ""),
        details = tostring(details or "")
    }
end

function hustle_meter.forensic_write_summary(reason)
    if hustle_meter.S.forensicCaptureEnabled ~= true then return false end
    local f = hustle_meter.Forensic
    local scanner = type(hustle_meter.Scanner) == "table" and hustle_meter.Scanner or {}

    local live = hustle_meter.forensic_test_snapshot("summary-live")
    local test = {
        active = f.testActive == true,
        start = f.testStart,
        ending = f.testEnd
    }

    if type(f.testStart) == "table" then
        test.currentAuthoritativeDelta = (tonumber(live.total or 0) or 0) - (tonumber(f.testStart.total or 0) or 0)
        test.currentConfirmedDelta = (tonumber(live.confirmedTotal or 0) or 0) - (tonumber(f.testStart.confirmedTotal or 0) or 0)
        test.currentTrackerDelta = (tonumber(live.trackerTotal or 0) or 0) - (tonumber(f.testStart.trackerTotal or 0) or 0)
        test.currentPast24Delta = (tonumber(live.past24h or 0) or 0) - (tonumber(f.testStart.past24h or 0) or 0)
        test.currentPast168Delta = (tonumber(live.past168h or 0) or 0) - (tonumber(f.testStart.past168h or 0) or 0)
        test.currentGainCountDelta = (tonumber(live.gainCount or 0) or 0) - (tonumber(f.testStart.gainCount or 0) or 0)
    end

    local data = {
        version = hustle_meter.Version,
        build = hustle_meter.Build,
        reason = tostring(reason or "periodic"),
        sessionId = tostring(f.sessionId or ""),
        startedAt = tonumber(f.startedAt or 0) or 0,
        startedMs = tonumber(f.startedMs or 0) or 0,
        updatedAt = os.time(),
        updatedMs = hustle_meter.now(),
        accountName = tostring(hustle_meter.S.currentAccountName or "Detecting..."),
        accountKey = tostring(hustle_meter.S.currentAccountKey or "pending"),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        rawReadCount = tonumber(f.rawReadCount or 0) or 0,
        rawChangeCount = tonumber(f.rawChangeCount or 0) or 0,
        rawPositiveChangeTotal = tonumber(f.rawPositiveChangeTotal or 0) or 0,
        rawNegativeChangeTotal = tonumber(f.rawNegativeChangeTotal or 0) or 0,
        acceptedGainCount = tonumber(f.acceptedGainCount or 0) or 0,
        acceptedGainAmount = tonumber(f.acceptedGainAmount or 0) or 0,
        writeFailures = tonumber(f.writeFailures or 0) or 0,
        forensicTraceFile = tostring(hustle_meter.ForensicTraceFile or ""),
        forensicEventsFile = tostring(hustle_meter.ForensicEventsFile or ""),
        cheraxLogPath = tostring(hustle_meter.CheraxLogPath or ""),
        cheraxLogExists = hustle_meter.file_exists(hustle_meter.CheraxLogPath),
        live = live,
        test = test,
        scanner = {
            status = tostring(hustle_meter.S.scannerStatus or ""),
            inTransition = scanner.inTransition == true,
            transitionId = tonumber(scanner.transitionId or 0) or 0,
            confirmedTotal = tonumber(scanner.confirmedTotal or 0) or 0,
            confirmedBank = tonumber(scanner.confirmedBank or 0) or 0,
            confirmedWallet0 = tonumber(scanner.confirmedWallet0 or 0) or 0,
            confirmedWallet1 = tonumber(scanner.confirmedWallet1 or 0) or 0,
            anchorActive = scanner.anchorActive == true,
            anchorTotal = tonumber(scanner.anchorTotal or 0) or 0,
            anchorCreditedAbove = tonumber(scanner.anchorCreditedAbove or 0) or 0,
            candidate = scanner.candidate,
            resumeCandidate = scanner.resumeCandidate
        },
        recentChanges = f.recentChanges,
        recentEvents = f.recentEvents
    }

    local ok = hustle_meter.try_write_file(
        hustle_meter.ForensicSummaryFile,
        "return " .. hustle_meter.serialize(data, "") .. "\n"
    )
    if ok then f.lastSummaryMs = hustle_meter.now() end
    return ok
end

function hustle_meter.forensic_write_readme()
    local lines = {
        "HUSTLEMETER - OPTIONAL DETAILED PAYOUT CAPTURE",
        "====================================================",
        "",
        "HustleMeter records lightweight automatic diagnostics. START DETAILED CAPTURE temporarily enables high-detail raw GTA$ and scanner recording.",
        "",
        "RECOMMENDED TEST",
        "1. Load HustleMeter before starting the payout activity.",
        "2. Open Config > Files & Support.",
        "3. Click START DETAILED CAPTURE immediately before starting the activity.",
        "4. Complete the payout normally. Do not reload HustleMeter during the test.",
        "5. After returning to freemode, wait at least 20 seconds.",
        "6. Click MARK CAPTURE END.",
        "7. Click Create Support ZIP.",
        "8. Send the resulting HustleMeter_Support.zip.",
        "",
        "If you forget MARK CAPTURE END, Create Support ZIP automatically records a final marker.",
        "",
        "WHAT IS CAPTURED",
        "- raw NETWORK_GET_VC_BALANCE on every scanner cycle",
        "- bank balance",
        "- character wallet 0 and wallet 1",
        "- bank+wallet0, bank+wallet1, and bank+wallet0+wallet1 validation",
        "- raw deltas between consecutive reads",
        "- confirmed scanner baseline and tracker baseline",
        "- rolling 1 Day / 7 Days values",
        "- scanner candidate/read counts",
        "- transition and 30-second anchor state",
        "- every Online/session/loading/player-switch flag",
        "- every HustleMeter debug decision/event",
        "- exact START -> END authoritative GTA$ delta",
        "- exact START -> END HustleMeter 1D/7D delta",
        "- full Cherax.log when present",
        "",
        "PRIVACY",
        "Cherax.log and forensic files may contain player names, Rockstar IDs, IP addresses,",
        "local paths, and other session/debug information. Share only with trusted support."
    }
    return hustle_meter.try_write_file(hustle_meter.ForensicReadmeFile, table.concat(lines, "\n") .. "\n")
end

function hustle_meter.forensic_boot_session()
    local f = hustle_meter.Forensic
    f.enabled = true
    f.testActive = false
    f.sessionId = (os.date("%Y%m%d_%H%M%S") or tostring(os.time())) .. "_" .. tostring(hustle_meter.Build)
    f.startedAt = os.time()
    f.startedMs = hustle_meter.now()
    f.sequence = 0
    f.lastLoggedMs = 0
    f.lastSummaryMs = 0
    hustle_meter.S.forensicStatus = "Automatic diagnostics active. Detailed capture idle."
    hustle_meter.forensic_write_readme()
    hustle_meter.forensic_event("DIAGNOSTIC_SESSION_START", "HustleMeter production diagnostic session started.", "sessionId=" .. tostring(f.sessionId))
    hustle_meter.forensic_write_summary("diagnostic-session-start")
end

function hustle_meter.forensic_clear_test_files()
    local paths = {
        hustle_meter.ForensicTraceFile, hustle_meter.ForensicEventsFile, hustle_meter.ForensicSummaryFile
    }
    for _, path in ipairs(paths) do
        pcall(os.remove, path)
        for i = 1, 3 do pcall(os.remove, path .. "." .. tostring(i)) end
    end
end

function hustle_meter.forensic_start_one_shot()
    if hustle_meter.S.supportZipBusy == true or hustle_meter.S.supportZipQueued == true then
        hustle_meter.S.forensicStatus = "Wait for Support ZIP creation to finish before starting detailed capture."
        hustle_meter.toast(hustle_meter.S.forensicStatus, 5000)
        return false
    end
    if hustle_meter.Forensic and hustle_meter.Forensic.testActive == true then
        hustle_meter.S.forensicStatus = "Detailed payout capture is already active."
        hustle_meter.toast(hustle_meter.S.forensicStatus, 3500)
        return false
    end

    hustle_meter.forensic_clear_test_files()

    local oldSessionId = hustle_meter.Forensic.sessionId
    hustle_meter.Forensic = {
        enabled = true,
        sessionId = (os.date("%Y%m%d_%H%M%S") or tostring(os.time())) .. "_" .. tostring(hustle_meter.Build),
        startedAt = os.time(),
        startedMs = hustle_meter.now(),
        sequence = 0,
        lastLoggedMs = 0,
        lastSummaryMs = 0,
        lastRawTotal = nil,
        lastRawBank = nil,
        lastRawWallet = nil,
        lastRawWallet0 = nil,
        lastRawWallet1 = nil,
        rawReadCount = 0,
        rawChangeCount = 0,
        rawPositiveChangeTotal = 0,
        rawNegativeChangeTotal = 0,
        acceptedGainCount = 0,
        acceptedGainAmount = 0,
        writeFailures = 0,
        testActive = true,
        testStart = nil,
        testEnd = nil,
        recentChanges = {},
        recentEvents = {}
    }

    hustle_meter.ensure_current_account(true)
    hustle_meter.recalculate_windows()
    hustle_meter.Forensic.testStart = hustle_meter.forensic_test_snapshot("TEST_START")
    hustle_meter.S.forensicStatus = "DETAILED CAPTURE ACTIVE: start baseline captured."

    local s = hustle_meter.Forensic.testStart
    hustle_meter.forensic_event(
        "TEST_START",
        "One-shot payout test baseline captured.",
        ("total=%s confirmed=%s tracker=%s past24=%s past168=%s bank=%s w0=%s w1=%s oldSession=%s")
            :format(
                tostring(s.total), tostring(s.confirmedTotal), tostring(s.trackerTotal),
                tostring(s.past24h), tostring(s.past168h), tostring(s.bank),
                tostring(s.wallet0), tostring(s.wallet1), tostring(oldSessionId)
            )
    )
    hustle_meter.forensic_write_summary("test-start")
    hustle_meter.toast("Detailed payout capture started. Complete the payout normally, then mark test end.", 6500)
    return true
end

function hustle_meter.forensic_mark_test_end(reason)
    local f = hustle_meter.Forensic
    if type(f.testStart) ~= "table" or f.testActive ~= true then
        f.testActive = false
        hustle_meter.S.forensicStatus = "No active detailed capture. Click START first."
        hustle_meter.forensic_event("TEST_END_WITHOUT_START", "End marker requested without an active START marker.", tostring(reason or "manual"))
        hustle_meter.forensic_write_summary("end-without-start")
        hustle_meter.toast(hustle_meter.S.forensicStatus, 4500)
        return false
    end

    hustle_meter.recalculate_windows()
    f.testEnd = hustle_meter.forensic_test_snapshot("TEST_END")
    f.testActive = false

    local s, e = f.testStart, f.testEnd
    local authoritativeDelta = (tonumber(e.total or 0) or 0) - (tonumber(s.total or 0) or 0)
    local confirmedDelta = (tonumber(e.confirmedTotal or 0) or 0) - (tonumber(s.confirmedTotal or 0) or 0)
    local trackerDelta = (tonumber(e.trackerTotal or 0) or 0) - (tonumber(s.trackerTotal or 0) or 0)
    local past24Delta = (tonumber(e.past24h or 0) or 0) - (tonumber(s.past24h or 0) or 0)
    local past168Delta = (tonumber(e.past168h or 0) or 0) - (tonumber(s.past168h or 0) or 0)
    local gainCountDelta = (tonumber(e.gainCount or 0) or 0) - (tonumber(s.gainCount or 0) or 0)

    hustle_meter.S.forensicStatus =
        ("DETAILED CAPTURE COMPLETE: authoritative %+d / 1D %+d / 7D %+d")
            :format(authoritativeDelta, past24Delta, past168Delta)

    hustle_meter.forensic_event(
        "TEST_END",
        "One-shot payout test final marker captured.",
        ("reason=%s authoritativeDelta=%s confirmedDelta=%s trackerDelta=%s past24Delta=%s past168Delta=%s gainCountDelta=%s startTotal=%s endTotal=%s")
            :format(
                tostring(reason or "manual"), tostring(authoritativeDelta), tostring(confirmedDelta),
                tostring(trackerDelta), tostring(past24Delta), tostring(past168Delta),
                tostring(gainCountDelta), tostring(s.total), tostring(e.total)
            )
    )
    hustle_meter.forensic_write_summary("test-end-" .. tostring(reason or "manual"))
    hustle_meter.toast(
        ("Forensic test ended. GTA$ delta: %s | HustleMeter 1D delta: %s")
            :format(hustle_meter.format_money(authoritativeDelta, true), hustle_meter.format_money(past24Delta, true)),
        7000
    )
    return true
end

function hustle_meter.forensic_periodic_maintenance()
    if hustle_meter.S.forensicCaptureEnabled ~= true then return end
    local nowMs = hustle_meter.now()
    local interval = math.max(1000, math.floor(tonumber(hustle_meter.S.forensicSummaryIntervalMs or 5000) or 5000))
    if nowMs - (tonumber(hustle_meter.Forensic.lastSummaryMs or 0) or 0) >= interval then
        hustle_meter.forensic_write_summary("periodic")
    end
end

function hustle_meter.schedule_forensic_start()
    if hustle_meter.PendingForensicStart == true or (hustle_meter.Forensic and hustle_meter.Forensic.testActive == true) then
        hustle_meter.S.forensicStatus = "Detailed payout capture is already active or starting."
        hustle_meter.toast(hustle_meter.S.forensicStatus, 3500)
        return false
    end
    if hustle_meter.S.supportZipBusy == true or hustle_meter.S.supportZipQueued == true then
        hustle_meter.S.forensicStatus = "Wait for Support ZIP creation to finish."
        hustle_meter.toast(hustle_meter.S.forensicStatus, 4000)
        return false
    end
    hustle_meter.PendingForensicStart = true
    hustle_meter.S.forensicStatus = "Starting detailed capture on worker..."
    return true
end

function hustle_meter.schedule_forensic_end()
    if not (hustle_meter.Forensic and hustle_meter.Forensic.testActive == true) then
        hustle_meter.PendingForensicEnd = false
        hustle_meter.S.forensicStatus = "No active detailed capture. Click START first."
        hustle_meter.toast(hustle_meter.S.forensicStatus, 4000)
        return false
    end
    if hustle_meter.PendingForensicEnd == true then
        return false
    end
    hustle_meter.PendingForensicEnd = true
    hustle_meter.S.forensicStatus = "Marking detailed capture end on worker..."
    return true
end

function hustle_meter.process_pending_forensic_actions()
    if hustle_meter.PendingForensicStart == true then
        hustle_meter.PendingForensicStart = false
        local ok, result = pcall(hustle_meter.forensic_start_one_shot)
        if not ok then
            hustle_meter.S.forensicStatus = "ERROR starting capture: " .. tostring(result)
            hustle_meter.forensic_event("FORENSIC_START_ERROR", "Could not start detailed capture.", tostring(result))
        elseif result ~= true and tostring(hustle_meter.S.forensicStatus or ""):find("^Starting") then
            hustle_meter.S.forensicStatus = "Detailed capture did not start."
        end
    end

    if hustle_meter.PendingForensicEnd == true then
        hustle_meter.PendingForensicEnd = false
        local ok, result = pcall(function() return hustle_meter.forensic_mark_test_end("manual-button") end)
        if not ok then
            hustle_meter.S.forensicStatus = "ERROR ending capture: " .. tostring(result)
            hustle_meter.forensic_event("FORENSIC_END_ERROR", "Could not mark detailed capture end.", tostring(result))
        elseif result ~= true and tostring(hustle_meter.S.forensicStatus or ""):find("^Marking") then
            hustle_meter.S.forensicStatus = "Detailed capture did not end."
        end
    end
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- transition diagnostics
-- note: detailed tracing is concentrated around transitions and suspicious money
-- activity so future bug reports can be reconstructed without noisy normal logging.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.ensure_debug_dir()
    hustle_meter.ensure_dir()
    if FileMgr and FileMgr.CreateDir and hustle_meter.DebugDir then FileMgr.CreateDir(hustle_meter.DebugDir) end
end

function hustle_meter.debug_file_size(path)
    local f = io.open(tostring(path or ""), "rb")
    if not f then return 0 end
    local size = f:seek("end") or 0
    f:close()
    return tonumber(size) or 0
end

function hustle_meter.rotate_debug_file(path)
    if not path or path == "" then return end
    local maxBytes = math.max(1048576, math.floor(tonumber(hustle_meter.S.diagnosticMaxTraceBytes or 4194304) or 4194304))
    if hustle_meter.debug_file_size(path) < maxBytes then return end
    pcall(os.remove, path .. ".3")
    pcall(os.rename, path .. ".2", path .. ".3")
    pcall(os.rename, path .. ".1", path .. ".2")
    pcall(os.rename, path, path .. ".1")
end

function hustle_meter.append_debug_line(path, line)
    if hustle_meter.S.diagnosticTraceEnabled ~= true then return false end
    hustle_meter.ensure_debug_dir()
    hustle_meter.rotate_debug_file(path)
    local f = io.open(tostring(path or ""), "a")
    if not f then return false end
    f:write(tostring(line or ""), "\n")
    f:close()
    return true
end

function hustle_meter.debug_clean(v)
    local t = tostring(v == nil and "nil" or v)
    t = t:gsub("[\r\n]+", " "):gsub("|", "/")
    return t
end

function hustle_meter.capture_session_flags()
    local function b(fn)
        local ok, value = pcall(fn)
        return ok and value == true or false
    end
    local function i(fn)
        local ok, value = pcall(fn)
        if ok then return tonumber(value) or -1 end
        return -1
    end
    return {
        active = b(NETWORK_IS_SESSION_ACTIVE),
        inSession = b(NETWORK_IS_IN_SESSION),
        started = b(NETWORK_IS_SESSION_STARTED),
        signedOnline = b(NETWORK_IS_SIGNED_ONLINE),
        playerOnline = b(IS_PLAYER_ONLINE),
        gameInProgress = b(NETWORK_IS_GAME_IN_PROGRESS),
        loading = b(GET_IS_LOADING_SCREEN_ACTIVE),
        playerSwitch = b(IS_PLAYER_SWITCH_IN_PROGRESS),
        switchState = i(GET_PLAYER_SWITCH_STATE),
        fadedOut = b(IS_SCREEN_FADED_OUT),
        fadingOut = b(IS_SCREEN_FADING_OUT),
        fadingIn = b(IS_SCREEN_FADING_IN)
    }
end

function hustle_meter.session_flags_text(f)
    f = type(f) == "table" and f or {}
    return ("active=%s inSession=%s started=%s signed=%s playerOnline=%s gameProgress=%s loading=%s playerSwitch=%s switchState=%s faded=%s fadingOut=%s fadingIn=%s")
        :format(tostring(f.active), tostring(f.inSession), tostring(f.started), tostring(f.signedOnline), tostring(f.playerOnline),
            tostring(f.gameInProgress), tostring(f.loading), tostring(f.playerSwitch), tostring(f.switchState),
            tostring(f.fadedOut), tostring(f.fadingOut), tostring(f.fadingIn))
end

function hustle_meter.money_consistency(total, bank, wallet0, wallet1)
    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet0 = math.floor(tonumber(wallet0 or 0) or 0)
    wallet1 = math.floor(tonumber(wallet1 or 0) or 0)

    local sum0 = bank + wallet0
    local sum1 = bank + wallet1
    local sumCombined = bank + wallet0 + wallet1

    local diff0 = math.abs(total - sum0)
    local diff1 = math.abs(total - sum1)
    local diffCombined = math.abs(total - sumCombined)
    local bestDiff = math.min(diff0, diff1, diffCombined)

    local matchesWallet0 = diff0 == 0
    local matchesWallet1 = diff1 == 0
    local matchesCombinedWallets = diffCombined == 0
    local matchMode = "none"

    -- Prefer the historical single-wallet representation when both expressions are
    -- mathematically identical (for example when the other wallet is $0). The new
    -- combined mode is used when both character wallets genuinely contribute.
    if matchesWallet0 then
        matchMode = "bank+wallet0"
    elseif matchesWallet1 then
        matchMode = "bank+wallet1"
    elseif matchesCombinedWallets then
        matchMode = "bank+wallet0+wallet1"
    end

    return {
        sum0 = sum0,
        sum1 = sum1,
        sumCombined = sumCombined,
        diff0 = diff0,
        diff1 = diff1,
        diffCombined = diffCombined,
        bestDiff = bestDiff,
        matchesWallet0 = matchesWallet0,
        matchesWallet1 = matchesWallet1,
        matchesCombinedWallets = matchesCombinedWallets,
        matchMode = matchMode,
        consistent = bestDiff == 0
    }
end

function hustle_meter.debug_event(kind, message, extra)
    local scanner = type(hustle_meter.Scanner) == "table" and hustle_meter.Scanner or {}
    local line = ("%s | ms=%d | %-28s | account=%s | edition=%s/%s | transitionId=%s | confirmed=%s | pre=%s | %s | %s")
        :format(os.date("%Y-%m-%d %H:%M:%S"), hustle_meter.now(), tostring(kind or "EVENT"),
            hustle_meter.debug_clean(hustle_meter.S.currentAccountName or "Detecting"),
            hustle_meter.debug_clean(hustle_meter.S.currentGameEdition or "Unknown"),
            hustle_meter.debug_clean(hustle_meter.S.currentCheraxEdition or "Unknown"),
            hustle_meter.debug_clean(scanner.transitionId or 0), hustle_meter.debug_clean(scanner.confirmedTotal or 0),
            hustle_meter.debug_clean(scanner.preTransitionTotal or 0), hustle_meter.debug_clean(message or ""), hustle_meter.debug_clean(extra or ""))
    hustle_meter.append_debug_line(hustle_meter.TransitionEventsFile, line)
    if hustle_meter.S.forensicCaptureEnabled == true and hustle_meter.forensic_event then
        hustle_meter.forensic_event(kind, message, extra)
    end
end

function hustle_meter.trace_scan(stage, nowMs, total, bank, wallet, wallet0, wallet1, flags, consistency, note)
    if hustle_meter.S.diagnosticTraceEnabled ~= true then return end
    local scanner = hustle_meter.get_transaction_scanner()
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()
    flags = type(flags) == "table" and flags or hustle_meter.capture_session_flags()
    consistency = type(consistency) == "table" and consistency or hustle_meter.money_consistency(total, bank, wallet0, wallet1)

    local inHotWindow = scanner.inTransition == true or scanner.anchorActive == true or nowMs <= (tonumber(scanner.debugTailUntilMs or 0) or 0)
    local idleMs = math.max(1000, math.floor(tonumber(hustle_meter.S.diagnosticIdleSnapshotMs or 30000) or 30000))
    if not inHotWindow and nowMs - (tonumber(scanner.lastDebugTraceMs or 0) or 0) < idleMs then return end
    scanner.lastDebugTraceMs = nowMs

    local rc = type(scanner.resumeCandidate) == "table" and scanner.resumeCandidate or {}
    local c = type(scanner.candidate) == "table" and scanner.candidate or {}
    local anchorRemaining = 0
    if scanner.anchorActive == true then
        anchorRemaining = math.max(0, (tonumber(scanner.anchorUntilMs or 0) or 0) - nowMs)
    end
    local line = ("%s | ms=%d | stage=%s | transitionId=%s | inTransition=%s | anchorActive=%s | anchorTotal=%s | anchorCredited=%s | anchorRemainingMs=%s | onlineNow=%s | strongOnline=%s | total=%s | bank=%s | wallet=%s | wallet0=%s | wallet1=%s | sum0=%s | sum1=%s | sumCombined=%s | diff0=%s | diff1=%s | diffCombined=%s | matchMode=%s | consistent=%s | confirmedTotal=%s | confirmedBank=%s | preTotal=%s | preBank=%s | resumeTotal=%s | resumeReads=%s | candidateTotal=%s | candidateReads=%s | %s | note=%s")
        :format(os.date("%Y-%m-%d %H:%M:%S"), nowMs, hustle_meter.debug_clean(stage or "scan"), hustle_meter.debug_clean(scanner.transitionId or 0),
            tostring(scanner.inTransition == true), tostring(scanner.anchorActive == true), hustle_meter.debug_clean(scanner.anchorTotal or 0),
            hustle_meter.debug_clean(scanner.anchorCreditedAbove or 0), hustle_meter.debug_clean(anchorRemaining),
            tostring(scanner.lastOnlineNow == true), tostring(scanner.lastStrongOnlineNow == true),
            hustle_meter.debug_clean(total), hustle_meter.debug_clean(bank), hustle_meter.debug_clean(wallet), hustle_meter.debug_clean(wallet0), hustle_meter.debug_clean(wallet1),
            hustle_meter.debug_clean(consistency.sum0), hustle_meter.debug_clean(consistency.sum1), hustle_meter.debug_clean(consistency.sumCombined),
            hustle_meter.debug_clean(consistency.diff0), hustle_meter.debug_clean(consistency.diff1), hustle_meter.debug_clean(consistency.diffCombined),
            hustle_meter.debug_clean(consistency.matchMode), tostring(consistency.consistent == true),
            hustle_meter.debug_clean(scanner.confirmedTotal), hustle_meter.debug_clean(scanner.confirmedBank), hustle_meter.debug_clean(scanner.preTransitionTotal), hustle_meter.debug_clean(scanner.preTransitionBank),
            hustle_meter.debug_clean(rc.total), hustle_meter.debug_clean(rc.reads), hustle_meter.debug_clean(c.total), hustle_meter.debug_clean(c.reads),
            hustle_meter.session_flags_text(flags), hustle_meter.debug_clean(note or ""))
    hustle_meter.append_debug_line(hustle_meter.ScannerTraceFile, line)
end

function hustle_meter.write_last_transition_snapshot(stage, extra)
    local scanner = hustle_meter.get_transaction_scanner()
    local data = {
        updatedAt = os.time(), updatedAtMs = hustle_meter.now(), stage = tostring(stage or "unknown"),
        scriptVersion = hustle_meter.Version, scriptBuild = hustle_meter.Build,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"), accountKey = tostring(hustle_meter.S.currentAccountKey or "pending"),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"), cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        transitionId = tonumber(scanner.transitionId or 0) or 0, inTransition = scanner.inTransition == true,
        transitionStartedMs = tonumber(scanner.transitionStartedMs or 0) or 0, resumeStartedMs = tonumber(scanner.resumeStartedMs or 0) or 0,
        strongOnlineSinceMs = tonumber(scanner.strongOnlineSinceMs or 0) or 0,
        preTransitionTotal = tonumber(scanner.preTransitionTotal or 0) or 0, preTransitionBank = tonumber(scanner.preTransitionBank or 0) or 0,
        preTransitionWallet = tonumber(scanner.preTransitionWallet or 0) or 0, preTransitionWallet0 = tonumber(scanner.preTransitionWallet0 or 0) or 0,
        preTransitionWallet1 = tonumber(scanner.preTransitionWallet1 or 0) or 0,
        confirmedTotal = tonumber(scanner.confirmedTotal or 0) or 0, confirmedBank = tonumber(scanner.confirmedBank or 0) or 0,
        confirmedWallet = tonumber(scanner.confirmedWallet or 0) or 0, confirmedWallet0 = tonumber(scanner.confirmedWallet0 or 0) or 0,
        confirmedWallet1 = tonumber(scanner.confirmedWallet1 or 0) or 0,
        resumeCandidate = scanner.resumeCandidate,
        anchorActive = scanner.anchorActive == true,
        anchorTotal = tonumber(scanner.anchorTotal or 0) or 0,
        anchorStartedMs = tonumber(scanner.anchorStartedMs or 0) or 0,
        anchorUntilMs = tonumber(scanner.anchorUntilMs or 0) or 0,
        anchorCreditedAbove = tonumber(scanner.anchorCreditedAbove or 0) or 0,
        anchorCandidate = scanner.anchorCandidate,
        lastFlags = scanner.lastFlags, extra = extra
    }
    hustle_meter.ensure_debug_dir()
    local ok = hustle_meter.try_write_file(hustle_meter.LastTransitionFile, "return " .. hustle_meter.serialize(data, "") .. "\n")
    if ok and hustle_meter.save_diagnostics then
        hustle_meter.save_diagnostics("transition-" .. tostring(stage or "unknown"))
    end
    return ok
end

function hustle_meter.record_suspicious_transition(reason, payload)
    local data = hustle_meter.load_table(hustle_meter.SuspiciousFile)
    if type(data) ~= "table" then data = { events = {} } end
    if type(data.events) ~= "table" then data.events = {} end
    local item = type(payload) == "table" and payload or {}
    item.t = os.time()
    item.ms = hustle_meter.now()
    item.reason = tostring(reason or "unknown")
    item.accountName = tostring(hustle_meter.S.currentAccountName or "Unknown")
    item.accountKey = tostring(hustle_meter.S.currentAccountKey or "pending")
    item.gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown")
    item.cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown")
    item.scriptBuild = tostring(hustle_meter.Build or "Unknown")
    item.transitionId = type(hustle_meter.Scanner) == "table" and tonumber(hustle_meter.Scanner.transitionId or 0) or 0
    data.events[#data.events + 1] = item
    while #data.events > 100 do table.remove(data.events, 1) end
    hustle_meter.ensure_debug_dir()
    hustle_meter.try_write_file(hustle_meter.SuspiciousFile, "return " .. hustle_meter.serialize(data, "") .. "\n")
    hustle_meter.S.scannerQuarantinedCount = (tonumber(hustle_meter.S.scannerQuarantinedCount or 0) or 0) + 1
    hustle_meter.debug_event("QUARANTINE", reason, "total=" .. tostring(item.total or "?") .. " delta=" .. tostring(item.delta or "?"))
    if hustle_meter.save_diagnostics then hustle_meter.save_diagnostics("quarantine") end
end

function hustle_meter.load_table(path)
    local file = io.open(path, "r")
    if not file then return nil end
    file:close()
    local loader = loadfile(path)
    if not loader then return nil end
    local result = loader()
    if type(result) == "table" then return result end
    return nil
end

function hustle_meter.resolve_hud_timeout_index(seconds)
    seconds = tonumber(seconds or 5) or 5
    if seconds == 5 then return 0 end
    for i, value in ipairs(hustle_meter.HudTimeoutSeconds or {}) do
        if tonumber(value) == seconds then return i - 1 end
    end
    return 0
end

function hustle_meter.resolve_hud_timeout_seconds(index)
    index = tonumber(index or 0) or 0
    local seconds = (hustle_meter.HudTimeoutSeconds or {})[index + 1]
    seconds = tonumber(seconds or 5) or 5
    if seconds == 0 then return 0 end
    if seconds < 1 then seconds = 1 end
    if seconds > 10 then seconds = 10 end
    return seconds
end

function hustle_meter.get_hud_timeout_label()
    local hideMs = tonumber(hustle_meter.S.hudHideMs or 5000) or 5000
    if hideMs <= 0 then return "No timeout" end
    return tostring(math.floor((hideMs / 1000) + 0.5)) .. "s"
end

function hustle_meter.is_hud_visible(ms)
    local visibleUntil = tonumber(hustle_meter.S.hudVisibleUntilMs or 0) or 0
    if visibleUntil == -1 then return true end
    return visibleUntil > (tonumber(ms) or hustle_meter.now())
end

function hustle_meter.apply_hud_timeout_index(index, save, preview)
    index = tonumber(index or 0) or 0
    local maxIndex = math.max(0, #(hustle_meter.HudTimeoutSeconds or {}) - 1)
    if index < 0 or index > maxIndex then index = 0 end
    local seconds = hustle_meter.resolve_hud_timeout_seconds(index)
    hustle_meter.S.hudTimeoutIndex = index
    hustle_meter.S.hudHideMs = seconds * 1000
    if save then hustle_meter.save_config(true) end
    if preview then
        hustle_meter.show_hud(seconds == 0 and "no timeout" or ("timeout " .. tostring(seconds) .. "s"))
    end
    return seconds
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- config save / load
-- note: user HUD placement, outline, timeout, and toggles are persisted here.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.save_config(silent)
    local config = {}
    for k, v in pairs(hustle_meter.S) do
        local vt = type(v)
        if vt == "number" or vt == "boolean" or vt == "string" then
            config[k] = v
        end
    end
    config.hudVisibleUntilMs = 0
    config.hudLastKeyPressed = false
    config.hudKeyPressCount = 0
    config.hudLastKeyPressMs = 0
    -- Runtime-only Hard Cap state must never persist as "blocked" across reloads.
    config.hardCapCashPickupsBlocked = false
    config.hardCapPickupTestUntilMs = 0
    config.hardCapPayoutTestArmed = false
    config.hardCapPayoutTestUntilMs = 0
    config.hardCapFirewallInstalled = false
    config.predictiveHeistGuardProbeBusy = false
    config.predictiveHeistGuardLastAttemptMs = 0
    config.preTransactionHoldBusy = false
    config.hardCapLastApplyMs = 0
    config.savedAt = os.time()
    config.version = hustle_meter.Version
    config.scriptBuild = hustle_meter.Build

    local ok = hustle_meter.try_write_file(hustle_meter.ConfigFile, "return " .. hustle_meter.serialize(config, "") .. "\n")
    if ok and not silent then hustle_meter.toast("Settings saved.", 2200) end
    if not ok then hustle_meter.warn("Failed to save config: " .. tostring(hustle_meter.ConfigFile)) end
    return ok
end

function hustle_meter.load_config(silent)
    local data = hustle_meter.load_table(hustle_meter.ConfigFile)
    if type(data) ~= "table" then
        -- Genuine new install: keep firstRunWelcomeCompleted=false so the
        -- one-time welcome opens automatically after the initial config is created.
        hustle_meter.save_config(true)
        return false
    end

    local hadFirstRunWelcomeState = data.firstRunWelcomeCompleted ~= nil

    for k, defaultValue in pairs(hustle_meter.Defaults) do
        if data[k] ~= nil and type(data[k]) == type(defaultValue) then
            hustle_meter.S[k] = data[k]
        end
    end

    -- Existing users upgrading from a build that predates the welcome UI should
    -- not be interrupted by a "first-time" popup. They can preview it from Config.
    if not hadFirstRunWelcomeState then
        hustle_meter.S.firstRunWelcomeCompleted = true
        hustle_meter.S.firstRunWelcomeCompletedAt = tonumber(data.savedAt or os.time()) or os.time()
    end

    -- Default outline: 1.15 unless the user has already tuned/saved it.
    if data.hudOutline == nil then hustle_meter.S.hudOutline = 1.15 end

    -- Legacy config upgrade: use faster polling for more accurate timestamped gain events
    -- and force the Online-only guard ON.
    local legacyFastPollingKey = "ledger" .. "R" .. "2Migrated"
    if data.fastLedgerPollingApplied ~= true and data[legacyFastPollingKey] ~= true then
        hustle_meter.S.updateMs = 1000
        hustle_meter.S.onlineOnly = true
        hustle_meter.S.onlineStableMs = 10000
        hustle_meter.S.fastLedgerPollingApplied = true
    end

    -- HustleMeter is intentionally GTA Online-only.
    -- Do not allow an older config to turn this OFF, because singleplayer money reads
    -- can create confusing or invalid baselines.
    hustle_meter.S.onlineOnly = true
    -- Build 044: compact support diagnostics only.
    hustle_meter.S.forensicCaptureEnabled = false
    hustle_meter.S.forensicSnapshotIntervalMs = 1000
    hustle_meter.S.forensicOneShotSnapshotIntervalMs = 100
    hustle_meter.S.forensicMaxTraceBytes = 33554432
    hustle_meter.S.forensicSummaryIntervalMs = 5000

    -- Support ZIP progress is runtime-only. Never inherit a stale busy/queued state
    -- from a config saved while an older build was packaging diagnostics.
    hustle_meter.S.supportZipBusy = false
    hustle_meter.S.supportZipQueued = false
    hustle_meter.S.supportZipCurrentFile = ""
    hustle_meter.S.supportZipProgress = 0
    hustle_meter.S.supportZipTotalFiles = 0
    hustle_meter.S.supportZipStatus = "Ready to create support ZIP."
    if (tonumber(hustle_meter.S.updateMs or 1000) or 1000) > 1000 then hustle_meter.S.updateMs = 1000 end
    if (tonumber(hustle_meter.S.scannerConfirmReads or 3) or 3) < 3 then hustle_meter.S.scannerConfirmReads = 3 end

    -- v1.0.5 production guard. Preserve the tested transition validation and
    -- post-transition anchor that prevents temporary balance loss/restoration from
    -- becoming false income.
    if data.diagnosticGuardV3Applied ~= true or tostring(data.version or "") ~= tostring(hustle_meter.Version) or tostring(data.scriptBuild or "") ~= tostring(hustle_meter.Build) then
        hustle_meter.S.scannerPostTransitionStableMs = 10000
        hustle_meter.S.scannerPostTransitionStableReads = 20
        hustle_meter.S.scannerPostTransitionStrongSessionMs = 5000
        hustle_meter.S.scannerPostTransitionAnchorMs = 30000
        hustle_meter.S.scannerAnchorGainStableMs = 5000
        hustle_meter.S.scannerAnchorGainStableReads = 10
        hustle_meter.S.scannerRequireMoneyConsistency = true
        hustle_meter.S.scannerQuarantineSuspiciousTransitions = true
        hustle_meter.S.diagnosticTraceEnabled = true
        hustle_meter.S.diagnosticIdleSnapshotMs = 30000
        hustle_meter.S.diagnosticTransitionTailMs = 60000
        hustle_meter.S.diagnosticMaxTraceBytes = 4194304
        hustle_meter.S.diagnosticGuardV2Applied = true
        hustle_meter.S.diagnosticGuardV3Applied = true
        hustle_meter.S.verboseLogs = false
    end

    -- HUD auto-hide timeout supports 1-10 real seconds or a persistent No timeout mode.
    -- Keep 5 seconds as the default/first combo entry for new and legacy configs.
    local loadedHideMs = tonumber(hustle_meter.S.hudHideMs or 5000) or 5000
    local loadedSeconds
    if data.hudHideMs ~= nil and loadedHideMs <= 0 then
        loadedSeconds = 0
    else
        loadedSeconds = math.floor((loadedHideMs / 1000) + 0.5)
        if loadedSeconds < 1 or loadedSeconds > 10 then loadedSeconds = 5 end
    end
    hustle_meter.S.hudTimeoutIndex = hustle_meter.resolve_hud_timeout_index(loadedSeconds)
    hustle_meter.S.hudHideMs = hustle_meter.resolve_hud_timeout_seconds(hustle_meter.S.hudTimeoutIndex) * 1000

    -- Approved HUD default migration. This intentionally updates older saved
    -- configs once so existing users land on the approved HustleMeter position.
    local legacyHudDefaultKey = "moneycheck" .. "R" .. "6DefaultsMigrated"
    if data.approvedHudDefaultsApplied ~= true and data[legacyHudDefaultKey] ~= true then
        hustle_meter.S.hud24X = 0.833
        hustle_meter.S.hud24Y = 0.0180
        hustle_meter.S.hud24Scale = 0.400
        hustle_meter.S.hud168X = 0.833
        hustle_meter.S.hud168Y = 0.0393
        hustle_meter.S.hud168Scale = 0.400
        hustle_meter.S.hudOutline = 1.15
        hustle_meter.S.warningColorsEnabled = true
        hustle_meter.S.approvedHudDefaultsApplied = true
        hustle_meter.save_config(true)
    end

    hustle_meter.S.hudVisibleUntilMs = 0
    hustle_meter.S.hudLastKeyPressed = false
    hustle_meter.S.hudKeyPressCount = 0
    hustle_meter.S.hudLastKeyPressMs = 0

    -- Never trust persisted runtime pickup-block state.
    hustle_meter.S.hardCapCashPickupsBlocked = false
    hustle_meter.S.hardCapPickupTestUntilMs = 0
    hustle_meter.S.hardCapPayoutTestArmed = false
    hustle_meter.S.hardCapPayoutTestUntilMs = 0
    hustle_meter.S.hardCapFirewallInstalled = false
    hustle_meter.S.predictiveHeistGuardProbeBusy = false
    hustle_meter.S.predictiveHeistGuardLastAttemptMs = 0
    hustle_meter.S.preTransactionHoldBusy = false
    hustle_meter.S.hardCapLastApplyMs = 0
    hustle_meter.S.hardCapLastState = "off"
    hustle_meter.S.hardCapLastBlockReason = ""

    -- Build 042 migration: Smart Cut is a payout-planning controller, so the old
    -- diagnostic BLOCK ALL mode must not remain armed from Builds 033-041.
    if hustle_meter.S.smartCutBuild042MigrationApplied ~= true then
        hustle_meter.S.hardCapBlockAllIncomingTestMode = false
        hustle_meter.S.smartCutBuild042MigrationApplied = true
        hustle_meter.save_config(true)
    end
    hustle_meter.S.smartCutLastProcessedGainCount = -1

    hustle_meter.S.hardCapTransactionFirewallEnabled = false
    hustle_meter.S.hardCapBlockAllIncomingTestMode = false
    hustle_meter.S.hardCapBlockGenericTransactionsTestMode = false
    hustle_meter.S.hardCapBlockKnownGlobalCommitTestMode = false
    hustle_meter.S.liveMoneyScannerEnabled = false
    hustle_meter.S.liveMoneyDeepLogging = false
    hustle_meter.S.liveMoneyPollMs = 1000
    hustle_meter.S.heistRiskScannerEnabled = false
    hustle_meter.S.predictiveHeistGuardEnabled = false
    hustle_meter.S.preTransactionHoldEnabled = false
    hustle_meter.S.forensicCaptureEnabled = false

    -- Build 058: legacy Build040/041 cut locks are not user-facing Smart Heists.
    -- Keep them permanently disabled so OFF means zero cut writes from HustleMeter.
    hustle_meter.S.silentNightApartmentLockEnabled = false
    hustle_meter.S.silentNightApartmentPresetWatchEnabled = false
    hustle_meter.S.silentNightApartmentLiveFeatureWatchEnabled = false
    hustle_meter.S.silentNightAdditionalHeistLockEnabled = false
    hustle_meter.S.silentNightAdditionalPresetWatchEnabled = false
    hustle_meter.S.silentNightAdditionalLiveFeatureWatchEnabled = false

    -- Build 061 retirement: stale Smart Heists settings remain inert and OFF.
    hustle_meter.S.smartCutControllerEnabled = false
    hustle_meter.S.smartPlayersEnabled = false
    hustle_meter.S.smartCutHardDisableReleasePending = false

    hustle_meter.S.smartCutAbsolute100CapEnabled = true
    hustle_meter.S.smartCutPresetWatchEnabled = true
    hustle_meter.S.smartCutLiveWatchEnabled = true
    hustle_meter.S.smartCutEnforceCooldowns = true
    hustle_meter.S.smartCutModeIndex = 0
    hustle_meter.S.smartCutApartmentFirstWeekly = false
    hustle_meter.S.smartCutCasinoFirstWeekly = false
    hustle_meter.S.smartCutDoomsdayFirstWeekly = false

    hustle_meter.S.firstRunWelcomeCompleted = true
    if tonumber(hustle_meter.S.firstRunWelcomeCompletedAt or 0) <= 0 then
        hustle_meter.S.firstRunWelcomeCompletedAt = os.time()
    end

    if hustle_meter.S.releaseCleanup044Applied ~= true then
        hustle_meter.S.releaseCleanup044Applied = true
        hustle_meter.save_config(true)
    end

    -- Build 045 RC2: start every Smart Heist at a normal 1X week once.
    if hustle_meter.S.releaseCleanup045Applied ~= true then
        hustle_meter.S.smartCutApartmentMultiplierIndex = 0
        hustle_meter.S.smartCutCayoMultiplierIndex = 0
        hustle_meter.S.smartCutCasinoMultiplierIndex = 0
        hustle_meter.S.smartCutDoomsdayMultiplierIndex = 0
        hustle_meter.S.weeklyProfileStatus = "Using 1X defaults."
        hustle_meter.S.weeklyProfileSource = "Default"
        hustle_meter.S.releaseCleanup045Applied = true
        hustle_meter.save_config(true)
    end

    -- Build 052 hotfix: Smart percentage controls are opt-in.
    -- Existing users are switched OFF exactly once. After this migration,
    -- any later manual ON/OFF choice is left untouched.
    if hustle_meter.S.releaseCleanup052SmartCutOptInApplied ~= true then
        hustle_meter.S.smartCutControllerEnabled = false
        hustle_meter.S.smartPlayersEnabled = false
        hustle_meter.S.releaseCleanup052SmartCutOptInApplied = true
        hustle_meter.save_config(true)
    end

    -- Build 061: Smart Heists is retired; do not perform any third-party release write.
    hustle_meter.S.releaseCleanup058HardDisableApplied = true
    hustle_meter.S.smartCutHardDisableReleasePending = false

    local bufferValues = hustle_meter.HardCap and hustle_meter.HardCap.SafetyBufferValues or { 0 }
    local bufferIndex = math.floor(tonumber(hustle_meter.S.hardCapSafetyBufferIndex or 0) or 0)
    if bufferIndex < 0 or bufferIndex >= #bufferValues then bufferIndex = 0 end
    hustle_meter.S.hardCapSafetyBufferIndex = bufferIndex
    hustle_meter.S.hardCapSafetyBuffer = tonumber(bufferValues[bufferIndex + 1] or 0) or 0

    if not silent then hustle_meter.toast("Settings loaded.", 2200) end
    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- formatting / warning math
-- note: converts raw deltas into GTA-style money text and warning bands.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.format_money(value, includePlus)
    value = tonumber(value or 0) or 0
    local sign = ""
    if value < 0 then
        sign = "-"
        value = math.abs(value)
    elseif includePlus and value > 0 then
        sign = "+"
    end

    value = math.floor(value + 0.5)
    local text = tostring(value)
    while true do
        local nextText, count = text:gsub("^(%-?%d+)(%d%d%d)", "%1,%2")
        text = nextText
        if count == 0 then break end
    end
    return sign .. "$" .. text
end

function hustle_meter.get_risk_band(amount, window)
    amount = tonumber(amount or 0) or 0
    local bands = (tonumber(window or 24) == 168) and hustle_meter.Risk.Bands168 or hustle_meter.Risk.Bands24
    if amount > bands.max then return "over" end
    if amount > bands.risky then return "stop" end
    if amount > bands.cautious then return "risky" end
    if amount > bands.safe then return "cautious" end
    return "safe"
end

function hustle_meter.get_risk_info(amount, window)
    local is168 = tonumber(window or 24) == 168
    if hustle_meter.S.warningColorsEnabled ~= true then
        if is168 then return hustle_meter.RiskColors.safe168 or hustle_meter.RiskColors.safe, "safe" end
        return hustle_meter.RiskColors.safe, "safe"
    end

    local key = hustle_meter.get_risk_band(amount, window)
    if is168 then
        local lightKey = tostring(key) .. "168"
        if hustle_meter.RiskColors[lightKey] then
            return hustle_meter.RiskColors[lightKey], key
        end
    end
    return hustle_meter.RiskColors[key] or hustle_meter.RiskColors.safe, key
end

function hustle_meter.get_dashboard_risk_info(amount, window)
    local is168 = tonumber(window or 24) == 168
    local key = hustle_meter.get_risk_band(amount, window)
    if is168 then
        local lightKey = tostring(key) .. "168"
        if hustle_meter.RiskColors[lightKey] then
            return hustle_meter.RiskColors[lightKey], key
        end
    end
    return hustle_meter.RiskColors[key] or hustle_meter.RiskColors.safe, key
end

function hustle_meter.get_display_past_values()
    return tonumber(hustle_meter.S.past24h or 0) or 0, tonumber(hustle_meter.S.past168h or 0) or 0
end

function hustle_meter.resolve_hard_cap_buffer(index)
    local values = hustle_meter.HardCap and hustle_meter.HardCap.SafetyBufferValues or { 0 }
    index = math.floor(tonumber(index or hustle_meter.S.hardCapSafetyBufferIndex or 0) or 0)
    if index < 0 or index >= #values then index = 0 end
    return tonumber(values[index + 1] or 0) or 0, index
end

function hustle_meter.get_hard_cap_state(expectedAmount)
    expectedAmount = math.max(0, math.floor(tonumber(expectedAmount or 0) or 0))
    local day = math.max(0, math.floor(tonumber(hustle_meter.S.past24h or 0) or 0))
    local week = math.max(0, math.floor(tonumber(hustle_meter.S.past168h or 0) or 0))
    local maxDay = math.max(0, math.floor(tonumber(hustle_meter.Risk.Max24 or 30000000) or 30000000))
    local maxWeek = math.max(0, math.floor(tonumber(hustle_meter.Risk.Max168 or 150000000) or 150000000))
    local buffer = select(1, hustle_meter.resolve_hard_cap_buffer())

    local stopDay = math.max(0, maxDay - buffer)
    local stopWeek = math.max(0, maxWeek - buffer)
    local remainingDay = math.max(0, stopDay - day)
    local remainingWeek = math.max(0, stopWeek - week)
    local remaining = math.min(remainingDay, remainingWeek)

    local projectedDay = day + expectedAmount
    local projectedWeek = week + expectedAmount
    local atOrOver = day >= stopDay or week >= stopWeek
    local projectedOver = projectedDay > stopDay or projectedWeek > stopWeek

    local limitingWindow
    if remainingDay <= remainingWeek then limitingWindow = "1 Day" else limitingWindow = "7 Days" end

    return {
        enabled = hustle_meter.S.hardCapGuardEnabled == true,
        blockCashPickups = hustle_meter.S.hardCapBlockCashPickups == true,
        day = day,
        week = week,
        maxDay = maxDay,
        maxWeek = maxWeek,
        buffer = buffer,
        stopDay = stopDay,
        stopWeek = stopWeek,
        remainingDay = remainingDay,
        remainingWeek = remainingWeek,
        remaining = remaining,
        limitingWindow = limitingWindow,
        expectedAmount = expectedAmount,
        projectedDay = projectedDay,
        projectedWeek = projectedWeek,
        atOrOver = atOrOver,
        projectedOver = projectedOver
    }
end

function hustle_meter.would_exceed_hard_cap(amount)
    return hustle_meter.get_hard_cap_state(amount).projectedOver == true
end

function hustle_meter.can_accept_payout(amount)
    if hustle_meter.S.hardCapGuardEnabled ~= true then return true end
    return hustle_meter.would_exceed_hard_cap(amount) ~= true
end

function hustle_meter.get_remaining_allowance()
    return hustle_meter.get_hard_cap_state(0).remaining
end

function hustle_meter.guard_expected_payout(amount, source, notify)
    amount = math.max(0, math.floor(tonumber(amount or 0) or 0))
    local state = hustle_meter.get_hard_cap_state(amount)
    if hustle_meter.S.hardCapGuardEnabled ~= true then
        return true, state, "guard-disabled"
    end
    if state.projectedOver ~= true then
        return true, state, "allowed"
    end

    local message = ("%s blocked by Hard Cap Guard: %s expected, only %s remaining (%s limit).")
        :format(
            tostring(source or "Payout"),
            hustle_meter.format_money(amount),
            hustle_meter.format_money(state.remaining),
            tostring(state.limitingWindow)
        )
    hustle_meter.S.hardCapStatus = message
    hustle_meter.S.hardCapLastBlockReason = tostring(source or "expected-payout")
    if notify ~= false then hustle_meter.toast(message, 7500) end
    if hustle_meter.debug_event then
        hustle_meter.debug_event("HARD_CAP_PROJECTED_PAYOUT_BLOCKED", message,
            "amount=" .. tostring(amount) .. " remaining=" .. tostring(state.remaining))
    end
    return false, state, "would-exceed"
end

-- Public integration aliases for other Cherax Lua mods.
-- Example:
-- if _G.HustleMeter and not _G.HustleMeter.CanAcceptPayout(12000000) then return end
hustle_meter.CanAcceptPayout = hustle_meter.can_accept_payout
hustle_meter.WouldExceedHardCap = hustle_meter.would_exceed_hard_cap
hustle_meter.GetRemainingAllowance = hustle_meter.get_remaining_allowance
hustle_meter.GetHardCapState = hustle_meter.get_hard_cap_state
hustle_meter.GuardExpectedPayout = hustle_meter.guard_expected_payout

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 061: Smart Heists retired
-- HustleMeter intentionally does not control third-party heist cuts or presets.
-- ═══════════════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 038: direct external payout / mission-finish integration
--
-- External scripts call this BEFORE they mutate mission state or trigger a payout.
-- Returns: allowed:boolean, state:table, reason:string
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.external_guard_metadata_text(metadata)
    if type(metadata) ~= "table" then return tostring(metadata or "") end
    local keys = {}
    for key in pairs(metadata) do keys[#keys + 1] = tostring(key) end
    table.sort(keys)
    local parts = {}
    for _, key in ipairs(keys) do
        local value = metadata[key]
        if type(value) ~= "table" then
            parts[#parts + 1] = tostring(key) .. "=" .. tostring(value)
        end
    end
    return table.concat(parts, ",")
end

function hustle_meter.external_payout_guard_log(kind, source, amount, reason, metadata, state)
    hustle_meter.ensure_debug_dir()
    local f = io.open(tostring(hustle_meter.ExternalPayoutGuardLogFile or ""), "a")
    if not f then return false end
    f:write(("%s | ms=%s | %s | source=%s | amount=%s | reason=%s | blockAll=%s | hardCap=%s | day=%s | week=%s | remaining=%s | metadata=%s\n")
        :format(
            os.date("%Y-%m-%d %H:%M:%S"),
            tostring(hustle_meter.now()),
            tostring(kind or "REQUEST"),
            tostring(source or "External Payout"),
            tostring(amount or 0),
            tostring(reason or ""),
            tostring(hustle_meter.S.hardCapBlockAllIncomingTestMode == true),
            tostring(hustle_meter.S.hardCapGuardEnabled == true),
            tostring(state and state.day or hustle_meter.S.past24h or 0),
            tostring(state and state.week or hustle_meter.S.past168h or 0),
            tostring(state and state.remaining or hustle_meter.get_remaining_allowance()),
            hustle_meter.external_guard_metadata_text(metadata)
        ))
    f:close()
    return true
end

function hustle_meter.guard_external_payout(source, amount, metadata, notify)
    source = tostring(source or "External Payout")
    amount = math.max(0, math.floor(tonumber(amount or 0) or 0))
    local state = hustle_meter.get_hard_cap_state(amount)
    local metadataText = hustle_meter.external_guard_metadata_text(metadata)

    hustle_meter.S.externalPayoutGuardCalls =
        (tonumber(hustle_meter.S.externalPayoutGuardCalls or 0) or 0) + 1
    hustle_meter.S.externalPayoutGuardLastSource = source
    hustle_meter.S.externalPayoutGuardLastAmount = amount
    hustle_meter.S.externalPayoutGuardLastMetadata =
        metadataText ~= "" and metadataText or "None"
    hustle_meter.S.externalPayoutGuardLastMs = hustle_meter.now()

    hustle_meter.external_payout_guard_log(
        "REQUEST", source, amount, "evaluating", metadata, state
    )

    -- Diagnostic mode: BLOCK ALL denies the payout-producing ACTION before it
    -- executes, even if amount is unknown (0) and the normal rolling-cap guard is off.
    if hustle_meter.S.hardCapBlockAllIncomingTestMode == true then
        local reason = "block-all-test"
        local message =
            source .. " BLOCKED before payout creation by HustleMeter BLOCK ALL test mode."

        hustle_meter.S.externalPayoutGuardBlocked =
            (tonumber(hustle_meter.S.externalPayoutGuardBlocked or 0) or 0) + 1
        hustle_meter.S.externalPayoutGuardLastDecision = "BLOCKED"
        hustle_meter.S.externalPayoutGuardLastReason = reason
        hustle_meter.S.hardCapStatus = message
        hustle_meter.S.hardCapLastBlockReason = source

        hustle_meter.external_payout_guard_log(
            "BLOCKED", source, amount, reason, metadata, state
        )
        if hustle_meter.debug_event then
            hustle_meter.debug_event(
                "EXTERNAL_PAYOUT_ACTION_BLOCKED",
                message,
                "source=" .. source
                    .. " amount=" .. tostring(amount)
                    .. " metadata=" .. metadataText
            )
        end
        if notify ~= false then hustle_meter.toast(message, 7000) end
        return false, state, reason
    end

    if hustle_meter.S.hardCapGuardEnabled == true and state.projectedOver == true then
        local reason = "would-exceed"
        local message =
            ("%s blocked before payout creation: %s expected, %s remaining (%s).")
                :format(
                    source,
                    hustle_meter.format_money(amount),
                    hustle_meter.format_money(state.remaining),
                    tostring(state.limitingWindow)
                )

        hustle_meter.S.externalPayoutGuardBlocked =
            (tonumber(hustle_meter.S.externalPayoutGuardBlocked or 0) or 0) + 1
        hustle_meter.S.externalPayoutGuardLastDecision = "BLOCKED"
        hustle_meter.S.externalPayoutGuardLastReason = reason
        hustle_meter.S.hardCapStatus = message
        hustle_meter.S.hardCapLastBlockReason = source

        hustle_meter.external_payout_guard_log(
            "BLOCKED", source, amount, reason, metadata, state
        )
        if hustle_meter.debug_event then
            hustle_meter.debug_event(
                "EXTERNAL_PAYOUT_ACTION_BLOCKED",
                message,
                "source=" .. source
                    .. " amount=" .. tostring(amount)
                    .. " remaining=" .. tostring(state.remaining)
            )
        end
        if notify ~= false then hustle_meter.toast(message, 7000) end
        return false, state, reason
    end

    hustle_meter.S.externalPayoutGuardAllowed =
        (tonumber(hustle_meter.S.externalPayoutGuardAllowed or 0) or 0) + 1
    hustle_meter.S.externalPayoutGuardLastDecision = "ALLOWED"
    hustle_meter.S.externalPayoutGuardLastReason =
        hustle_meter.S.hardCapGuardEnabled == true and "within-cap" or "guard-disabled"

    hustle_meter.external_payout_guard_log(
        "ALLOWED",
        source,
        amount,
        hustle_meter.S.externalPayoutGuardLastReason,
        metadata,
        state
    )
    return true, state, hustle_meter.S.externalPayoutGuardLastReason
end

function hustle_meter.should_block_incoming_money(source, amount, metadata)
    local allowed, state, reason =
        hustle_meter.guard_external_payout(source, amount, metadata, true)
    return allowed ~= true, state, reason
end

hustle_meter.IntegrationVersion = 1
hustle_meter.GuardExternalPayout = hustle_meter.guard_external_payout
hustle_meter.GuardPayout = hustle_meter.guard_external_payout
hustle_meter.ShouldBlockIncomingMoney = hustle_meter.should_block_incoming_money

function hustle_meter.apply_cash_pickup_permission(allowed, reason)
    allowed = allowed == true
    local playerId
    local okPlayer, value = pcall(PLAYER_ID)
    if okPlayer then playerId = tonumber(value) end
    if playerId == nil then
        hustle_meter.S.hardCapPickupApplyFailures = (tonumber(hustle_meter.S.hardCapPickupApplyFailures or 0) or 0) + 1
        return false, "PLAYER_ID unavailable"
    end

    local successes, failures = 0, 0
    for _, pickup in ipairs(hustle_meter.HardCap.PickupTypes or {}) do
        local ok = pcall(SET_PLAYER_PERMITTED_TO_COLLECT_PICKUPS_OF_TYPE, playerId, pickup.hash, allowed)
        if ok then successes = successes + 1 else failures = failures + 1 end
    end

    hustle_meter.S.hardCapPickupApplySuccesses = (tonumber(hustle_meter.S.hardCapPickupApplySuccesses or 0) or 0) + successes
    hustle_meter.S.hardCapPickupApplyFailures = (tonumber(hustle_meter.S.hardCapPickupApplyFailures or 0) or 0) + failures

    if failures == 0 then
        hustle_meter.S.hardCapCashPickupsBlocked = not allowed
        hustle_meter.S.hardCapLastApplyMs = hustle_meter.now()
        if hustle_meter.debug_event then
            hustle_meter.debug_event(
                allowed and "HARD_CAP_CASH_PICKUPS_ALLOWED" or "HARD_CAP_CASH_PICKUPS_BLOCKED",
                tostring(reason or ""),
                "types=" .. tostring(successes)
            )
        end
        return true
    end
    return false, tostring(failures) .. " pickup permission call(s) failed"
end

function hustle_meter.restore_hard_cap_cash_pickups(reason)
    if hustle_meter.S.hardCapCashPickupsBlocked ~= true then return true end
    return hustle_meter.apply_cash_pickup_permission(true, reason or "restore")
end

function hustle_meter.schedule_hard_cap_pickup_test()
    hustle_meter.PendingHardCapPickupTest = true
    hustle_meter.S.hardCapStatus = "Pickup block test queued..."
end

function hustle_meter.process_pending_hard_cap_actions()
    if hustle_meter.PendingHardCapPickupTest == true then
        hustle_meter.PendingHardCapPickupTest = false
        hustle_meter.S.hardCapPickupTestUntilMs = hustle_meter.now() + 30000
        hustle_meter.S.hardCapStatus = "TEST ACTIVE: cash pickups blocked for 30 seconds."
        hustle_meter.toast("Hard Cap pickup test active for 30 seconds. Try collecting NPC cash now.", 6500)
        if hustle_meter.debug_event then
            hustle_meter.debug_event("HARD_CAP_PICKUP_TEST_START", "30-second local cash-pickup block test started.", "")
        end
    end
end

function hustle_meter.update_hard_cap_guard(force)
    local nowMs = hustle_meter.now()
    local testUntil = tonumber(hustle_meter.S.hardCapPickupTestUntilMs or 0) or 0
    local testActive = testUntil > nowMs
    local state = hustle_meter.get_hard_cap_state(0)
    local online = hustle_meter.is_gta_online_session_detected and hustle_meter.is_gta_online_session_detected() or false

    local shouldBlock = false
    local reason = ""

    if testActive and online then
        shouldBlock = true
        reason = "30-second pickup test"
    elseif hustle_meter.S.hardCapBlockAllIncomingTestMode == true
        and hustle_meter.S.hardCapBlockCashPickups == true
        and online then
        shouldBlock = true
        reason = "BLOCK ALL incoming-money test mode"
    elseif hustle_meter.S.hardCapGuardEnabled == true
        and hustle_meter.S.hardCapBlockCashPickups == true
        and state.atOrOver == true
        and online then
        shouldBlock = true
        reason = ("%s cap reached; %s / %s")
            :format(
                tostring(state.limitingWindow),
                hustle_meter.format_money(state.day),
                hustle_meter.format_money(state.week)
            )
    end

    if shouldBlock then
        local reapplyDue = (nowMs - (tonumber(hustle_meter.S.hardCapLastApplyMs or 0) or 0)) >= 1000
        if hustle_meter.S.hardCapCashPickupsBlocked ~= true or force == true or reapplyDue then
            local ok, err = hustle_meter.apply_cash_pickup_permission(false, reason)
            if not ok then
                hustle_meter.S.hardCapStatus = "Pickup block error: " .. tostring(err or "unknown")
                return false
            end
        end

        if testActive then
            local left = math.max(0, math.ceil((testUntil - nowMs) / 1000))
            hustle_meter.S.hardCapStatus = "TEST ACTIVE: cash pickups blocked (" .. tostring(left) .. "s remaining)."
        else
            hustle_meter.S.hardCapStatus =
                ("HARD CAP ACTIVE: cash pickups blocked. Remaining allowance: %s.")
                    :format(hustle_meter.format_money(state.remaining))
            if hustle_meter.S.hardCapLastState ~= "blocked" then
                hustle_meter.S.hardCapTriggeredAt = os.time()
                hustle_meter.toast("Hard Cap reached. Supported physical GTA$ pickups are now blocked.", 7500)
            end
        end

        hustle_meter.S.hardCapLastState = "blocked"
        hustle_meter.S.hardCapLastBlockReason = reason
        return true
    end

    if hustle_meter.S.hardCapCashPickupsBlocked == true then
        hustle_meter.restore_hard_cap_cash_pickups(testActive and "test-ended" or "below-cap-or-disabled")
        if hustle_meter.S.hardCapLastState == "blocked" then
            hustle_meter.toast("Hard Cap cash-pickup block released.", 4000)
        end
    end

    if testUntil > 0 and not testActive then
        hustle_meter.S.hardCapPickupTestUntilMs = 0
        if hustle_meter.debug_event then
            hustle_meter.debug_event("HARD_CAP_PICKUP_TEST_END", "30-second pickup test completed.", "")
        end
    end

    if hustle_meter.S.hardCapGuardEnabled == true then
        hustle_meter.S.hardCapStatus =
            ("Guard armed. %s remaining before the effective cap.")
                :format(hustle_meter.format_money(state.remaining))
        hustle_meter.S.hardCapLastState = "armed"
    else
        hustle_meter.S.hardCapStatus = "Off. Tracking limits only."
        hustle_meter.S.hardCapLastState = "off"
    end
    return true
end



-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 033: Live Payout Scanner / deep money diagnostics
-- ═══════════════════════════════════════════════════════════════════════════════════

hustle_meter.LiveMoneyGlobalLabels = {
    [4516758] = "tx_state_commit",
    [4516759] = "tx_guard_limit",
    [4516760] = "tx_amount",
    [4516761] = "tx_service_hash",
    [4516762] = "tx_aux4",
    [4516763] = "tx_aux5",
    [4516764] = "tx_aux6",
    [4516765] = "tx_aux7"
}

function hustle_meter.live_money_safe(v)
    return tostring(v == nil and "nil" or v):gsub("[\r\n|]+", " ")
end

function hustle_meter.live_money_hash_text(v)
    local n = tonumber(v)
    if not n then return tostring(v or "nil") end
    return string.format("%d/0x%08X", math.floor(n), math.floor(n) & 0xFFFFFFFF)
end

function hustle_meter.rotate_live_money_file(path)
    if not path or path == "" then return end
    local maxBytes = math.max(
        8388608,
        math.floor(tonumber(hustle_meter.S.liveMoneyMaxTraceBytes or 67108864) or 67108864)
    )
    if hustle_meter.debug_file_size(path) < maxBytes then return end
    pcall(os.remove, path .. ".3")
    pcall(os.rename, path .. ".2", path .. ".3")
    pcall(os.rename, path .. ".1", path .. ".2")
    pcall(os.rename, path, path .. ".1")
end

function hustle_meter.append_live_money_line(path, line)
    if hustle_meter.S.liveMoneyDeepLogging ~= true then return false end
    hustle_meter.ensure_debug_dir()
    hustle_meter.rotate_live_money_file(path)
    local f = io.open(tostring(path or ""), "a")
    if not f then
        hustle_meter.LiveMoney.writeFailures = (tonumber(hustle_meter.LiveMoney.writeFailures or 0) or 0) + 1
        hustle_meter.S.liveMoneyWriteFailures = hustle_meter.LiveMoney.writeFailures
        return false
    end
    f:write(tostring(line or ""), "\n")
    f:close()
    return true
end

function hustle_meter.live_money_push(listName, item, maxItems)
    local live = hustle_meter.LiveMoney
    live[listName] = type(live[listName]) == "table" and live[listName] or {}
    live[listName][#live[listName] + 1] = item
    maxItems = math.max(10, tonumber(maxItems or 100) or 100)
    while #live[listName] > maxItems do table.remove(live[listName], 1) end
end

function hustle_meter.live_money_event(kind, detail, amount, confidence)
    if hustle_meter.S.liveMoneyScannerEnabled ~= true then return end
    local live = hustle_meter.LiveMoney
    local nowMs = hustle_meter.now()
    live.eventCount = (tonumber(live.eventCount or 0) or 0) + 1
    local item = {
        t = os.time(), ms = nowMs,
        kind = tostring(kind or "EVENT"),
        detail = tostring(detail or ""),
        amount = tonumber(amount or 0) or 0,
        confidence = tostring(confidence or "")
    }
    hustle_meter.live_money_push("recentEvents", item, 150)

    hustle_meter.append_live_money_line(
        hustle_meter.LiveMoneyEventsFile,
        ("%s | ms=%s | session=%s | kind=%s | confidence=%s | amount=%s | detail=%s")
            :format(
                os.date("%Y-%m-%d %H:%M:%S"),
                tostring(nowMs),
                hustle_meter.live_money_safe(live.sessionId),
                hustle_meter.live_money_safe(kind),
                hustle_meter.live_money_safe(confidence),
                tostring(amount or 0),
                hustle_meter.live_money_safe(detail)
            )
    )
end

function hustle_meter.live_money_signal(kind, path, amount, detail, confidence)
    if hustle_meter.S.liveMoneyScannerEnabled ~= true then return end
    local live = hustle_meter.LiveMoney
    local nowMs = hustle_meter.now()
    amount = tonumber(amount or 0) or 0
    confidence = tostring(confidence or "MEDIUM")

    live.signalCount = (tonumber(live.signalCount or 0) or 0) + 1
    live.lastSignal = {
        t = os.time(), ms = nowMs,
        kind = tostring(kind or "SIGNAL"),
        path = tostring(path or "Unknown"),
        amount = amount,
        detail = tostring(detail or ""),
        confidence = confidence
    }
    live.hotUntilMs = math.max(
        tonumber(live.hotUntilMs or 0) or 0,
        nowMs + math.max(1000, tonumber(hustle_meter.S.liveMoneySignalHotWindowMs or 15000) or 15000)
    )

    hustle_meter.S.liveMoneySignalCount = live.signalCount
    hustle_meter.S.liveMoneySignalLevel = confidence
    hustle_meter.S.liveMoneyLastSignal = tostring(kind or "SIGNAL") .. " via " .. tostring(path or "Unknown")
    hustle_meter.S.liveMoneyLastSignalAmount = amount
    hustle_meter.S.liveMoneyLastSignalAgeMs = 0

    hustle_meter.live_money_event(
        "PRE_MONEY_SIGNAL:" .. tostring(kind or "SIGNAL"),
        tostring(path or "Unknown") .. " | " .. tostring(detail or ""),
        amount,
        confidence
    )
end

function hustle_meter.live_money_global_values()
    local values = {}
    if not ScriptGlobal or not ScriptGlobal.GetInt then return values end
    for index = 4516758, 4516765 do
        local ok, value = pcall(ScriptGlobal.GetInt, index)
        if ok and value ~= nil then values[index] = tonumber(value) or value end
    end
    return values
end

function hustle_meter.live_money_capture_globals(nowMs)
    local live = hustle_meter.LiveMoney
    local values = hustle_meter.live_money_global_values()

    for index, value in pairs(values) do
        local previous = live.globals[index]
        if previous ~= value then
            live.globals[index] = value
            local label = hustle_meter.LiveMoneyGlobalLabels[index] or "unknown"
            local detail = ("global=%s label=%s from=%s to=%s")
                :format(tostring(index), tostring(label), tostring(previous), tostring(value))

            hustle_meter.append_live_money_line(
                hustle_meter.LiveMoneyGlobalsFile,
                ("%s | ms=%s | %s")
                    :format(os.date("%Y-%m-%d %H:%M:%S"), tostring(nowMs), detail)
            )

            if previous ~= nil then
                if index == 4516760 and tonumber(value or 0) and tonumber(value or 0) > 0 then
                    hustle_meter.live_money_signal(
                        "GLOBAL_AMOUNT",
                        "ScriptGlobal[4516760]",
                        tonumber(value) or 0,
                        detail,
                        "HIGH"
                    )
                elseif index == 4516758 and tonumber(value) == 2 then
                    local amount = tonumber(values[4516760] or live.globals[4516760] or 0) or 0
                    hustle_meter.live_money_signal(
                        "GLOBAL_COMMIT",
                        "ScriptGlobal[4516758]=2",
                        amount,
                        detail .. " amountGlobal=" .. tostring(amount),
                        "VERY HIGH"
                    )
                elseif index == 4516761 and tonumber(value or 0) ~= 0 then
                    hustle_meter.live_money_signal(
                        "GLOBAL_SERVICE_HASH",
                        "ScriptGlobal[4516761]",
                        0,
                        detail .. " hash=" .. hustle_meter.live_money_hash_text(value),
                        "MEDIUM"
                    )
                end
            end
        end
    end
end

function hustle_meter.live_money_read_tx_state()
    local function b(fn, ...)
        local ok, value = pcall(fn, ...)
        return ok and value == true or false
    end
    local slot = tonumber(hustle_meter.S.characterSlot or 0) or 0
    return {
        transactionInProgress = b(NET_GAMESERVER_TRANSACTION_IN_PROGRESS),
        basketActive = b(NET_GAMESERVER_BASKET_IS_ACTIVE),
        sessionValid = b(NET_GAMESERVER_IS_SESSION_VALID, slot),
        refreshPending = b(NET_GAMESERVER_IS_SESSION_REFRESH_PENDING),
        startSessionPending = b(NET_GAMESERVER_START_SESSION_PENDING),
        useServerTransactions = b(NET_GAMESERVER_USE_SERVER_TRANSACTIONS),
        catalogValid = b(NET_GAMESERVER_CATALOG_IS_VALID),
        catalogCurrent = b(NET_GAMESERVER_IS_CATALOG_CURRENT)
    }
end

function hustle_meter.live_money_correlate(delta, total, bank, wallet0, wallet1, nowMs)
    local live = hustle_meter.LiveMoney
    local signal = live.lastSignal
    local ageMs = signal and (nowMs - (tonumber(signal.ms or nowMs) or nowMs)) or nil
    local window = math.max(1000, tonumber(hustle_meter.S.liveMoneyCorrelationWindowMs or 20000) or 20000)

    if signal and ageMs and ageMs >= 0 and ageMs <= window then
        local correlation = {
            t = os.time(), ms = nowMs,
            delta = delta, total = total, bank = bank,
            wallet0 = wallet0, wallet1 = wallet1,
            signalKind = tostring(signal.kind or ""),
            signalPath = tostring(signal.path or ""),
            signalAmount = tonumber(signal.amount or 0) or 0,
            signalConfidence = tostring(signal.confidence or ""),
            signalAgeMs = ageMs,
            exactAmountMatch =
                tonumber(signal.amount or 0) > 0
                and math.floor(tonumber(signal.amount or 0) or 0) == math.floor(delta)
        }
        live.correlationCount = (tonumber(live.correlationCount or 0) or 0) + 1
        live.lastCorrelation = correlation
        hustle_meter.live_money_push("recentCorrelations", correlation, 80)
        hustle_meter.S.liveMoneyCorrelationCount = live.correlationCount

        local description =
            ("%+d GTA$ %dms after %s via %s predicted=%s exact=%s")
                :format(
                    math.floor(delta),
                    math.floor(ageMs),
                    tostring(signal.kind or ""),
                    tostring(signal.path or ""),
                    tostring(signal.amount or 0),
                    tostring(correlation.exactAmountMatch)
                )
        hustle_meter.S.liveMoneyLastCorrelation = description

        hustle_meter.append_live_money_line(
            hustle_meter.LiveMoneyCorrelationFile,
            ("%s | ms=%s | %s | total=%s bank=%s w0=%s w1=%s confidence=%s")
                :format(
                    os.date("%Y-%m-%d %H:%M:%S"),
                    tostring(nowMs),
                    hustle_meter.live_money_safe(description),
                    tostring(total), tostring(bank), tostring(wallet0), tostring(wallet1),
                    hustle_meter.live_money_safe(signal.confidence)
                )
        )
        hustle_meter.live_money_event("SIGNAL_MONEY_CORRELATION", description, delta, signal.confidence)
    else
        local description =
            ("Money changed %+d with no visible pre-signal inside %dms.")
                :format(math.floor(delta), math.floor(window))
        hustle_meter.S.liveMoneyLastCorrelation = description
        hustle_meter.live_money_event("UNSIGNALED_MONEY_CHANGE", description, delta, "UNKNOWN")
    end
end

function hustle_meter.live_money_write_trace(nowMs, total, bank, wallet, wallet0, wallet1, meta, tx, flags, force)
    if hustle_meter.S.liveMoneyDeepLogging ~= true then return end
    local live = hustle_meter.LiveMoney

    local hotUntil = math.max(
        tonumber(live.hotUntilMs or 0) or 0,
        tonumber(live.manualHotUntilMs or 0) or 0,
        tonumber(hustle_meter.S.liveMoneyManualHotUntilMs or 0) or 0
    )
    local hot = nowMs <= hotUntil
    local interval = hot
        and math.max(10, tonumber(hustle_meter.S.liveMoneyHotTraceMs or 25) or 25)
        or math.max(25, tonumber(hustle_meter.S.liveMoneyIdleTraceMs or 100) or 100)

    if force ~= true and nowMs - (tonumber(live.lastTraceMs or 0) or 0) < interval then return end
    live.lastTraceMs = nowMs
    live.traceCount = (tonumber(live.traceCount or 0) or 0) + 1

    local scanner = type(hustle_meter.Scanner) == "table" and hustle_meter.Scanner or {}
    local consistency = type(meta) == "table" and meta.consistency or {}
    local signal = type(live.lastSignal) == "table" and live.lastSignal or {}
    local signalAge = signal.ms and math.max(0, nowMs - (tonumber(signal.ms) or nowMs)) or -1
    local g = live.globals or {}

    local line = table.concat({
        os.date("%Y-%m-%d %H:%M:%S"),
        "ms=" .. tostring(nowMs),
        "session=" .. hustle_meter.live_money_safe(live.sessionId),
        "hot=" .. tostring(hot),
        "total=" .. tostring(total),
        "bank=" .. tostring(bank),
        "activeWallet=" .. tostring(wallet),
        "wallet0=" .. tostring(wallet0),
        "wallet1=" .. tostring(wallet1),
        "matchMode=" .. hustle_meter.live_money_safe(consistency.matchMode),
        "consistent=" .. tostring(consistency.consistent == true),
        "txInProgress=" .. tostring(tx.transactionInProgress == true),
        "basketActive=" .. tostring(tx.basketActive == true),
        "shopSessionValid=" .. tostring(tx.sessionValid == true),
        "refreshPending=" .. tostring(tx.refreshPending == true),
        "startSessionPending=" .. tostring(tx.startSessionPending == true),
        "useServerTransactions=" .. tostring(tx.useServerTransactions == true),
        "catalogValid=" .. tostring(tx.catalogValid == true),
        "catalogCurrent=" .. tostring(tx.catalogCurrent == true),
        "globalState=" .. tostring(g[4516758]),
        "globalGuard=" .. tostring(g[4516759]),
        "globalAmount=" .. tostring(g[4516760]),
        "globalHash=" .. hustle_meter.live_money_hash_text(g[4516761]),
        "globalAux4=" .. tostring(g[4516762]),
        "globalAux5=" .. tostring(g[4516763]),
        "globalAux6=" .. tostring(g[4516764]),
        "globalAux7=" .. tostring(g[4516765]),
        "lastSignalKind=" .. hustle_meter.live_money_safe(signal.kind),
        "lastSignalPath=" .. hustle_meter.live_money_safe(signal.path),
        "lastSignalAmount=" .. tostring(signal.amount or 0),
        "lastSignalConfidence=" .. hustle_meter.live_money_safe(signal.confidence),
        "lastSignalAgeMs=" .. tostring(signalAge),
        "blockAllTest=" .. tostring(hustle_meter.S.hardCapBlockAllIncomingTestMode == true),
        "firewallPath=" .. hustle_meter.live_money_safe(hustle_meter.S.hardCapFirewallLastPath),
        "firewallNative=" .. hustle_meter.live_money_safe(hustle_meter.S.hardCapFirewallLastNative),
        "firewallAmount=" .. tostring(hustle_meter.S.hardCapFirewallLastAmount or 0),
        "firewallDecision=" .. hustle_meter.live_money_safe(hustle_meter.S.hardCapFirewallLastDecision),
        "scannerConfirmed=" .. tostring(scanner.confirmedTotal or 0),
        "scannerTransition=" .. tostring(scanner.inTransition == true),
        "scannerTransitionId=" .. tostring(scanner.transitionId or 0),
        "anchorActive=" .. tostring(scanner.anchorActive == true),
        "anchorTotal=" .. tostring(scanner.anchorTotal or 0),
        "candidateTotal=" .. tostring(type(scanner.candidate) == "table" and scanner.candidate.total or nil),
        "candidateReads=" .. tostring(type(scanner.candidate) == "table" and scanner.candidate.reads or nil),
        "trackerTotal=" .. tostring(hustle_meter.Tracker and hustle_meter.Tracker.lastTotal or 0),
        "past24=" .. tostring(hustle_meter.S.past24h or 0),
        "past168=" .. tostring(hustle_meter.S.past168h or 0),
        "onlineActive=" .. tostring(flags.active == true),
        "inSession=" .. tostring(flags.inSession == true),
        "started=" .. tostring(flags.started == true),
        "signedOnline=" .. tostring(flags.signedOnline == true),
        "playerOnline=" .. tostring(flags.playerOnline == true),
        "loading=" .. tostring(flags.loading == true),
        "playerSwitch=" .. tostring(flags.playerSwitch == true),
        "switchState=" .. tostring(flags.switchState),
        "faded=" .. tostring(flags.fadedOut == true),
        "fadingOut=" .. tostring(flags.fadingOut == true),
        "fadingIn=" .. tostring(flags.fadingIn == true)
    }, " | ")

    hustle_meter.append_live_money_line(hustle_meter.LiveMoneyTraceFile, line)
end

function hustle_meter.live_money_write_summary(reason)
    local live = hustle_meter.LiveMoney
    local data = {
        version = hustle_meter.Version,
        build = hustle_meter.Build,
        reason = tostring(reason or "periodic"),
        updatedAt = os.time(),
        updatedMs = hustle_meter.now(),
        sessionId = tostring(live.sessionId or ""),
        startedAt = tonumber(live.startedAt or 0) or 0,
        readCount = tonumber(live.readCount or 0) or 0,
        traceCount = tonumber(live.traceCount or 0) or 0,
        eventCount = tonumber(live.eventCount or 0) or 0,
        moneyChangeCount = tonumber(live.moneyChangeCount or 0) or 0,
        positiveChangeTotal = tonumber(live.positiveChangeTotal or 0) or 0,
        negativeChangeTotal = tonumber(live.negativeChangeTotal or 0) or 0,
        signalCount = tonumber(live.signalCount or 0) or 0,
        correlationCount = tonumber(live.correlationCount or 0) or 0,
        writeFailures = tonumber(live.writeFailures or 0) or 0,
        lastTotal = live.lastTotal,
        lastBank = live.lastBank,
        lastWallet = live.lastWallet,
        lastWallet0 = live.lastWallet0,
        lastWallet1 = live.lastWallet1,
        lastSignal = live.lastSignal,
        lastMoneyChange = live.lastMoneyChange,
        lastCorrelation = live.lastCorrelation,
        transaction = {
            inProgress = hustle_meter.S.liveMoneyTransactionInProgress == true,
            basketActive = hustle_meter.S.liveMoneyBasketActive == true,
            sessionValid = hustle_meter.S.liveMoneySessionValid == true,
            refreshPending = hustle_meter.S.liveMoneyRefreshPending == true,
            startSessionPending = hustle_meter.S.liveMoneyStartSessionPending == true,
            useServerTransactions = hustle_meter.S.liveMoneyUseServerTransactions == true,
            catalogValid = hustle_meter.S.liveMoneyCatalogValid == true,
            catalogCurrent = hustle_meter.S.liveMoneyCatalogCurrent == true
        },
        globals = live.globals,
        recentEvents = live.recentEvents,
        recentCorrelations = live.recentCorrelations,
        heistRisk = {
            level = tostring(live.riskLevel or "LOW"),
            score = tonumber(live.riskScore or 0) or 0,
            reason = tostring(live.riskReason or ""),
            activeScripts = live.activeScripts,
            activeRiskScripts = live.activeRiskScripts,
            highRiskSinceMs = tonumber(live.highRiskSinceMs or 0) or 0,
            riskChangeCount = tonumber(live.riskChangeCount or 0) or 0,
            activitySession = hustle_meter.S.heistRiskActivitySession == true,
            mpCutscene = hustle_meter.S.heistRiskMpCutscene == true,
            networkTransitionStarted = hustle_meter.S.heistRiskNetworkTransitionStarted == true,
            networkTransitionBusy = hustle_meter.S.heistRiskNetworkTransitionBusy == true
        },
        pendingIncident = live.pendingIncident,
        lastIncident = live.lastIncident,
        incidentCount = tonumber(live.incidentCount or 0) or 0,
        markerCount = tonumber(live.markerCount or 0) or 0,
        status = tostring(hustle_meter.S.liveMoneyStatus or ""),
        blockAllIncomingTestMode = hustle_meter.S.hardCapBlockAllIncomingTestMode == true,
        firewall = {
            status = tostring(hustle_meter.S.hardCapFirewallStatus or ""),
            earnObserved = tonumber(hustle_meter.S.hardCapFirewallEarnObserved or 0) or 0,
            serviceObserved = tonumber(hustle_meter.S.hardCapFirewallServiceObserved or 0) or 0,
            globalObserved = tonumber(hustle_meter.S.hardCapFirewallGlobalObserved or 0) or 0,
            blocked = tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0,
            lastPath = tostring(hustle_meter.S.hardCapFirewallLastPath or ""),
            lastNative = tostring(hustle_meter.S.hardCapFirewallLastNative or ""),
            lastAmount = tonumber(hustle_meter.S.hardCapFirewallLastAmount or 0) or 0,
            lastDecision = tostring(hustle_meter.S.hardCapFirewallLastDecision or ""),
            lastPattern = tostring(hustle_meter.S.hardCapFirewallLastPattern or "")
        }
    }

    local ok = hustle_meter.try_write_file(
        hustle_meter.LiveMoneySummaryFile,
        "return " .. hustle_meter.serialize(data, "") .. "\n"
    )
    if ok then live.lastSummaryMs = hustle_meter.now() end
    return ok
end


function hustle_meter.heist_risk_script_category(name)
    local s = tostring(name or ""):lower()
    if s == "" then return nil end

    if s:find("fm_mission_controller", 1, true) then
        return "MISSION_CONTROLLER", 60
    end
    if s:find("finale", 1, true)
        or s:find("heist", 1, true)
        or s:find("gangops", 1, true)
        or s:find("casino_heist", 1, true)
        or s:find("island_heist", 1, true) then
        return "HEIST_SCRIPT", 60
    end
    if s:find("fm_content_", 1, true) then
        return "MISSION_CONTENT", 40
    end
    if s:find("fixer", 1, true)
        or s:find("tuner", 1, true)
        or s:find("salvage", 1, true)
        or s:find("agency", 1, true)
        or s:find("smuggler", 1, true) then
        return "MISSION_FAMILY", 30
    end
    return nil
end

function hustle_meter.heist_risk_scan_active_scripts(nowMs)
    local live = hustle_meter.LiveMoney
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()
    local interval = math.max(100, tonumber(hustle_meter.S.heistRiskScriptScanMs or 250) or 250)
    if nowMs - (tonumber(live.lastScriptScanMs or 0) or 0) < interval then
        return live.activeScripts or {}, live.activeRiskScripts or {}
    end
    live.lastScriptScanMs = nowMs

    local scripts = {}
    local riskScripts = {}
    local ok = pcall(function()
        SCRIPT_THREAD_ITERATOR_RESET()
        local seenIds = {}
        for _ = 1, 512 do
            local threadId = tonumber(SCRIPT_THREAD_ITERATOR_GET_NEXT_THREAD_ID() or 0) or 0
            if threadId <= 0 or seenIds[threadId] then break end
            seenIds[threadId] = true

            local scriptName = GET_NAME_OF_SCRIPT_WITH_THIS_ID(threadId)
            scriptName = tostring(scriptName or "")
            if scriptName ~= "" and scriptName ~= "nil" then
                scripts[#scripts + 1] = scriptName
                local category, score = hustle_meter.heist_risk_script_category(scriptName)
                if category then
                    riskScripts[#riskScripts + 1] = {
                        name = scriptName,
                        category = category,
                        score = score,
                        threadId = threadId
                    }
                end
            end
        end
    end)

    if not ok then
        hustle_meter.live_money_event(
            "SCRIPT_SCAN_ERROR",
            "Could not enumerate active script threads.",
            0,
            "INFO"
        )
        return live.activeScripts or {}, live.activeRiskScripts or {}
    end

    table.sort(scripts)
    table.sort(riskScripts, function(a, b)
        return tostring(a.name or "") < tostring(b.name or "")
    end)

    local signatureParts = {}
    for _, item in ipairs(riskScripts) do
        signatureParts[#signatureParts + 1] =
            tostring(item.name) .. ":" .. tostring(item.category)
    end
    local signature = table.concat(signatureParts, ",")

    if signature ~= tostring(live.lastRiskScriptSignature or "") then
        local oldSignature = tostring(live.lastRiskScriptSignature or "")
        live.lastRiskScriptSignature = signature

        local detail = "from={" .. oldSignature .. "} to={" .. signature .. "}"
        hustle_meter.append_live_money_line(
            hustle_meter.HeistRiskLogFile,
            ("%s | ms=%s | ACTIVE_RISK_SCRIPTS_CHANGED | %s")
                :format(os.date("%Y-%m-%d %H:%M:%S"), tostring(nowMs), detail)
        )
        hustle_meter.live_money_event(
            "ACTIVE_RISK_SCRIPTS_CHANGED",
            detail,
            0,
            #riskScripts > 0 and "HIGH" or "INFO"
        )
    end

    live.activeScripts = scripts
    live.activeRiskScripts = riskScripts

    local display = {}
    for _, item in ipairs(riskScripts) do
        display[#display + 1] =
            tostring(item.name) .. " [" .. tostring(item.category) .. "]"
    end
    hustle_meter.S.heistRiskActiveScripts =
        #display > 0 and table.concat(display, ", ") or "None"

    return scripts, riskScripts
end

function hustle_meter.heist_risk_level_for_score(score)
    score = tonumber(score or 0) or 0
    if score >= 90 then return "CRITICAL" end
    if score >= 60 then return "HIGH" end
    if score >= 30 then return "ELEVATED" end
    return "LOW"
end

function hustle_meter.heist_risk_update(nowMs, tx, flags)
    if hustle_meter.S.heistRiskScannerEnabled ~= true then return "OFF", 0, "Risk scanner disabled." end

    local live = hustle_meter.LiveMoney
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()
    tx = type(tx) == "table" and tx or {}
    flags = type(flags) == "table" and flags or {}

    local _, riskScripts = hustle_meter.heist_risk_scan_active_scripts(nowMs)

    local function b(fn)
        local ok, value = pcall(fn)
        return ok and value == true or false
    end

    local activitySession = b(NETWORK_IS_ACTIVITY_SESSION)
    local mpCutscene = b(NETWORK_IS_IN_MP_CUTSCENE)
    local networkTransitionStarted = b(NETWORK_IS_TRANSITION_STARTED)
    local networkTransitionBusy = b(NETWORK_IS_TRANSITION_BUSY)

    hustle_meter.S.heistRiskActivitySession = activitySession
    hustle_meter.S.heistRiskMpCutscene = mpCutscene
    hustle_meter.S.heistRiskNetworkTransitionStarted = networkTransitionStarted
    hustle_meter.S.heistRiskNetworkTransitionBusy = networkTransitionBusy

    local score = 0
    local reasons = {}

    local bestScriptScore = 0
    for _, item in ipairs(riskScripts or {}) do
        bestScriptScore = math.max(bestScriptScore, tonumber(item.score or 0) or 0)
    end
    if bestScriptScore > 0 then
        score = score + bestScriptScore
        reasons[#reasons + 1] = "risk-script"
    end

    if activitySession then score = score + 25; reasons[#reasons + 1] = "activity-session" end
    if mpCutscene then score = score + 15; reasons[#reasons + 1] = "mp-cutscene" end
    if networkTransitionStarted or networkTransitionBusy then
        score = score + 20
        reasons[#reasons + 1] = "network-transition"
    end
    if tx.transactionInProgress then
        score = score + 35
        reasons[#reasons + 1] = "money-transaction-in-progress"
    end
    if tx.basketActive then
        score = score + 20
        reasons[#reasons + 1] = "transaction-basket-active"
    end
    if flags.loading == true or flags.playerSwitch == true
        or flags.fadedOut == true or flags.fadingOut == true or flags.fadingIn == true then
        score = score + 10
        reasons[#reasons + 1] = "loading/fade/transition"
    end

    local signal = live.lastSignal
    if type(signal) == "table" then
        local age = nowMs - (tonumber(signal.ms or nowMs) or nowMs)
        if age >= 0 and age <= 5000 then
            score = score + 15
            reasons[#reasons + 1] = "recent-pre-money-signal"
        end
    end

    local level = hustle_meter.heist_risk_level_for_score(score)
    local reason = #reasons > 0 and table.concat(reasons, " + ") or "No mission/heist indicators."

    if tostring(live.riskLevel or "LOW") ~= level
        or tonumber(live.riskScore or 0) ~= score
        or tostring(live.riskReason or "") ~= reason then

        local previousLevel = tostring(live.riskLevel or "LOW")
        local previousScore = tonumber(live.riskScore or 0) or 0

        if previousLevel ~= level then
            live.riskChangeCount = (tonumber(live.riskChangeCount or 0) or 0) + 1
            live.riskSinceMs = nowMs
            if level == "HIGH" or level == "CRITICAL" then
                if (tonumber(live.highRiskSinceMs or 0) or 0) <= 0 then
                    live.highRiskSinceMs = nowMs
                end
            elseif previousLevel == "HIGH" or previousLevel == "CRITICAL" then
                live.highRiskSinceMs = 0
            end

            hustle_meter.append_live_money_line(
                hustle_meter.HeistRiskLogFile,
                ("%s | ms=%s | RISK_LEVEL_CHANGE | from=%s/%s to=%s/%s | reason=%s | scripts=%s")
                    :format(
                        os.date("%Y-%m-%d %H:%M:%S"),
                        tostring(nowMs),
                        previousLevel, tostring(previousScore),
                        level, tostring(score),
                        hustle_meter.live_money_safe(reason),
                        hustle_meter.live_money_safe(hustle_meter.S.heistRiskActiveScripts)
                    )
            )

            hustle_meter.live_money_event(
                "HEIST_RISK_LEVEL:" .. level,
                "score=" .. tostring(score) .. " reason=" .. reason
                    .. " scripts=" .. tostring(hustle_meter.S.heistRiskActiveScripts),
                0,
                level
            )
        end

        live.riskLevel = level
        live.riskScore = score
        live.riskReason = reason
    end

    hustle_meter.S.heistRiskLevel = level
    hustle_meter.S.heistRiskScore = score
    hustle_meter.S.heistRiskStatus = reason
    hustle_meter.S.heistRiskHighSinceMs = tonumber(live.highRiskSinceMs or 0) or 0
    hustle_meter.S.heistRiskHighForMs =
        (tonumber(live.highRiskSinceMs or 0) or 0) > 0
        and math.max(0, nowMs - live.highRiskSinceMs) or 0

    live.lastActivitySession = activitySession
    live.lastMpCutscene = mpCutscene
    live.lastNetworkTransitionStarted = networkTransitionStarted
    live.lastNetworkTransitionBusy = networkTransitionBusy

    return level, score, reason
end

function hustle_meter.heist_timeline_push(nowMs, total, bank, wallet0, wallet1, tx, flags)
    local live = hustle_meter.LiveMoney
    local interval = math.max(50, tonumber(hustle_meter.S.heistRiskTimelineMs or 100) or 100)
    if nowMs - (tonumber(live.lastTimelineMs or 0) or 0) < interval then return end
    live.lastTimelineMs = nowMs

    live.timeline = type(live.timeline) == "table" and live.timeline or {}
    live.timeline[#live.timeline + 1] = {
        t = os.time(),
        ms = nowMs,
        total = tonumber(total or 0) or 0,
        bank = tonumber(bank or 0) or 0,
        wallet0 = tonumber(wallet0 or 0) or 0,
        wallet1 = tonumber(wallet1 or 0) or 0,
        txInProgress = tx.transactionInProgress == true,
        basketActive = tx.basketActive == true,
        shopSessionValid = tx.sessionValid == true,
        activitySession = hustle_meter.S.heistRiskActivitySession == true,
        mpCutscene = hustle_meter.S.heistRiskMpCutscene == true,
        networkTransitionStarted = hustle_meter.S.heistRiskNetworkTransitionStarted == true,
        networkTransitionBusy = hustle_meter.S.heistRiskNetworkTransitionBusy == true,
        loading = flags.loading == true,
        playerSwitch = flags.playerSwitch == true,
        sessionStarted = flags.started == true,
        riskLevel = tostring(live.riskLevel or "LOW"),
        riskScore = tonumber(live.riskScore or 0) or 0,
        riskReason = tostring(live.riskReason or ""),
        riskScripts = tostring(hustle_meter.S.heistRiskActiveScripts or "None"),
        lastSignalKind = type(live.lastSignal) == "table" and tostring(live.lastSignal.kind or "") or "",
        lastSignalPath = type(live.lastSignal) == "table" and tostring(live.lastSignal.path or "") or "",
        lastSignalAmount = type(live.lastSignal) == "table" and tonumber(live.lastSignal.amount or 0) or 0,
        firewallPath = tostring(hustle_meter.S.hardCapFirewallLastPath or ""),
        firewallNative = tostring(hustle_meter.S.hardCapFirewallLastNative or ""),
        globalState = tonumber(live.globals and live.globals[4516758] or 0) or 0,
        globalAmount = tonumber(live.globals and live.globals[4516760] or 0) or 0,
        globalServiceHash = tonumber(live.globals and live.globals[4516761] or 0) or 0
    }

    local keepAfter = nowMs - math.max(
        60000,
        (tonumber(hustle_meter.S.heistRiskPreIncidentMs or 30000) or 30000)
            + (tonumber(hustle_meter.S.heistRiskPostIncidentMs or 15000) or 15000)
            + 15000
    )
    while #live.timeline > 1
        and tonumber(live.timeline[1].ms or 0) < keepAfter do
        table.remove(live.timeline, 1)
    end
end

function hustle_meter.heist_incident_begin(delta, nowMs, total, bank, wallet0, wallet1)
    local live = hustle_meter.LiveMoney
    local preMs = math.max(5000, tonumber(hustle_meter.S.heistRiskPreIncidentMs or 30000) or 30000)
    local pre = {}
    for _, item in ipairs(live.timeline or {}) do
        local age = nowMs - (tonumber(item.ms or nowMs) or nowMs)
        if age >= 0 and age <= preMs then
            pre[#pre + 1] = item
        end
    end

    live.incidentCount = (tonumber(live.incidentCount or 0) or 0) + 1
    live.pendingIncident = {
        incidentId = tostring(os.date("%Y%m%d_%H%M%S")) .. "_" .. tostring(live.incidentCount),
        startedAt = os.time(),
        payoutMs = nowMs,
        payoutDelta = math.floor(tonumber(delta or 0) or 0),
        payoutTotal = tonumber(total or 0) or 0,
        payoutBank = tonumber(bank or 0) or 0,
        payoutWallet0 = tonumber(wallet0 or 0) or 0,
        payoutWallet1 = tonumber(wallet1 or 0) or 0,
        riskLevelAtPayout = tostring(live.riskLevel or "LOW"),
        riskScoreAtPayout = tonumber(live.riskScore or 0) or 0,
        riskReasonAtPayout = tostring(live.riskReason or ""),
        riskScriptsAtPayout = tostring(hustle_meter.S.heistRiskActiveScripts or "None"),
        lastSignalAtPayout = live.lastSignal,
        lastCorrelationAtPayout = live.lastCorrelation,
        firewall = {
            lastPath = tostring(hustle_meter.S.hardCapFirewallLastPath or ""),
            lastNative = tostring(hustle_meter.S.hardCapFirewallLastNative or ""),
            lastAmount = tonumber(hustle_meter.S.hardCapFirewallLastAmount or 0) or 0,
            lastDecision = tostring(hustle_meter.S.hardCapFirewallLastDecision or ""),
            lastPattern = tostring(hustle_meter.S.hardCapFirewallLastPattern or "")
        },
        globalsAtPayout = live.globals,
        preTimeline = pre,
        postTimeline = {},
        finalizeAfterMs = nowMs + math.max(
            5000,
            tonumber(hustle_meter.S.heistRiskPostIncidentMs or 15000) or 15000
        )
    }

    hustle_meter.S.heistRiskIncidentCount = live.incidentCount
    hustle_meter.S.heistRiskLastIncident =
        ("Incident #%d: %s at risk=%s/%s")
            :format(
                live.incidentCount,
                hustle_meter.format_money(delta, true),
                tostring(live.riskLevel or "LOW"),
                tostring(live.riskScore or 0)
            )

    hustle_meter.append_live_money_line(
        hustle_meter.PayoutIncidentLogFile,
        ("%s | ms=%s | INCIDENT_STARTED | id=%s delta=%s total=%s risk=%s/%s reason=%s scripts=%s")
            :format(
                os.date("%Y-%m-%d %H:%M:%S"),
                tostring(nowMs),
                tostring(live.pendingIncident.incidentId),
                tostring(delta),
                tostring(total),
                tostring(live.riskLevel),
                tostring(live.riskScore),
                hustle_meter.live_money_safe(live.riskReason),
                hustle_meter.live_money_safe(hustle_meter.S.heistRiskActiveScripts)
            )
    )
end

function hustle_meter.heist_incident_maintain(nowMs)
    local live = hustle_meter.LiveMoney
    local incident = live.pendingIncident
    if type(incident) ~= "table" then return end

    local timeline = live.timeline or {}
    local last = timeline[#timeline]
    if type(last) == "table"
        and tonumber(last.ms or 0) > tonumber(incident.payoutMs or 0) then
        local post = incident.postTimeline or {}
        local previous = post[#post]
        if not previous or tonumber(previous.ms or 0) ~= tonumber(last.ms or 0) then
            post[#post + 1] = last
            incident.postTimeline = post
        end
    end

    if nowMs < tonumber(incident.finalizeAfterMs or math.huge) then return end

    incident.finalizedAt = os.time()
    incident.finalizedMs = nowMs
    incident.finalRiskLevel = tostring(live.riskLevel or "LOW")
    incident.finalRiskScore = tonumber(live.riskScore or 0) or 0
    incident.finalRiskReason = tostring(live.riskReason or "")
    incident.finalActiveRiskScripts = tostring(hustle_meter.S.heistRiskActiveScripts or "None")
    incident.finalBalance = {
        total = live.lastTotal,
        bank = live.lastBank,
        wallet0 = live.lastWallet0,
        wallet1 = live.lastWallet1
    }

    hustle_meter.try_write_file(
        hustle_meter.PayoutIncidentLatestFile,
        "return " .. hustle_meter.serialize(incident, "") .. "\n"
    )

    hustle_meter.append_live_money_line(
        hustle_meter.PayoutIncidentLogFile,
        ("%s | ms=%s | INCIDENT_FINALIZED | id=%s delta=%s preSnapshots=%s postSnapshots=%s riskAtPayout=%s/%s")
            :format(
                os.date("%Y-%m-%d %H:%M:%S"),
                tostring(nowMs),
                tostring(incident.incidentId),
                tostring(incident.payoutDelta),
                tostring(#(incident.preTimeline or {})),
                tostring(#(incident.postTimeline or {})),
                tostring(incident.riskLevelAtPayout),
                tostring(incident.riskScoreAtPayout)
            )
    )

    live.lastIncident = incident
    live.pendingIncident = nil
end

function hustle_meter.schedule_heist_marker(label)
    hustle_meter.PendingHeistMarker = tostring(label or "USER_MARKER")
    hustle_meter.S.heistRiskLastMarker = "Queued: " .. tostring(label or "USER_MARKER")
end

function hustle_meter.process_pending_heist_marker()
    local label = hustle_meter.PendingHeistMarker
    if not label then return end
    hustle_meter.PendingHeistMarker = nil

    local live = hustle_meter.LiveMoney
    local nowMs = hustle_meter.now()
    live.markerCount = (tonumber(live.markerCount or 0) or 0) + 1

    local detail =
        ("marker=%s number=%s total=%s risk=%s/%s reason=%s scripts=%s tx=%s basket=%s")
            :format(
                tostring(label),
                tostring(live.markerCount),
                tostring(live.lastTotal or hustle_meter.S.liveMoneyRawTotal or 0),
                tostring(live.riskLevel or "LOW"),
                tostring(live.riskScore or 0),
                tostring(live.riskReason or ""),
                tostring(hustle_meter.S.heistRiskActiveScripts or "None"),
                tostring(hustle_meter.S.liveMoneyTransactionInProgress == true),
                tostring(hustle_meter.S.liveMoneyBasketActive == true)
            )

    live.lastMarkerMs = nowMs
    live.lastMarkerLabel = tostring(label)
    hustle_meter.S.heistRiskLastMarker =
        tostring(label) .. " @ " .. os.date("%H:%M:%S")

    hustle_meter.append_live_money_line(
        hustle_meter.HeistMarkerLogFile,
        ("%s | ms=%s | %s")
            :format(os.date("%Y-%m-%d %H:%M:%S"), tostring(nowMs), hustle_meter.live_money_safe(detail))
    )

    hustle_meter.live_money_event(
        "USER_MARKER:" .. tostring(label),
        detail,
        0,
        "USER"
    )

    -- A marker should force a deep window because it is likely near useful activity.
    local untilMs = nowMs + 60000
    live.manualHotUntilMs = math.max(tonumber(live.manualHotUntilMs or 0) or 0, untilMs)
    hustle_meter.S.liveMoneyManualHotUntilMs = live.manualHotUntilMs
    hustle_meter.toast("Heist diagnostic marker saved: " .. tostring(label), 4000)
end



function hustle_meter.netshop_read_int_pointer_native(nativeFn)
    if not Memory or not Memory.AllocInt or not Memory.ReadInt or not Memory.Free then
        return false, -999999, "Memory API unavailable"
    end

    local ptr = nil
    local ok, called, value = pcall(function()
        ptr = Memory.AllocInt()
        if not ptr or ptr == 0 then error("AllocInt failed") end
        pcall(Memory.WriteInt, ptr, -999999)
        called = nativeFn(ptr)
        value = Memory.ReadInt(ptr)
    end)

    if ptr and ptr ~= 0 then pcall(Memory.Free, ptr) end
    if not ok then return false, -999999, tostring(called or value or "pointer call failed") end
    return called == true, tonumber(value or -999999) or -999999, nil
end

function hustle_meter.netshop_get_state_and_status()
    if not Memory or not Memory.AllocInt or not Memory.ReadInt or not Memory.Free then
        return {
            callOk = false,
            state = -999999,
            status = false,
            error = "Memory API unavailable"
        }
    end

    local statePtr, statusPtr = nil, nil
    local callResult, stateValue, statusValue = false, -999999, false
    local ok, err = pcall(function()
        statePtr = Memory.AllocInt()
        statusPtr = Memory.AllocInt()
        if not statePtr or statePtr == 0 or not statusPtr or statusPtr == 0 then
            error("AllocInt failed")
        end
        pcall(Memory.WriteInt, statePtr, -999999)
        pcall(Memory.WriteInt, statusPtr, 0)
        callResult = NET_GAMESERVER_GET_SESSION_STATE_AND_STATUS(statePtr, statusPtr) == true
        stateValue = tonumber(Memory.ReadInt(statePtr) or -999999) or -999999
        statusValue = (tonumber(Memory.ReadInt(statusPtr) or 0) or 0) ~= 0
    end)

    if statePtr and statePtr ~= 0 then pcall(Memory.Free, statePtr) end
    if statusPtr and statusPtr ~= 0 then pcall(Memory.Free, statusPtr) end

    return {
        callOk = ok and callResult == true,
        state = stateValue,
        status = statusValue,
        error = ok and nil or tostring(err)
    }
end

function hustle_meter.netshop_deep_state()
    local basic = hustle_meter.live_money_read_tx_state()
    local manager = hustle_meter.netshop_get_state_and_status()
    local startCallOk, startStatus, startErr =
        hustle_meter.netshop_read_int_pointer_native(NET_GAMESERVER_RETRIEVE_START_SESSION_STATUS)
    local errorCallOk, errorCode, errorErr =
        hustle_meter.netshop_read_int_pointer_native(NET_GAMESERVER_RETRIEVE_SESSION_ERROR_CODE)

    local out = {
        txInProgress = basic.transactionInProgress == true,
        basketActive = basic.basketActive == true,
        sessionValid = basic.sessionValid == true,
        refreshPending = basic.refreshPending == true,
        startSessionPending = basic.startSessionPending == true,
        useServerTransactions = basic.useServerTransactions == true,
        catalogValid = basic.catalogValid == true,
        catalogCurrent = basic.catalogCurrent == true,

        managerCallOk = manager.callOk == true,
        sessionState = tonumber(manager.state or -999999) or -999999,
        sessionStatus = manager.status == true,
        managerError = manager.error,

        startStatusCallOk = startCallOk == true,
        startStatus = tonumber(startStatus or -999999) or -999999,
        startStatusError = startErr,

        sessionErrorCallOk = errorCallOk == true,
        sessionErrorCode = tonumber(errorCode or -999999) or -999999,
        sessionErrorReadError = errorErr
    }

    hustle_meter.S.preTransactionHoldLastSessionState = out.sessionState
    hustle_meter.S.preTransactionHoldLastSessionStatus = out.sessionStatus
    hustle_meter.S.preTransactionHoldLastStartStatus = out.startStatus
    hustle_meter.S.preTransactionHoldLastErrorCode = out.sessionErrorCode
    return out
end

function hustle_meter.pretransaction_hold_log(kind, detail)
    hustle_meter.ensure_debug_dir()
    local f = io.open(tostring(hustle_meter.PreTransactionHoldLogFile or ""), "a")
    if not f then return false end
    f:write(("%s | ms=%s | %s | %s\n"):format(
        os.date("%Y-%m-%d %H:%M:%S"),
        tostring(hustle_meter.now()),
        hustle_meter.live_money_safe(kind),
        hustle_meter.live_money_safe(detail)
    ))
    f:close()
    return true
end

function hustle_meter.pretransaction_hold_should_start(nowMs, tx, flags)
    if hustle_meter.S.preTransactionHoldEnabled ~= true then return false, "disabled" end
    if hustle_meter.S.hardCapBlockAllIncomingTestMode ~= true
        and not (
            hustle_meter.S.hardCapGuardEnabled == true
            and hustle_meter.get_hard_cap_state(0).atOrOver == true
        ) then
        return false, "blocking-policy-not-active"
    end

    local live = hustle_meter.LiveMoney
    if live.preHoldBusy == true then return false, "already-busy" end
    if nowMs < (tonumber(live.preHoldCooldownUntilMs or 0) or 0) then
        return false, "cooldown"
    end
    if tx.transactionInProgress == true then
        return false, "transaction-already-started"
    end

    local hasRiskScript = hustle_meter.predictive_guard_has_risk_script()
    local activity = hustle_meter.S.heistRiskActivitySession == true
    local transitionCue = hustle_meter.predictive_guard_transition_cue(flags)
    local markerRecent, markerAge, markerLabel =
        hustle_meter.predictive_guard_recent_payout_marker(nowMs)

    local markerOk =
        hustle_meter.S.preTransactionHoldRequirePayoutMarker ~= true
        or markerRecent

    local qualifies =
        hasRiskScript
        and activity
        and transitionCue
        and markerOk

    local detail = table.concat({
        "riskScript=" .. tostring(hasRiskScript),
        "activity=" .. tostring(activity),
        "transitionCue=" .. tostring(transitionCue),
        "markerRequired=" .. tostring(hustle_meter.S.preTransactionHoldRequirePayoutMarker == true),
        "markerRecent=" .. tostring(markerRecent),
        "markerAgeMs=" .. tostring(markerAge),
        "markerLabel=" .. tostring(markerLabel),
        "risk=" .. tostring(live.riskLevel or "LOW") .. "/" .. tostring(live.riskScore or 0)
    }, " | ")

    return qualifies, detail
end

function hustle_meter.pretransaction_hold_snapshot(label, attempt)
    local total, bank, wallet, _, meta = hustle_meter.read_money_balance()
    local wallet0 = type(meta) == "table" and tonumber(meta.wallet0 or 0) or 0
    local wallet1 = type(meta) == "table" and tonumber(meta.wallet1 or 0) or 0
    local deep = hustle_meter.netshop_deep_state()

    return {
        label = tostring(label or ""),
        t = os.time(),
        ms = hustle_meter.now(),
        elapsedMs = type(attempt) == "table"
            and math.max(0, hustle_meter.now() - (tonumber(attempt.startedMs or hustle_meter.now()) or hustle_meter.now()))
            or 0,
        total = tonumber(total or 0) or 0,
        bank = tonumber(bank or 0) or 0,
        wallet = tonumber(wallet or 0) or 0,
        wallet0 = wallet0,
        wallet1 = wallet1,
        deep = deep,
        riskLevel = tostring(hustle_meter.LiveMoney.riskLevel or "LOW"),
        riskScore = tonumber(hustle_meter.LiveMoney.riskScore or 0) or 0,
        riskReason = tostring(hustle_meter.LiveMoney.riskReason or ""),
        riskScripts = tostring(hustle_meter.S.heistRiskActiveScripts or "None")
    }
end

function hustle_meter.pretransaction_hold_write_latest(attempt)
    return hustle_meter.try_write_file(
        hustle_meter.PreTransactionHoldLatestFile,
        "return " .. hustle_meter.serialize(attempt, "") .. "\n"
    )
end

function hustle_meter.pretransaction_hold_worker(attempt)
    local live = hustle_meter.LiveMoney
    live.preHoldBusy = true
    hustle_meter.S.preTransactionHoldBusy = true

    local durationMs = math.max(500, tonumber(hustle_meter.S.preTransactionHoldDurationMs or 4000) or 4000)
    local intervalMs = math.max(10, math.min(250, tonumber(hustle_meter.S.preTransactionHoldIntervalMs or 25) or 25))
    local postWatchMs = math.max(1000, tonumber(hustle_meter.S.preTransactionHoldPostWatchMs or 5000) or 5000)
    local holdEndMs = attempt.startedMs + durationMs
    local baselineTotal = tonumber(attempt.before.total or 0) or 0
    local charSlot = tonumber(hustle_meter.S.characterSlot or 0) or 0

    attempt.holdDurationMs = durationMs
    attempt.intervalMs = intervalMs
    attempt.postWatchMs = postWatchMs
    attempt.calls = {}
    attempt.samples = {}
    attempt.txRisingDuringHold = false
    attempt.moneyLandedDuringHold = false

    local iteration = 0
    while hustle_meter.now() < holdEndMs do
        iteration = iteration + 1
        local before = hustle_meter.pretransaction_hold_snapshot("hold-before-" .. tostring(iteration), attempt)

        if before.deep.txInProgress then attempt.txRisingDuringHold = true end
        if before.total > baselineTotal then
            attempt.moneyLandedDuringHold = true
            break
        end

        local callMs = hustle_meter.now()
        local ok, value = pcall(NET_GAMESERVER_CLEAR_SESSION, charSlot)
        local call = {
            ms = callMs,
            elapsedMs = callMs - attempt.startedMs,
            pcallOk = ok,
            returnValue = ok and value or nil,
            error = ok and nil or tostring(value),
            before = before.deep
        }
        attempt.calls[#attempt.calls + 1] = call
        hustle_meter.S.preTransactionHoldLastClearReturn =
            ok and tostring(value) or ("ERROR: " .. tostring(value))

        -- Keep detailed per-call logging compact but complete.
        hustle_meter.pretransaction_hold_log(
            "HOLD_CLEAR",
            "attempt=" .. tostring(attempt.attemptId)
                .. " n=" .. tostring(iteration)
                .. " elapsed=" .. tostring(call.elapsedMs)
                .. " return=" .. tostring(call.returnValue)
                .. " total=" .. tostring(before.total)
                .. " tx=" .. tostring(before.deep.txInProgress)
                .. " valid=" .. tostring(before.deep.sessionValid)
                .. " startPending=" .. tostring(before.deep.startSessionPending)
                .. " mgrState=" .. tostring(before.deep.sessionState)
                .. " mgrStatus=" .. tostring(before.deep.sessionStatus)
                .. " startStatus=" .. tostring(before.deep.startStatus)
                .. " errCode=" .. tostring(before.deep.sessionErrorCode)
        )

        -- Keep a sampled timeline every ~100ms plus any meaningful state edge.
        if iteration == 1
            or before.deep.txInProgress
            or before.deep.startSessionPending
            or before.deep.sessionValid
            or (iteration % math.max(1, math.floor(100 / intervalMs)) == 0) then
            attempt.samples[#attempt.samples + 1] = before
        end

        if Script and Script.Yield then Script.Yield(intervalMs) end
    end

    attempt.holdEndedMs = hustle_meter.now()
    attempt.holdEndSnapshot = hustle_meter.pretransaction_hold_snapshot("hold-end", attempt)

    hustle_meter.pretransaction_hold_log(
        "HOLD_END",
        "attempt=" .. tostring(attempt.attemptId)
            .. " calls=" .. tostring(#attempt.calls)
            .. " txRising=" .. tostring(attempt.txRisingDuringHold)
            .. " total=" .. tostring(attempt.holdEndSnapshot.total)
            .. " delta=" .. tostring(attempt.holdEndSnapshot.total - baselineTotal)
    )

    -- Post-watch without additional clear calls so delayed payouts are not mistaken
    -- for success.
    local postEndMs = hustle_meter.now() + postWatchMs
    attempt.postWatch = {}
    local lastSampleMs = 0
    while hustle_meter.now() < postEndMs do
        local snap = hustle_meter.pretransaction_hold_snapshot("post-watch", attempt)
        if snap.total > baselineTotal then
            attempt.postWatch[#attempt.postWatch + 1] = snap
            break
        end

        if snap.ms - lastSampleMs >= 250 then
            attempt.postWatch[#attempt.postWatch + 1] = snap
            lastSampleMs = snap.ms
        end
        if Script and Script.Yield then Script.Yield(25) end
    end

    local final = hustle_meter.pretransaction_hold_snapshot("final", attempt)
    attempt.final = final
    attempt.completedAt = os.time()
    attempt.completedMs = hustle_meter.now()
    local delta = final.total - baselineTotal

    if delta > 0 then
        attempt.outcome = "FAILED: payout landed +" .. tostring(math.floor(delta))
    elseif attempt.txRisingDuringHold == false then
        attempt.outcome = "CANDIDATE SUCCESS: payout transaction never rose during 4s hold and no GTA$ arrived during 5s post-watch"
    else
        attempt.outcome = "CANDIDATE SUCCESS: transaction rose but no positive GTA$ arrived during hold + post-watch"
    end

    live.preHoldBusy = false
    live.preHoldLastAttempt = attempt
    live.preHoldCooldownUntilMs =
        hustle_meter.now() + math.max(1000, tonumber(hustle_meter.S.preTransactionHoldCooldownMs or 15000) or 15000)

    hustle_meter.S.preTransactionHoldBusy = false
    hustle_meter.S.preTransactionHoldLastOutcome = tostring(attempt.outcome)
    hustle_meter.S.preTransactionHoldStatus = tostring(attempt.outcome)

    hustle_meter.pretransaction_hold_log(
        "ATTEMPT_FINAL",
        "attempt=" .. tostring(attempt.attemptId)
            .. " outcome=" .. tostring(attempt.outcome)
            .. " baseline=" .. tostring(baselineTotal)
            .. " final=" .. tostring(final.total)
            .. " delta=" .. tostring(delta)
            .. " calls=" .. tostring(#attempt.calls)
    )
    hustle_meter.pretransaction_hold_write_latest(attempt)
end

function hustle_meter.pretransaction_hold_start(nowMs, detail)
    local live = hustle_meter.LiveMoney
    if live.preHoldBusy == true then return false end

    live.preHoldAttemptCount = (tonumber(live.preHoldAttemptCount or 0) or 0) + 1
    live.preHoldLastStartMs = nowMs

    local before = hustle_meter.pretransaction_hold_snapshot("before-hold", nil)
    local attempt = {
        attemptId = tostring(os.date("%Y%m%d_%H%M%S")) .. "_" .. tostring(live.preHoldAttemptCount),
        startedAt = os.time(),
        startedMs = nowMs,
        triggerDetail = tostring(detail or ""),
        markerLabel = tostring(live.lastMarkerLabel or ""),
        markerAgeMs = math.max(0, nowMs - (tonumber(live.lastMarkerMs or nowMs) or nowMs)),
        before = before
    }

    hustle_meter.S.preTransactionHoldAttempts = live.preHoldAttemptCount
    hustle_meter.S.preTransactionHoldLastAttempt =
        "Attempt " .. tostring(live.preHoldAttemptCount) .. " @ " .. os.date("%H:%M:%S")
    hustle_meter.S.preTransactionHoldStatus =
        "PRE-TRANSACTION HOLD ACTIVE: keeping player-balance session cleared."
    hustle_meter.S.preTransactionHoldBusy = true

    hustle_meter.pretransaction_hold_log(
        "ATTEMPT_START",
        "attempt=" .. tostring(attempt.attemptId)
            .. " baseline=" .. tostring(before.total)
            .. " marker=" .. tostring(attempt.markerLabel)
            .. " markerAgeMs=" .. tostring(attempt.markerAgeMs)
            .. " detail=" .. tostring(detail)
    )
    hustle_meter.toast(
        "Pre-Transaction Session Hold ACTIVE for 4 seconds.",
        5000
    )

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            local ok, err = pcall(hustle_meter.pretransaction_hold_worker, attempt)
            if not ok then
                live.preHoldBusy = false
                hustle_meter.S.preTransactionHoldBusy = false
                hustle_meter.S.preTransactionHoldLastOutcome = "Worker error: " .. tostring(err)
                hustle_meter.S.preTransactionHoldStatus = "Worker error: " .. tostring(err)
                hustle_meter.pretransaction_hold_log(
                    "WORKER_ERROR",
                    "attempt=" .. tostring(attempt.attemptId) .. " error=" .. tostring(err)
                )
            end
        end)
    else
        hustle_meter.pretransaction_hold_worker(attempt)
    end

    return true
end

function hustle_meter.pretransaction_hold_tick(nowMs, tx, flags)
    if hustle_meter.S.preTransactionHoldEnabled ~= true then return end
    local qualifies, detail = hustle_meter.pretransaction_hold_should_start(nowMs, tx, flags)
    if qualifies then
        hustle_meter.pretransaction_hold_start(nowMs, detail)
    end
end

function hustle_meter.predictive_guard_method_name(index)
    local list = hustle_meter.PredictiveGuard and hustle_meter.PredictiveGuard.MethodNames or {}
    index = math.floor(tonumber(index or hustle_meter.S.predictiveHeistGuardMethodIndex or 0) or 0)
    if index < 0 or index >= #list then index = 0 end
    return tostring(list[index + 1] or "Observe Only"), index
end

function hustle_meter.predictive_guard_trigger_name(index)
    local list = hustle_meter.PredictiveGuard and hustle_meter.PredictiveGuard.TriggerNames or {}
    index = math.floor(tonumber(index or hustle_meter.S.predictiveHeistGuardTriggerIndex or 0) or 0)
    if index < 0 or index >= #list then index = 0 end
    return tostring(list[index + 1] or "Qualified Transaction Rising Edge"), index
end

function hustle_meter.predictive_guard_log(kind, detail)
    hustle_meter.ensure_debug_dir()
    local f = io.open(tostring(hustle_meter.PredictiveGuardLogFile or ""), "a")
    if not f then return false end
    f:write(("%s | ms=%s | %s | %s\n"):format(
        os.date("%Y-%m-%d %H:%M:%S"),
        tostring(hustle_meter.now()),
        hustle_meter.live_money_safe(kind),
        hustle_meter.live_money_safe(detail)
    ))
    f:close()
    return true
end

function hustle_meter.predictive_guard_has_risk_script()
    local live = hustle_meter.LiveMoney
    return type(live.activeRiskScripts) == "table" and #live.activeRiskScripts > 0
end

function hustle_meter.predictive_guard_transition_cue(flags)
    flags = type(flags) == "table" and flags or {}
    return flags.loading == true
        or flags.playerSwitch == true
        or flags.fadedOut == true
        or flags.fadingOut == true
        or flags.fadingIn == true
        or hustle_meter.S.heistRiskMpCutscene == true
        or hustle_meter.S.heistRiskNetworkTransitionStarted == true
        or hustle_meter.S.heistRiskNetworkTransitionBusy == true
end

function hustle_meter.predictive_guard_recent_payout_marker(nowMs)
    local live = hustle_meter.LiveMoney
    local markerMs = tonumber(live.lastMarkerMs or 0) or 0
    if markerMs <= 0 then return false, math.huge, "" end
    local age = math.max(0, (tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()) - markerMs)
    local window = math.max(1000, tonumber(hustle_meter.S.predictiveHeistGuardMarkerWindowMs or 60000) or 60000)
    local label = tostring(live.lastMarkerLabel or "")
    return label == "PAYOUT_TRIGGER_NOW" and age <= window, age, label
end

function hustle_meter.predictive_guard_candidate(nowMs, tx, flags)
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()
    tx = type(tx) == "table" and tx or {}
    flags = type(flags) == "table" and flags or {}

    local live = hustle_meter.LiveMoney
    local riskLevel = tostring(live.riskLevel or "LOW")
    local riskScore = tonumber(live.riskScore or 0) or 0
    local riskReason = tostring(live.riskReason or "")
    local hasRiskScript = hustle_meter.predictive_guard_has_risk_script()
    local activity = hustle_meter.S.heistRiskActivitySession == true
    local transitionCue = hustle_meter.predictive_guard_transition_cue(flags)
    local markerRecent, markerAge, markerLabel = hustle_meter.predictive_guard_recent_payout_marker(nowMs)
    local triggerName, triggerIndex = hustle_meter.predictive_guard_trigger_name()

    -- Build 036 key fix:
    -- "CRITICAL" is not itself an independent payout cue because the
    -- transaction-in-progress state contributes to the risk score. Build 034
    -- observed a harmless in-heist transaction pulse that reached CRITICAL/120.
    -- Require a separate payout clue: finale/loading/fade/cutscene/transition OR
    -- the recent PAYOUT_TRIGGER_NOW user marker.
    local independentPayoutCue = transitionCue or markerRecent

    local missionContextOk =
        hustle_meter.S.predictiveHeistGuardRequireMissionContext ~= true
        or (hasRiskScript and activity)

    local qualifies = false
    if triggerIndex == 0 then
        qualifies =
            tx.transactionInProgress == true
            and missionContextOk
            and independentPayoutCue
    elseif triggerIndex == 1 then
        qualifies =
            tx.transactionInProgress == true
            and missionContextOk
            and transitionCue
    else
        qualifies =
            tx.transactionInProgress == true
            and missionContextOk
            and markerRecent
    end

    local reasons = {
        "tx=" .. tostring(tx.transactionInProgress == true),
        "riskScript=" .. tostring(hasRiskScript),
        "activity=" .. tostring(activity),
        "transitionCue=" .. tostring(transitionCue),
        "recentPayoutMarker=" .. tostring(markerRecent),
        "markerAgeMs=" .. tostring(markerAge),
        "risk=" .. riskLevel .. "/" .. tostring(riskScore),
        "riskReason=" .. riskReason
    }
    local detail = table.concat(reasons, " | ")

    live.predictiveLastCandidateReason = detail
    live.predictiveLastCandidateQualified = qualifies
    hustle_meter.S.predictiveHeistGuardLastCandidate =
        (qualifies and "QUALIFIED: " or "REJECTED: ") .. detail

    hustle_meter.predictive_guard_log(
        qualifies and "CANDIDATE_QUALIFIED" or "CANDIDATE_REJECTED",
        "trigger=" .. tostring(triggerName)
            .. " | independentCue=" .. tostring(independentPayoutCue)
            .. " | " .. detail
    )

    return qualifies, {
        triggerName = triggerName,
        riskLevel = riskLevel,
        riskScore = riskScore,
        riskReason = riskReason,
        hasRiskScript = hasRiskScript,
        activitySession = activity,
        transitionCue = transitionCue,
        markerRecent = markerRecent,
        markerAgeMs = markerAge,
        markerLabel = markerLabel,
        independentPayoutCue = independentPayoutCue,
        detail = detail
    }
end

function hustle_meter.predictive_guard_read_snapshot(label, attempt)
    local nowMs = hustle_meter.now()
    local total, bank, wallet, _, meta = hustle_meter.read_money_balance()
    local tx = hustle_meter.live_money_read_tx_state()
    local live = hustle_meter.LiveMoney
    local wallet0 = type(meta) == "table" and tonumber(meta.wallet0 or 0) or 0
    local wallet1 = type(meta) == "table" and tonumber(meta.wallet1 or 0) or 0

    return {
        label = tostring(label or "snapshot"),
        t = os.time(),
        ms = nowMs,
        elapsedMs = type(attempt) == "table"
            and math.max(0, nowMs - (tonumber(attempt.attemptMs or nowMs) or nowMs))
            or 0,
        total = tonumber(total or 0) or 0,
        bank = tonumber(bank or 0) or 0,
        wallet = tonumber(wallet or 0) or 0,
        wallet0 = wallet0,
        wallet1 = wallet1,
        txInProgress = tx.transactionInProgress == true,
        basketActive = tx.basketActive == true,
        shopSessionValid = tx.sessionValid == true,
        refreshPending = tx.refreshPending == true,
        startSessionPending = tx.startSessionPending == true,
        activitySession = hustle_meter.S.heistRiskActivitySession == true,
        mpCutscene = hustle_meter.S.heistRiskMpCutscene == true,
        networkTransitionStarted = hustle_meter.S.heistRiskNetworkTransitionStarted == true,
        networkTransitionBusy = hustle_meter.S.heistRiskNetworkTransitionBusy == true,
        riskLevel = tostring(live.riskLevel or "LOW"),
        riskScore = tonumber(live.riskScore or 0) or 0,
        riskReason = tostring(live.riskReason or ""),
        riskScripts = tostring(hustle_meter.S.heistRiskActiveScripts or "None"),
        globalState = tonumber(live.globals and live.globals[4516758] or 0) or 0,
        globalAmount = tonumber(live.globals and live.globals[4516760] or 0) or 0,
        globalServiceHash = tonumber(live.globals and live.globals[4516761] or 0) or 0
    }
end

function hustle_meter.predictive_guard_execute_method(methodIndex)
    local methodName, normalizedIndex = hustle_meter.predictive_guard_method_name(methodIndex)
    local result = {
        methodIndex = normalizedIndex,
        methodName = methodName,
        calls = {}
    }

    local function record(callName, fn)
        local ok, value = pcall(fn)
        result.calls[#result.calls + 1] = {
            name = callName,
            pcallOk = ok,
            returnValue = ok and value or nil,
            error = ok and nil or tostring(value)
        }
        return ok, value
    end

    if normalizedIndex == 0 then
        result.observeOnly = true

    elseif normalizedIndex == 1 then
        record("NET_GAMESERVER_BASKET_END", function()
            return NET_GAMESERVER_BASKET_END()
        end)

    elseif normalizedIndex == 2 then
        record("NET_GAMESERVER_CLEAR_SESSION(0)", function()
            return NET_GAMESERVER_CLEAR_SESSION(0)
        end)

    elseif normalizedIndex == 3 then
        record("NET_GAMESERVER_CLEAR_SESSION(1)", function()
            return NET_GAMESERVER_CLEAR_SESSION(1)
        end)

    elseif normalizedIndex == 4 then
        record("NET_GAMESERVER_BASKET_END", function()
            return NET_GAMESERVER_BASKET_END()
        end)
        record("NET_GAMESERVER_CLEAR_SESSION(0)", function()
            return NET_GAMESERVER_CLEAR_SESSION(0)
        end)

    elseif normalizedIndex == 5 then
        record("NET_GAMESERVER_CLEAR_SESSION(0)", function()
            return NET_GAMESERVER_CLEAR_SESSION(0)
        end)
        record("NET_GAMESERVER_START_SESSION_RESTART(false,true)", function()
            return NET_GAMESERVER_START_SESSION_RESTART(false, true)
        end)
    end

    return result
end

function hustle_meter.predictive_guard_probe_attempt(attempt)
    if type(attempt) ~= "table" then return end

    local live = hustle_meter.LiveMoney
    live.predictiveProbeBusy = true
    hustle_meter.S.predictiveHeistGuardProbeBusy = true

    local probes = {}
    local offsets = hustle_meter.PredictiveGuard and hustle_meter.PredictiveGuard.ProbeOffsetsMs or {0,25,100,250,500,1000,5000}
    local previousOffset = 0

    for _, targetOffset in ipairs(offsets) do
        targetOffset = math.max(0, tonumber(targetOffset or 0) or 0)
        local wait = math.max(0, targetOffset - previousOffset)
        if wait > 0 and Script and Script.Yield then Script.Yield(wait) end
        previousOffset = targetOffset

        local snap = hustle_meter.predictive_guard_read_snapshot("+" .. tostring(targetOffset) .. "ms", attempt)
        probes[#probes + 1] = snap

        hustle_meter.predictive_guard_log(
            "POST_ABORT_PROBE",
            "attempt=" .. tostring(attempt.attemptId)
                .. " offset=" .. tostring(targetOffset)
                .. " total=" .. tostring(snap.total)
                .. " deltaFromBaseline=" .. tostring(snap.total - (tonumber(attempt.before.total or 0) or 0))
                .. " tx=" .. tostring(snap.txInProgress)
                .. " basket=" .. tostring(snap.basketActive)
                .. " sessionValid=" .. tostring(snap.shopSessionValid)
                .. " risk=" .. tostring(snap.riskLevel) .. "/" .. tostring(snap.riskScore)
        )
    end

    attempt.probes = probes
    attempt.completedAt = os.time()
    attempt.completedMs = hustle_meter.now()

    local final = probes[#probes] or attempt.afterImmediate or attempt.before
    local moneyDelta = (tonumber(final.total or 0) or 0) - (tonumber(attempt.before.total or 0) or 0)

    if moneyDelta > 0 then
        attempt.outcome = "FAILED: payout landed +" .. tostring(math.floor(moneyDelta))
    elseif attempt.methodResult and attempt.methodResult.observeOnly == true then
        attempt.outcome = "OBSERVE ONLY: no abort attempted"
    elseif final.txInProgress == false then
        attempt.outcome = "CANDIDATE SUCCESS: no positive GTA$ within 5s and transaction not in progress"
    else
        attempt.outcome = "INCONCLUSIVE: no positive GTA$ within 5s but transaction still active"
    end

    hustle_meter.S.predictiveHeistGuardLastOutcome = tostring(attempt.outcome)
    hustle_meter.S.predictiveHeistGuardProbeBusy = false
    live.predictiveProbeBusy = false
    live.lastPredictiveAttempt = attempt

    hustle_meter.try_write_file(
        hustle_meter.PredictiveAbortLatestFile,
        "return " .. hustle_meter.serialize(attempt, "") .. "\n"
    )

    hustle_meter.predictive_guard_log(
        "ATTEMPT_FINAL",
        "attempt=" .. tostring(attempt.attemptId)
            .. " outcome=" .. tostring(attempt.outcome)
            .. " finalTotal=" .. tostring(final.total)
            .. " moneyDelta=" .. tostring(moneyDelta)
            .. " finalTx=" .. tostring(final.txInProgress)
    )
end

function hustle_meter.predictive_guard_attempt(nowMs, tx, flags, total, bank, wallet0, wallet1, context)
    local live = hustle_meter.LiveMoney
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()

    if hustle_meter.S.predictiveHeistGuardEnabled ~= true then return false, "disabled" end

    local cooldownUntil = tonumber(live.predictiveCooldownUntilMs or 0) or 0
    if nowMs < cooldownUntil then
        hustle_meter.S.predictiveHeistGuardStatus =
            "Qualified candidate ignored during cooldown (" .. tostring(cooldownUntil - nowMs) .. "ms left)."
        return false, "cooldown"
    end

    local blockAll = hustle_meter.S.hardCapBlockAllIncomingTestMode == true
    local capState = hustle_meter.get_hard_cap_state(0)
    local capRequiresBlock =
        hustle_meter.S.hardCapGuardEnabled == true
        and capState.atOrOver == true

    if not blockAll and not capRequiresBlock then
        hustle_meter.S.predictiveHeistGuardStatus =
            "Qualified payout candidate observed, but blocking policy is not active."
        return false, "policy-not-active"
    end

    live.predictiveAttemptCount = (tonumber(live.predictiveAttemptCount or 0) or 0) + 1
    live.predictiveBlockedCandidateCount = (tonumber(live.predictiveBlockedCandidateCount or 0) or 0) + 1
    live.lastPredictiveAttemptMs = nowMs
    live.predictiveCooldownUntilMs =
        nowMs + math.max(1000, tonumber(hustle_meter.S.predictiveHeistGuardCooldownMs or 10000) or 10000)

    local methodName, methodIndex = hustle_meter.predictive_guard_method_name()
    local attempt = {
        attemptId = tostring(os.date("%Y%m%d_%H%M%S")) .. "_" .. tostring(live.predictiveAttemptCount),
        t = os.time(),
        attemptMs = nowMs,
        methodIndex = methodIndex,
        methodName = methodName,
        blockAllTestMode = blockAll,
        capState = capState,
        context = context,
        before = {
            total = tonumber(total or 0) or 0,
            bank = tonumber(bank or 0) or 0,
            wallet0 = tonumber(wallet0 or 0) or 0,
            wallet1 = tonumber(wallet1 or 0) or 0,
            txInProgress = tx and tx.transactionInProgress == true or false,
            basketActive = tx and tx.basketActive == true or false,
            riskLevel = tostring(live.riskLevel or "LOW"),
            riskScore = tonumber(live.riskScore or 0) or 0,
            riskReason = tostring(live.riskReason or ""),
            riskScripts = tostring(hustle_meter.S.heistRiskActiveScripts or "None"),
            markerLabel = tostring(live.lastMarkerLabel or ""),
            markerAgeMs = context and context.markerAgeMs or nil
        }
    }

    hustle_meter.S.predictiveHeistGuardAttempts = live.predictiveAttemptCount
    hustle_meter.S.predictiveHeistGuardCandidateCount = live.predictiveBlockedCandidateCount
    hustle_meter.S.predictiveHeistGuardLastAttemptMs = nowMs
    hustle_meter.S.predictiveHeistGuardStatus =
        "ABORT ATTEMPT: " .. methodName .. " on qualified heist transaction."
    hustle_meter.S.predictiveHeistGuardLastAttempt =
        methodName .. " @ " .. os.date("%H:%M:%S")

    hustle_meter.predictive_guard_log(
        "ATTEMPT_START",
        "attempt=" .. tostring(attempt.attemptId)
            .. " method=" .. methodName
            .. " total=" .. tostring(total)
            .. " bank=" .. tostring(bank)
            .. " w0=" .. tostring(wallet0)
            .. " w1=" .. tostring(wallet1)
            .. " context=" .. tostring(context and context.detail or "")
    )

    local methodResult = hustle_meter.predictive_guard_execute_method(methodIndex)
    attempt.methodResult = methodResult

    local returns = {}
    for _, call in ipairs(methodResult.calls or {}) do
        returns[#returns + 1] =
            tostring(call.name) .. "="
            .. (call.pcallOk and tostring(call.returnValue) or ("ERROR:" .. tostring(call.error)))
    end
    if methodResult.observeOnly then returns[#returns + 1] = "ObserveOnly=true" end

    hustle_meter.S.predictiveHeistGuardLastReturn =
        #returns > 0 and table.concat(returns, "; ") or "No calls"
    attempt.afterImmediate = hustle_meter.predictive_guard_read_snapshot("immediate-after", attempt)

    hustle_meter.predictive_guard_log(
        "ATTEMPT_NATIVE_RESULT",
        "attempt=" .. tostring(attempt.attemptId)
            .. " results=" .. hustle_meter.S.predictiveHeistGuardLastReturn
            .. " txAfter=" .. tostring(attempt.afterImmediate.txInProgress)
            .. " totalAfter=" .. tostring(attempt.afterImmediate.total)
    )

    live.pendingPredictiveAttempt = attempt

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            local ok, err = pcall(hustle_meter.predictive_guard_probe_attempt, attempt)
            if not ok then
                live.predictiveProbeBusy = false
                hustle_meter.S.predictiveHeistGuardProbeBusy = false
                hustle_meter.S.predictiveHeistGuardLastOutcome = "Probe error: " .. tostring(err)
                hustle_meter.predictive_guard_log(
                    "PROBE_ERROR",
                    "attempt=" .. tostring(attempt.attemptId) .. " error=" .. tostring(err)
                )
            end
        end)
    else
        hustle_meter.predictive_guard_probe_attempt(attempt)
    end

    return true, methodName
end

function hustle_meter.live_money_probe_tick()
    if hustle_meter.S.liveMoneyScannerEnabled ~= true then
        hustle_meter.S.liveMoneyStatus = "Live Payout Scanner disabled."
        return
    end

    local live = hustle_meter.LiveMoney
    local nowMs = hustle_meter.now()
    live.lastProbeMs = nowMs
    live.readCount = (tonumber(live.readCount or 0) or 0) + 1

    hustle_meter.live_money_capture_globals(nowMs)
    local tx = hustle_meter.live_money_read_tx_state()

    hustle_meter.S.liveMoneyTransactionInProgress = tx.transactionInProgress == true
    hustle_meter.S.liveMoneyBasketActive = tx.basketActive == true
    hustle_meter.S.liveMoneySessionValid = tx.sessionValid == true
    hustle_meter.S.liveMoneyRefreshPending = tx.refreshPending == true
    hustle_meter.S.liveMoneyStartSessionPending = tx.startSessionPending == true
    hustle_meter.S.liveMoneyUseServerTransactions = tx.useServerTransactions == true
    hustle_meter.S.liveMoneyCatalogValid = tx.catalogValid == true
    hustle_meter.S.liveMoneyCatalogCurrent = tx.catalogCurrent == true

    local transactionRisingEdge = false

    local stateChanges = {
        {"transactionInProgress", live.lastTransactionInProgress, tx.transactionInProgress, "TRANSACTION_ACTIVITY", "HIGH"},
        {"basketActive", live.lastBasketActive, tx.basketActive, "BASKET_ACTIVITY", "MEDIUM"},
        {"sessionValid", live.lastSessionValid, tx.sessionValid, "SHOP_SESSION_VALID", "LOW"},
        {"refreshPending", live.lastRefreshPending, tx.refreshPending, "SHOP_REFRESH_PENDING", "LOW"},
        {"startSessionPending", live.lastStartSessionPending, tx.startSessionPending, "SHOP_SESSION_START_PENDING", "LOW"},
        {"useServerTransactions", live.lastUseServerTransactions, tx.useServerTransactions, "SERVER_TRANSACTIONS_MODE", "LOW"},
        {"catalogValid", live.lastCatalogValid, tx.catalogValid, "CATALOG_VALID", "LOW"},
        {"catalogCurrent", live.lastCatalogCurrent, tx.catalogCurrent, "CATALOG_CURRENT", "LOW"}
    }

    for _, state in ipairs(stateChanges) do
        local key, before, after, signalName, confidence = state[1], state[2], state[3], state[4], state[5]
        if before ~= nil and before ~= after then
            hustle_meter.live_money_event(
                "TX_STATE_CHANGE:" .. tostring(key),
                tostring(key) .. "=" .. tostring(after),
                0,
                confidence
            )
            if key == "transactionInProgress" and before == false and after == true then
                transactionRisingEdge = true
                live.lastPredictiveTxRisingMs = nowMs
                hustle_meter.predictive_guard_log(
                    "TX_RISING_EDGE",
                    "riskBeforeCurrentTick=" .. tostring(live.riskLevel or "LOW")
                        .. "/" .. tostring(live.riskScore or 0)
                        .. " scripts=" .. tostring(hustle_meter.S.heistRiskActiveScripts or "None")
                )
            end
            if after == true and (key == "transactionInProgress" or key == "basketActive") then
                hustle_meter.live_money_signal(
                    signalName,
                    "NET_GAMESERVER state",
                    0,
                    tostring(key) .. " rising edge",
                    confidence
                )
            end
        end
    end

    live.lastTransactionInProgress = tx.transactionInProgress
    live.lastBasketActive = tx.basketActive
    live.lastSessionValid = tx.sessionValid
    live.lastRefreshPending = tx.refreshPending
    live.lastStartSessionPending = tx.startSessionPending
    live.lastUseServerTransactions = tx.useServerTransactions
    live.lastCatalogValid = tx.catalogValid
    live.lastCatalogCurrent = tx.catalogCurrent

    local total, bank, wallet, details, meta = hustle_meter.read_money_balance()
    if total == nil then
        hustle_meter.S.liveMoneyStatus = "Probe read failed: authoritative GTA$ unavailable."
        return
    end

    local wallet0 = type(meta) == "table" and tonumber(meta.wallet0 or 0) or 0
    local wallet1 = type(meta) == "table" and tonumber(meta.wallet1 or 0) or 0

    hustle_meter.S.liveMoneyRawTotal = tonumber(total or 0) or 0
    hustle_meter.S.liveMoneyRawBank = tonumber(bank or 0) or 0
    hustle_meter.S.liveMoneyRawWallet0 = wallet0
    hustle_meter.S.liveMoneyRawWallet1 = wallet1
    hustle_meter.S.liveMoneyReadCount = live.readCount

    local changed = false
    local delta = 0
    if live.lastTotal ~= nil then
        delta = (tonumber(total or 0) or 0) - (tonumber(live.lastTotal or 0) or 0)
        if delta ~= 0
            or tonumber(bank or 0) ~= tonumber(live.lastBank or 0)
            or wallet0 ~= tonumber(live.lastWallet0 or 0)
            or wallet1 ~= tonumber(live.lastWallet1 or 0) then
            changed = true
        end
    end

    local hot = nowMs <= math.max(
        tonumber(live.hotUntilMs or 0) or 0,
        tonumber(live.manualHotUntilMs or 0) or 0,
        tonumber(hustle_meter.S.liveMoneyManualHotUntilMs or 0) or 0
    )
    if hot or nowMs - (tonumber(live.lastFlagsMs or 0) or 0) >= 100 then
        live.lastFlags = hustle_meter.capture_session_flags()
        live.lastFlagsMs = nowMs
    end
    local flags = type(live.lastFlags) == "table" and live.lastFlags or {}

    hustle_meter.heist_risk_update(nowMs, tx, flags)
    hustle_meter.heist_timeline_push(nowMs, total, bank, wallet0, wallet1, tx, flags)
    hustle_meter.heist_incident_maintain(nowMs)

    -- Build 037: use the learned finale/loading transition as a pre-transaction
    -- warning and hold the shopping session invalid before transactionInProgress rises.
    hustle_meter.pretransaction_hold_tick(nowMs, tx, flags)

    if transactionRisingEdge then
        local qualified, context = hustle_meter.predictive_guard_candidate(nowMs, tx, flags)
        if qualified then
            hustle_meter.predictive_guard_attempt(
                nowMs, tx, flags, total, bank, wallet0, wallet1, context
            )
        else
            hustle_meter.predictive_guard_log(
                "TX_RISING_REJECTED",
                tostring(context and context.detail or "no context")
            )
        end
    end

    if changed then
        live.moneyChangeCount = (tonumber(live.moneyChangeCount or 0) or 0) + 1
        local lastBank = tonumber(live.lastBank or 0) or 0
        local lastW0 = tonumber(live.lastWallet0 or 0) or 0
        local lastW1 = tonumber(live.lastWallet1 or 0) or 0

        if delta > 0 then
            live.positiveChangeTotal = (tonumber(live.positiveChangeTotal or 0) or 0) + delta
        elseif delta < 0 then
            live.negativeChangeTotal = (tonumber(live.negativeChangeTotal or 0) or 0) + math.abs(delta)
        end

        live.lastMoneyChange = {
            t = os.time(), ms = nowMs,
            delta = delta, total = total, bank = bank,
            wallet0 = wallet0, wallet1 = wallet1,
            bankDelta = (tonumber(bank or 0) or 0) - lastBank,
            wallet0Delta = wallet0 - lastW0,
            wallet1Delta = wallet1 - lastW1
        }

        hustle_meter.S.liveMoneyMoneyChangeCount = live.moneyChangeCount
        hustle_meter.S.liveMoneyLastDelta = delta
        hustle_meter.S.liveMoneyLastDeltaAgeMs = 0

        hustle_meter.live_money_event(
            delta > 0 and "MONEY_INCREASE" or (delta < 0 and "MONEY_DECREASE" or "MONEY_COMPONENT_CHANGE"),
            ("total=%s delta=%+d bank=%s bankDelta=%+d w0=%s w0Delta=%+d w1=%s w1Delta=%+d")
                :format(
                    tostring(total), math.floor(delta),
                    tostring(bank), math.floor(live.lastMoneyChange.bankDelta),
                    tostring(wallet0), math.floor(live.lastMoneyChange.wallet0Delta),
                    tostring(wallet1), math.floor(live.lastMoneyChange.wallet1Delta)
                ),
            delta,
            delta > 0 and "CONFIRMED MONEY" or "INFO"
        )

        if delta ~= 0 then
            hustle_meter.live_money_correlate(delta, total, bank, wallet0, wallet1, nowMs)
        end
        if delta > 0 then
            hustle_meter.heist_incident_begin(delta, nowMs, total, bank, wallet0, wallet1)
        end
        live.hotUntilMs = math.max(tonumber(live.hotUntilMs or 0) or 0, nowMs + 10000)
    end

    live.lastTotal = total
    live.lastBank = bank
    live.lastWallet = wallet
    live.lastWallet0 = wallet0
    live.lastWallet1 = wallet1

    if type(live.lastSignal) == "table" then
        hustle_meter.S.liveMoneyLastSignalAgeMs =
            math.max(0, nowMs - (tonumber(live.lastSignal.ms or nowMs) or nowMs))
    end
    if type(live.lastMoneyChange) == "table" then
        hustle_meter.S.liveMoneyLastDeltaAgeMs =
            math.max(0, nowMs - (tonumber(live.lastMoneyChange.ms or nowMs) or nowMs))
    end

    local signal = live.lastSignal
    local signalAge = signal and (nowMs - (tonumber(signal.ms or nowMs) or nowMs)) or math.huge
    local signalWindow = math.max(1000, tonumber(hustle_meter.S.liveMoneySignalHotWindowMs or 15000) or 15000)

    if changed and delta > 0 then
        hustle_meter.S.liveMoneyStatus =
            ("MONEY ARRIVED: %s | bank=%+d w0=%+d w1=%+d")
                :format(
                    hustle_meter.format_money(delta, true),
                    math.floor(live.lastMoneyChange.bankDelta),
                    math.floor(live.lastMoneyChange.wallet0Delta),
                    math.floor(live.lastMoneyChange.wallet1Delta)
                )
        hustle_meter.S.liveMoneySignalLevel = "CONFIRMED"
    elseif signal and signalAge >= 0 and signalAge <= signalWindow then
        local amountText = tonumber(signal.amount or 0) > 0
            and (" expected=" .. hustle_meter.format_money(signal.amount))
            or ""
        hustle_meter.S.liveMoneyStatus =
            ("POSSIBLE INCOMING MONEY: %s via %s%s | %dms ago")
                :format(
                    tostring(signal.kind or "signal"),
                    tostring(signal.path or "unknown"),
                    amountText,
                    math.floor(signalAge)
                )
        hustle_meter.S.liveMoneySignalLevel = tostring(signal.confidence or "MEDIUM")
    elseif tx.transactionInProgress then
        hustle_meter.S.liveMoneyStatus =
            "TRANSACTION IN PROGRESS: waiting for a stronger money signal / balance change."
        hustle_meter.S.liveMoneySignalLevel = "MEDIUM"
    elseif tostring(live.riskLevel or "LOW") == "HIGH"
        or tostring(live.riskLevel or "LOW") == "CRITICAL" then
        hustle_meter.S.liveMoneyStatus =
            ("HIGH-RISK PAYOUT WINDOW: %s/%s | %s")
                :format(
                    tostring(live.riskLevel),
                    tostring(live.riskScore),
                    tostring(live.riskReason)
                )
        hustle_meter.S.liveMoneySignalLevel = tostring(live.riskLevel)
    else
        hustle_meter.S.liveMoneyStatus =
            ("MONITORING: heist risk %s/%s | %s")
                :format(
                    tostring(live.riskLevel or "LOW"),
                    tostring(live.riskScore or 0),
                    tostring(live.riskReason or "")
                )
        hustle_meter.S.liveMoneySignalLevel = "NONE"
    end

    hustle_meter.live_money_write_trace(
        nowMs, total, bank, wallet, wallet0, wallet1, meta, tx, flags, changed
    )

    if nowMs - (tonumber(live.lastSummaryMs or 0) or 0) >= 1000 then
        hustle_meter.live_money_write_summary("periodic")
    end
end

