    local live = hustle_meter.LiveMoney
    live.sessionId = (os.date("%Y%m%d_%H%M%S") or tostring(os.time())) .. "_" .. tostring(hustle_meter.Build)
    live.startedAt = os.time()
    live.startedMs = hustle_meter.now()
    live.readCount = 0
    live.traceCount = 0
    live.eventCount = 0
    live.moneyChangeCount = 0
    live.positiveChangeTotal = 0
    live.negativeChangeTotal = 0
    live.signalCount = 0
    live.correlationCount = 0
    live.lastProbeMs = 0
    live.lastTraceMs = 0
    live.lastSummaryMs = 0
    live.lastFlagsMs = 0
    live.lastTotal = nil
    live.lastBank = nil
    live.lastWallet = nil
    live.lastWallet0 = nil
    live.lastWallet1 = nil
    live.lastTransactionInProgress = nil
    live.lastBasketActive = nil
    live.lastSessionValid = nil
    live.lastRefreshPending = nil
    live.lastStartSessionPending = nil
    live.lastUseServerTransactions = nil
    live.lastCatalogValid = nil
    live.lastCatalogCurrent = nil
    live.globals = {}
    live.lastSignal = nil
    live.lastMoneyChange = nil
    live.lastCorrelation = nil
    live.recentEvents = {}
