    live.riskSinceMs = hustle_meter.now()
    live.highRiskSinceMs = 0
    live.riskChangeCount = 0
    live.timeline = {}
    live.lastTimelineMs = 0
    live.pendingIncident = nil
    live.incidentCount = 0
    live.lastIncident = nil
    live.markerCount = 0
    live.lastMarkerMs = 0
    live.lastMarkerLabel = ""
    live.lastPredictiveTxRisingMs = 0
    live.lastPredictiveAttemptMs = 0
    live.predictiveAttemptCount = 0
    live.predictiveBlockedCandidateCount = 0
    live.predictiveCooldownUntilMs = 0
    live.pendingPredictiveAttempt = nil
    live.lastPredictiveAttempt = nil
    live.predictiveProbeBusy = false
    live.predictiveLastCandidateReason = ""
