    hustle_meter.S.predictiveHeistGuardLastAttempt = "None"
    hustle_meter.S.predictiveHeistGuardAttempts = 0
    hustle_meter.S.predictiveHeistGuardCandidateCount = 0
    hustle_meter.S.predictiveHeistGuardLastReturn = "None"
    hustle_meter.S.predictiveHeistGuardLastOutcome = "None"
    hustle_meter.S.predictiveHeistGuardLastAttemptMs = 0
    hustle_meter.S.predictiveHeistGuardProbeBusy = false

