function hustle_meter.schedule_live_money_clear()
    hustle_meter.PendingLiveMoneyClear = true
end

function hustle_meter.schedule_live_money_hot_capture()
    hustle_meter.PendingLiveMoneyHotCapture = true
end

function hustle_meter.process_pending_live_money_actions()
    if hustle_meter.PendingLiveMoneyClear == true then
        hustle_meter.PendingLiveMoneyClear = false
        local paths = {
            hustle_meter.LiveMoneyTraceFile,
            hustle_meter.LiveMoneyEventsFile,
            hustle_meter.LiveMoneyGlobalsFile,
            hustle_meter.LiveMoneyCorrelationFile,
            hustle_meter.LiveMoneySummaryFile,
            hustle_meter.HeistRiskLogFile,
            hustle_meter.HeistMarkerLogFile,
            hustle_meter.PayoutIncidentLogFile,
            hustle_meter.PayoutIncidentLatestFile,
            hustle_meter.PredictiveGuardLogFile,
            hustle_meter.PredictiveAbortLatestFile,
            hustle_meter.PreTransactionHoldLogFile,
            hustle_meter.PreTransactionHoldLatestFile,
            hustle_meter.ExternalPayoutGuardLogFile,
            hustle_meter.SilentNightApartmentLockLogFile,
            hustle_meter.SilentNightMultiHeistLockLogFile,
            hustle_meter.SmartCutLogFile,
            hustle_meter.SmartCutLatestFile
        }
        for _, path in ipairs(paths) do
            pcall(os.remove, path)
            for i = 1, 3 do pcall(os.remove, path .. "." .. tostring(i)) end
        end
        hustle_meter.live_money_boot()
        hustle_meter.toast("Live Payout Scanner logs cleared and restarted.", 4500)
    end

    if hustle_meter.PendingLiveMoneyHotCapture == true then
        hustle_meter.PendingLiveMoneyHotCapture = false
        local untilMs = hustle_meter.now() + 60000
        hustle_meter.LiveMoney.manualHotUntilMs = untilMs
        hustle_meter.S.liveMoneyManualHotUntilMs = untilMs
        hustle_meter.S.liveMoneyStatus = "DEEP CAPTURE ACTIVE: 25ms trace for 60 seconds."
        hustle_meter.live_money_event(
            "MANUAL_DEEP_CAPTURE_START",
            "Forced 25ms trace window for 60 seconds.",
            0,
            "INFO"
        )
        hustle_meter.toast("60-second Deep Money Capture STARTED. Trigger the payout now.", 6500)
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 032: experimental network-money transaction firewall / profiler
--
-- Layer 1: proven physical GTA$ pickup guard (Build 031).
-- Layer 2: known NETWORK_EARN_* calls invoked through Cherax Lua after HustleMeter loads.
-- Layer 3: GTA.BeginService / NET_GAMESERVER transaction profiling.
-- Layer 4: known global transaction-control pattern profiling.
--
-- Important limitation:
-- Native calls made internally by Rockstar scripts, Cherax C++ modules, or another
-- module that cached its own dispatcher before HustleMeter loaded cannot necessarily
-- be intercepted by Lua. The profiler tells us which path is visible before we enable
-- permanent blocking for a generic transaction pattern.
