hustle_meter.HardCapEarnNativeCount = 0
for _ in pairs(hustle_meter.HardCap.EarnNatives or {}) do
    hustle_meter.HardCapEarnNativeCount = hustle_meter.HardCapEarnNativeCount + 1
end

hustle_meter.HardCap.TransactionNatives = {
    BEGIN_SERVICE = 0x3C5FD37B5499582E,
    CHECKOUT_START = 0x39BE7CEA8D9CC8E6,
    BASKET_START = 0x279F08B1A4B29B7E
}

-- Pattern seen in the supplied Cherax Lua corpus. Some money tools use this global
-- transaction control block instead of GTA.BeginService. This is profiler/test-only
-- because the offset can change between GTA builds/editions.
hustle_meter.HardCap.GlobalTransaction = {
    base = 4516758,
    watched = {
        [4516758] = "commit/state",
        [4516759] = "limit/guard",
        [4516760] = "amount",
        [4516761] = "service/hash",
        [4516763] = "aux5",
        [4516764] = "aux6",
        [4516765] = "aux7"
    }
}

function hustle_meter.hard_cap_tx_safe(value)
    return tostring(value == nil and "nil" or value):gsub("[\r\n|]+", " ")
end

function hustle_meter.hard_cap_tx_log(kind, details)
    hustle_meter.ensure_debug_dir()
    local f = io.open(tostring(hustle_meter.HardCapTransactionLogFile or ""), "a")
    if not f then return false end
    f:write(("%s | %s | day=%s | week=%s | remaining=%s | %s\n"):format(
        os.date("%Y-%m-%d %H:%M:%S"),
        hustle_meter.hard_cap_tx_safe(kind),
        tostring(hustle_meter.S.past24h or 0),
        tostring(hustle_meter.S.past168h or 0),
        tostring(hustle_meter.get_remaining_allowance()),
        hustle_meter.hard_cap_tx_safe(details)
    ))
    f:close()
    return true
end

function hustle_meter.hard_cap_args_text(args, maxArgs)
    local parts = {}
    for i = 1, math.min(#args, tonumber(maxArgs or 8) or 8) do
        parts[#parts + 1] = tostring(i) .. "=" .. hustle_meter.hard_cap_tx_safe(args[i])
    end
    return table.concat(parts, " ")
end

function hustle_meter.hard_cap_extract_known_amount(definition, args)
    if type(definition) ~= "table" or type(definition.amount) ~= "table" then return nil end
    local amount, found = 0, false
    for _, index in ipairs(definition.amount) do
        local n = tonumber(args[index])
        if n and n > 0 then
            amount = amount + math.floor(n)
            found = true
        end
    end
    return found and amount or nil
end

function hustle_meter.hard_cap_payout_test_is_active()
    local nowMs = hustle_meter.now()
    local untilMs = tonumber(hustle_meter.S.hardCapPayoutTestUntilMs or 0) or 0
    if hustle_meter.S.hardCapPayoutTestArmed == true and untilMs > nowMs then return true end

    if hustle_meter.S.hardCapPayoutTestArmed == true then
        hustle_meter.S.hardCapPayoutTestArmed = false
        hustle_meter.S.hardCapPayoutTestUntilMs = 0
        hustle_meter.S.hardCapFirewallStatus = "Next-payout test expired without intercepting a blockable transaction."
        hustle_meter.hard_cap_tx_log("PAYOUT_TEST_EXPIRED", "No blockable transaction was intercepted.")
    end
    return false
end

function hustle_meter.schedule_hard_cap_payout_test()
    hustle_meter.PendingHardCapPayoutTest = true
    hustle_meter.S.hardCapFirewallStatus = "Next-payout firewall test queued..."
end

function hustle_meter.hard_cap_consume_payout_test(path, amount, detail)
    hustle_meter.S.hardCapPayoutTestArmed = false
    hustle_meter.S.hardCapPayoutTestUntilMs = 0
    hustle_meter.S.hardCapFirewallBlocked = (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
    hustle_meter.S.hardCapFirewallLastPath = tostring(path or "")
    hustle_meter.S.hardCapFirewallLastAmount = tonumber(amount or 0) or 0
    hustle_meter.S.hardCapFirewallLastDecision = "blocked-test"
    hustle_meter.S.hardCapFirewallStatus = "TEST BLOCKED: " .. tostring(path or "transaction")
        .. (tonumber(amount or 0) > 0 and (" " .. hustle_meter.format_money(amount)) or "")
    hustle_meter.hard_cap_tx_log("PAYOUT_TEST_BLOCKED",
        tostring(path or "") .. " amount=" .. tostring(amount or 0) .. " " .. tostring(detail or ""))
    hustle_meter.toast("Hard Cap test BLOCKED the next payout transaction.", 7500)
end

function hustle_meter.hard_cap_should_block_known_earn(definition, args, path)
    local amount = hustle_meter.hard_cap_extract_known_amount(definition, args)
    hustle_meter.S.hardCapFirewallEarnObserved = (tonumber(hustle_meter.S.hardCapFirewallEarnObserved or 0) or 0) + 1
    hustle_meter.S.hardCapFirewallLastPath = tostring(path or "NETWORK_EARN")
    hustle_meter.S.hardCapFirewallLastNative = tostring(definition and definition.name or "Unknown")
    hustle_meter.S.hardCapFirewallLastAmount = tonumber(amount or 0) or 0

    local argText = hustle_meter.hard_cap_args_text(args, 16)

    if hustle_meter.live_money_signal then
        hustle_meter.live_money_signal(
            "NETWORK_EARN_CALL",
            tostring(definition and definition.name or path or "NETWORK_EARN"),
            tonumber(amount or 0) or 0,
            argText,
            amount ~= nil and "VERY HIGH" or "HIGH"
        )
    end

    local blockAll = hustle_meter.S.hardCapBlockAllIncomingTestMode == true
    local oneShot = hustle_meter.hard_cap_payout_test_is_active()
    local capBlock = amount ~= nil
        and hustle_meter.S.hardCapGuardEnabled == true
        and hustle_meter.would_exceed_hard_cap(amount) == true

    if blockAll or oneShot or capBlock then
        hustle_meter.S.hardCapFirewallBlocked = (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
        local why = blockAll and "blocked-all-test" or (oneShot and "blocked-one-shot" or "blocked-cap")
        hustle_meter.S.hardCapFirewallLastDecision = why
        hustle_meter.S.hardCapLastBlockReason = tostring(definition and definition.name or "NETWORK_EARN")

        if oneShot then
            hustle_meter.S.hardCapPayoutTestArmed = false
            hustle_meter.S.hardCapPayoutTestUntilMs = 0
        end

        local amountText = amount ~= nil and hustle_meter.format_money(amount) or "unknown amount"
        hustle_meter.S.hardCapFirewallStatus =
            tostring(definition and definition.name or "NETWORK_EARN") .. " BLOCKED (" .. amountText .. ")"

        hustle_meter.hard_cap_tx_log(
            "EARN_BLOCKED",
            "reason=" .. tostring(why)
                .. " native=" .. tostring(definition and definition.name or "Unknown")
                .. " amount=" .. tostring(amount or "unknown")
                .. " declaredArgs=" .. tostring(definition and definition.args or "")
                .. " actual=" .. argText
        )
        return true
    end

    if amount == nil then
        hustle_meter.S.hardCapFirewallLastDecision = "observed-unknown-amount"
        hustle_meter.S.hardCapFirewallLastPattern =
            tostring(definition and definition.name or "Unknown") .. " " .. argText
        hustle_meter.hard_cap_tx_log(
            "EARN_OBSERVED_UNKNOWN_AMOUNT",
            tostring(definition and definition.name or "Unknown") .. " " .. argText
        )
        return false
    end

    hustle_meter.S.hardCapFirewallLastDecision = "allowed"
    hustle_meter.hard_cap_tx_log(
        "EARN_ALLOWED",
        tostring(definition and definition.name or "Unknown")
            .. " amount=" .. tostring(amount) .. " " .. argText
    )
    return false
end

function hustle_meter.hard_cap_observe_service(path, args)
    hustle_meter.S.hardCapFirewallServiceObserved =
        (tonumber(hustle_meter.S.hardCapFirewallServiceObserved or 0) or 0) + 1
    local pattern = tostring(path or "service") .. " " .. hustle_meter.hard_cap_args_text(args, 16)
    local possibleValue = tonumber(args and args[5] or 0) or 0
    if hustle_meter.live_money_signal then
        hustle_meter.live_money_signal(
            "SERVICE_TRANSACTION",
            tostring(path or "service"),
            possibleValue > 0 and possibleValue or 0,
            pattern,
            possibleValue > 0 and "HIGH" or "MEDIUM"
        )
    end
    hustle_meter.S.hardCapFirewallLastPath = tostring(path or "service")
    hustle_meter.S.hardCapFirewallLastPattern = pattern
    hustle_meter.hard_cap_tx_log("SERVICE_OBSERVED", pattern)
end

function hustle_meter.hard_cap_observe_global(index, value)
    local watched = hustle_meter.HardCap.GlobalTransaction.watched
    local label = watched and watched[tonumber(index)] or nil
    if not label then return false end
    hustle_meter.S.hardCapFirewallGlobalObserved =
        (tonumber(hustle_meter.S.hardCapFirewallGlobalObserved or 0) or 0) + 1
    local detail = "global=" .. tostring(index) .. " label=" .. tostring(label) .. " value=" .. tostring(value)
    if hustle_meter.live_money_signal then
        local confidence = tonumber(index) == hustle_meter.HardCap.GlobalTransaction.base and tonumber(value) == 2
            and "VERY HIGH" or "MEDIUM"
        hustle_meter.live_money_signal(
            tonumber(index) == hustle_meter.HardCap.GlobalTransaction.base and tonumber(value) == 2
                and "GLOBAL_TRANSACTION_COMMIT" or "GLOBAL_TRANSACTION_WRITE",
            "ScriptGlobal.SetInt[" .. tostring(index) .. "]",
            tonumber(index) == 4516760 and (tonumber(value) or 0) or 0,
            detail,
            confidence
        )
    end
    hustle_meter.S.hardCapFirewallLastPath = "ScriptGlobal.SetInt"
    hustle_meter.S.hardCapFirewallLastPattern = detail
    hustle_meter.hard_cap_tx_log("GLOBAL_TX_OBSERVED", detail)
    return true
end

function hustle_meter.restore_native_transaction_firewall()
    local backup = rawget(_G, "__HUSTLEMETER_TX_FIREWALL")
    if type(backup) ~= "table" or backup.installed ~= true then
        hustle_meter.S.hardCapFirewallInstalled = false
        return true
    end

    pcall(function()
        if Natives then
            if backup.invokeVoid then Natives.InvokeVoid = backup.invokeVoid end
            if backup.invokeBool then Natives.InvokeBool = backup.invokeBool end
        end
        if GTA then
            if backup.beginService then GTA.BeginService = backup.beginService end
            if backup.checkoutStart then GTA.CheckoutStart = backup.checkoutStart end
        end
        if ScriptGlobal and backup.scriptGlobalSetInt then
            ScriptGlobal.SetInt = backup.scriptGlobalSetInt
        end
        if type(backup.moneyFunctions) == "table" and type(_G.MONEY) == "table" then
            for name, fn in pairs(backup.moneyFunctions) do
                if type(fn) == "function" then _G.MONEY[name] = fn end
            end
        end
        if type(backup.globalEarnFunctions) == "table" then
            for name, fn in pairs(backup.globalEarnFunctions) do
                if type(fn) == "function" then _G[name] = fn end
            end
        end
    end)

    backup.installed = false
    hustle_meter.S.hardCapFirewallInstalled = false
    hustle_meter.S.hardCapFirewallStatus = "Transaction firewall restored/removed."
    return true
end

function hustle_meter.install_native_transaction_firewall()
    if hustle_meter.S.hardCapTransactionFirewallEnabled ~= true then return false end

    local existing = rawget(_G, "__HUSTLEMETER_TX_FIREWALL")
    if type(existing) == "table" and existing.installed == true then
        hustle_meter.S.hardCapFirewallInstalled = true
        return true
    end

    local backup = {
        installed = true,
        invokeVoid = Natives and Natives.InvokeVoid or nil,
        invokeBool = Natives and Natives.InvokeBool or nil,
        beginService = GTA and GTA.BeginService or nil,
        checkoutStart = GTA and GTA.CheckoutStart or nil,
        scriptGlobalSetInt = ScriptGlobal and ScriptGlobal.SetInt or nil,
        moneyFunctions = {},
        globalEarnFunctions = {}
    }
    _G.__HUSTLEMETER_TX_FIREWALL = backup

    if Natives and type(backup.invokeVoid) == "function" then
        Natives.InvokeVoid = function(hash, ...)
            local definition = hustle_meter.HardCap.EarnNatives[hash]
            if definition then
                local args = {...}
                if hustle_meter.hard_cap_should_block_known_earn(definition, args, "Natives.InvokeVoid") then
                    return nil
                end
            end
            return backup.invokeVoid(hash, ...)
        end
    end

    if Natives and type(backup.invokeBool) == "function" then
        Natives.InvokeBool = function(hash, ...)
            local args = {...}
            if hash == hustle_meter.HardCap.TransactionNatives.BEGIN_SERVICE then
                hustle_meter.hard_cap_observe_service("NET_GAMESERVER_BEGIN_SERVICE", args)

                -- Test-only generic service block. The 5th parameter is the documented
                -- service value/price, but this native is also used for purchases, so
                -- automatic cap mode will not block it until we prove heist hashes.
                local value = tonumber(args[5])
                local blockGeneric =
                    hustle_meter.S.hardCapBlockAllIncomingTestMode == true
                    and hustle_meter.S.hardCapBlockGenericTransactionsTestMode == true
                if blockGeneric then
                    hustle_meter.S.hardCapFirewallBlocked =
                        (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
                    hustle_meter.S.hardCapFirewallLastDecision = "blocked-generic-begin-service-test"
                    hustle_meter.S.hardCapFirewallStatus =
                        "BLOCK ALL TEST: NET_GAMESERVER_BEGIN_SERVICE rejected."
                    hustle_meter.hard_cap_tx_log(
                        "GENERIC_SERVICE_BLOCKED_ALL_TEST",
                        "value=" .. tostring(value) .. " " .. hustle_meter.hard_cap_args_text(args, 16)
                    )
                    return false
                elseif hustle_meter.hard_cap_payout_test_is_active()
                    and value and value > 0 and value <= 100000000 then
                    hustle_meter.hard_cap_consume_payout_test(
                        "NET_GAMESERVER_BEGIN_SERVICE", value,
                        hustle_meter.hard_cap_args_text(args, 8)
                    )
                    return false
                end

            elseif hash == hustle_meter.HardCap.TransactionNatives.CHECKOUT_START then
                hustle_meter.hard_cap_observe_service("NET_GAMESERVER_CHECKOUT_START", args)
                if hustle_meter.S.hardCapBlockAllIncomingTestMode == true
                    and hustle_meter.S.hardCapBlockGenericTransactionsTestMode == true then
                    hustle_meter.S.hardCapFirewallBlocked =
                        (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
                    hustle_meter.S.hardCapFirewallLastDecision = "blocked-checkout-test"
                    hustle_meter.hard_cap_tx_log(
                        "CHECKOUT_BLOCKED_ALL_TEST",
                        hustle_meter.hard_cap_args_text(args, 16)
                    )
                    return false
                end
            elseif hash == hustle_meter.HardCap.TransactionNatives.BASKET_START then
                hustle_meter.hard_cap_observe_service("NET_GAMESERVER_BASKET_START", args)
                if hustle_meter.S.hardCapBlockAllIncomingTestMode == true
                    and hustle_meter.S.hardCapBlockGenericTransactionsTestMode == true then
                    hustle_meter.S.hardCapFirewallBlocked =
                        (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
                    hustle_meter.S.hardCapFirewallLastDecision = "blocked-basket-start-test"
                    hustle_meter.hard_cap_tx_log(
                        "BASKET_START_BLOCKED_ALL_TEST",
                        hustle_meter.hard_cap_args_text(args, 16)
                    )
                    return false
                end
            end

            return backup.invokeBool(hash, ...)
        end
    end

    if GTA and type(backup.beginService) == "function" then
        GTA.BeginService = function(typeHash, category, service, action, price, flags)
            local args = {typeHash, category, service, action, price, flags}
            hustle_meter.hard_cap_observe_service("GTA.BeginService", args)

            local amount = tonumber(price)
            if hustle_meter.S.hardCapBlockAllIncomingTestMode == true
                and hustle_meter.S.hardCapBlockGenericTransactionsTestMode == true then
                hustle_meter.S.hardCapFirewallBlocked =
                    (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
                hustle_meter.S.hardCapFirewallLastDecision = "blocked-gta-begin-service-test"
                hustle_meter.S.hardCapFirewallStatus =
                    "BLOCK ALL TEST: GTA.BeginService rejected."
                hustle_meter.hard_cap_tx_log(
                    "GTA_BEGIN_SERVICE_BLOCKED_ALL_TEST",
                    hustle_meter.hard_cap_args_text(args, 16)
                )
                return false, 0
            elseif hustle_meter.hard_cap_payout_test_is_active()
                and amount and amount > 0 and amount <= 100000000 then
                hustle_meter.hard_cap_consume_payout_test(
                    "GTA.BeginService", amount,
                    hustle_meter.hard_cap_args_text(args, 8)
                )
                return false, 0
            end

            return backup.beginService(typeHash, category, service, action, price, flags)
        end
    end

    if GTA and type(backup.checkoutStart) == "function" then
        GTA.CheckoutStart = function(transactionId)
            hustle_meter.hard_cap_observe_service("GTA.CheckoutStart", {transactionId})
            return backup.checkoutStart(transactionId)
        end
    end

    if ScriptGlobal and type(backup.scriptGlobalSetInt) == "function" then
        ScriptGlobal.SetInt = function(index, value)
            local watched = hustle_meter.hard_cap_observe_global(index, value)

            -- Test-only global transaction commit block. The supplied Cherax Lua
            -- corpus uses base global 4516758 and writes state=2 to commit a money
            -- transaction. Do not use this as a permanent cross-build rule yet.
            if watched
                and tonumber(index) == hustle_meter.HardCap.GlobalTransaction.base
                and tonumber(value) == 2 then

                if hustle_meter.S.hardCapBlockAllIncomingTestMode == true
                    and hustle_meter.S.hardCapBlockKnownGlobalCommitTestMode == true then
                    hustle_meter.S.hardCapFirewallBlocked =
                        (tonumber(hustle_meter.S.hardCapFirewallBlocked or 0) or 0) + 1
                    hustle_meter.S.hardCapFirewallLastDecision = "blocked-global-commit-test"
                    hustle_meter.S.hardCapFirewallStatus =
                        "BLOCK ALL TEST: known global transaction commit suppressed."
                    hustle_meter.hard_cap_tx_log(
                        "GLOBAL_COMMIT_BLOCKED_ALL_TEST",
                        "global=" .. tostring(index) .. " value=" .. tostring(value)
                    )
                    return nil
                elseif hustle_meter.hard_cap_payout_test_is_active() then
                    hustle_meter.hard_cap_consume_payout_test(
                        "ScriptGlobal money transaction commit", 0,
                        "global=" .. tostring(index) .. " value=" .. tostring(value)
                    )
                    return nil
                end
            end

            return backup.scriptGlobalSetInt(index, value)
        end
    end

    hustle_meter.S.hardCapFirewallInstalled = true
    hustle_meter.refresh_named_earn_firewall()
    hustle_meter.S.hardCapFirewallStatus = "Transaction firewall/profiler installed."
    hustle_meter.hard_cap_tx_log("FIREWALL_INSTALLED",
        "NETWORK_EARN + NET_GAMESERVER/GTA service + known transaction-global profiler installed.")
    return true
end

function hustle_meter.refresh_named_earn_firewall()
    local backup = rawget(_G, "__HUSTLEMETER_TX_FIREWALL")
    if type(backup) ~= "table" or backup.installed ~= true then return false end

    for _, definition in pairs(hustle_meter.HardCap.EarnNatives or {}) do
        local name = tostring(definition.name or "")
        if name ~= "" then
            if type(_G.MONEY) == "table" then
                local current = _G.MONEY[name]
                if type(current) == "function" and backup.moneyFunctions[name] == nil then
                    local originalFn = current
                    local def = definition
                    local wrapperName = name
                    backup.moneyFunctions[name] = originalFn
                    _G.MONEY[name] = function(...)
                        local args = {...}
                        if hustle_meter.hard_cap_should_block_known_earn(
                            def, args, "MONEY." .. wrapperName
                        ) then
                            return nil
                        end
                        return originalFn(...)
                    end
                    hustle_meter.hard_cap_tx_log(
                        "NAMED_WRAPPER_INSTALLED",
                        "MONEY." .. wrapperName
                    )
                end
            end

            local globalCurrent = rawget(_G, name)
            if type(globalCurrent) == "function" and backup.globalEarnFunctions[name] == nil then
                local originalFn = globalCurrent
                local def = definition
                local wrapperName = name
                backup.globalEarnFunctions[name] = originalFn
                _G[name] = function(...)
                    local args = {...}
                    if hustle_meter.hard_cap_should_block_known_earn(
                        def, args, "_G." .. wrapperName
                    ) then
                        return nil
                    end
                    return originalFn(...)
                end
                hustle_meter.hard_cap_tx_log(
                    "NAMED_WRAPPER_INSTALLED",
                    "_G." .. wrapperName
                )
            end
        end
    end
    return true
end

function hustle_meter.process_pending_hard_cap_payout_test()
    if hustle_meter.PendingHardCapPayoutTest ~= true then return end
    hustle_meter.PendingHardCapPayoutTest = false
    hustle_meter.install_native_transaction_firewall()
    hustle_meter.S.hardCapPayoutTestArmed = true
    hustle_meter.S.hardCapPayoutTestUntilMs = hustle_meter.now() + 120000
    hustle_meter.S.hardCapFirewallStatus =
        "ARMED: first visible payout/service/global transaction will be blocked for 120 seconds."
    hustle_meter.hard_cap_tx_log("PAYOUT_TEST_ARMED",
        "First visible payout/service/global transaction will be blocked for 120 seconds.")
    hustle_meter.toast("Next heist payout block ARMED for 120 seconds.", 7000)
end

function hustle_meter.update_transaction_firewall()
    if hustle_meter.S.hardCapTransactionFirewallEnabled ~= true then
        hustle_meter.restore_native_transaction_firewall()
        return
    end
    hustle_meter.install_native_transaction_firewall()
    hustle_meter.refresh_named_earn_firewall()
    hustle_meter.hard_cap_payout_test_is_active()
end

function hustle_meter.normalize_money_value(value)
    local n = tonumber(value)
    if not n then return nil end
    if n < -2147483648 or n > 2147483647 then return nil end
    if n < 0 then return nil end
    return math.floor(n)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- balance reader
-- note: reads bank/wallet/total balance and rejects suspicious invalid values.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.read_money_balance()
    local bank, wallet0, wallet1, nativeTotal = nil, nil, nil, nil
    local details = {}

    local bankResult = NETWORK_GET_VC_BANK_BALANCE()
    bank = hustle_meter.normalize_money_value(bankResult)
    details[#details + 1] = "bank=true/" .. tostring(bankResult)

    local wallet0Result = NETWORK_GET_VC_WALLET_BALANCE(0)
    wallet0 = hustle_meter.normalize_money_value(wallet0Result)
    details[#details + 1] = "wallet0=true/" .. tostring(wallet0Result)

    local wallet1Result = NETWORK_GET_VC_WALLET_BALANCE(1)
    wallet1 = hustle_meter.normalize_money_value(wallet1Result)
    details[#details + 1] = "wallet1=true/" .. tostring(wallet1Result)

    local totalResult = NETWORK_GET_VC_BALANCE()
    nativeTotal = hustle_meter.normalize_money_value(totalResult)
    details[#details + 1] = "activeBalance=true/" .. tostring(totalResult)
    details[#details + 1] = "gameEdition=" .. tostring(hustle_meter.S.currentGameEdition or "Unknown")
    details[#details + 1] = "cheraxEdition=" .. tostring(hustle_meter.S.currentCheraxEdition or "Unknown")

    -- v1.0.4: NETWORK_GET_VC_BALANCE is the authoritative tracked value. Bank and
    -- both character wallets remain diagnostics only. This prevents a temporary
    -- bank=0 or stale wallet read during EE/loading transitions from becoming a
    -- false decrease followed by a fake multi-million-dollar gain.
    if nativeTotal == nil then
        return nil, nil, nil, table.concat(details, " | "), nil
    end

    bank = bank or 0
    wallet0 = wallet0 or 0
    wallet1 = wallet1 or 0
    local activeWallet = 0
    if bank <= nativeTotal then activeWallet = nativeTotal - bank end
    local consistency = hustle_meter.money_consistency(nativeTotal, bank, wallet0, wallet1)
    details[#details + 1] = "bankPlusWallet0=" .. tostring(consistency.sum0)
    details[#details + 1] = "bankPlusWallet1=" .. tostring(consistency.sum1)
    details[#details + 1] = "bankPlusWallet0PlusWallet1=" .. tostring(consistency.sumCombined)
    details[#details + 1] = "diff0=" .. tostring(consistency.diff0)
    details[#details + 1] = "diff1=" .. tostring(consistency.diff1)
    details[#details + 1] = "diffCombined=" .. tostring(consistency.diffCombined)
    details[#details + 1] = "moneyMatchMode=" .. tostring(consistency.matchMode)
    details[#details + 1] = "moneyConsistent=" .. tostring(consistency.consistent)

    local meta = {
        wallet0 = wallet0,
        wallet1 = wallet1,
        nativeTotal = nativeTotal,
        activeWallet = activeWallet,
        balanceMode = hustle_meter.BalanceMode,
        consistency = consistency
    }

    return nativeTotal, bank, activeWallet, table.concat(details, " | "), meta
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- ledger sorting / time text
-- note: keeps samples and gains ordered by real-world timestamp.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.sort_samples()
    table.sort(hustle_meter.Tracker.samples, function(a, b)
        return tonumber(a.t or 0) < tonumber(b.t or 0)
    end)
end

function hustle_meter.sort_gains()
    table.sort(hustle_meter.Tracker.gains or {}, function(a, b)
        local at = tonumber(a.t or 0) or 0
        local bt = tonumber(b.t or 0) or 0
        if at ~= bt then return at < bt end
        return (tonumber(a.detectedAtMs or 0) or 0) < (tonumber(b.detectedAtMs or 0) or 0)
    end)
end

function hustle_meter.time_text(t)
    t = tonumber(t or 0) or 0
    if t <= 0 then return "None" end
    local text = os.date("%Y-%m-%d %H:%M:%S", t)
    if text then return tostring(text) end
    return tostring(t)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- gta online gate
-- note: singleplayer/story mode is blocked from UI and tracker baseline logic.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.is_gta_online_session_detected()
    -- UI/lightweight guard: only treat real GTA Online sessions as active.
    -- Do not use NETWORK_IS_GAME_IN_PROGRESS here because that can be true in story/singleplayer contexts.
    local active = NETWORK_IS_SESSION_ACTIVE()
    local inSession = NETWORK_IS_IN_SESSION()
    local started = NETWORK_IS_SESSION_STARTED()

    return active == true or inSession == true or started == true
end

function hustle_meter.is_gta_online_ready()
    -- Hard guard: HustleMeter only tracks in GTA Online.
    -- This prevents story-mode/offline balances from becoming a false baseline.
    hustle_meter.S.onlineOnly = true

    local active = NETWORK_IS_SESSION_ACTIVE()
    local inSession = NETWORK_IS_IN_SESSION()
    local started = NETWORK_IS_SESSION_STARTED()
    local signedOnline = NETWORK_IS_SIGNED_ONLINE()
    local playerOnline = IS_PLAYER_ONLINE()

    -- Strict Online-only guard. Session natives are the main proof; signed-online natives are diagnostic only.
    -- Avoid NETWORK_IS_GAME_IN_PROGRESS for this because story mode can report game-progress without an Online session.
    local onlineNow = (active == true) or (inSession == true) or (started == true)
    local ms = hustle_meter.now()

    if onlineNow then
        if hustle_meter.S.lastOnline ~= true then
            hustle_meter.S.onlineSinceMs = ms
            hustle_meter.S.lastOnline = true
        elseif (tonumber(hustle_meter.S.onlineSinceMs or 0) or 0) <= 0 then
            hustle_meter.S.onlineSinceMs = ms
        end
    else
        hustle_meter.S.lastOnline = false
        hustle_meter.S.onlineSinceMs = 0
        hustle_meter.S.onlineStatus = ("Paused: not in GTA Online. active=%s inSession=%s sessionStarted=%s signedOnline=%s playerOnline=%s")
            :format(tostring(active), tostring(inSession), tostring(started), tostring(signedOnline), tostring(playerOnline))
        return false
    end

    local stableFor = ms - (tonumber(hustle_meter.S.onlineSinceMs or ms) or ms)
    local needStable = tonumber(hustle_meter.S.onlineStableMs or 10000) or 10000
    if stableFor < needStable then
        hustle_meter.S.onlineStatus = ("Waiting for stable GTA Online session: %.1fs / %.1fs")
            :format(stableFor / 1000.0, needStable / 1000.0)
        return false
    end

    hustle_meter.S.onlineStatus = ("GTA Online ready. active=%s inSession=%s sessionStarted=%s signedOnline=%s playerOnline=%s stable=%.1fs")
        :format(tostring(active), tostring(inSession), tostring(started), tostring(signedOnline), tostring(playerOnline), stableFor / 1000.0)
    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- legacy import
-- note: older sample-only histories are upgraded into timestamped gain events.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.sample_is_all_zero(sample)
    if type(sample) ~= "table" then return false end
    return (tonumber(sample.total or 0) or 0) <= 0
        and (tonumber(sample.bank or 0) or 0) <= 0
        and (tonumber(sample.wallet or 0) or 0) <= 0
        and (tonumber(sample.wallet0 or 0) or 0) <= 0
        and (tonumber(sample.wallet1 or 0) or 0) <= 0
end

function hustle_meter.is_transient_zero_sample(samples, index)
    if type(samples) ~= "table" then return false end
    index = math.floor(tonumber(index or 0) or 0)
    if index <= 1 or index >= #samples then return false end

    local prev = samples[index - 1]
    local zero = samples[index]
    local nextSample = samples[index + 1]
    if type(prev) ~= "table" or type(zero) ~= "table" or type(nextSample) ~= "table" then
        return false
    end

    local prevTotal = tonumber(prev.total or 0) or 0
    local nextTotal = tonumber(nextSample.total or 0) or 0
    if prevTotal <= 0 or nextTotal <= 0 then return false end
    if not hustle_meter.sample_is_all_zero(zero) then return false end

    local zeroTime = tonumber(zero.t or 0) or 0
    local nextTime = tonumber(nextSample.t or 0) or 0
    if zeroTime <= 0 or nextTime <= zeroTime then return false end

    local gap = nextTime - zeroTime
    return gap <= (tonumber(hustle_meter.ZeroSampleImportMaxGapSeconds or 30) or 30)
end

function hustle_meter.import_gains_from_samples(samples)
    local gains = {}
    if type(samples) ~= "table" or #samples < 2 then return gains end

    table.sort(samples, function(a, b)
        return tonumber(a.t or 0) < tonumber(b.t or 0)
    end)

    local prev = samples[1]
    local i = 2
    while i <= #samples do
        local cur = samples[i]

        -- Build 053: a brief all-zero sample between two valid positive balances is
        -- transition/loading noise, not a legitimate new earnings baseline.
        if hustle_meter.is_transient_zero_sample(samples, i) then
            i = i + 1
            cur = samples[i]
            if cur == nil then break end
        end

        local prevTotal = tonumber(prev.total or 0) or 0
        local curTotal = tonumber(cur.total or 0) or 0
        local delta = curTotal - prevTotal

        if delta > 0 then
            gains[#gains + 1] = {
                t = tonumber(cur.t or os.time()) or os.time(),
                amount = math.floor(delta),
                totalBefore = math.floor(prevTotal),
                totalAfter = math.floor(curTotal),
                source = "imported-sample-delta"
            }
        end

        prev = cur
        i = i + 1
    end

    return gains
end

function hustle_meter.repair_existing_imported_zero_baseline_gains(samples, gains)
    if type(samples) ~= "table" or type(gains) ~= "table" then
        return gains or {}, 0, 0
    end

    table.sort(samples, function(a, b)
        return tonumber(a.t or 0) < tonumber(b.t or 0)
    end)

    local repaired = {}
    local repairedCount = 0
    local removedCount = 0

    for _, event in ipairs(gains) do
        local keep = true
        local replacement = event

        if type(event) == "table"
            and tostring(event.source or "") == "imported-sample-delta"
            and (tonumber(event.totalBefore or 0) or 0) <= 0
            and (tonumber(event.totalAfter or 0) or 0) > 0 then

            local eventTime = tonumber(event.t or 0) or 0
            local eventAfter = tonumber(event.totalAfter or 0) or 0
            local matchIndex = nil

            for i = 3, #samples do
                local sampleTime = tonumber(samples[i].t or 0) or 0
                local sampleTotal = tonumber(samples[i].total or 0) or 0
                if sampleTime == eventTime and sampleTotal == eventAfter then
                    matchIndex = i
                    break
                end
            end

            if matchIndex
                and hustle_meter.is_transient_zero_sample(samples, matchIndex - 1) then

                local prior = samples[matchIndex - 2]
                local current = samples[matchIndex]
                local priorTotal = tonumber(prior and prior.total or 0) or 0
                local currentTotal = tonumber(current and current.total or 0) or 0
                local correctedDelta = currentTotal - priorTotal

                if correctedDelta > 0 then
                    replacement = {}
                    for k, v in pairs(event) do replacement[k] = v end
                    replacement.amount = math.floor(correctedDelta)
                    replacement.totalBefore = math.floor(priorTotal)
                    replacement.totalAfter = math.floor(currentTotal)
                    replacement.source = "imported-sample-delta-zero-repaired"
                    replacement.repairedBy = hustle_meter.ZeroSampleImportRepairId
                    replacement.originalAmount = math.floor(tonumber(event.amount or 0) or 0)
                    replacement.originalTotalBefore = math.floor(tonumber(event.totalBefore or 0) or 0)
                    repairedCount = repairedCount + 1
                else
                    keep = false
                    removedCount = removedCount + 1
                end
            end
        end

        if keep then repaired[#repaired + 1] = replacement end
    end

    return repaired, repairedCount, removedCount
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- history load
-- note: loads saved ledger and safely imports older MoneyCheck/Startup histories.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.load_history()
    if hustle_meter.Tracker.loaded and hustle_meter.Tracker.loadedFile == hustle_meter.HistoryFile then return true end
    hustle_meter.Tracker.loaded = true
    hustle_meter.Tracker.loadedFile = hustle_meter.HistoryFile

    local data = hustle_meter.load_table(hustle_meter.HistoryFile)
    if type(data) == "table" then
        if type(data.samples) == "table" then hustle_meter.Tracker.samples = data.samples else hustle_meter.Tracker.samples = {} end
        if type(data.gains) == "table" then hustle_meter.Tracker.gains = data.gains else hustle_meter.Tracker.gains = {} end
        hustle_meter.Tracker.lastTotal = tonumber(data.lastTotal or data.lastBalance or data.total or 0)
        hustle_meter.Tracker.lastBank = tonumber(data.lastBank or data.bank or 0)
        hustle_meter.Tracker.lastWallet = tonumber(data.lastWallet or data.wallet or 0)
        hustle_meter.Tracker.lastWallet0 = tonumber(data.lastWallet0 or data.wallet0)
        hustle_meter.Tracker.lastWallet1 = tonumber(data.lastWallet1 or data.wallet1)
        hustle_meter.Tracker.balanceMode = tostring(data.balanceMode or "legacy-active-wallet")
        if hustle_meter.is_valid_account_name(data.accountName) then hustle_meter.Tracker.accountName = data.accountName end
        if data.accountKey then hustle_meter.Tracker.accountKey = tostring(data.accountKey) end
        hustle_meter.Tracker.gameEdition = tostring(data.gameEdition or hustle_meter.Tracker.gameEdition or "Unknown")
        hustle_meter.Tracker.cheraxEdition = tostring(data.cheraxEdition or hustle_meter.Tracker.cheraxEdition or "Unknown")
        hustle_meter.Tracker.cheraxVersion = tostring(data.cheraxVersion or hustle_meter.Tracker.cheraxVersion or "Unknown")
        hustle_meter.Tracker.cheraxBuild = tonumber(data.cheraxBuild or hustle_meter.Tracker.cheraxBuild or 0) or 0
        hustle_meter.Tracker.historyResetMigrationId = tostring(data.historyResetMigrationId or "")
        hustle_meter.Tracker.historyResetAt = tonumber(data.historyResetAt or 0) or 0
        hustle_meter.Tracker.historyResetBackup = data.historyResetBackup and tostring(data.historyResetBackup) or nil
        hustle_meter.Tracker.dualWalletRecoveryId = tostring(data.dualWalletRecoveryId or "")
        hustle_meter.Tracker.dualWalletRecoveryAt = tonumber(data.dualWalletRecoveryAt or 0) or 0
        hustle_meter.Tracker.dualWalletRecoveryBackup = data.dualWalletRecoveryBackup and tostring(data.dualWalletRecoveryBackup) or nil
        hustle_meter.Tracker.dualWalletRecoveryFromTotal = tonumber(data.dualWalletRecoveryFromTotal or 0) or 0
    else
        hustle_meter.Tracker.samples = {}; hustle_meter.Tracker.gains = {}; hustle_meter.Tracker.lastTotal = nil; hustle_meter.Tracker.lastBank = nil; hustle_meter.Tracker.lastWallet = nil; hustle_meter.Tracker.lastWallet0 = nil; hustle_meter.Tracker.lastWallet1 = nil; hustle_meter.Tracker.balanceMode = nil; hustle_meter.Tracker.historyResetMigrationId = nil; hustle_meter.Tracker.historyResetAt = nil; hustle_meter.Tracker.historyResetBackup = nil; hustle_meter.Tracker.dualWalletRecoveryId = nil; hustle_meter.Tracker.dualWalletRecoveryAt = nil; hustle_meter.Tracker.dualWalletRecoveryBackup = nil; hustle_meter.Tracker.dualWalletRecoveryFromTotal = nil
    end

    if #hustle_meter.Tracker.gains == 0 and #hustle_meter.Tracker.samples >= 2 then
        hustle_meter.Tracker.gains = hustle_meter.import_gains_from_samples(hustle_meter.Tracker.samples)
    end

    -- Build 053 one-time repair for ledgers already affected by the old importer.
    local repairAccountKey = hustle_meter.sanitize_account_key(
        hustle_meter.S.currentAccountKey or hustle_meter.Tracker.accountKey or "unknown"
    )
    if repairAccountKey ~= "unknown"
        and repairAccountKey ~= "pending"
        and not hustle_meter.zero_sample_import_repair_marker_complete(repairAccountKey) then

        local repairedGains, repairedCount, removedCount =
            hustle_meter.repair_existing_imported_zero_baseline_gains(
                hustle_meter.Tracker.samples,
                hustle_meter.Tracker.gains
            )

        local backupPath = nil
        local repairPersisted = true

        if repairedCount > 0 or removedCount > 0 then
            local archiveOk = false
            backupPath, archiveOk =
                hustle_meter.archive_pre_zero_sample_import_repair_history(repairAccountKey)

            if archiveOk then
                hustle_meter.Tracker.gains = repairedGains
                if type(data) == "table" then
                    data.gains = repairedGains
                    data.updatedAt = os.time()
                    data.scriptBuild = tostring(hustle_meter.Build or "Unknown")
                    data.zeroSampleImportRepairId = hustle_meter.ZeroSampleImportRepairId
                    data.zeroSampleImportRepairAt = os.time()
                    data.zeroSampleImportRepairCount = repairedCount
                    data.zeroSampleImportRemovedCount = removedCount

                    repairPersisted = hustle_meter.try_write_file(
                        hustle_meter.HistoryFile,
                        "return " .. hustle_meter.serialize(data, "") .. "\n"
                    )
                end
            else
                repairPersisted = false
            end
        end

        if repairPersisted then
            hustle_meter.write_zero_sample_import_repair_marker(
                repairAccountKey,
                repairedCount,
                removedCount,
                backupPath
            )

            if repairedCount > 0 or removedCount > 0 then
                hustle_meter.warn(
                    ("Build 053 repaired imported history: corrected=%d removed=%d")
                        :format(repairedCount, removedCount)
                )
            end
        else
            hustle_meter.warn(
                "Build 053 history repair was detected but could not be safely archived/persisted."
            )
        end
    end

    hustle_meter.sort_samples(); hustle_meter.sort_gains()
    local lastSample = hustle_meter.Tracker.samples[#hustle_meter.Tracker.samples]
    if lastSample and (not hustle_meter.Tracker.lastTotal or hustle_meter.Tracker.lastTotal <= 0) then
        hustle_meter.Tracker.lastTotal = tonumber(lastSample.total or 0) or 0
        hustle_meter.Tracker.lastBank = tonumber(lastSample.bank or 0) or 0
        hustle_meter.Tracker.lastWallet = tonumber(lastSample.wallet or 0) or 0
        hustle_meter.Tracker.lastWallet0 = tonumber(lastSample.wallet0)
        hustle_meter.Tracker.lastWallet1 = tonumber(lastSample.wallet1)
    end
    hustle_meter.S.sampleCount = #(hustle_meter.Tracker.samples or {})
    hustle_meter.S.gainCount = #(hustle_meter.Tracker.gains or {})
    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- rolling window cleanup
-- note: gains older than 168 real-life hours are pruned from the saved ledger.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.prune_history(nowSec)
    nowSec = tonumber(nowSec or os.time()) or os.time()
    local keepGainsAfter = nowSec - (168 * 60 * 60)
    local keepSamplesAfter = nowSec - (8 * 24 * 60 * 60)

    local keptGains = {}
    for _, gain in ipairs(hustle_meter.Tracker.gains or {}) do
        local t = tonumber(gain.t or 0) or 0
        local amount = tonumber(gain.amount or 0) or 0
        if t > keepGainsAfter and amount > 0 then keptGains[#keptGains + 1] = gain end
    end
    hustle_meter.Tracker.gains = keptGains

    local keptSamples = {}
    for _, sample in ipairs(hustle_meter.Tracker.samples or {}) do
        local t = tonumber(sample.t or 0) or 0
        if t > keepSamplesAfter then keptSamples[#keptSamples + 1] = sample end
    end
    hustle_meter.Tracker.samples = keptSamples

    hustle_meter.S.sampleCount = #keptSamples
    hustle_meter.S.gainCount = #keptGains
end

function hustle_meter.prune_samples(nowSec)
    -- Compatibility wrapper for older code paths.
    hustle_meter.prune_history(nowSec)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- history save
-- note: writes the latest ledger snapshot after pruning stale entries.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.save_history()
    hustle_meter.load_history()
    hustle_meter.prune_history(os.time())
    hustle_meter.ensure_account_dir(hustle_meter.S.currentAccountKey or hustle_meter.Tracker.accountKey or "unknown")
    local data = {
        version = hustle_meter.Version,
        updatedAt = os.time(),
        accountName = tostring(hustle_meter.S.currentAccountName or hustle_meter.Tracker.accountName or "Unknown"),
        accountKey = tostring(hustle_meter.S.currentAccountKey or hustle_meter.Tracker.accountKey or "unknown"),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or hustle_meter.Tracker.gameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or hustle_meter.Tracker.cheraxEdition or "Unknown"),
        cheraxVersion = tostring(hustle_meter.S.currentCheraxVersion or hustle_meter.Tracker.cheraxVersion or "Unknown"),
        cheraxBuild = tonumber(hustle_meter.S.currentCheraxBuild or hustle_meter.Tracker.cheraxBuild or 0) or 0,
        scriptBuild = tostring(hustle_meter.Build or "Unknown"),
        historyResetMigrationId = tostring(hustle_meter.Tracker.historyResetMigrationId or ""),
        historyResetAt = tonumber(hustle_meter.Tracker.historyResetAt or 0) or 0,
        historyResetBackup = hustle_meter.Tracker.historyResetBackup and tostring(hustle_meter.Tracker.historyResetBackup) or nil,
        dualWalletRecoveryId = tostring(hustle_meter.Tracker.dualWalletRecoveryId or ""),
        dualWalletRecoveryAt = tonumber(hustle_meter.Tracker.dualWalletRecoveryAt or 0) or 0,
        dualWalletRecoveryBackup = hustle_meter.Tracker.dualWalletRecoveryBackup and tostring(hustle_meter.Tracker.dualWalletRecoveryBackup) or nil,
        dualWalletRecoveryFromTotal = tonumber(hustle_meter.Tracker.dualWalletRecoveryFromTotal or 0) or 0,
        balanceMode = tostring(hustle_meter.Tracker.balanceMode or hustle_meter.BalanceMode),
        lastTotal = tonumber(hustle_meter.Tracker.lastTotal or hustle_meter.S.lastBalance or 0) or 0,
        lastBank = tonumber(hustle_meter.Tracker.lastBank or hustle_meter.S.lastBank or 0) or 0,
        lastWallet = tonumber(hustle_meter.Tracker.lastWallet or hustle_meter.S.lastWallet or 0) or 0,
        lastWallet0 = tonumber(hustle_meter.Tracker.lastWallet0 or 0) or 0,
        lastWallet1 = tonumber(hustle_meter.Tracker.lastWallet1 or 0) or 0,
        gains = hustle_meter.Tracker.gains or {},
        samples = hustle_meter.Tracker.samples or {}
    }
    local ok = hustle_meter.try_write_file(hustle_meter.HistoryFile, "return " .. hustle_meter.serialize(data, "") .. "\n")
    if ok then
        hustle_meter.Tracker.lastSaveMs = hustle_meter.now()
        hustle_meter.register_account(data.accountName, data.accountKey)
        hustle_meter.save_diagnostics("ledger-save")
    end
    return ok
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- sample writer
-- note: samples preserve balance checkpoints without counting spending as income.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.add_sample(total, bank, wallet, force, wallet0, wallet1)
    hustle_meter.load_history()
    local nowSec = os.time()
    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet = math.floor(tonumber(wallet or 0) or 0)
    wallet0 = wallet0 ~= nil and math.floor(tonumber(wallet0 or 0) or 0) or nil
    wallet1 = wallet1 ~= nil and math.floor(tonumber(wallet1 or 0) or 0) or nil

    local samples = hustle_meter.Tracker.samples or {}
    local last = samples[#samples]
    local changed = (not last) or tonumber(last.total or -1) ~= total or tonumber(last.bank or -1) ~= bank or tonumber(last.wallet or -1) ~= wallet
        or (wallet0 ~= nil and tonumber(last.wallet0 or -1) ~= wallet0)
        or (wallet1 ~= nil and tonumber(last.wallet1 or -1) ~= wallet1)
    local oldEnough = (not last) or (nowSec - (tonumber(last.t or 0) or 0)) >= 60

    if (not last) or changed or oldEnough or force then
        samples[#samples + 1] = {
            t = nowSec,
            accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
            accountKey = tostring(hustle_meter.S.currentAccountKey or "unknown"),
            gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
            cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
            total = total,
            bank = bank,
            wallet = wallet,
            wallet0 = wallet0,
            wallet1 = wallet1,
            balanceMode = hustle_meter.BalanceMode
        }
        hustle_meter.Tracker.samples = samples
        hustle_meter.prune_history(nowSec)
        return true
    end
    return false
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- gain event writer
-- note: only positive balance deltas become earned-money ledger events.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.add_gain_event(amount, beforeTotal, afterTotal, bank, wallet, source, scanDetails)
    hustle_meter.load_history()
    local nowSec = os.time()
    amount = math.floor(tonumber(amount or 0) or 0)
    if amount <= 0 then return false end

    local gain = {
        t = nowSec,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
        accountKey = tostring(hustle_meter.S.currentAccountKey or "unknown"),
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        amount = amount,
        totalBefore = math.floor(tonumber(beforeTotal or 0) or 0),
        totalAfter = math.floor(tonumber(afterTotal or 0) or 0),
        bank = math.floor(tonumber(bank or 0) or 0),
        wallet = math.floor(tonumber(wallet or 0) or 0),
        source = tostring(source or "balance-increase")
    }

    if type(scanDetails) == "table" then
        gain.detectedAtMs = math.floor(tonumber(scanDetails.detectedAtMs or hustle_meter.now()) or hustle_meter.now())
        gain.bankDelta = math.floor(tonumber(scanDetails.bankDelta or 0) or 0)
        gain.walletDelta = math.floor(tonumber(scanDetails.walletDelta or 0) or 0)
        gain.wallet0Delta = math.floor(tonumber(scanDetails.wallet0Delta or 0) or 0)
        gain.wallet1Delta = math.floor(tonumber(scanDetails.wallet1Delta or 0) or 0)
        gain.wallet0 = math.floor(tonumber(scanDetails.wallet0 or 0) or 0)
        gain.wallet1 = math.floor(tonumber(scanDetails.wallet1 or 0) or 0)
        gain.scanIntervalMs = math.floor(tonumber(scanDetails.scanIntervalMs or 0) or 0)
        gain.transitionBridge = scanDetails.transitionBridge == true
        gain.confirmReads = math.floor(tonumber(scanDetails.confirmReads or 0) or 0)
        gain.scanReason = tostring(scanDetails.scanReason or "")
    end

    hustle_meter.Tracker.gains = hustle_meter.Tracker.gains or {}
    hustle_meter.Tracker.gains[#hustle_meter.Tracker.gains + 1] = gain
    if hustle_meter.forensic_record_gain then hustle_meter.forensic_record_gain(gain) end
    hustle_meter.sort_gains()
    hustle_meter.prune_history(nowSec)

    hustle_meter.S.lastGainAmount = amount
    hustle_meter.S.lastGainTime = hustle_meter.time_text(nowSec)

    if hustle_meter.S.verboseLogs then
        hustle_meter.log(("Gain event: +%s at %s | before=%s after=%s source=%s")
            :format(hustle_meter.format_money(amount), hustle_meter.S.lastGainTime, hustle_meter.format_money(beforeTotal), hustle_meter.format_money(afterTotal), tostring(source or "balance-increase")))
    end

    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- rolling totals
-- note: sums gain events inside the requested real-life time window.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.get_window_gain(windowSeconds, nowSec)
    hustle_meter.load_history()
    nowSec = tonumber(nowSec or os.time()) or os.time()
    local cutoff = nowSec - (tonumber(windowSeconds or 86400) or 86400)
    local gain = 0
    for _, event in ipairs(hustle_meter.Tracker.gains or {}) do
        local t = tonumber(event.t or 0) or 0
        local amount = tonumber(event.amount or 0) or 0
        -- Strictly greater than cutoff means a gain drops out exactly when it becomes
        -- 24h/168h old. Example: $2,000 at 2:00 AM is no longer counted at 2:00 AM tomorrow.
        if t > cutoff and amount > 0 then gain = gain + amount end
    end
    return math.floor(gain)
end

function hustle_meter.recalculate_windows()
    hustle_meter.load_history()
    -- Real-life rolling windows. This uses the PC/OS timestamp, not GTA clock time.
    -- 24H entries are excluded once they are older than 86,400 seconds.
    -- 168H entries are physically pruned once they are older than 604,800 seconds.
    local nowSec = os.time()
    hustle_meter.prune_history(nowSec)
    hustle_meter.S.past24h = hustle_meter.get_window_gain(24 * 60 * 60, nowSec)
    hustle_meter.S.past168h = hustle_meter.get_window_gain(168 * 60 * 60, nowSec)
    hustle_meter.S.sampleCount = #(hustle_meter.Tracker.samples or {})
    hustle_meter.S.gainCount = #(hustle_meter.Tracker.gains or {})
end


function hustle_meter.write_support_info(reason)
    local scanner = type(hustle_meter.Scanner) == "table" and hustle_meter.Scanner or {}
    local updatedAt = tonumber(hustle_meter.S.lastSupportSnapshotAt or os.time()) or os.time()
    local currentTrackedBalance = tonumber(scanner.confirmedTotal)
    if currentTrackedBalance == nil or currentTrackedBalance <= 0 then
        currentTrackedBalance = tonumber(hustle_meter.S.lastBalance or 0) or 0
    end
    local lines = {
        "HUSTLEMETER SUPPORT INFO",
        "========================",
        "",
        "Diagnostics are captured automatically. You do NOT need to press a diagnostic button.",
        "If HustleMeter behaves incorrectly, click Create Support ZIP in the HustleMeter tab.",
        "HustleMeter creates a validated streaming HustleMeter_Support.zip and copies its exact file path for you.",
        "",
        "Folder: " .. tostring(hustle_meter.RootDir or ""),
        "Support ZIP: " .. tostring(hustle_meter.SupportZipPath or ""),
