end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- transaction scanner
-- note: rapidly watches bank + wallet through heist/session transitions and records
-- each confirmed balance step instead of waiting for the normal 10-second Online gate.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.reset_transaction_scanner(accountKey)
    hustle_meter.Scanner = {
        accountKey = tostring(accountKey or hustle_meter.S.currentAccountKey or "pending"),
        initialized = false,
        confirmedTotal = nil,
        confirmedBank = nil,
        confirmedWallet = nil,
        confirmedWallet0 = nil,
        confirmedWallet1 = nil,
        candidate = nil,
        trustedUntilMs = 0,
        burstUntilMs = 0,
        lastOnlineNow = nil,
        lastStrongOnlineNow = nil,
        strongOnlineSinceMs = 0,
        inTransition = false,
        transitionId = 0,
        transitionStartedMs = 0,
        preTransitionTotal = nil,
        preTransitionBank = nil,
        preTransitionWallet = nil,
        preTransitionWallet0 = nil,
        preTransitionWallet1 = nil,
        resumeStartedMs = 0,
        resumeCandidate = nil,
        anchorActive = false,
        anchorTotal = nil,
        anchorBank = nil,
        anchorWallet = nil,
        anchorWallet0 = nil,
        anchorWallet1 = nil,
        anchorStartedMs = 0,
        anchorUntilMs = 0,
        anchorCreditedAbove = 0,
        anchorCandidate = nil,
        anchorLastSuppressedSignature = nil,
        anchorLastGainSignature = nil,
        dualWalletRecoveryEvaluated = false,
        debugTailUntilMs = 0,
        lastDebugTraceMs = 0,
        lastFlags = nil,
        lastAttemptMs = 0,
        lastReadMs = 0,
        lastMaintenanceMs = 0,
        lastSaveMs = 0,
        dirty = false,
        nextDelayMs = tonumber(hustle_meter.S.scannerIdleMs or 100) or 100
    }
end

function hustle_meter.get_transaction_scanner()
    if type(hustle_meter.Scanner) ~= "table" then
        hustle_meter.reset_transaction_scanner(hustle_meter.S.currentAccountKey)
    end
    return hustle_meter.Scanner
end

function hustle_meter.same_money_snapshot(a, total, bank, wallet, wallet0, wallet1)
    return type(a) == "table"
        and math.floor(tonumber(a.total or -1) or -1) == math.floor(tonumber(total or -2) or -2)
        and math.floor(tonumber(a.bank or -1) or -1) == math.floor(tonumber(bank or -2) or -2)
        and math.floor(tonumber(a.wallet or -1) or -1) == math.floor(tonumber(wallet or -2) or -2)
        and math.floor(tonumber(a.wallet0 or -1) or -1) == math.floor(tonumber(wallet0 or -2) or -2)
        and math.floor(tonumber(a.wallet1 or -1) or -1) == math.floor(tonumber(wallet1 or -2) or -2)
end

function hustle_meter.transaction_scan_allowed(nowMs)
    local scanner = hustle_meter.get_transaction_scanner()
    nowMs = tonumber(nowMs or hustle_meter.now()) or hustle_meter.now()

    local flags = hustle_meter.capture_session_flags()
    scanner.lastFlags = flags
    local onlineNow = (flags.active == true) or (flags.inSession == true) or (flags.started == true)
    local strongOnlineNow = flags.active == true and flags.inSession == true and flags.started == true
        and flags.loading ~= true and flags.playerSwitch ~= true
    local previousOnline = scanner.lastOnlineNow
    local previousStrong = scanner.lastStrongOnlineNow

    -- Strong Online means every session flag agrees AND GTA is not loading/switching.
    -- Build 002 only watched the weaker OR-based Online state, so a Story transition
    -- could slip through if one session flag stayed true while the money natives changed.
    if strongOnlineNow then
        if (tonumber(scanner.strongOnlineSinceMs or 0) or 0) <= 0 then
            scanner.strongOnlineSinceMs = nowMs
            hustle_meter.debug_event("STRONG_ONLINE_BEGIN", hustle_meter.session_flags_text(flags), "")
        end
    else
        if (tonumber(scanner.strongOnlineSinceMs or 0) or 0) > 0 then
            hustle_meter.debug_event("STRONG_ONLINE_LOST", hustle_meter.session_flags_text(flags), "strongForMs=" .. tostring(nowMs - scanner.strongOnlineSinceMs))
        end
        scanner.strongOnlineSinceMs = 0
    end

    local function begin_transition(trigger)
        if scanner.inTransition then return end
        if scanner.anchorActive == true then
            hustle_meter.debug_event("POST_TRANSITION_ANCHOR_INTERRUPTED", "A new session transition started before the prior anchor grace window finished.",
                ("trigger=%s anchorTotal=%s creditedAbove=%s confirmed=%s")
                    :format(tostring(trigger), tostring(scanner.anchorTotal or 0), tostring(scanner.anchorCreditedAbove or 0), tostring(scanner.confirmedTotal or 0)))
            scanner.anchorActive = false
            scanner.anchorCandidate = nil
            scanner.anchorUntilMs = 0
        end
        scanner.inTransition = true
        scanner.transitionId = (tonumber(scanner.transitionId or 0) or 0) + 1
        scanner.transitionStartedMs = nowMs
        scanner.preTransitionTotal = tonumber(scanner.confirmedTotal or hustle_meter.Tracker.lastTotal or 0) or 0
        scanner.preTransitionBank = tonumber(scanner.confirmedBank or hustle_meter.Tracker.lastBank or 0) or 0
        scanner.preTransitionWallet = tonumber(scanner.confirmedWallet or hustle_meter.Tracker.lastWallet or 0) or 0
        scanner.preTransitionWallet0 = tonumber(scanner.confirmedWallet0 or hustle_meter.Tracker.lastWallet0 or 0) or 0
        scanner.preTransitionWallet1 = tonumber(scanner.confirmedWallet1 or hustle_meter.Tracker.lastWallet1 or 0) or 0
        scanner.resumeStartedMs = 0
        scanner.resumeCandidate = nil
        scanner.candidate = nil
        scanner.strongOnlineSinceMs = 0
        scanner.burstUntilMs = nowMs + (tonumber(hustle_meter.S.scannerBurstDurationMs or 45000) or 45000)
        scanner.debugTailUntilMs = nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000)
        hustle_meter.S.scannerTransitionCount = (tonumber(hustle_meter.S.scannerTransitionCount or 0) or 0) + 1
        hustle_meter.debug_event("TRANSITION_GUARD_STARTED",
            "Frozen balance because the Online state stopped being fully trustworthy.",
            ("trigger=%s preTotal=%s preBank=%s preWallet=%s w0=%s w1=%s | %s")
                :format(tostring(trigger), tostring(scanner.preTransitionTotal), tostring(scanner.preTransitionBank), tostring(scanner.preTransitionWallet),
                    tostring(scanner.preTransitionWallet0), tostring(scanner.preTransitionWallet1), hustle_meter.session_flags_text(flags)))
        hustle_meter.write_last_transition_snapshot("transition-guard-started", { trigger = trigger, flags = flags })
    end

    -- Start guarding on ANY loss of a previously trustworthy full Online state. This
    -- catches Story/player-switch/loading transitions even when one weak session flag
    -- remains true, which is a likely explanation for the $2M -> $165M reproduction.
    if previousStrong == nil and onlineNow and strongOnlineNow ~= true then
        begin_transition("startup-partial-online")
    elseif previousStrong == true and strongOnlineNow == false then
        begin_transition("strong-online-lost")
    elseif previousOnline == true and onlineNow == false then
        begin_transition("weak-online-lost")
    elseif scanner.inTransition ~= true and (flags.loading == true or flags.playerSwitch == true) and previousOnline == true then
        begin_transition(flags.playerSwitch and "player-switch" or "loading-screen")
    end

    -- Mark the first moment strong Online has genuinely returned. Actual money
    -- reconciliation still waits for the separate 5s strong-session + 10s full-snapshot gates.
    if scanner.inTransition and strongOnlineNow and previousStrong ~= true then
        scanner.resumeStartedMs = nowMs
        scanner.resumeCandidate = nil
        scanner.candidate = nil
        scanner.debugTailUntilMs = nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000)
        hustle_meter.debug_event("TRANSITION_STRONG_ONLINE_RETURNED",
            "All Online session flags are back and loading/player-switch are clear; beginning money validation.",
            hustle_meter.session_flags_text(flags))
        hustle_meter.write_last_transition_snapshot("strong-online-returned", { flags = flags })
    end

    scanner.lastOnlineNow = onlineNow
    scanner.lastStrongOnlineNow = strongOnlineNow

    if onlineNow then
        scanner.trustedUntilMs = nowMs + (tonumber(hustle_meter.S.scannerTransitionBridgeMs or 120000) or 120000)
    end

    -- While a transition is active, anything short of strong Online is diagnostics-only.
    -- This remains true even if one weak session flag claims we are technically Online.
    local bridge = scanner.inTransition == true and strongOnlineNow ~= true

    if not onlineNow and scanner.inTransition ~= true then
        hustle_meter.S.scannerStatus = "Paused: waiting for GTA Online transaction access."
        return false, false, false, flags
    end

    if bridge then
        scanner.burstUntilMs = math.max(tonumber(scanner.burstUntilMs or 0) or 0,
            nowMs + (tonumber(hustle_meter.S.scannerBurstDurationMs or 45000) or 45000))
        hustle_meter.S.scannerStatus = "Transition guard: raw reads logged only; baseline frozen until strong Online returns."
    elseif scanner.inTransition then
        hustle_meter.S.scannerStatus = "Strong Online returned; validating full money snapshot before reconciliation."
    else
        hustle_meter.S.scannerStatus = "Scanning authoritative GTA Online balance."
    end

    return true, bridge, onlineNow, flags
end

function hustle_meter.classify_scan_source(bankDelta, wallet0Delta, wallet1Delta, bridge)
    bankDelta = tonumber(bankDelta or 0) or 0
    wallet0Delta = tonumber(wallet0Delta or 0) or 0
    wallet1Delta = tonumber(wallet1Delta or 0) or 0
    local walletPositive = wallet0Delta > 0 or wallet1Delta > 0
    if bridge then return "heist-transition-scan" end
    if bankDelta > 0 and walletPositive then return "bank-wallet-transaction-scan" end
    if bankDelta > 0 then return "bank-transaction-scan" end
    if walletPositive then return "character-wallet-transaction-scan" end
    return "balance-transaction-scan"
end

function hustle_meter.commit_scanned_snapshot(total, bank, wallet, wallet0, wallet1, bridge, confirmReads, reason)
    local scanner = hustle_meter.get_transaction_scanner()
    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet = math.floor(tonumber(wallet or 0) or 0)
    wallet0 = math.floor(tonumber(wallet0 or 0) or 0)
    wallet1 = math.floor(tonumber(wallet1 or 0) or 0)

    local previousTotal = tonumber(scanner.confirmedTotal)
    local previousBank = tonumber(scanner.confirmedBank)
    local previousWallet = tonumber(scanner.confirmedWallet)
    local previousWallet0 = tonumber(scanner.confirmedWallet0)
    local previousWallet1 = tonumber(scanner.confirmedWallet1)

    if previousTotal == nil then previousTotal = tonumber(hustle_meter.Tracker.lastTotal or 0) or 0 end
    if previousBank == nil then previousBank = tonumber(hustle_meter.Tracker.lastBank or 0) or 0 end
    if previousWallet == nil then previousWallet = tonumber(hustle_meter.Tracker.lastWallet or 0) or 0 end
    if previousWallet0 == nil then previousWallet0 = tonumber(hustle_meter.Tracker.lastWallet0 or 0) or 0 end
    if previousWallet1 == nil then previousWallet1 = tonumber(hustle_meter.Tracker.lastWallet1 or 0) or 0 end

    if previousTotal <= 0 then
        scanner.confirmedTotal = total
        scanner.confirmedBank = bank
        scanner.confirmedWallet = wallet
        scanner.confirmedWallet0 = wallet0
        scanner.confirmedWallet1 = wallet1
        scanner.initialized = true
        hustle_meter.Tracker.lastTotal = total
        hustle_meter.Tracker.lastBank = bank
        hustle_meter.Tracker.lastWallet = wallet
        hustle_meter.Tracker.lastWallet0 = wallet0
        hustle_meter.Tracker.lastWallet1 = wallet1
        hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode
        hustle_meter.S.lastBalance = total
        hustle_meter.S.lastBank = bank
        hustle_meter.S.lastWallet = wallet
        hustle_meter.add_sample(total, bank, wallet, true, wallet0, wallet1)
        scanner.dirty = true
        hustle_meter.S.lastStatus = "Transaction scanner baseline captured."
        hustle_meter.debug_event("BASELINE_CAPTURED", "Initial scanner baseline captured.",
            ("total=%s bank=%s wallet=%s w0=%s w1=%s"):format(tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1)))
        return true
    end

    local delta = total - previousTotal
    local bankDelta = bank - previousBank
    local walletDelta = wallet - previousWallet
    local wallet0Delta = wallet0 - previousWallet0
    local wallet1Delta = wallet1 - previousWallet1
    local changed = delta ~= 0 or bankDelta ~= 0 or walletDelta ~= 0 or wallet0Delta ~= 0 or wallet1Delta ~= 0

    scanner.confirmedTotal = total
    scanner.confirmedBank = bank
    scanner.confirmedWallet = wallet
    scanner.confirmedWallet0 = wallet0
    scanner.confirmedWallet1 = wallet1
    scanner.initialized = true
    hustle_meter.Tracker.lastTotal = total
    hustle_meter.Tracker.lastBank = bank
    hustle_meter.Tracker.lastWallet = wallet
    hustle_meter.Tracker.lastWallet0 = wallet0
    hustle_meter.Tracker.lastWallet1 = wallet1
    hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode
    hustle_meter.S.lastBalance = total
    hustle_meter.S.lastBank = bank
    hustle_meter.S.lastWallet = wallet

    if not changed then return false end

    local added = false
    if delta > 0 then
        local nowMs = hustle_meter.now()
        local source
        if reason == "post-transition-reconcile" then
            source = "session-transition-reconcile"
        elseif reason == "post-transition-anchor-gain" then
            source = "session-transition-anchor-gain"
        else
            source = hustle_meter.classify_scan_source(bankDelta, wallet0Delta, wallet1Delta, bridge)
        end
        added = hustle_meter.add_gain_event(delta, previousTotal, total, bank, wallet, source, {
            detectedAtMs = nowMs,
            bankDelta = bankDelta,
            walletDelta = walletDelta,
            wallet0Delta = wallet0Delta,
            wallet1Delta = wallet1Delta,
            wallet0 = wallet0,
            wallet1 = wallet1,
            scanIntervalMs = tonumber(scanner.nextDelayMs or 0) or 0,
            transitionBridge = bridge == true,
            confirmReads = confirmReads or 0,
            scanReason = tostring(reason or "")
        })
        scanner.burstUntilMs = nowMs + (tonumber(hustle_meter.S.scannerBurstDurationMs or 45000) or 45000)
        hustle_meter.S.scannerDetectedCount = (tonumber(hustle_meter.S.scannerDetectedCount or 0) or 0) + 1
        hustle_meter.S.lastStatus = ("Transaction captured: +%s%s")
            :format(hustle_meter.format_money(delta), bridge and " during heist/session transition." or ".")
        hustle_meter.debug_event("GAIN_COMMITTED", "Positive GTA$ balance step added to rolling earnings.",
            ("delta=%s before=%s after=%s bankDelta=%s walletDelta=%s w0Delta=%s w1Delta=%s reason=%s reads=%s")
                :format(tostring(delta), tostring(previousTotal), tostring(total), tostring(bankDelta), tostring(walletDelta), tostring(wallet0Delta), tostring(wallet1Delta), tostring(reason), tostring(confirmReads)))
    elseif delta < 0 then
        hustle_meter.S.lastStatus = "Balance decrease confirmed; baseline updated without adding earnings."
        hustle_meter.debug_event("DECREASE_COMMITTED", "Balance decrease accepted as baseline-only change.",
            ("delta=%s before=%s after=%s bankDelta=%s walletDelta=%s reason=%s")
                :format(tostring(delta), tostring(previousTotal), tostring(total), tostring(bankDelta), tostring(walletDelta), tostring(reason)))
    else
        hustle_meter.S.lastStatus = "Bank/wallet transfer confirmed; earnings total unchanged."
        hustle_meter.debug_event("TRANSFER_COMMITTED", "Total unchanged while bank/wallet components moved.",
            ("total=%s bankDelta=%s walletDelta=%s w0Delta=%s w1Delta=%s")
                :format(tostring(total), tostring(bankDelta), tostring(walletDelta), tostring(wallet0Delta), tostring(wallet1Delta)))
    end

    hustle_meter.add_sample(total, bank, wallet, true, wallet0, wallet1)
    scanner.dirty = true
    return added or changed
end

function hustle_meter.scan_money_transactions(force)
    if not hustle_meter.S.enabled or hustle_meter.S.transactionScannerEnabled ~= true then return false end

    local nowMs = hustle_meter.now()
    local scanner = hustle_meter.get_transaction_scanner()
    local minimumDelay = math.max(25, math.floor(tonumber(scanner.nextDelayMs or hustle_meter.S.scannerIdleMs or 100) or 100))
    if force ~= true and nowMs - (tonumber(scanner.lastAttemptMs or 0) or 0) < minimumDelay then
        return true
    end
    scanner.lastAttemptMs = nowMs

    -- Detect session transitions before resolving the Rockstar username. During
    -- Story/loading screens GTA can temporarily return "**Invalid**" for the name;
    -- transition state must still be recorded without switching/creating an account.
    local allowed, bridge, onlineNow, sessionFlags = hustle_meter.transaction_scan_allowed(nowMs)
    if not allowed then
        scanner.nextDelayMs = 250
        return false
    end

    if not bridge then
        if not hustle_meter.ensure_current_account(force == true) then
            hustle_meter.S.scannerStatus = "Waiting for valid Rockstar username before scanning."
            scanner.nextDelayMs = 250
            return false
        end

        if tostring(scanner.accountKey or "") ~= tostring(hustle_meter.S.currentAccountKey or "") then
            hustle_meter.reset_transaction_scanner(hustle_meter.S.currentAccountKey)
            scanner = hustle_meter.get_transaction_scanner()
            -- Preserve the transition state if the account key only changed because
            -- v1.0.4 added LE/EE isolation while returning to the same Rockstar user.
            if onlineNow then
                scanner.lastOnlineNow = true
            end
        end
    end

    hustle_meter.load_history()

    local total, bank, wallet, details, moneyMeta = hustle_meter.read_money_balance()
    local wallet0 = moneyMeta and tonumber(moneyMeta.wallet0 or 0) or 0
    local wallet1 = moneyMeta and tonumber(moneyMeta.wallet1 or 0) or 0
    hustle_meter.S.lastReadDetails = tostring(details or "")
    scanner.lastReadMs = nowMs
    local consistency = hustle_meter.money_consistency(total, bank, wallet0, wallet1)
    local forensicStage = bridge and "transition-bridge-read" or (scanner.inTransition and "post-transition-raw" or "online-read")
    hustle_meter.trace_scan(forensicStage,
        nowMs, total, bank, wallet, wallet0, wallet1, sessionFlags, consistency, details)
    hustle_meter.forensic_capture_money_snapshot(
        forensicStage, nowMs, total, bank, wallet, wallet0, wallet1, sessionFlags, consistency, details
    )

    if total == nil or (total <= 0 and (tonumber(hustle_meter.Tracker.lastTotal or scanner.confirmedTotal or 0) or 0) > 0) then
        hustle_meter.S.scannerStatus = bridge and "Transition guard rejected an invalid/zero money snapshot." or "Waiting for a valid Online money snapshot."
        if bridge or scanner.inTransition then
            hustle_meter.S.scannerInvalidTransitionSnapshots = (tonumber(hustle_meter.S.scannerInvalidTransitionSnapshots or 0) or 0) + 1
            hustle_meter.debug_event("INVALID_MONEY_SNAPSHOT", "Rejected nil/zero balance while a prior positive baseline exists.",
                ("total=%s bank=%s wallet=%s w0=%s w1=%s | %s")
                    :format(tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1), hustle_meter.session_flags_text(sessionFlags)))
        end
        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        return false
    end

    -- Never import/migrate or change the confirmed baseline while session flags are
    -- in the transition bridge. These reads are diagnostics only. This is the core
    -- v1.0.4 protection against EE bank=0 / stale-wallet rebound false earnings.
    if bridge then
        scanner.candidate = nil
        scanner.resumeCandidate = nil
        hustle_meter.S.scannerHeldTransitionSnapshots = (tonumber(hustle_meter.S.scannerHeldTransitionSnapshots or 0) or 0) + 1
        scanner.debugTailUntilMs = math.max(tonumber(scanner.debugTailUntilMs or 0) or 0,
            nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000))
        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        return true
    end

    -- After any Story/Online/heist transition, hold the old confirmed baseline and
    -- wait until the returned Online balance remains stable for both a time window
    -- and several reads. Then reconcile exactly once against the pre-transition total.
    if scanner.inTransition and onlineNow then
        if (tonumber(scanner.resumeStartedMs or 0) or 0) <= 0 then scanner.resumeStartedMs = nowMs end

        -- Build 003 requires the ENTIRE money snapshot to remain unchanged, not just
        -- NETWORK_GET_VC_BALANCE(). Build 002 only compared total, allowing a stable
        -- bogus total to pass while bank/wallet natives were still changing underneath it.
        local rc = scanner.resumeCandidate
        if hustle_meter.same_money_snapshot(rc, total, bank, wallet, wallet0, wallet1) then
            rc.reads = (tonumber(rc.reads or 1) or 1) + 1
            rc.lastMs = nowMs
        else
            scanner.resumeCandidate = {
                total = total, bank = bank, wallet = wallet, wallet0 = wallet0, wallet1 = wallet1,
                reads = 1, firstMs = nowMs, lastMs = nowMs
            }
            rc = scanner.resumeCandidate
            hustle_meter.debug_event("POST_TRANSITION_CANDIDATE_CHANGED", "Full money snapshot changed; stability timer restarted.",
                ("total=%s bank=%s wallet=%s w0=%s w1=%s")
                    :format(tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1)))
        end

        local stableMs = math.max(2000, math.floor(tonumber(hustle_meter.S.scannerPostTransitionStableMs or 10000) or 10000))
        local stableReads = math.max(5, math.floor(tonumber(hustle_meter.S.scannerPostTransitionStableReads or 20) or 20))
        local strongNeedMs = math.max(1000, math.floor(tonumber(hustle_meter.S.scannerPostTransitionStrongSessionMs or 5000) or 5000))
        local oldTotal = tonumber(scanner.preTransitionTotal or scanner.confirmedTotal or hustle_meter.Tracker.lastTotal or 0) or 0
        local oldBank = tonumber(scanner.preTransitionBank or scanner.confirmedBank or hustle_meter.Tracker.lastBank or 0) or 0
        local oldWallet = tonumber(scanner.preTransitionWallet or scanner.confirmedWallet or hustle_meter.Tracker.lastWallet or 0) or 0
        local oldWallet0 = tonumber(scanner.preTransitionWallet0 or scanner.confirmedWallet0 or hustle_meter.Tracker.lastWallet0 or 0) or 0
        local oldWallet1 = tonumber(scanner.preTransitionWallet1 or scanner.confirmedWallet1 or hustle_meter.Tracker.lastWallet1 or 0) or 0

        local timeStable = nowMs - (tonumber(rc.firstMs or nowMs) or nowMs) >= stableMs
        local readsStable = (tonumber(rc.reads or 0) or 0) >= stableReads
        local strongForMs = (tonumber(scanner.strongOnlineSinceMs or 0) or 0) > 0 and (nowMs - scanner.strongOnlineSinceMs) or 0
        local strongSessionReady = scanner.lastStrongOnlineNow == true and strongForMs >= strongNeedMs
        local rcConsistency = hustle_meter.money_consistency(rc.total, rc.bank, rc.wallet0, rc.wallet1)
        local moneyConsistent = hustle_meter.S.scannerRequireMoneyConsistency ~= true or rcConsistency.consistent == true
        local bankRestored = not (oldBank > 0 and (tonumber(rc.bank or 0) or 0) <= 0)
        local noLoadingOrSwitch = not (sessionFlags and (sessionFlags.loading == true or sessionFlags.playerSwitch == true))
        local transitionReady = timeStable and readsStable and strongSessionReady and moneyConsistent and bankRestored and noLoadingOrSwitch

        local validationNote = ("stable=%s/%sms reads=%s/%s strong=%sms/%sms consistency=%s match=%s diff0=%s diff1=%s diffCombined=%s bankRestored=%s loading=%s playerSwitch=%s")
            :format(tostring(timeStable), tostring(stableMs), tostring(rc.reads or 0), tostring(stableReads), tostring(strongForMs), tostring(strongNeedMs),
                tostring(moneyConsistent), tostring(rcConsistency.matchMode), tostring(rcConsistency.diff0), tostring(rcConsistency.diff1), tostring(rcConsistency.diffCombined),
                tostring(bankRestored), tostring(sessionFlags and sessionFlags.loading == true), tostring(sessionFlags and sessionFlags.playerSwitch == true))
        hustle_meter.trace_scan("post-transition-validation", nowMs, rc.total, rc.bank, rc.wallet, rc.wallet0, rc.wallet1,
            sessionFlags, rcConsistency, validationNote)

        if transitionReady then
            local didReset, resetReason = hustle_meter.perform_one_time_history_reset(rc.total, rc.bank, rc.wallet, rc.wallet0, rc.wallet1)
            if didReset then
                scanner = hustle_meter.get_transaction_scanner()
                scanner.inTransition = false
                scanner.preTransitionTotal = nil
                scanner.preTransitionBank = nil
                scanner.preTransitionWallet = nil
                scanner.preTransitionWallet0 = nil
                scanner.preTransitionWallet1 = nil
                scanner.resumeStartedMs = 0
                scanner.resumeCandidate = nil
                scanner.candidate = nil
                scanner.debugTailUntilMs = nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000)
                scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
                hustle_meter.S.scannerStatus = "Post-transition balance validated; clean baseline created."
                hustle_meter.debug_event("POST_TRANSITION_RESET_BASELINE", "History migration used a validated post-transition balance as the clean baseline.", validationNote)
                hustle_meter.write_last_transition_snapshot("reset-baseline-complete", { validation = validationNote })
                return true
            elseif resetReason == "archive-failed" or resetReason == "save-failed" then
                hustle_meter.S.scannerStatus = "History reset is waiting for storage to become writable."
                scanner.nextDelayMs = 500
                return false
            end

            -- Build 026 recovery: if an older build demonstrably quarantined this
            -- exact baseline because both GTA Online character wallets contributed to
            -- NETWORK_GET_VC_BALANCE(), repair the stale baseline before the anchor can
            -- mistake the entire historical gap for new earnings.
            local recoveredLegacyDualWallet, recoveryReason = hustle_meter.perform_legacy_dual_wallet_recovery(
                rc.total, rc.bank, rc.wallet, rc.wallet0, rc.wallet1
            )
            if recoveredLegacyDualWallet then
                scanner = hustle_meter.get_transaction_scanner()
                scanner.inTransition = false
                scanner.preTransitionTotal = nil
                scanner.preTransitionBank = nil
                scanner.preTransitionWallet = nil
                scanner.preTransitionWallet0 = nil
                scanner.preTransitionWallet1 = nil
                scanner.resumeStartedMs = 0
                scanner.resumeCandidate = nil
                scanner.candidate = nil
                scanner.anchorActive = false
                scanner.anchorCandidate = nil
                scanner.debugTailUntilMs = nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000)
                scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
                hustle_meter.S.scannerStatus = "Legacy dual-wallet baseline recovered; normal transaction scanning resumed."
                hustle_meter.write_last_transition_snapshot("dual-wallet-recovery-complete", {
                    validation = validationNote,
                    recoveryReason = recoveryReason
                })
                return true
            elseif recoveryReason == "archive-failed" or recoveryReason == "save-failed" then
                hustle_meter.S.scannerStatus = "Dual-wallet recovery is waiting for storage to become writable."
                scanner.nextDelayMs = 500
                return false
            end

            -- Migration was already completed. Do NOT immediately lower the confirmed
            -- baseline to the returned snapshot. GTA can return slightly below the old
            -- total and then restore that amount seconds later; build 003 would see the
            -- restoration as income. Instead preserve the exact pre-transition total for
            -- a 30-second grace window and only credit stable money ABOVE that anchor.
            scanner.confirmedTotal = oldTotal
            scanner.confirmedBank = oldBank
            scanner.confirmedWallet = oldWallet
            scanner.confirmedWallet0 = oldWallet0
            scanner.confirmedWallet1 = oldWallet1
            scanner.inTransition = false
            scanner.anchorActive = true
            scanner.anchorTotal = oldTotal
            scanner.anchorBank = oldBank
            scanner.anchorWallet = oldWallet
            scanner.anchorWallet0 = oldWallet0
            scanner.anchorWallet1 = oldWallet1
            scanner.anchorStartedMs = nowMs
            scanner.anchorUntilMs = nowMs + math.max(10000, math.floor(tonumber(hustle_meter.S.scannerPostTransitionAnchorMs or 30000) or 30000))
            scanner.anchorCreditedAbove = 0
            scanner.anchorCandidate = nil
            scanner.anchorLastSuppressedSignature = nil
            scanner.anchorLastGainSignature = nil
            scanner.resumeStartedMs = 0
            scanner.resumeCandidate = nil
            scanner.candidate = nil
            scanner.debugTailUntilMs = nowMs + math.max(tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000,
                math.max(10000, math.floor(tonumber(hustle_meter.S.scannerPostTransitionAnchorMs or 30000) or 30000)) + 30000)
            hustle_meter.S.scannerPostTransitionAnchors = (tonumber(hustle_meter.S.scannerPostTransitionAnchors or 0) or 0) + 1
            hustle_meter.S.scannerStatus = "Post-transition anchor active: synchronization returns cannot become earnings."
            hustle_meter.debug_event("POST_TRANSITION_ANCHOR_STARTED", "Validated return snapshot is being observed behind the frozen pre-transition balance anchor.",
                validationNote .. " anchor=" .. tostring(oldTotal) .. " initialReturn=" .. tostring(rc.total) .. " initialDelta=" .. tostring((tonumber(rc.total or 0) or 0) - oldTotal))
            hustle_meter.write_last_transition_snapshot("anchor-started", { validation = validationNote, initialReturn = rc })
        else
            local reasonParts = {}
            if not timeStable then reasonParts[#reasonParts + 1] = "snapshot-not-stable-10s" end
            if not readsStable then reasonParts[#reasonParts + 1] = "not-enough-identical-reads" end
            if not strongSessionReady then reasonParts[#reasonParts + 1] = "full-session-flags-not-stable" end
            if not moneyConsistent then reasonParts[#reasonParts + 1] = "active-total-does-not-match-bank-plus-known-wallets" end
            if not bankRestored then reasonParts[#reasonParts + 1] = "bank-temporarily-zero" end
            if not noLoadingOrSwitch then reasonParts[#reasonParts + 1] = "loading-or-player-switch-active" end
            local reasonText = table.concat(reasonParts, ",")
            hustle_meter.S.scannerStatus = "Post-transition money quarantined: " .. (reasonText ~= "" and reasonText or "validation pending")

            -- Once the candidate has otherwise been around long enough to be meaningful,
            -- preserve one structured suspicious record instead of spamming the file every 50ms.
            if timeStable and readsStable and (not moneyConsistent or not bankRestored or not strongSessionReady or not noLoadingOrSwitch) then
                local signature = table.concat({ tostring(rc.total), tostring(rc.bank), tostring(rc.wallet0), tostring(rc.wallet1), reasonText }, ":")
                if scanner.lastQuarantineSignature ~= signature then
                    scanner.lastQuarantineSignature = signature
                    hustle_meter.record_suspicious_transition(reasonText, {
                        total = rc.total, bank = rc.bank, wallet = rc.wallet, wallet0 = rc.wallet0, wallet1 = rc.wallet1,
                        delta = (tonumber(rc.total or 0) or 0) - oldTotal,
                        preTotal = oldTotal, preBank = oldBank, preWallet = oldWallet, preWallet0 = oldWallet0, preWallet1 = oldWallet1,
                        reads = rc.reads, stableForMs = nowMs - (tonumber(rc.firstMs or nowMs) or nowMs),
                        strongForMs = strongForMs, consistency = rcConsistency, flags = sessionFlags
                    })
                    hustle_meter.write_last_transition_snapshot("quarantined", { reason = reasonText, validation = validationNote })
                end
            end
        end

        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        return true
    end

    -- Build 004 post-transition anchor. For a short grace period after the returned
    -- Online snapshot is fully validated, keep the exact pre-transition GTA$ total as
    -- the accounting floor. GTA may temporarily come back below this amount and then
    -- restore it; those restorations are synchronization, not income. Only a stable,
    -- money-consistent amount ABOVE the original anchor can create earnings.
    if scanner.anchorActive == true then
        local anchorTotal = tonumber(scanner.anchorTotal or scanner.confirmedTotal or hustle_meter.Tracker.lastTotal or 0) or 0
        local creditedAbove = math.max(0, tonumber(scanner.anchorCreditedAbove or 0) or 0)
        local ac = scanner.anchorCandidate
        if hustle_meter.same_money_snapshot(ac, total, bank, wallet, wallet0, wallet1) then
            ac.reads = (tonumber(ac.reads or 1) or 1) + 1
            ac.lastMs = nowMs
        else
            scanner.anchorCandidate = {
                total = total, bank = bank, wallet = wallet, wallet0 = wallet0, wallet1 = wallet1,
                reads = 1, firstMs = nowMs, lastMs = nowMs
            }
            ac = scanner.anchorCandidate
            hustle_meter.debug_event("POST_TRANSITION_ANCHOR_CANDIDATE", "Anchor-window money snapshot changed; stability timer restarted.",
                ("anchor=%s credited=%s total=%s bank=%s wallet=%s w0=%s w1=%s")
                    :format(tostring(anchorTotal), tostring(creditedAbove), tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1)))
        end

        local acConsistency = hustle_meter.money_consistency(ac.total, ac.bank, ac.wallet0, ac.wallet1)
        local strongForMs = (tonumber(scanner.strongOnlineSinceMs or 0) or 0) > 0 and (nowMs - scanner.strongOnlineSinceMs) or 0
        local stableForMs = nowMs - (tonumber(ac.firstMs or nowMs) or nowMs)
        local excess = (tonumber(ac.total or 0) or 0) - anchorTotal
        local potentialNewGain = excess - creditedAbove
        local gainStableMs = math.max(1000, math.floor(tonumber(hustle_meter.S.scannerAnchorGainStableMs or 5000) or 5000))
        local gainStableReads = math.max(5, math.floor(tonumber(hustle_meter.S.scannerAnchorGainStableReads or 10) or 10))
        if potentialNewGain >= 10000000 then
            gainStableMs = math.max(gainStableMs, 10000)
            gainStableReads = math.max(gainStableReads, 20)
        end
        local gainReady = potentialNewGain > 0
            and stableForMs >= gainStableMs
            and (tonumber(ac.reads or 0) or 0) >= gainStableReads
            and acConsistency.consistent == true
            and scanner.lastStrongOnlineNow == true
            and strongForMs >= 5000
            and not (sessionFlags and (sessionFlags.loading == true or sessionFlags.playerSwitch == true))

        hustle_meter.trace_scan("post-transition-anchor", nowMs, ac.total, ac.bank, ac.wallet, ac.wallet0, ac.wallet1,
            sessionFlags, acConsistency,
            ("anchor=%s credited=%s excess=%s potentialNewGain=%s reads=%s/%s stable=%sms/%sms strong=%sms remaining=%sms")
                :format(tostring(anchorTotal), tostring(creditedAbove), tostring(excess), tostring(potentialNewGain),
                    tostring(ac.reads or 0), tostring(gainStableReads), tostring(stableForMs), tostring(gainStableMs), tostring(strongForMs),
                    tostring(math.max(0, (tonumber(scanner.anchorUntilMs or 0) or 0) - nowMs))))

        if gainReady then
            -- Keep the confirmed baseline at anchor + previously credited excess so a
            -- later sync dip cannot erase the accounting reference or be re-counted.
            local expectedConfirmed = anchorTotal + creditedAbove
            scanner.confirmedTotal = expectedConfirmed
            hustle_meter.Tracker.lastTotal = expectedConfirmed
            local beforeGain = expectedConfirmed
            hustle_meter.commit_scanned_snapshot(ac.total, ac.bank, ac.wallet, ac.wallet0, ac.wallet1,
                false, ac.reads or gainStableReads, "post-transition-anchor-gain")
            scanner.anchorCreditedAbove = math.max(creditedAbove, (tonumber(ac.total or 0) or 0) - anchorTotal)
            hustle_meter.S.scannerAnchorGainCommits = (tonumber(hustle_meter.S.scannerAnchorGainCommits or 0) or 0) + 1
            hustle_meter.debug_event("POST_TRANSITION_ANCHOR_GAIN", "Stable GTA$ above the pre-transition anchor was credited exactly once.",
                ("anchor=%s before=%s after=%s newlyCredited=%s totalCreditedAbove=%s reads=%s stableMs=%s")
                    :format(tostring(anchorTotal), tostring(beforeGain), tostring(ac.total), tostring((tonumber(ac.total or 0) or 0) - beforeGain),
                        tostring(scanner.anchorCreditedAbove), tostring(ac.reads or 0), tostring(stableForMs)))
            scanner.anchorCandidate = nil
            creditedAbove = tonumber(scanner.anchorCreditedAbove or 0) or 0
        elseif excess <= creditedAbove then
            -- This includes the classic failure pattern: return below the old total and
            -- later climb back to it. Never lower the accounting baseline during the
            -- grace window, so the restoration has nothing to be counted against.
            local signature = table.concat({ tostring(ac.total), tostring(anchorTotal), tostring(creditedAbove) }, ":")
            if scanner.anchorLastSuppressedSignature ~= signature and stableForMs >= 1000 then
                scanner.anchorLastSuppressedSignature = signature
                hustle_meter.S.scannerAnchorSuppressedReturns = (tonumber(hustle_meter.S.scannerAnchorSuppressedReturns or 0) or 0) + 1
                hustle_meter.debug_event("POST_TRANSITION_ANCHOR_SYNC", "At/below-anchor balance treated as post-transition synchronization; no earnings and no downward baseline move.",
                    ("anchor=%s credited=%s observed=%s excess=%s reads=%s stableMs=%s")
                        :format(tostring(anchorTotal), tostring(creditedAbove), tostring(ac.total), tostring(excess), tostring(ac.reads or 0), tostring(stableForMs)))
            end
        end

        local anchorExpired = nowMs >= (tonumber(scanner.anchorUntilMs or 0) or 0)
        if anchorExpired then
            -- Do not release the guard on a moving or inconsistent snapshot. Extend in
            -- five-second chunks until the final state is trustworthy.
            local finalReads = math.max(5, math.floor(tonumber(hustle_meter.S.scannerConfirmReads or 3) or 3))
            local finalReady = stableForMs >= 2000
                and (tonumber(ac.reads or 0) or 0) >= finalReads
                and acConsistency.consistent == true
                and scanner.lastStrongOnlineNow == true
                and strongForMs >= 5000
                and not (sessionFlags and (sessionFlags.loading == true or sessionFlags.playerSwitch == true))

            if finalReady then
                local finalTotal = tonumber(ac.total or 0) or 0
                local currentConfirmed = tonumber(scanner.confirmedTotal or (anchorTotal + (tonumber(scanner.anchorCreditedAbove or 0) or 0))) or 0

                -- If a gain became stable exactly as the window expired, credit only
                -- the still-uncredited amount above the original anchor before closing.
                local finalExcess = finalTotal - anchorTotal
                local finalCredited = tonumber(scanner.anchorCreditedAbove or 0) or 0
                if finalExcess > finalCredited then
                    scanner.confirmedTotal = anchorTotal + finalCredited
                    hustle_meter.Tracker.lastTotal = scanner.confirmedTotal
                    hustle_meter.commit_scanned_snapshot(ac.total, ac.bank, ac.wallet, ac.wallet0, ac.wallet1,
                        false, ac.reads or finalReads, "post-transition-anchor-gain")
                    scanner.anchorCreditedAbove = finalExcess
                    hustle_meter.S.scannerAnchorGainCommits = (tonumber(hustle_meter.S.scannerAnchorGainCommits or 0) or 0) + 1
                    currentConfirmed = finalTotal
                elseif finalTotal ~= currentConfirmed
                    or tonumber(ac.bank or 0) ~= tonumber(scanner.confirmedBank or 0)
                    or tonumber(ac.wallet0 or 0) ~= tonumber(scanner.confirmedWallet0 or 0)
                    or tonumber(ac.wallet1 or 0) ~= tonumber(scanner.confirmedWallet1 or 0) then
                    -- After the full grace period, a stable lower balance can finally
                    -- become the new baseline. Decreases never add earnings.
                    hustle_meter.commit_scanned_snapshot(ac.total, ac.bank, ac.wallet, ac.wallet0, ac.wallet1,
                        false, ac.reads or finalReads, "post-transition-anchor-finalize")
                end

                scanner.anchorActive = false
                scanner.anchorCandidate = nil
                scanner.anchorUntilMs = 0
                scanner.preTransitionTotal = nil
                scanner.preTransitionBank = nil
                scanner.preTransitionWallet = nil
                scanner.preTransitionWallet0 = nil
                scanner.preTransitionWallet1 = nil
                scanner.debugTailUntilMs = nowMs + (tonumber(hustle_meter.S.diagnosticTransitionTailMs or 60000) or 60000)
                hustle_meter.S.scannerPostTransitionReconciles = (tonumber(hustle_meter.S.scannerPostTransitionReconciles or 0) or 0) + 1
                hustle_meter.S.scannerStatus = "Post-transition anchor completed; normal transaction scanning resumed."
                hustle_meter.debug_event("POST_TRANSITION_ANCHOR_COMPLETE", "Grace window ended on a stable authoritative GTA$ snapshot.",
                    ("anchor=%s final=%s creditedAbove=%s stableMs=%s reads=%s")
                        :format(tostring(anchorTotal), tostring(finalTotal), tostring(scanner.anchorCreditedAbove or 0), tostring(stableForMs), tostring(ac.reads or 0)))
                hustle_meter.write_last_transition_snapshot("anchor-complete", {
                    anchorTotal = anchorTotal, finalTotal = finalTotal, creditedAbove = scanner.anchorCreditedAbove,
                    stableForMs = stableForMs, reads = ac.reads
                })
            else
                scanner.anchorUntilMs = nowMs + 5000
                hustle_meter.S.scannerAnchorExtensions = (tonumber(hustle_meter.S.scannerAnchorExtensions or 0) or 0) + 1
                hustle_meter.S.scannerStatus = "Post-transition anchor extended: waiting for a stable final money snapshot."
                hustle_meter.debug_event("POST_TRANSITION_ANCHOR_EXTENDED", "Grace window expired but the final snapshot was not trustworthy yet; extending 5 seconds.",
                    ("total=%s reads=%s stableMs=%s consistent=%s strongForMs=%s")
                        :format(tostring(ac.total), tostring(ac.reads or 0), tostring(stableForMs), tostring(acConsistency.consistent == true), tostring(strongForMs)))
            end
        else
            hustle_meter.S.scannerStatus = ("Post-transition anchor: %.1fs remaining; pre-transition balance protected.")
                :format(math.max(0, ((tonumber(scanner.anchorUntilMs or 0) or 0) - nowMs) / 1000.0))
        end

        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        return true
    end

    -- The diagnostic reset/baseline must never occur immediately when a weak Online
    -- flag first appears. Require a fully trustworthy Online state for at least 5s.
    if not hustle_meter.history_reset_marker_complete(hustle_meter.S.currentAccountKey) then
        local strongForMs = (tonumber(scanner.strongOnlineSinceMs or 0) or 0) > 0 and (nowMs - scanner.strongOnlineSinceMs) or 0
        local needStrongMs = math.max(5000, math.floor(tonumber(hustle_meter.S.scannerPostTransitionStrongSessionMs or 5000) or 5000))
        if scanner.lastStrongOnlineNow ~= true or strongForMs < needStrongMs or consistency.consistent ~= true then
            hustle_meter.S.scannerStatus = ("History reset waiting for trustworthy Online baseline: strong %.1fs/%.1fs, moneyConsistent=%s")
                :format(strongForMs / 1000.0, needStrongMs / 1000.0, tostring(consistency.consistent == true))
            scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
            return true
        end
    end

    -- Public v1.0.4 migration: once a valid account + edition + Online balance is
    -- available, archive the old edition-specific ledger and restart rolling 24H/168H
    -- totals from $0. The current GTA$ balance becomes the clean baseline and is never
    -- treated as newly earned money. A per-account/per-edition marker prevents repeats.
    local didHistoryReset, resetReason = hustle_meter.perform_one_time_history_reset(total, bank, wallet, wallet0, wallet1)
    if didHistoryReset then
        scanner = hustle_meter.get_transaction_scanner()
        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        return true
    elseif resetReason == "archive-failed" or resetReason == "save-failed" then
        scanner.nextDelayMs = 500
        return false
    end

    -- Build 026 recovery also runs when the script starts directly in a stable Online
    -- session without crossing the transition branch above.
    local recoveredLegacyDualWallet, recoveryReason = hustle_meter.perform_legacy_dual_wallet_recovery(
        total, bank, wallet, wallet0, wallet1
    )
    if recoveredLegacyDualWallet then
        scanner = hustle_meter.get_transaction_scanner()
        scanner.nextDelayMs = tonumber(hustle_meter.S.scannerBurstMs or 50) or 50
        hustle_meter.S.scannerStatus = "Legacy dual-wallet baseline recovered; future earnings will be counted from the repaired baseline."
        return true
    elseif recoveryReason == "archive-failed" or recoveryReason == "save-failed" then
        scanner.nextDelayMs = 500
        return false
    end

    -- Edition-isolated v1.0.4 ledgers start from the current authoritative balance.
    -- Older unsuffixed LE/EE ledgers remain untouched rather than importing possibly
    -- contaminated v1.0.3 transition gains into the new edition-specific ledger.
    if tostring(hustle_meter.Tracker.balanceMode or "") ~= tostring(hustle_meter.BalanceMode) then
        scanner.confirmedTotal = total
        scanner.confirmedBank = bank
        scanner.confirmedWallet = wallet
        scanner.confirmedWallet0 = wallet0
        scanner.confirmedWallet1 = wallet1
        scanner.initialized = true
        scanner.candidate = nil
        hustle_meter.Tracker.lastTotal = total
        hustle_meter.Tracker.lastBank = bank
        hustle_meter.Tracker.lastWallet = wallet
        hustle_meter.Tracker.lastWallet0 = wallet0
        hustle_meter.Tracker.lastWallet1 = wallet1
        hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode
        hustle_meter.S.lastBalance = total
        hustle_meter.S.lastBank = bank
        hustle_meter.S.lastWallet = wallet
        hustle_meter.add_sample(total, bank, wallet, true, wallet0, wallet1)
        scanner.dirty = true
        hustle_meter.S.lastStatus = "v1.0.4 authoritative balance baseline captured for " .. tostring(hustle_meter.S.currentGameEdition or "Unknown") .. "."
    elseif not scanner.initialized then
        scanner.confirmedTotal = tonumber(hustle_meter.Tracker.lastTotal)
        scanner.confirmedBank = tonumber(hustle_meter.Tracker.lastBank)
        scanner.confirmedWallet = tonumber(hustle_meter.Tracker.lastWallet)
        scanner.confirmedWallet0 = tonumber(hustle_meter.Tracker.lastWallet0)
        scanner.confirmedWallet1 = tonumber(hustle_meter.Tracker.lastWallet1)
        scanner.initialized = true
        if scanner.confirmedTotal == nil or scanner.confirmedTotal <= 0 then
            scanner.confirmedTotal = total
            scanner.confirmedBank = bank
            scanner.confirmedWallet = wallet
            scanner.confirmedWallet0 = wallet0
            scanner.confirmedWallet1 = wallet1
        end

        -- Keep the public/UI/support state synchronized with the authoritative
        -- edition-specific ledger immediately after startup. Previously these
        -- fields could retain an older config snapshot until the next transaction.
        hustle_meter.S.lastBalance = tonumber(scanner.confirmedTotal or total or 0) or 0
        hustle_meter.S.lastBank = tonumber(scanner.confirmedBank or bank or 0) or 0
        hustle_meter.S.lastWallet = tonumber(scanner.confirmedWallet or wallet or 0) or 0
    end

    -- Normal Online scanning still cross-checks the active balance against bank +
    -- both character wallets. This acts as a second safety net if a transition signal
    -- somehow slips past the session-state detector.
    local confirmedTotal = tonumber(scanner.confirmedTotal or hustle_meter.Tracker.lastTotal or 0) or 0
    if math.floor(total) == math.floor(confirmedTotal) then
        scanner.candidate = nil
        -- Total wealth did not change, so bank/cash movement is a transfer rather than
        -- earnings. Keep diagnostic/public state fresh without creating an event.
        scanner.confirmedBank = bank
        scanner.confirmedWallet = wallet
        scanner.confirmedWallet0 = wallet0
        scanner.confirmedWallet1 = wallet1
        hustle_meter.Tracker.lastBank = bank
        hustle_meter.Tracker.lastWallet = wallet
        hustle_meter.Tracker.lastWallet0 = wallet0
        hustle_meter.Tracker.lastWallet1 = wallet1
        hustle_meter.S.lastBalance = confirmedTotal
        hustle_meter.S.lastBank = bank
        hustle_meter.S.lastWallet = wallet
    else
        local candidate = scanner.candidate
        if hustle_meter.same_money_snapshot(candidate, total, bank, wallet, wallet0, wallet1) then
            candidate.reads = (tonumber(candidate.reads or 1) or 1) + 1
            candidate.lastMs = nowMs
        else
            scanner.candidate = {
                total = total, bank = bank, wallet = wallet, wallet0 = wallet0, wallet1 = wallet1,
                reads = 1, firstMs = nowMs, lastMs = nowMs, bridge = false
            }
            candidate = scanner.candidate
            hustle_meter.debug_event("NORMAL_CANDIDATE_CHANGED", "Online money snapshot changed; confirmation restarted.",
                ("confirmed=%s candidate=%s bank=%s wallet=%s w0=%s w1=%s")
                    :format(tostring(confirmedTotal), tostring(total), tostring(bank), tostring(wallet), tostring(wallet0), tostring(wallet1)))
        end

        local delta = (tonumber(candidate.total or 0) or 0) - confirmedTotal
        local absDelta = math.abs(delta)
        local requiredReads = math.max(2, math.floor(tonumber(hustle_meter.S.scannerConfirmReads or 3) or 3))
        local requiredStableMs = 150
        if absDelta >= 10000000 then
            requiredReads = math.max(requiredReads, 10)
            requiredStableMs = 5000
        end
        local candidateStableMs = nowMs - (tonumber(candidate.firstMs or nowMs) or nowMs)
        local candidateConsistency = hustle_meter.money_consistency(candidate.total, candidate.bank, candidate.wallet0, candidate.wallet1)
        local moneyConsistent = hustle_meter.S.scannerRequireMoneyConsistency ~= true or candidateConsistency.consistent == true
        local strongForMs = (tonumber(scanner.strongOnlineSinceMs or 0) or 0) > 0 and (nowMs - scanner.strongOnlineSinceMs) or 0
        local strongReady = scanner.lastStrongOnlineNow == true and strongForMs >= 1000
        if absDelta >= 10000000 then strongReady = scanner.lastStrongOnlineNow == true and strongForMs >= 5000 end
        local enoughReads = (tonumber(candidate.reads or 0) or 0) >= requiredReads
        local enoughTime = candidateStableMs >= requiredStableMs
        local canCommit = moneyConsistent and strongReady and enoughTime and (force == true or enoughReads)

        hustle_meter.trace_scan("normal-candidate-validation", nowMs, candidate.total, candidate.bank, candidate.wallet,
            candidate.wallet0, candidate.wallet1, sessionFlags, candidateConsistency,
            ("delta=%s reads=%s/%s stable=%sms/%sms strong=%sms consistent=%s match=%s diffCombined=%s")
                :format(tostring(delta), tostring(candidate.reads or 0), tostring(requiredReads), tostring(candidateStableMs), tostring(requiredStableMs), tostring(strongForMs),
                    tostring(moneyConsistent), tostring(candidateConsistency.matchMode), tostring(candidateConsistency.diffCombined)))

        if canCommit then
            hustle_meter.debug_event("NORMAL_CANDIDATE_ACCEPT", "Confirmed Online balance step accepted.",
                ("delta=%s reads=%s stableMs=%s consistency=%s")
                    :format(tostring(delta), tostring(candidate.reads or 0), tostring(candidateStableMs), tostring(moneyConsistent)))
            hustle_meter.commit_scanned_snapshot(candidate.total, candidate.bank, candidate.wallet, candidate.wallet0, candidate.wallet1,
                false, candidate.reads or requiredReads, "confirmed-authoritative-step")
            scanner.candidate = nil
        elseif enoughTime and enoughReads and (not moneyConsistent or not strongReady) then
            local reason = (not moneyConsistent and "normal-money-source-mismatch" or "normal-strong-online-not-stable")
            local signature = table.concat({ reason, tostring(candidate.total), tostring(candidate.bank), tostring(candidate.wallet0), tostring(candidate.wallet1) }, ":")
            if scanner.lastNormalQuarantineSignature ~= signature then
                scanner.lastNormalQuarantineSignature = signature
                hustle_meter.record_suspicious_transition(reason, {
                    total = candidate.total, bank = candidate.bank, wallet = candidate.wallet,
                    wallet0 = candidate.wallet0, wallet1 = candidate.wallet1, delta = delta,
                    preTotal = confirmedTotal, preBank = scanner.confirmedBank,
                    reads = candidate.reads, stableForMs = candidateStableMs,
                    strongForMs = strongForMs, consistency = candidateConsistency, flags = sessionFlags
                })
            end
            hustle_meter.S.scannerStatus = "Online balance change quarantined pending trustworthy money/session values."
        end
    end

    local burst = nowMs <= (tonumber(scanner.burstUntilMs or 0) or 0)
    scanner.nextDelayMs = burst
        and (tonumber(hustle_meter.S.scannerBurstMs or 50) or 50)
        or (tonumber(hustle_meter.S.scannerIdleMs or 100) or 100)

    return true
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- tracker maintenance
-- note: the scanner owns transaction detection; this maintenance pass refreshes
-- rolling windows and commits dirty history without writing the ledger every scan.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.update_tracker(force)
    if not hustle_meter.S.enabled then return false end

    local scanned = hustle_meter.scan_money_transactions(force == true)
    local scanner = hustle_meter.get_transaction_scanner()
    local nowMs = hustle_meter.now()

    if force == true or nowMs - (tonumber(scanner.lastMaintenanceMs or 0) or 0) >= 1000 then
        scanner.lastMaintenanceMs = nowMs
        hustle_meter.is_gta_online_ready()
        hustle_meter.recalculate_windows()

        if scanner.confirmedTotal ~= nil then
            local sampleAdded = hustle_meter.add_sample(scanner.confirmedTotal, scanner.confirmedBank, scanner.confirmedWallet, false, scanner.confirmedWallet0, scanner.confirmedWallet1)
            if sampleAdded then scanner.dirty = true end
        end

        local saveDue = nowMs - (tonumber(scanner.lastSaveMs or 0) or 0) >= 30000
        if scanner.dirty or saveDue then
            if hustle_meter.save_history() then
                scanner.lastSaveMs = nowMs
                scanner.dirty = false
            end
        end
    end

    return scanned
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- hud visibility / hotkey
-- note: z shows the HUD; triple-Z hides timed modes but is ignored by No timeout.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.show_hud(reason)
    if not hustle_meter.S.enabled then return end
    if hustle_meter.S.onlineOnly and not hustle_meter.is_gta_online_ready() then
        hustle_meter.S.hudVisibleUntilMs = 0
        hustle_meter.S.lastStatus = hustle_meter.S.onlineStatus or "HustleMeter is GTA Online only."
        -- No toast here. The tab already shows the Single Player / offline message.
        return
    end
    hustle_meter.update_tracker(false)
    local hideMs = tonumber(hustle_meter.S.hudHideMs or 5000) or 5000
    hustle_meter.S.hudVisibleUntilMs = hideMs <= 0 and -1 or (hustle_meter.now() + hideMs)
    hustle_meter.S.lastStatus = "HUD shown by " .. tostring(reason or "manual")
end

function hustle_meter.hide_hud(reason)
    hustle_meter.S.hudVisibleUntilMs = 0
    hustle_meter.S.hudKeyPressCount = 0
    hustle_meter.S.lastStatus = "HUD hidden" .. (reason and (" by " .. tostring(reason)) or "")
end

function hustle_meter.reset_hud_preset()
    hustle_meter.S.hud24X = 0.833
    hustle_meter.S.hud24Y = 0.0180
    hustle_meter.S.hud24Scale = 0.400
    hustle_meter.S.hud168X = 0.833
    hustle_meter.S.hud168Y = 0.0393
    hustle_meter.S.hud168Scale = 0.400
    hustle_meter.S.hudAlpha = 245
    hustle_meter.S.hudOutline = 1.15
    hustle_meter.S.hudTimeoutIndex = 0
    hustle_meter.S.hudHideMs = 5000
    hustle_meter.S.warningColorsEnabled = true
    hustle_meter.S.approvedHudDefaultsApplied = true
    hustle_meter.save_config(false)
    hustle_meter.show_hud("preset reset")
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- manual reset controls
-- note: settings reset never touches ledger history. money reset is active-account/
-- edition only, archives the current ledger first, and requires a trustworthy Online
-- money snapshot before establishing a new local baseline.
-- ═══════════════════════════════════════════════════════════════════════════════════

hustle_meter.UserSettingResetKeys = {
    "enabled",
    "hudHotkeyEnabled",
    "hudKeyCode",
    "hudHideMs",
    "hudTimeoutIndex",
    "hudTriplePressWindowMs",
    "hud24X",
    "hud24Y",
    "hud24Scale",
    "hud168X",
    "hud168Y",
    "hud168Scale",
    "hudAlpha",
    "hudOutline",
    "warningColorsEnabled"
}

function hustle_meter.open_settings_reset_confirmation()
    hustle_meter.SettingsResetConfirmOpen = true
    hustle_meter.SettingsResetLastForceOpenMs = 0
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.close_settings_reset_confirmation()
    hustle_meter.SettingsResetConfirmOpen = false
    hustle_meter.SettingsResetLastForceOpenMs = 0
end

function hustle_meter.keep_settings_reset_confirmation_active()
    if hustle_meter.SettingsResetConfirmOpen ~= true then return end
    local now = hustle_meter.now()
    if now - (tonumber(hustle_meter.SettingsResetLastForceOpenMs or 0) or 0) < 750 then return end
    hustle_meter.SettingsResetLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.schedule_hud_reset()
    if hustle_meter.PendingHudReset == true or hustle_meter.ResetWorkerBusy == true then
        hustle_meter.LastResetWorkerStatus = "HUD reset is already queued or running."
        return false
    end
    hustle_meter.PendingHudReset = true
    hustle_meter.LastResetWorkerStatus = "HUD reset queued."
    return true
end

function hustle_meter.schedule_settings_reset()
    if hustle_meter.PendingSettingsReset == true or hustle_meter.ResetWorkerBusy == true then
        hustle_meter.LastResetWorkerStatus = "Settings reset is already queued or running."
        return false
    end
    hustle_meter.PendingSettingsReset = true
    hustle_meter.LastResetWorkerStatus = "Settings reset queued."
    return true
end

function hustle_meter.schedule_money_history_reset()
    if hustle_meter.PendingMoneyReset == true or hustle_meter.ResetWorkerBusy == true then
        hustle_meter.LastResetWorkerStatus = "Money history reset is already queued or running."
        return false
    end
    hustle_meter.PendingMoneyReset = true
    hustle_meter.LastResetWorkerStatus = "Money history reset queued."
    return true
end

function hustle_meter.reset_user_settings()
    for _, key in ipairs(hustle_meter.UserSettingResetKeys or {}) do
        local value = hustle_meter.Defaults[key]
        if value ~= nil then hustle_meter.S[key] = value end
    end

    hustle_meter.S.hudVisibleUntilMs = 0
    hustle_meter.S.hudLastKeyPressed = false
    hustle_meter.S.hudKeyPressCount = 0
    hustle_meter.S.hudLastKeyPressMs = 0
    hustle_meter.S.approvedHudDefaultsApplied = true

    if hustle_meter.sync_feature_states then hustle_meter.sync_feature_states() end
    hustle_meter.save_config(true)
    hustle_meter.toast("Settings reset to HustleMeter defaults. Money history was not changed.", 4500)
end

function hustle_meter.get_manual_money_reset_backup_file(accountKey)
    accountKey = hustle_meter.sanitize_account_key(accountKey or hustle_meter.S.currentAccountKey or "unknown")
    hustle_meter.ensure_account_backup_dir(accountKey)
    local stamp = os.date("%Y%m%d_%H%M%S") or tostring(os.time())
    local base = hustle_meter.get_account_backup_dir(accountKey) .. "\\manual_reset_" .. tostring(stamp)
    local path = base .. ".lua"
    local suffix = 2
    while hustle_meter.file_exists(path) do
        path = base .. "_" .. tostring(suffix) .. ".lua"
        suffix = suffix + 1
    end
    return path
end

function hustle_meter.backup_money_history_for_manual_reset(accountKey)
    accountKey = hustle_meter.sanitize_account_key(accountKey or hustle_meter.S.currentAccountKey or "unknown")
    local source = hustle_meter.get_account_history_file(accountKey)
    if not hustle_meter.file_exists(source) then return nil, true end
    local content = hustle_meter.read_file(source)
    if not content or content == "" then return nil, true end
    local backup = hustle_meter.get_manual_money_reset_backup_file(accountKey)
    if hustle_meter.try_write_file(backup, content) then return backup, true end
    return nil, false
end

function hustle_meter.open_money_reset_confirmation()
    hustle_meter.recalculate_windows()
    hustle_meter.MoneyResetConfirmOpen = true
    hustle_meter.MoneyResetLastForceOpenMs = 0
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.close_money_reset_confirmation()
    hustle_meter.MoneyResetConfirmOpen = false
    hustle_meter.MoneyResetLastForceOpenMs = 0
end

function hustle_meter.keep_money_reset_confirmation_active()
    if hustle_meter.MoneyResetConfirmOpen ~= true then return end
    local now = hustle_meter.now()
    if now - (tonumber(hustle_meter.MoneyResetLastForceOpenMs or 0) or 0) < 750 then return end
    hustle_meter.MoneyResetLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.perform_manual_money_history_reset()
    if not hustle_meter.is_gta_online_ready() then
        hustle_meter.toast("Reset cancelled. Enter a stable GTA Online session first so HustleMeter can capture a safe new balance baseline.", 6500)
        return false
    end

    if not hustle_meter.ensure_current_account(true) then
        hustle_meter.toast("Reset cancelled. HustleMeter could not confirm the active Rockstar account.", 5500)
        return false
    end

    local accountKey = hustle_meter.sanitize_account_key(hustle_meter.S.currentAccountKey or "unknown")
    if accountKey == "unknown" or accountKey == "pending" then
        hustle_meter.toast("Reset cancelled. Active account ledger is not ready yet.", 5000)
        return false
    end

    hustle_meter.load_history()
    hustle_meter.recalculate_windows()
    hustle_meter.save_history()

    local total, bank, wallet, details, moneyMeta = hustle_meter.read_money_balance()
    local wallet0 = moneyMeta and tonumber(moneyMeta.wallet0 or 0) or 0
    local wallet1 = moneyMeta and tonumber(moneyMeta.wallet1 or 0) or 0
    local consistency = moneyMeta and moneyMeta.consistency or hustle_meter.money_consistency(total, bank, wallet0, wallet1)

    if total == nil or tonumber(total or 0) <= 0 then
        hustle_meter.toast("Reset cancelled. HustleMeter could not read a trustworthy active GTA$ balance.", 6000)
        return false
    end
    if hustle_meter.S.scannerRequireMoneyConsistency == true and (not consistency or consistency.consistent ~= true) then
        hustle_meter.toast("Reset cancelled. Bank/wallet values are still synchronizing. Wait a few seconds and try again.", 6500)
        return false
    end

    local backupPath, backupOk = hustle_meter.backup_money_history_for_manual_reset(accountKey)
    if not backupOk then
        hustle_meter.toast("Reset cancelled. HustleMeter could not back up the existing money history.", 6500)
        return false
    end

    local nowSec = os.time()
    local previousPast24 = tonumber(hustle_meter.S.past24h or 0) or 0
    local previousPast168 = tonumber(hustle_meter.S.past168h or 0) or 0

    total = math.floor(tonumber(total or 0) or 0)
    bank = math.floor(tonumber(bank or 0) or 0)
    wallet = math.floor(tonumber(wallet or 0) or 0)
    wallet0 = math.floor(tonumber(wallet0 or 0) or 0)
    wallet1 = math.floor(tonumber(wallet1 or 0) or 0)

    hustle_meter.Tracker.samples = {{
        t = nowSec,
        accountName = tostring(hustle_meter.S.currentAccountName or "Unknown"),
        accountKey = accountKey,
        gameEdition = tostring(hustle_meter.S.currentGameEdition or "Unknown"),
        cheraxEdition = tostring(hustle_meter.S.currentCheraxEdition or "Unknown"),
        total = total,
        bank = bank,
        wallet = wallet,
        wallet0 = wallet0,
        wallet1 = wallet1,
        balanceMode = hustle_meter.BalanceMode,
        manualResetBaseline = true
    }}
    hustle_meter.Tracker.gains = {}
    hustle_meter.Tracker.lastTotal = total
    hustle_meter.Tracker.lastBank = bank
    hustle_meter.Tracker.lastWallet = wallet
    hustle_meter.Tracker.lastWallet0 = wallet0
    hustle_meter.Tracker.lastWallet1 = wallet1
    hustle_meter.Tracker.balanceMode = hustle_meter.BalanceMode

    hustle_meter.S.lastBalance = total
    hustle_meter.S.lastBank = bank
    hustle_meter.S.lastWallet = wallet
    hustle_meter.S.past24h = 0
    hustle_meter.S.past168h = 0
    hustle_meter.S.gainCount = 0
    hustle_meter.S.sampleCount = 1
    hustle_meter.S.lastGainAmount = 0
    hustle_meter.S.lastGainTime = "None"
    hustle_meter.S.lastStatus = "Local money history manually reset from the current GTA$ balance."

    local scanner = hustle_meter.get_transaction_scanner()
    scanner.accountKey = accountKey
    scanner.confirmedTotal = total
    scanner.confirmedBank = bank
    scanner.confirmedWallet = wallet
    scanner.confirmedWallet0 = wallet0
    scanner.confirmedWallet1 = wallet1
    scanner.initialized = true
    scanner.candidate = nil
    scanner.resumeCandidate = nil
    scanner.inTransition = false
    scanner.anchorActive = false
    scanner.anchorCandidate = nil
    scanner.anchorUntilMs = 0
    scanner.preTransitionTotal = nil
    scanner.preTransitionBank = nil
    scanner.preTransitionWallet = nil
    scanner.preTransitionWallet0 = nil
    scanner.preTransitionWallet1 = nil
    scanner.dirty = true

    if not hustle_meter.save_history() then
        if backupPath and backupPath ~= "" then
            local original = hustle_meter.read_file(backupPath)
            if original and original ~= "" then hustle_meter.try_write_file(hustle_meter.HistoryFile, original) end
        end
        hustle_meter.Tracker.loaded = false
        hustle_meter.Tracker.loadedFile = nil
        hustle_meter.load_history()
        hustle_meter.recalculate_windows()
        scanner.confirmedTotal = tonumber(hustle_meter.Tracker.lastTotal)
        scanner.confirmedBank = tonumber(hustle_meter.Tracker.lastBank)
        scanner.confirmedWallet = tonumber(hustle_meter.Tracker.lastWallet)
        scanner.confirmedWallet0 = tonumber(hustle_meter.Tracker.lastWallet0)
        scanner.confirmedWallet1 = tonumber(hustle_meter.Tracker.lastWallet1)
        scanner.initialized = scanner.confirmedTotal ~= nil and scanner.confirmedTotal > 0
        scanner.candidate = nil
        scanner.dirty = false
        hustle_meter.toast("Money history reset failed to save. The previous ledger backup was preserved.", 7000)
        return false
    end

    hustle_meter.register_account(hustle_meter.S.currentAccountName, accountKey)
    hustle_meter.save_diagnostics("manual-money-history-reset")
    hustle_meter.debug_event("MANUAL_MONEY_HISTORY_RESET",
        "User confirmed a local rolling-money-history reset.",
        ("past24=%s past168=%s baseline=%s backup=%s details=%s")
            :format(tostring(previousPast24), tostring(previousPast168), tostring(total), tostring(backupPath or "none"), tostring(details or "")))
    hustle_meter.toast("Money history reset. Tracking now starts from the current GTA$ balance. A backup of the previous ledger was preserved.", 7500)
    return true
end

function hustle_meter.process_pending_reset_actions()
    if hustle_meter.ResetWorkerBusy == true then return false end

    local action = nil
    if hustle_meter.PendingHudReset == true then
        hustle_meter.PendingHudReset = false
        action = "hud"
    elseif hustle_meter.PendingSettingsReset == true then
        hustle_meter.PendingSettingsReset = false
        action = "settings"
    elseif hustle_meter.PendingMoneyReset == true then
        hustle_meter.PendingMoneyReset = false
        action = "money"
    else
        return false
    end

    hustle_meter.ResetWorkerBusy = true
    if action == "hud" then
        hustle_meter.LastResetWorkerStatus = "Resetting HUD outside ClickGUI render..."
    elseif action == "settings" then
        hustle_meter.LastResetWorkerStatus = "Resetting settings outside ClickGUI render..."
    else
        hustle_meter.LastResetWorkerStatus = "Resetting money history outside ClickGUI render..."
    end

    local ok, result = pcall(function()
        if action == "hud" then
            hustle_meter.reset_hud_preset()
            return true
        elseif action == "settings" then
            hustle_meter.reset_user_settings()
            return true
        end
        return hustle_meter.perform_manual_money_history_reset()
    end)

    if not ok then
        hustle_meter.LastResetWorkerStatus = "Reset worker error: " .. tostring(result)
        hustle_meter.warn(hustle_meter.LastResetWorkerStatus)
        hustle_meter.toast("Reset could not be completed safely.", 6500)
    elseif result == false then
        if action == "hud" then
            hustle_meter.LastResetWorkerStatus = "HUD reset did not complete."
        elseif action == "settings" then
            hustle_meter.LastResetWorkerStatus = "Settings reset did not complete."
        else
            hustle_meter.LastResetWorkerStatus = "Money history reset was cancelled by safety checks."
        end
    else
        if action == "hud" then
            hustle_meter.LastResetWorkerStatus = "HUD reset complete."
        elseif action == "settings" then
            hustle_meter.LastResetWorkerStatus = "Settings reset complete."
        else
            hustle_meter.LastResetWorkerStatus = "Money history reset complete."
        end
    end

    hustle_meter.ResetWorkerBusy = false
    return true
end

function hustle_meter.key_just_pressed()
    if not hustle_meter.S.hudHotkeyEnabled then return false end
    local pressed = false
    if Utils and Utils.IsKeyPressed then
        pressed = Utils.IsKeyPressed(hustle_meter.S.hudKeyCode or 0x5A) == true
    end

    local was = hustle_meter.S.hudLastKeyPressed == true
    hustle_meter.S.hudLastKeyPressed = pressed
    return pressed and not was
end

function hustle_meter.handle_hotkey()
    if not hustle_meter.S.enabled then return end
    if hustle_meter.key_just_pressed() then
        local ms = hustle_meter.now()
        local active = hustle_meter.is_hud_visible(ms)
        local noTimeout = (tonumber(hustle_meter.S.hudHideMs or 5000) or 5000) <= 0

        -- No timeout is intentionally one-way through the Z hotkey: Z can show or
        -- reaffirm the HUD, but double-Z/triple-Z must never dismiss it.
        if noTimeout then
            hustle_meter.S.hudKeyPressCount = 0
            hustle_meter.S.hudLastKeyPressMs = ms
            hustle_meter.show_hud("Z key - no timeout")
            return
        end

        local windowMs = tonumber(hustle_meter.S.hudTriplePressWindowMs or 5000) or 5000
        local lastPress = tonumber(hustle_meter.S.hudLastKeyPressMs or 0) or 0

        if active and (ms - lastPress) <= windowMs then
            hustle_meter.S.hudKeyPressCount = (tonumber(hustle_meter.S.hudKeyPressCount or 0) or 0) + 1
        else
            hustle_meter.S.hudKeyPressCount = 1
        end

        hustle_meter.S.hudLastKeyPressMs = ms

        if (tonumber(hustle_meter.S.hudKeyPressCount or 0) or 0) >= 3 then
            hustle_meter.hide_hud("triple Z")
            return
        end

        hustle_meter.show_hud("Z key")
    end
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- hud text renderer
-- note: draws the GTA-style outlined money text without image notifications.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.hud_text_raw(text, x, y, scale, r, g, b, a, font, rightAlign, outline)
    text = tostring(text or "")
    scale = tonumber(scale or 0.30) or 0.30
    font = tonumber(font or 7) or 7
    rightAlign = rightAlign == true
    outline = outline ~= false

    SET_SCRIPT_GFX_DRAW_ORDER(7)
    SET_SCRIPT_GFX_DRAW_BEHIND_PAUSEMENU(true)
    SET_TEXT_FONT(font)
    SET_TEXT_SCALE(0.0, scale + 0.0)
    SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 230)
    SET_TEXT_CENTRE(false)
    SET_TEXT_RIGHT_JUSTIFY(rightAlign)

    if rightAlign then
        SET_TEXT_WRAP(0.0, x + 0.0)
    else
        SET_TEXT_WRAP(0.0, 1.0)
    end

    if outline then
        SET_TEXT_EDGE(1, 0, 0, 0, 230)
        SET_TEXT_DROPSHADOW(1, 0, 0, 0, 230)
        SET_TEXT_DROP_SHADOW()
        SET_TEXT_OUTLINE()
    end

    BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
    ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(text)
    END_TEXT_COMMAND_DISPLAY_TEXT(x + 0.0, y + 0.0, 0)

    if rightAlign then
        SET_TEXT_RIGHT_JUSTIFY(false)
    end
end

function hustle_meter.hud_text(text, x, y, scale, r, g, b, a, font, rightAlign)
    local s = tonumber(scale or 0.30) or 0.30
    local outlineMul = tonumber(hustle_meter.S.hudOutline or 1.15) or 1.15
    outlineMul = hustle_meter.clamp_float(outlineMul, 0.25, 2.50)
    local o = math.max(0.0005625, s * 0.0020) * outlineMul
    local shadowAlpha = hustle_meter.clamp_int((tonumber(a or 230) or 230) + 20, 80, 255)
    local offsets = {
        { -o,  0.0 }, {  o,  0.0 }, { 0.0, -o }, { 0.0,  o },
        { -o, -o },  {  o, -o },  { -o,  o },  {  o,  o }
    }
    for _, d in ipairs(offsets) do
        hustle_meter.hud_text_raw(text, (x or 0) + d[1], (y or 0) + d[2], s, 0, 0, 0, shadowAlpha, font, rightAlign, false)
    end
    hustle_meter.hud_text_raw(text, x, y, s, r, g, b, a, font, rightAlign, true)
end

function hustle_meter.render_hud()
    if not hustle_meter.S.enabled then return end
    if not hustle_meter.is_hud_visible() then return end

    hustle_meter.recalculate_windows()

    local alpha = hustle_meter.clamp_int(hustle_meter.S.hudAlpha or 245, 70, 255)
    local display24, display168 = hustle_meter.get_display_past_values()
    local value24 = hustle_meter.format_money(display24, false)
    local value168 = hustle_meter.format_money(display168, false)
    local line24 = "1 Day: " .. tostring(value24)
    local line168 = "7 Days: " .. tostring(value168)
    local color24 = hustle_meter.get_risk_info(display24, 24)
    local color168 = hustle_meter.get_risk_info(display168, 168)

    hustle_meter.hud_text(line24, hustle_meter.S.hud24X, hustle_meter.S.hud24Y, hustle_meter.S.hud24Scale, color24.r, color24.g, color24.b, alpha, 7, true)
    hustle_meter.hud_text(line168, hustle_meter.S.hud168X, hustle_meter.S.hud168Y, hustle_meter.S.hud168Scale, color168.r, color168.g, color168.b, alpha, 7, true)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- cherax feature helpers
-- note: direct feature helpers keep buttons/toggles/combos readable without hidden calls.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.feature_bool(feature)
    if not feature then return false end
    if feature.GetBoolValue then return feature:GetBoolValue() == true end
    if feature.IsToggled then return feature:IsToggled() == true end
    return false
end

function hustle_meter.set_feature_bool(feature, value)
    if not feature then return end
    if feature.SetBoolValue then feature:SetBoolValue(value == true) end
end

function hustle_meter.remove_feature(key)
    local hash = hustle_meter.hash(key)
    if FeatureMgr and FeatureMgr.RemoveFeature then FeatureMgr.RemoveFeature(hash) end
end

function hustle_meter.add_button(key, name, desc, callback)
    hustle_meter.H[key] = hustle_meter.hash(key)
    hustle_meter.remove_feature(key)
    local feature = FeatureMgr.AddFeature(hustle_meter.H[key], name, eFeatureType.Button, desc or "", callback)
    hustle_meter.Features[key] = feature
    if feature and feature.SetSaveable then feature:SetSaveable(false) end
    return feature
end

function hustle_meter.add_toggle(key, name, desc, settingKey, callback)
    hustle_meter.H[key] = hustle_meter.hash(key)
    hustle_meter.remove_feature(key)
    local feature = FeatureMgr.AddFeature(hustle_meter.H[key], name, eFeatureType.Toggle, desc or "", function(f)
        hustle_meter.S[settingKey] = hustle_meter.feature_bool(f)
        hustle_meter.save_config(true)
        if callback then callback(f) end
    end)
    hustle_meter.Features[key] = feature
    if feature and feature.SetDefaultValue then
        feature:SetDefaultValue(hustle_meter.S[settingKey] == true):Reset()
    elseif feature and feature.SetBoolValue then
        feature:SetBoolValue(hustle_meter.S[settingKey] == true)
    end
    if feature and feature.SetSaveable then feature:SetSaveable(false) end
    return feature
end

function hustle_meter.add_combo(key, name, desc, list, defaultIndex, callback)
    hustle_meter.H[key] = hustle_meter.hash(key)
    hustle_meter.remove_feature(key)
    local feature = FeatureMgr.AddFeature(hustle_meter.H[key], name, eFeatureType.Combo, desc or "", function(f)
        local idx = defaultIndex or 0
        if f and f.GetListIndex then idx = f:GetListIndex() end
        if callback then callback(f, idx) end
    end)
    hustle_meter.Features[key] = feature
    if feature and feature.SetList then feature:SetList(list or {}) end
    if feature and feature.SetListIndex then
        feature:SetListIndex(defaultIndex or 0)
    end
    if feature and feature.SetSaveable then feature:SetSaveable(false) end
    return feature
end

function hustle_meter.set_feature_list_index(feature, index)
    if not feature then return end
    if feature and feature.SetListIndex then feature:SetListIndex(index or 0) end
end

function hustle_meter.sync_feature_states()
    hustle_meter.set_feature_bool(hustle_meter.Features.EnableMoneyCheck, hustle_meter.S.enabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.WarningColors, hustle_meter.S.warningColorsEnabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.HardCapGuard, hustle_meter.S.hardCapGuardEnabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.HardCapCashPickups, hustle_meter.S.hardCapBlockCashPickups)
    hustle_meter.set_feature_bool(hustle_meter.Features.HardCapBlockAllIncoming, hustle_meter.S.hardCapBlockAllIncomingTestMode)
    hustle_meter.set_feature_bool(hustle_meter.Features.LiveMoneyScanner, hustle_meter.S.liveMoneyScannerEnabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.LiveMoneyDeepLogging, hustle_meter.S.liveMoneyDeepLogging)
    hustle_meter.set_feature_bool(hustle_meter.Features.PredictiveHeistGuard, hustle_meter.S.predictiveHeistGuardEnabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.PredictiveRequireMission, hustle_meter.S.predictiveHeistGuardRequireMissionContext)
    hustle_meter.set_feature_bool(hustle_meter.Features.PreTransactionHold, hustle_meter.S.preTransactionHoldEnabled)
    hustle_meter.set_feature_bool(hustle_meter.Features.PreTransactionHoldRequireMarker, hustle_meter.S.preTransactionHoldRequirePayoutMarker)
    hustle_meter.set_feature_list_index(hustle_meter.Features.PredictiveAbortMethod, hustle_meter.S.predictiveHeistGuardMethodIndex or 0)
    hustle_meter.set_feature_list_index(hustle_meter.Features.PredictiveTriggerMode, hustle_meter.S.predictiveHeistGuardTriggerIndex or 0)
    hustle_meter.set_feature_list_index(hustle_meter.Features.HardCapBuffer, hustle_meter.S.hardCapSafetyBufferIndex or 0)
    hustle_meter.set_feature_list_index(hustle_meter.Features.HudTimeout, hustle_meter.S.hudTimeoutIndex or 0)
end



