function hustle_meter.create_features()
    hustle_meter.add_toggle("EnableMoneyCheck", "Enable HustleMeter", "Tracks money snapshots and enables the HUD.", "enabled", function()
        if hustle_meter.S.enabled then hustle_meter.show_hud("enabled") else hustle_meter.hide_hud("disabled") end
    end)

    hustle_meter.add_toggle("WarningColors", "Warning Colors", "Turns Safe/Cautious/Risky/Please stop/Over limit HUD colors on or off.", "warningColorsEnabled", function() hustle_meter.show_hud("warning colors") end)

    hustle_meter.add_toggle("HardCapGuard", "Hard Cap Guard (Alpha)", "Experimental. Arms the rolling 1 Day / 7 Days cap guard. Physical GTA$ pickups can be blocked locally; server/cloud payouts require pre-payout integration.", "hardCapGuardEnabled", function()
        hustle_meter.S.hardCapStatus = hustle_meter.S.hardCapGuardEnabled and "Guard armed; worker evaluating limits..." or "Guard disabling; worker restoring pickups..."
    end)
    hustle_meter.add_toggle("HardCapCashPickups", "Block Physical Cash Pickups", "When Hard Cap Guard reaches the effective limit, deny known GTA$ pickup types for the local player instead of deleting them globally.", "hardCapBlockCashPickups", function()
        hustle_meter.S.hardCapStatus = "Pickup setting changed; worker applying state..."
    end)
    hustle_meter.add_combo("HardCapBuffer", "Hard Cap Safety Buffer", "Stops supported earnings before the full 30M / 150M guidance limit. Useful because unknown pickup values cannot be predicted exactly.", hustle_meter.HardCap.SafetyBufferNames, hustle_meter.S.hardCapSafetyBufferIndex or 0, function(_, idx)
        local buffer, normalizedIndex = hustle_meter.resolve_hard_cap_buffer(idx)
        hustle_meter.S.hardCapSafetyBufferIndex = normalizedIndex
        hustle_meter.S.hardCapSafetyBuffer = buffer
        hustle_meter.save_config(true)
        hustle_meter.S.hardCapStatus = "Safety buffer updated; worker evaluating limits..."
    end)
    hustle_meter.add_toggle("HardCapBlockAllIncoming", "BLOCK ALL INCOMING MONEY (TEST)", "Diagnostic Build 037 mode. ON by default. Blocks every visible NETWORK_EARN path plus generic service/basket/checkout and the known global commit even when you are below the rolling caps. Can interfere with normal GTA Online transactions.", "hardCapBlockAllIncomingTestMode", function()
        hustle_meter.S.hardCapFirewallStatus = hustle_meter.S.hardCapBlockAllIncomingTestMode
            and "BLOCK ALL TEST MODE enabled." or "Block-all test mode disabled; rolling-cap rules remain."
    end)
    hustle_meter.add_toggle("PreTransactionHold", "Pre-Transaction Session Hold (Build 037)", "New primary experiment. Starts during the finale/loading payout window BEFORE transactionInProgress rises and repeatedly clears the player-balance shopping session for 4 seconds.", "preTransactionHoldEnabled", function()
        hustle_meter.S.preTransactionHoldStatus = hustle_meter.S.preTransactionHoldEnabled
            and "Armed: waiting for finale transition + recent PAYOUT marker."
            or "Pre-Transaction Session Hold disabled."
    end)
    hustle_meter.add_toggle("PreTransactionHoldRequireMarker", "Require PAYOUT TRIGGER Marker", "Recommended ON for this experiment. Prevents the session hold from firing on unrelated mission transitions.", "preTransactionHoldRequirePayoutMarker")

    hustle_meter.add_toggle("PredictiveHeistGuard", "Predictive Heist Guard (Build 036)", "Experimental transaction-rising-edge guard. Build 036 requires an independent payout cue (finale/loading/fade/cutscene transition or recent PAYOUT marker) before an abort can fire.", "predictiveHeistGuardEnabled", function()
        hustle_meter.S.predictiveHeistGuardStatus = hustle_meter.S.predictiveHeistGuardEnabled
            and "Armed: waiting for a heist transaction edge with an independent payout cue."
            or "Predictive guard disabled."
    end)
    hustle_meter.add_combo("PredictiveAbortMethod", "Predictive Abort Method", "Select exactly one transaction-abort experiment. Default is Clear Session (0). Observe Only performs all detection/logging but never calls an abort native.", hustle_meter.PredictiveGuard.MethodNames, hustle_meter.S.predictiveHeistGuardMethodIndex or 2, function(_, idx)
        local _, normalized = hustle_meter.predictive_guard_method_name(idx)
        hustle_meter.S.predictiveHeistGuardMethodIndex = normalized
        hustle_meter.save_config(true)
        hustle_meter.S.predictiveHeistGuardStatus =
            "Abort method selected: " .. tostring(select(1, hustle_meter.predictive_guard_method_name(normalized)))
    end)
    hustle_meter.add_combo("PredictiveTriggerMode", "Predictive Trigger Rule", "Default rejects ordinary in-heist transaction pulses unless a transition/fade/cutscene cue or recent PAYOUT marker independently indicates the payout window.", hustle_meter.PredictiveGuard.TriggerNames, hustle_meter.S.predictiveHeistGuardTriggerIndex or 0, function(_, idx)
        local _, normalized = hustle_meter.predictive_guard_trigger_name(idx)
        hustle_meter.S.predictiveHeistGuardTriggerIndex = normalized
        hustle_meter.save_config(true)
    end)
    hustle_meter.add_toggle("PredictiveRequireMission", "Require Mission/Heist Context", "Recommended ON. Requires an active mission-risk Rockstar script before the Predictive Guard may abort a transaction.", "predictiveHeistGuardRequireMissionContext")

    hustle_meter.add_toggle("LiveMoneyScanner", "Live Payout Scanner", "High-frequency 25ms observer for GTA$ balance, transaction state, transaction globals, firewall events, and pre-signal correlation.", "liveMoneyScannerEnabled")
    hustle_meter.add_toggle("LiveMoneyDeepLogging", "Deep Money Logs", "Writes dedicated live payout scanner logs. Diagnostic Alpha default is ON.", "liveMoneyDeepLogging")
    hustle_meter.add_button("LiveMoneyHotCapture", "START 60s DEEP MONEY CAPTURE", "Forces the live scanner into 25ms trace mode for 60 seconds. Press immediately before triggering a heist/business payout.", function()
        hustle_meter.schedule_live_money_hot_capture()
    end)
    hustle_meter.add_button("LiveMoneyClear", "CLEAR / RESTART LIVE SCANNER LOGS", "Clears Build 034 live scanner, heist-risk, marker, and incident diagnostics and starts a fresh scanner session. Does not reset money history.", function()
