    hustle_meter.add_button("HeistMarkerPayout", "MARK PAYOUT TRIGGER NOW", "Press immediately before Instant Finish / finale completion / expected payout. Writes a precise marker and forces 60 seconds of deep tracing.", function()
        hustle_meter.schedule_heist_marker("PAYOUT_TRIGGER_NOW")
    end)
    hustle_meter.add_button("HeistMarkerEnd", "MARK HEIST / ACTIVITY END", "Writes the end-of-activity marker with current risk and transaction context.", function()
