    end)

    hustle_meter.add_button("HardCapPickupTest", "TEST CASH PICKUP BLOCK (30s)", "Temporarily blocks known physical GTA$ pickup types for 30 seconds so you can kill an NPC and test collection without reaching the real cap.", function()
        hustle_meter.schedule_hard_cap_pickup_test()
    end)
    hustle_meter.add_button("HardCapPayoutTest", "ARM NEXT HEIST PAYOUT BLOCK (120s)", "Experimental profiler test. For 120 seconds, blocks the first payout transaction path HustleMeter can actually intercept. Load HustleMeter before the payout mod when possible.", function()
        hustle_meter.schedule_hard_cap_payout_test()
    end)


    hustle_meter.add_button("PresetReset", "Reset HUD", "Restores the default HUD location, scale, and outline 1.15 using the Prime-safe deferred reset worker.", function()
        hustle_meter.schedule_hud_reset()
    end)
    hustle_meter.add_button("OutlineDown", "Outline -", "Fine tune black outline/shadow thinner.", function()
        hustle_meter.S.hudOutline = hustle_meter.clamp_float((hustle_meter.S.hudOutline or 1.15) - 0.05, 0.25, 2.50)
        hustle_meter.save_config(true)
        hustle_meter.show_hud("outline -")
    end)
