function hustle_meter.get_compact_scanner_status()
    local status = tostring(hustle_meter.S.scannerStatus or "Idle")
    if status == "Scanning authoritative GTA Online balance." then return "GTA Online balance active" end
    if status == "Post-transition anchor active: synchronization returns cannot become earnings." then return "Anchor active: sync returns blocked" end
    if status == "Post-transition balance validated; clean baseline created." then return "Baseline validated" end
    if status == "Transition guard: raw reads logged only; baseline frozen until strong Online returns." then return "Transition guard active" end
    if status == "Strong Online returned; validating full money snapshot before reconciliation." then return "Validating returned Online balance" end
    if status == "Paused: waiting for GTA Online transaction access." then return "Waiting for GTA Online" end
    if status == "Waiting for valid Rockstar username before scanning." then return "Waiting for Rockstar username" end
    if status == "Transition guard rejected an invalid/zero money snapshot." then return "Rejected invalid transition snapshot" end
    if status == "Waiting for a valid Online money snapshot." then return "Waiting for valid money snapshot" end
    if status == "Online balance change quarantined pending trustworthy money/session values." then return "Balance change quarantined" end

    local seconds = status:match("^Post%-transition anchor: ([0-9%.]+)s remaining; pre%-transition balance protected%.$")
    if seconds then return string.format("Anchor active: %ss left", tostring(seconds)) end

    local reason = status:match("^Post%-transition money quarantined: (.+)$")
    if reason then return "Money quarantined: " .. tostring(reason) end

    local waiting = status:match("^History reset waiting for trustworthy Online baseline: (.+)$")
    if waiting then return "History reset waiting for safe baseline" end

    local extended = status:match("^Post%-transition anchor extended: (.+)$")
    if extended then return "Anchor extended: stable snapshot pending" end

    local completed = status:match("^Post%-transition anchor completed; normal transaction scanning resumed%.$")
    if completed then return "Anchor complete: normal scanning resumed" end

    return status
end

function hustle_meter.get_compact_support_zip_status()
    local status = tostring(hustle_meter.S.supportZipStatus or "Ready to create support ZIP.")
    if status == "Ready to create support ZIP." then return "Ready" end
    if status == "Creating support ZIP... Please wait." then return "Creating... please wait." end
    if status == "Queued: preparing fast support ZIP..." then return "Queued..." end
    if status == "Preparing diagnostics..." then return "Preparing diagnostics..." end
    if status == "Finalizing ZIP directory..." then return "Finalizing..." end
    if status:find("^Scanning %d+/%d+:") then return status end
    if status:find("^Adding %d+/%d+:") then return status end
    if status:find("^Support ZIP created! File path copied to clipboard") then return "Created! Path copied." end
    if status:find("^Support ZIP created! Clipboard copy failed%. ZIP saved at:") then return "Created! Path not copied." end
    if status == "Support ZIP created." then return "Created." end
    if status == "Support ZIP failed." then return "Failed." end
    return status
end

