function hustle_meter.render_color_button(label, scheme, callback, width, height)
    if not ImGui or not ImGui.Button then return false end
    local colors = hustle_meter.ButtonColors[scheme or "Gray"] or hustle_meter.ButtonColors.Gray
    local pushed = 0
    if ImGui.PushStyleColor and ImGuiCol then
        local function push(key, color)
            if key ~= nil then
                ImGui.PushStyleColor(key, color[1], color[2], color[3], color[4])
                pushed = pushed + 1
            end
        end
        push(ImGuiCol.Button, colors.normal)
        push(ImGuiCol.ButtonHovered, colors.hover)
        push(ImGuiCol.ButtonActive, colors.active)
    end
    local clicked = ImGui.Button(tostring(label or "Button"), width or 0, height or 0) == true
    if pushed > 0 and ImGui.PopStyleColor then ImGui.PopStyleColor(pushed) end
    if clicked and callback then callback() end
    return clicked
end

function hustle_meter.push_tab_style()
    if not ImGui or not ImGui.PushStyleColor or not ImGuiCol then return 0 end
    local pushed = 0
    local function push(key, r, g, b, a)
        if key ~= nil then
            ImGui.PushStyleColor(key, r, g, b, a)
            pushed = pushed + 1
        end
    end
    push(ImGuiCol.Tab, 0.20, 0.10, 0.29, 0.96)
    push(ImGuiCol.TabHovered, 0.34, 0.16, 0.48, 1.00)
    push(ImGuiCol.TabActive, 0.10, 0.38, 0.20, 1.00)
    push(ImGuiCol.Header, 0.10, 0.28, 0.18, 0.92)
    push(ImGuiCol.HeaderHovered, 0.18, 0.42, 0.26, 1.00)
    push(ImGuiCol.HeaderActive, 0.28, 0.18, 0.46, 1.00)
    return pushed
end

function hustle_meter.pop_tab_style(count)
    count = tonumber(count or 0) or 0
    if count > 0 and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(count) end
end

function hustle_meter.copy_discord_link(silent)
    local copied = false
    if Utils and Utils.SetClipBoardText then
        Utils.SetClipBoardText(hustle_meter.DiscordLink, "")
        copied = true
    elseif ImGui and ImGui.SetClipboardText then
        ImGui.SetClipboardText(hustle_meter.DiscordLink)
        copied = true
    end
    if silent ~= true then
        hustle_meter.toast(copied and "Discord invite copied." or "Could not copy Discord invite.", 3000)
    end
    return copied
end

function hustle_meter.open_discord_link()
    if Utils and Utils.OpenURL then
        return Utils.OpenURL(hustle_meter.DiscordLink) ~= false
    end
    if Utils and Utils.OpenUrl then
        return Utils.OpenUrl(hustle_meter.DiscordLink) ~= false
    end
    if GUI and GUI.OpenURL then
        return GUI.OpenURL(hustle_meter.DiscordLink) ~= false
    end
    return false
end

function hustle_meter.copy_and_open_discord()
    local copied = hustle_meter.copy_discord_link(true)
    local opened = hustle_meter.open_discord_link()
    if opened and copied then
        hustle_meter.toast("Discord opened and invite copied.", 3500)
    elseif copied then
        hustle_meter.toast("Discord invite copied.", 3000)
    elseif opened then
        hustle_meter.toast("Discord opened.", 3000)
    else
        hustle_meter.toast("Could not open or copy Discord invite.", 4000)
    end
    return copied, opened
end

