-- ═══════════════════════════════════════════════════════════════════════════════════
-- tab renderer
-- note: draws the clean HustleMeter tab and the singleplayer gate message.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.render_main()
    if not hustle_meter.is_gta_online_session_detected() then
        hustle_meter.text_colored(1.0, 0.20, 0.20, 1.0, "HustleMeter is GTA Online-only.")
        hustle_meter.text_wrapped("Go Online to activate tracking.")
        return
    end
    hustle_meter.update_tracker(false)
    hustle_meter.recalculate_windows()
    local day = tonumber(hustle_meter.S.past24h or 0) or 0
    local week = tonumber(hustle_meter.S.past168h or 0) or 0
    local balance = tonumber(hustle_meter.S.lastBalance or 0) or 0
    local dayInfo = hustle_meter.get_dashboard_risk_info(day,24)
    local weekInfo = hustle_meter.get_dashboard_risk_info(week,168)

    hustle_meter.text_colored(0.35,1.00,0.45,1.00,"HUSTLEMETER")
    hustle_meter.same_line()
    hustle_meter.text_colored(0.72,0.42,1.00,1.00,tostring(hustle_meter.Version))
    hustle_meter.text_colored(0.42,0.82,1.00,1.00,"Track the grind. Keep the receipts.")
    hustle_meter.text("")

    if hustle_meter.begin_child("Tracking") then
        hustle_meter.text_colored(0.35,1.00,0.45,1.00,"TRACKING")
        hustle_meter.render_feature("EnableMoneyCheck")
        hustle_meter.subtle_text("GTA Online only  •  Account + LE/EE history is automatic")
        hustle_meter.end_child()
    end
    hustle_meter.text("")

    if ImGui and ImGui.BeginTable and ImGui.BeginTable("HMReleaseTotals",2,ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame or 0) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if hustle_meter.begin_child("1 Day") then
            local r,g,b=(dayInfo.r or 255)/255,(dayInfo.g or 255)/255,(dayInfo.b or 255)/255
            hustle_meter.text_colored(r,g,b,1.0,"1 DAY")
            hustle_meter.text_colored(r,g,b,1.0,hustle_meter.format_money(day))
            hustle_meter.subtle_text("Guidance: "..hustle_meter.format_money(hustle_meter.Risk.Max24))
            hustle_meter.text_wrapped("Remaining: "..hustle_meter.format_money(math.max(0,(hustle_meter.Risk.Max24 or 0)-day)))
            hustle_meter.end_child()
        end
        ImGui.TableSetColumnIndex(1)
        if hustle_meter.begin_child("7 Days") then
            local r,g,b=(weekInfo.r or 255)/255,(weekInfo.g or 255)/255,(weekInfo.b or 255)/255
            hustle_meter.text_colored(r,g,b,1.0,"7 DAYS")
            hustle_meter.text_colored(r,g,b,1.0,hustle_meter.format_money(week))
            hustle_meter.subtle_text("Guidance: "..hustle_meter.format_money(hustle_meter.Risk.Max168))
            hustle_meter.text_wrapped("Remaining: "..hustle_meter.format_money(math.max(0,(hustle_meter.Risk.Max168 or 0)-week)))
            hustle_meter.end_child()
        end
        ImGui.EndTable()
    end
    hustle_meter.text("")

    if ImGui and ImGui.BeginTable and ImGui.BeginTable("HMReleaseBottom",2,ImGuiTableFlags and ImGuiTableFlags.SizingStretchSame or 0) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if hustle_meter.begin_child("Current GTA$") then
            hustle_meter.text_colored(0.72,0.42,1.00,1.00,"CURRENT GTA$")
            hustle_meter.text_colored(1,1,1,1,hustle_meter.format_money(balance))
            hustle_meter.subtle_text("Validated Online balance")
            hustle_meter.end_child()
        end
        ImGui.TableSetColumnIndex(1)
        if hustle_meter.begin_child("Support") then
            hustle_meter.text_colored(1.00,0.78,0.25,1.00,"NEED HELP?")
            hustle_meter.render_feature("CreateSupportZip")
            hustle_meter.subtle_text(hustle_meter.get_compact_support_zip_status())
            hustle_meter.end_child()
        end
        ImGui.EndTable()
    end
    hustle_meter.text("")
end

