function hustle_meter.render_how_to_guide_picker()
    local guides = hustle_meter.HowToGuides or {}
    if #guides == 0 then return nil end

    local selected = math.floor(tonumber(hustle_meter.HowToState.selected or 1) or 1)
    if selected < 1 then selected = 1 end
    if selected > #guides then selected = #guides end
    hustle_meter.HowToState.selected = selected

    local current = guides[selected]
    local opened = ImGui and ImGui.BeginCombo and ImGui.BeginCombo("Guide", tostring(current.name or "Quick Setup")) == true
    if opened then
        for i, guide in ipairs(guides) do
            if ImGui.Selectable and ImGui.Selectable(tostring(guide.name), i == selected) == true then
                hustle_meter.HowToState.selected = i
                selected = i
                current = guide
            end
        end
        if ImGui.EndCombo then ImGui.EndCombo() end
    end
    return current
end

