-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 045 embedded Startup popup logo
-- source: https://raw.githubusercontent.com/xReVoLTiThemeDev/GTAV-Cherax/refs/heads/main/StartUp/assets/Startup_Logo.png
-- sha256: 32fdc59d3fa341f1f1d296e8147074e30a0ac043a5885f1f89a735ce901f03f1
-- ═══════════════════════════════════════════════════════════════════════════════════

hustle_meter.StartupLogoEmbeddedSize = 352212
hustle_meter.StartupLogoEmbeddedSha256 = "32fdc59d3fa341f1f1d296e8147074e30a0ac043a5885f1f89a735ce901f03f1"
hustle_meter.StartupLogoEmbeddedB64 = [=[

]=]

hustle_meter.StartupLogoState = hustle_meter.StartupLogoState or { texture_id=nil, texture_srv=nil, load_started=false, last_poll_ms=0 }

function hustle_meter.decode_base64_build045(data)
    data=tostring(data or ""):gsub("%s+","")
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup={}
    for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
    local out={}; local i=1
    while i<=#data do
        local a=lookup[data:sub(i,i)]; local b=lookup[data:sub(i+1,i+1)]
        local cc=data:sub(i+2,i+2); local dc=data:sub(i+3,i+3)
        local c=cc=="=" and nil or lookup[cc]; local d=dc=="=" and nil or lookup[dc]
        if a==nil or b==nil then break end
        local n=a*262144+b*4096+(c or 0)*64+(d or 0)
        out[#out+1]=string.char(math.floor(n/65536)%256)
        if c~=nil then out[#out+1]=string.char(math.floor(n/256)%256) end
        if d~=nil then out[#out+1]=string.char(n%256) end
        i=i+4
    end
    return table.concat(out)
end

function hustle_meter.ensure_startup_logo_file()
    local path=tostring(hustle_meter.StartupLogoPath or "")
    if path=="" then return false end
    if hustle_meter.file_exists(path) then return true end
    local encoded=hustle_meter.StartupLogoEmbeddedB64
    if type(encoded)~="string" or encoded=="" then return false end
    local bytes=hustle_meter.decode_base64_build045(encoded)
    local valid=type(bytes)=="string" and #bytes==tonumber(hustle_meter.StartupLogoEmbeddedSize or 0) and bytes:byte(1)==137 and bytes:sub(2,4)=="PNG"
    if not valid then return false end
    local f=io.open(path,"wb"); if not f then return false end
    f:write(bytes); f:close(); hustle_meter.StartupLogoEmbeddedB64=nil; return true
end

function hustle_meter.load_startup_logo_build045()
    local s=hustle_meter.StartupLogoState
    if s.texture_srv then return s.texture_srv end
    if not hustle_meter.ensure_startup_logo_file() or not Texture then return nil end
    if not s.texture_id then
        if s.load_started then return nil end
        s.load_started=true
        local id=nil
        if Texture.LoadTexture then id=Texture.LoadTexture(hustle_meter.StartupLogoPath) elseif Texture.LoadTextureAsync then id=Texture.LoadTextureAsync(hustle_meter.StartupLogoPath) end
        id=tonumber(id or 0) or 0
        if id==0 then s.load_started=false; return nil end
        s.texture_id=id
    end
    local now=hustle_meter.now(); if now-(tonumber(s.last_poll_ms or 0) or 0)<100 then return nil end; s.last_poll_ms=now
    local id=tonumber(s.texture_id or 0) or 0
    if Texture.IsTextureValid and Texture.IsTextureValid(id)~=true then return nil end
    local tex=Texture.GetTexture and Texture.GetTexture(id) or nil; if not tex then return nil end
    local srv=tex.GetCurrent and tex:GetCurrent() or tex; if not srv then return nil end
    s.texture_srv=srv; return srv
end

function hustle_meter.render_startup_logo_build045(size)
    size=tonumber(size or 118) or 118
    local srv=hustle_meter.load_startup_logo_build045(); if not srv or not ImGui or not ImGui.GetCursorScreenPos then return false end
    local x,y=ImGui.GetCursorScreenPos(); local px,py=0,0
    if type(x)=="number" then px,py=tonumber(x) or 0,tonumber(y) or 0 elseif type(x)=="table" then px=tonumber(x.x or x.X or x[1] or 0) or 0; py=tonumber(x.y or x.Y or x[2] or 0) or 0 end
    if ImGui.Dummy then ImGui.Dummy(size,size) end
    if ImGui.AddImageRounded then ImGui.AddImageRounded(srv,px,py,px+size,py+size,0,0,1,1,0xFFFFFFFF,12.0); return true end
    if ImGui.AddImage then ImGui.AddImage(srv,px,py,px+size,py+size); return true end
    return false
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- credits portrait
-- note: same hardened single-allocation Public_Urinal portrait pattern as Startup.
-- ═══════════════════════════════════════════════════════════════════════════════════

hustle_meter.CreditsState = hustle_meter.CreditsState or {
    download_started = false,
    load_started = false,
    load_failed = false,
    texture_id = nil,
    texture_srv = nil,
    active_path = "",
    load_requested_ms = 0,
    last_texture_poll_ms = 0,
    status = "Logo not loaded yet."
}

if not hustle_meter.CreditsState.texture_id and not hustle_meter.CreditsState.texture_srv then
    hustle_meter.CreditsState.load_started = false
    hustle_meter.CreditsState.load_failed = false
    hustle_meter.CreditsState.load_requested_ms = 0
    hustle_meter.CreditsState.last_texture_poll_ms = 0
end

function hustle_meter.resolve_public_urinal_icon_path()
    if hustle_meter.file_exists(hustle_meter.StartupPublicUrinalIconPath) then
        return hustle_meter.StartupPublicUrinalIconPath
    end
    if hustle_meter.file_exists(hustle_meter.PublicUrinalIconPath) then
        return hustle_meter.PublicUrinalIconPath
    end
    return hustle_meter.PublicUrinalIconPath
end

function hustle_meter.reset_public_urinal_texture_state()
    local state = hustle_meter.CreditsState
    state.load_started = false
    state.load_failed = false
    state.texture_id = nil
    state.texture_srv = nil
    state.active_path = ""
    state.load_requested_ms = 0
    state.last_texture_poll_ms = 0
end

function hustle_meter.load_public_urinal_icon()
    local state = hustle_meter.CreditsState
    if state.texture_srv then return state.texture_srv end
    if state.load_failed == true then return nil end

    local path = hustle_meter.resolve_public_urinal_icon_path()
    if not hustle_meter.file_exists(path) then return nil end
    if not Texture then
        state.load_failed = true
        state.status = "Texture API unavailable."
        return nil
    end

    -- Allocate exactly one Cherax texture slot. If an async texture is not GPU-ready
    -- yet, only poll that existing allocation instead of allocating a new one per frame.
    if not state.texture_id then
        if state.load_started == true then return nil end
        state.load_started = true
        state.active_path = path
        state.load_requested_ms = hustle_meter.now()
        state.last_texture_poll_ms = 0
        state.status = "Loading Public_Urinal logo..."

        local texture_id = nil
        if Texture.LoadTextureAsync then
            texture_id = Texture.LoadTextureAsync(path)
        elseif Texture.LoadTexture then
            texture_id = Texture.LoadTexture(path)
        end

        texture_id = tonumber(texture_id)
        if not texture_id or texture_id == 0 then
            state.load_failed = true
            state.status = "Logo texture allocation failed."
            return nil
        end
        state.texture_id = texture_id
    end

    local now = hustle_meter.now()
    if now - (tonumber(state.last_texture_poll_ms or 0) or 0) < 125 then return nil end
    state.last_texture_poll_ms = now

    local texture_id = tonumber(state.texture_id or 0) or 0
    if texture_id == 0 then return nil end

    if Texture.IsTextureValid and Texture.IsTextureValid(texture_id) ~= true then
        state.status = "Public_Urinal logo is still loading..."
        return nil
    end

    local texture = Texture.GetTexture and Texture.GetTexture(texture_id) or nil
    if not texture then
        state.status = "Public_Urinal logo is still loading..."
        return nil
    end

    local srv = texture:GetCurrent()
    if not srv then
        state.status = "Public_Urinal logo is still loading..."
        return nil
    end

    state.texture_srv = srv
    state.status = "Public_Urinal logo loaded."
    return srv
end

function hustle_meter.download_public_urinal_icon()
    local state = hustle_meter.CreditsState

    if hustle_meter.file_exists(hustle_meter.StartupPublicUrinalIconPath) then
        hustle_meter.load_public_urinal_icon()
        return
    end

    if hustle_meter.file_exists(hustle_meter.PublicUrinalIconPath) then
        hustle_meter.load_public_urinal_icon()
        return
    end

    if state.download_started then return end
    state.download_started = true
    state.status = "Downloading Public_Urinal logo..."

    if not Script or not Script.QueueJob or not Curl or not Curl.Easy then
        state.download_started = false
        state.status = "Logo download unavailable."
        return
    end

    Script.QueueJob(function()
        local curl = Curl.Easy()
        curl:Setopt(10002, hustle_meter.PublicUrinalIconUrl)
        curl:Setopt(52, 1)
        curl:Setopt(10018, "Mozilla/5.0 HustleMeter-Cherax")
        curl:Perform()

        local ticks = 0
        while not curl:GetFinished() and ticks < 300 do
            if Script and Script.Yield then Script.Yield(50) end
            ticks = ticks + 1
        end

        if not curl:GetFinished() then
            state.download_started = false
            state.status = "Logo download timed out."
            return
        end

        local code, content = curl:GetResponse()
        local success = code == 0 or code == true or (eCurlCode and code == eCurlCode.CURLE_OK)
        local looksLikePng = type(content) == "string"
            and #content > 100
            and ((content:byte(1) == 137 and content:sub(2, 4) == "PNG") or #content > 1000)

        if not success or not looksLikePng then
            state.download_started = false
            state.status = "Logo download failed."
            return
        end

        if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(hustle_meter.PublicUrinalIconDir) end
        local file = io.open(hustle_meter.PublicUrinalIconPath, "wb")
        if not file then
            state.download_started = false
            state.status = "Could not save Public_Urinal logo."
            return
        end

        file:write(content)
        file:close()

        state.download_started = false
        hustle_meter.reset_public_urinal_texture_state()
        state.status = "Public_Urinal logo downloaded."
        hustle_meter.load_public_urinal_icon()
    end)
end

function hustle_meter.ensure_public_urinal_icon()
    local path = hustle_meter.resolve_public_urinal_icon_path()
    if hustle_meter.file_exists(path) then
        hustle_meter.load_public_urinal_icon()
    else
        hustle_meter.download_public_urinal_icon()
    end
end

function hustle_meter.credits_get_cursor_pos_x()
    return ImGui and ImGui.GetCursorPosX and (tonumber(ImGui.GetCursorPosX()) or 0) or 0
end

function hustle_meter.credits_get_cursor_pos_y()
    return ImGui and ImGui.GetCursorPosY and (tonumber(ImGui.GetCursorPosY()) or 0) or 0
end

function hustle_meter.credits_set_cursor_pos_x(value)
    if ImGui and ImGui.SetCursorPosX then ImGui.SetCursorPosX(value) end
end

function hustle_meter.credits_set_cursor_pos_y(value)
    if ImGui and ImGui.SetCursorPosY then ImGui.SetCursorPosY(value) end
end

function hustle_meter.credits_content_width()
    local value = ImGui and ImGui.GetContentRegionAvail and ImGui.GetContentRegionAvail() or 0
    if type(value) == "number" then return tonumber(value) or 0 end
    if type(value) == "table" then
        return tonumber(value.x or value.X or value[1] or 0) or 0
    end
    return 0
end

function hustle_meter.render_public_urinal_icon(size)
    size = tonumber(size or 138) or 138
    hustle_meter.ensure_public_urinal_icon()

    local srv = hustle_meter.CreditsState.texture_srv or hustle_meter.load_public_urinal_icon()
    if not srv or not ImGui or not ImGui.GetCursorScreenPos then return false end

    local x, y = ImGui.GetCursorScreenPos()
    local cursor_x, cursor_y = 0, 0
    if type(x) == "number" then
        cursor_x, cursor_y = tonumber(x) or 0, tonumber(y) or 0
    elseif type(x) == "table" then
        cursor_x = tonumber(x.x or x.X or x[1] or 0) or 0
        cursor_y = tonumber(x.y or x.Y or x[2] or 0) or 0
    end
    if cursor_x <= 0 or cursor_y <= 0 then return false end

    local reserved = false
    if ImGui.Button then
        local pushed = 0
        if ImGui.PushStyleColor and ImGuiCol then
            ImGui.PushStyleColor(ImGuiCol.Button, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
            ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
        end
        ImGui.Button("##HustleMeter_Public_Urinal_Logo", size, size)
        if pushed > 0 and ImGui.PopStyleColor then ImGui.PopStyleColor(pushed) end
        reserved = true
    elseif ImGui.Dummy then
        ImGui.Dummy(size, size)
        reserved = true
    end

    if ImGui.AddImageRounded then
        ImGui.AddImageRounded(
            srv,
            cursor_x, cursor_y,
            cursor_x + size, cursor_y + size,
            0.0, 0.0, 1.0, 1.0,
            0xFFFFFFFF,
            8.0
        )
        return true
    end

    if ImGui.AddImage then
        ImGui.AddImage(srv, cursor_x, cursor_y, cursor_x + size, cursor_y + size)
        return true
    end

    return reserved
end

function hustle_meter.render_credits_portrait_right(anchor_y)
    local saved_x = hustle_meter.credits_get_cursor_pos_x()
    local saved_y = hustle_meter.credits_get_cursor_pos_y()
    local width = hustle_meter.credits_content_width()
    local size = 138

    local target_x = saved_x + 300
    if width > 360 then
        target_x = saved_x + math.max(250, width - size - 38)
    end

    hustle_meter.credits_set_cursor_pos_x(target_x)
    hustle_meter.credits_set_cursor_pos_y((tonumber(anchor_y) or saved_y) + 8)

    local drawn = hustle_meter.render_public_urinal_icon(size)

    hustle_meter.credits_set_cursor_pos_x(saved_x)
    hustle_meter.credits_set_cursor_pos_y(saved_y)
    return drawn
end

