        hustle_meter.text_colored(0.72, 0.42, 1.00, 1.00, "TRACKING DESIGN")
        hustle_meter.text_wrapped("Ledgers are isolated by Rockstar account and GTA edition (LE/EE). GTA Online transitions are handled conservatively because money/session natives can temporarily report incomplete values while loading.")
        hustle_meter.text_wrapped("Automatic diagnostics and Create Support ZIP preserve the ledger, transition timeline, edition information, and suspicious-transaction state needed for support.")
        hustle_meter.text("")

        hustle_meter.text("")
        hustle_meter.separator()

        local show_scripts = true
        if ImGui and ImGui.CollapsingHeader then
            show_scripts = ImGui.CollapsingHeader("Discover More Scripts") == true
        end
        if show_scripts then
            hustle_meter.render_scripts_showcase_content()
        else
            hustle_meter.subtle_text("Expand Discover More Scripts to see other Public_Urinal Cherax projects.")
        end

        hustle_meter.end_child()
    end
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- first-run welcome
-- note: one-time saved intro; Config can reopen a non-persistent preview.
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.get_display_size()
    if not ImGui or not ImGui.GetDisplaySize then return 1920, 1080 end
    local width, height = ImGui.GetDisplaySize()
    if type(width) == "table" then
        return tonumber(width.x or width.X or width[1] or 1920) or 1920,
            tonumber(width.y or width.Y or width[2] or 1080) or 1080
    end
    return tonumber(width or 1920) or 1920, tonumber(height or 1080) or 1080
end

function hustle_meter.first_run_window_flags()
    local flags = 0
    local function add(value)
        if value then flags = flags + value end
    end
    if ImGuiWindowFlags then
        add(ImGuiWindowFlags.NoTitleBar)
        add(ImGuiWindowFlags.NoResize)
        add(ImGuiWindowFlags.NoMove)
        add(ImGuiWindowFlags.NoCollapse)
        add(ImGuiWindowFlags.NoScrollbar)
        add(ImGuiWindowFlags.NoSavedSettings)
    end
    return flags
end

function hustle_meter.push_first_run_style(uiScale)
    uiScale = tonumber(uiScale or 1.0) or 1.0
    if uiScale <= 0 then uiScale = 1.0 end
    local colors, vars = 0, 0
    if ImGui and ImGui.PushStyleColor and ImGuiCol then
        local function color(key, r, g, b, a)
            if key ~= nil then
                ImGui.PushStyleColor(key, r, g, b, a)
                colors = colors + 1
            end
        end
        color(ImGuiCol.WindowBg, 0.035, 0.10, 0.055, 0.985)
        color(ImGuiCol.ChildBg, 0.045, 0.14, 0.075, 0.985)
        color(ImGuiCol.PopupBg, 0.04, 0.12, 0.065, 0.985)
        color(ImGuiCol.Border, 0.35, 1.00, 0.45, 1.00)
        color(ImGuiCol.Separator, 0.20, 0.55, 0.27, 1.00)
        color(ImGuiCol.Text, 1.00, 1.00, 1.00, 1.00)
    end
    if ImGui and ImGui.PushStyleVar and ImGuiStyleVar then
        local function scalar(key, value)
            if key ~= nil then ImGui.PushStyleVar(key, value); vars = vars + 1 end
        end
        local function pair(key, x, y)
            if key ~= nil then ImGui.PushStyleVar(key, x, y); vars = vars + 1 end
        end
        scalar(ImGuiStyleVar.WindowRounding, 16.0 * uiScale)
        scalar(ImGuiStyleVar.WindowBorderSize, 2.0 * uiScale)
        scalar(ImGuiStyleVar.FrameRounding, 10.0 * uiScale)
        scalar(ImGuiStyleVar.ChildRounding, 12.0 * uiScale)
        scalar(ImGuiStyleVar.ChildBorderSize, 1.0 * uiScale)
        pair(ImGuiStyleVar.WindowPadding, 24.0 * uiScale, 22.0 * uiScale)
        pair(ImGuiStyleVar.FramePadding, 10.0 * uiScale, 8.0 * uiScale)
        pair(ImGuiStyleVar.ItemSpacing, 12.0 * uiScale, 10.0 * uiScale)
    end
    return colors, vars
end

function hustle_meter.pop_first_run_style(colors, vars)
    if tonumber(vars or 0) > 0 and ImGui and ImGui.PopStyleVar then ImGui.PopStyleVar(vars) end
    if tonumber(colors or 0) > 0 and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(colors) end
end

function hustle_meter.first_run_begin_card(id, height)
    if not ImGui or not ImGui.BeginChild then return false end
    local flags = 0
    if ImGuiWindowFlags then
        flags = (ImGuiWindowFlags.NoScrollbar or 0) + (ImGuiWindowFlags.NoScrollWithMouse or 0)
    end
    return ImGui.BeginChild(tostring(id), 0, tonumber(height or 0) or 0, true, flags) == true
end

function hustle_meter.first_run_end_card()
    if ImGui and ImGui.EndChild then ImGui.EndChild() end
end

function hustle_meter.first_run_feature_line(r, g, b, title, body)
    hustle_meter.text_colored(r, g, b, 1.00, "• " .. tostring(title))
    hustle_meter.text_wrapped(body)
end

function hustle_meter.complete_first_run_welcome()
    if hustle_meter.FirstRunPreview == true then
        hustle_meter.FirstRunPreview = false
        hustle_meter.toast("Welcome preview closed. Saved first-run state was not changed.", 3500)
        return
    end
    hustle_meter.S.firstRunWelcomeCompleted = true
    hustle_meter.S.firstRunWelcomeCompletedAt = os.time()
    hustle_meter.save_config(true)
    hustle_meter.toast("Welcome complete. HustleMeter is ready.", 3500)
end

function hustle_meter.keep_first_run_welcome_active()
    if hustle_meter.S.firstRunWelcomeCompleted == true and hustle_meter.FirstRunPreview ~= true then return end
    local now = hustle_meter.now()
    if now - (tonumber(hustle_meter.FirstRunLastForceOpenMs or 0) or 0) < 750 then return end
    hustle_meter.FirstRunLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.render_first_run_welcome()
    if hustle_meter.S.firstRunWelcomeCompleted == true and hustle_meter.FirstRunPreview ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    local screenW, screenH = hustle_meter.get_display_size()
    local width = math.min(840, math.max(660, screenW - 110))
    local height = math.min(580, math.max(500, screenH - 100))
    local posX = math.max(18, (screenW - width) * 0.5)
    local posY = math.max(18, (screenH - height) * 0.5)

    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(posX, posY, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    local colors, vars = hustle_meter.push_first_run_style()
    local visible = ImGui.Begin("##HustleMeter_First_Run_Welcome", true, hustle_meter.first_run_window_flags())
    if visible then
        hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "FIRST-TIME SETUP")
        hustle_meter.text_colored(0.35, 1.00, 0.45, 1.00, "WELCOME TO HUSTLEMETER")
        hustle_meter.same_line()
        hustle_meter.text_colored(0.72, 0.72, 0.72, 1.00, tostring(hustle_meter.Version))
        hustle_meter.text_colored(0.42, 0.82, 1.00, 1.00, "Track the grind. Keep the receipts.")
        if hustle_meter.FirstRunPreview == true then
            hustle_meter.warn_text("PREVIEW MODE — your saved first-run completion state will not change.")
        else
            hustle_meter.subtle_text("A one-time introduction to clean, transition-safe GTA Online earnings tracking.")
        end
        hustle_meter.separator()

        if ImGui.BeginTable and ImGui.BeginTable("HustleMeterFirstRunLayout", 2, ImGuiTableFlags and ImGuiTableFlags.SizingStretchProp or 0) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            if hustle_meter.first_run_begin_card("##HustleMeter_First_Run_Left", 250) then
                hustle_meter.section_title("What HustleMeter does")
                hustle_meter.first_run_feature_line(0.35, 1.00, 0.45, "Rolling earnings", "Tracks validated positive GTA$ changes across real-life 1 Day and 7 Days windows.")
                hustle_meter.first_run_feature_line(0.42, 0.82, 1.00, "Transition-safe tracking", "Protects the baseline through Story Mode / GTA Online loading and bank-wallet reshuffles.")
                hustle_meter.first_run_feature_line(0.72, 0.42, 1.00, "Edition-isolated ledgers", "Separates Rockstar account history by LE / EE so different GTA editions do not overwrite each other.")
                hustle_meter.first_run_end_card()
            end

            ImGui.TableSetColumnIndex(1)
            if hustle_meter.first_run_begin_card("##HustleMeter_First_Run_Right", 250) then
                hustle_meter.section_title("Before you start")
                hustle_meter.warn_text("Run HustleMeter on startup")
                hustle_meter.text_wrapped("Keeping the script running gives the rolling ledger its cleanest timestamps and transition history.")
                hustle_meter.text("")
                hustle_meter.text_colored(0.42, 0.82, 1.00, 1.00, "GTA Online only")
                hustle_meter.text_wrapped("Story Mode balances are intentionally ignored.")
                hustle_meter.text("")
                hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "Need support?")
                hustle_meter.text_wrapped("Click Create Support ZIP. Logs and diagnostics are captured automatically.")
                hustle_meter.first_run_end_card()
            end
            ImGui.EndTable()
        end

        hustle_meter.text("")
        if hustle_meter.first_run_begin_card("##HustleMeter_First_Run_Footer", 130) then
            hustle_meter.text_colored(0.96, 0.96, 0.96, 1.00, "Ready to track?")
            hustle_meter.subtle_text("Z shows the HUD. Configure timed or No timeout behavior from Main / Config.")
            hustle_meter.separator()
            hustle_meter.render_color_button("CONTINUE TO HUSTLEMETER", "Green", hustle_meter.complete_first_run_welcome, 310, 42)
            hustle_meter.same_line()
            hustle_meter.render_color_button("OPEN DISCORD", "Blue", function()
                hustle_meter.copy_and_open_discord()
            end, 210, 42)
            hustle_meter.subtle_text("Updates  •  Support  •  Bug reports")
            hustle_meter.first_run_end_card()
        end
    end
    ImGui.End()
    hustle_meter.pop_first_run_style(colors, vars)
end


