function hustle_meter.render_settings_reset_confirmation()
    if hustle_meter.SettingsResetConfirmOpen ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    local screenW, screenH = hustle_meter.get_display_size()
    local width = math.min(720, math.max(500, screenW - 80))
    local height = math.min(520, math.max(400, screenH - 80))
    width = math.min(width, math.max(360, screenW - 20))
    height = math.min(height, math.max(340, screenH - 20))
