    if visible then
        hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "RESET SETTINGS?")
        hustle_meter.text_colored(1.00, 1.00, 1.00, 1.00, "Restore HustleMeter's user-facing defaults?")
        hustle_meter.subtle_text("Money history and Rockstar account ledgers are not changed.")
        hustle_meter.separator()

        local bodyHeight = math.max(100, height - 215)
        local bodyVisible = true
        if ImGui.BeginChild then
            bodyVisible = ImGui.BeginChild("##HustleMeter_Settings_Reset_Body", 0, bodyHeight, true, 0) == true
        end
        if bodyVisible then
            hustle_meter.section_title("Settings that will reset")
            hustle_meter.text_wrapped("• HustleMeter enabled state")
            hustle_meter.text_wrapped("• Z-key HUD behavior and timeout")
            hustle_meter.text_wrapped("• 1 Day / 7 Days HUD position and scale")
            hustle_meter.text_wrapped("• HUD alpha, outline, and warning colors")
            hustle_meter.text("")
            hustle_meter.text_colored(0.35, 1.00, 0.45, 1.00, "Money history will NOT be changed.")
            hustle_meter.text_wrapped("The active Rockstar account ledger, rolling earnings history, diagnostics, support files, and first-run completion state are preserved.")
            hustle_meter.text("")
            hustle_meter.subtle_text("Prime-safe: YES only queues the reset. The normal HustleMeter worker performs it after this popup closes.")
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        hustle_meter.separator()
        hustle_meter.render_color_button("NO, GO BACK", "Green", function()
            hustle_meter.close_settings_reset_confirmation()
        end, -1, 42)
        hustle_meter.render_color_button("YES, RESET SETTINGS", "Gold", function()
            hustle_meter.schedule_settings_reset()
            hustle_meter.close_settings_reset_confirmation()
        end, -1, 42)
    end
    ImGui.End()
    hustle_meter.pop_first_run_style(colors, vars)
end

function hustle_meter.render_money_reset_confirmation()
    if hustle_meter.MoneyResetConfirmOpen ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    hustle_meter.recalculate_windows()

    local screenW, screenH = hustle_meter.get_display_size()
    local width = math.min(760, math.max(520, screenW - 80))
    local height = math.min(620, math.max(460, screenH - 80))
    width = math.min(width, math.max(360, screenW - 20))
    height = math.min(height, math.max(360, screenH - 20))
    local posX = math.max(10, (screenW - width) * 0.5)
    local posY = math.max(10, (screenH - height) * 0.5)

    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(posX, posY, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    local colors, vars = hustle_meter.push_money_reset_style()
    local visible = ImGui.Begin("##HustleMeter_Money_Reset_Confirm", true, hustle_meter.first_run_window_flags())
    if visible then
        hustle_meter.text_colored(1.00, 0.30, 0.32, 1.00, "RESET MONEY HISTORY?")
        hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "Are you sure you want to do this?")
        hustle_meter.subtle_text("This action resets HustleMeter's LOCAL rolling ledger only.")
        hustle_meter.separator()

        local bodyHeight = math.max(120, height - 245)
        local bodyFlags = 0
        if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar then
            bodyFlags = bodyFlags + ImGuiWindowFlags.AlwaysVerticalScrollbar
        end
        local bodyVisible = true
        if ImGui.BeginChild then
            bodyVisible = ImGui.BeginChild("##HustleMeter_Money_Reset_Body", 0, bodyHeight, true, bodyFlags) == true
        end
        if bodyVisible then
            local past24 = tonumber(hustle_meter.S.past24h or 0) or 0
            local past168 = tonumber(hustle_meter.S.past168h or 0) or 0
            local max24 = tonumber(hustle_meter.Risk.Max24 or 30000000) or 30000000
            local max168 = tonumber(hustle_meter.Risk.Max168 or 150000000) or 150000000
            local color24, band24 = hustle_meter.get_dashboard_risk_info(past24, 24)
            local color168, band168 = hustle_meter.get_dashboard_risk_info(past168, 168)
            local overGuidance = past24 > max24 or past168 > max168

            hustle_meter.section_title("Current active ledger")
            hustle_meter.color_label(
                "Rockstar:",
                hustle_meter.account_display_name(hustle_meter.S.currentAccountName or "Detecting...", hustle_meter.S.currentGameEdition or "Unknown"),
                0.42, 0.82, 1.00, 1.00, 1.00, 1.00
            )
            hustle_meter.subtle_text("Only this active Rockstar account + current GTA edition will be reset.")
            hustle_meter.text("")

            hustle_meter.text_colored(color24.r / 255.0, color24.g / 255.0, color24.b / 255.0, 1.00,
                "1 Day: " .. hustle_meter.format_money(past24) .. "  /  " .. hustle_meter.format_money(max24) .. "  •  " .. tostring(color24.label or band24))
            hustle_meter.text_colored(color168.r / 255.0, color168.g / 255.0, color168.b / 255.0, 1.00,
                "7 Days: " .. hustle_meter.format_money(past168) .. "  /  " .. hustle_meter.format_money(max168) .. "  •  " .. tostring(color168.label or band168))

            hustle_meter.text("")
            hustle_meter.warn_text("IMPORTANT")
            hustle_meter.text_wrapped("Resetting HustleMeter does NOT erase Rockstar transaction records, change your GTA$ balance, or reduce any enforcement risk tied to previous activity.")
            hustle_meter.text("")
            hustle_meter.text_wrapped("The $30,000,000 / 1 Day and $150,000,000 / 7 Days values are HustleMeter guidance limits, not official Rockstar-published ban thresholds. High or unusual GTA$ activity can still carry account risk regardless of what this local HUD displays.")
            hustle_meter.text("")

            if overGuidance then
                hustle_meter.text_colored(1.00, 0.30, 0.32, 1.00, "RECOMMENDATION: NO, GO BACK")
                hustle_meter.text_wrapped("Your tracked earnings are already above at least one HustleMeter guidance limit. We strongly advise keeping the history so the HUD continues to show your real rolling total.")
            else
                hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "RESET ONLY FOR A DELIBERATE FRESH TRACKING PERIOD")
                hustle_meter.text_wrapped("A backup will be preserved automatically, but the visible 1 Day / 7 Days totals will restart from $0 after the reset.")
            end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        hustle_meter.separator()
        hustle_meter.render_color_button("NO, GO BACK", "Green", function()
            hustle_meter.close_money_reset_confirmation()
        end, -1, 42)
        hustle_meter.render_color_button("YES, RESET MONEY HISTORY", "Red", function()
            hustle_meter.schedule_money_history_reset()
            hustle_meter.close_money_reset_confirmation()
        end, -1, 42)
    end
    ImGui.End()
    hustle_meter.pop_first_run_style(colors, vars)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- Build 046 release popup flow
-- What's New / Changelog -> Startup
-- 0.75 DPI to match the compact Startup guided-popup approach.
-- ═══════════════════════════════════════════════════════════════════════════════════

hustle_meter.ReleasePopupStage = hustle_meter.ReleasePopupStage or nil
hustle_meter.ReleasePopupPreview = hustle_meter.ReleasePopupPreview or false
hustle_meter.ReleasePopupDpiScale = 0.80
hustle_meter.PopupCurrentDpiScale = 1.0

function hustle_meter.release_popup_px(value)
    local scale = tonumber(hustle_meter.PopupCurrentDpiScale or 1.0) or 1.0
    return math.max(1, math.floor((tonumber(value or 0) or 0) * scale + 0.5))
end

function hustle_meter.prepare_release_popup()
    if hustle_meter.ReleasePopupStage ~= nil then return end
    if tostring(hustle_meter.S.lastAcknowledgedReleaseBuild or "") ~= tostring(hustle_meter.Build) then
        hustle_meter.ReleasePopupStage = "changelog"
    end
end

function hustle_meter.finish_release_popup()
    local preview = hustle_meter.ReleasePopupPreview == true
    hustle_meter.ReleasePopupStage = nil
    hustle_meter.ReleasePopupPreview = false
    if not preview then
        hustle_meter.S.lastAcknowledgedStartupPromoBuild = tostring(hustle_meter.Build)
        hustle_meter.save_config(true)
    end
end

function hustle_meter.continue_release_changelog()
    if hustle_meter.ReleasePopupPreview ~= true then
        hustle_meter.S.lastAcknowledgedReleaseBuild = tostring(hustle_meter.Build)
        hustle_meter.save_config(true)
    end
    hustle_meter.ReleasePopupStage = "startup"
end

function hustle_meter.keep_first_run_welcome_active()
    hustle_meter.prepare_release_popup()
    if hustle_meter.ReleasePopupStage == nil then return end
    local now = hustle_meter.now()
    if now - (tonumber(hustle_meter.FirstRunLastForceOpenMs or 0) or 0) < 750 then return end
    hustle_meter.FirstRunLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function hustle_meter.release_popup_scroll_begin_build046(id, height)
    local pushed = false
    if ImGui and ImGui.PushStyleVar and ImGuiStyleVar and ImGuiStyleVar.ScrollbarSize then
        ImGui.PushStyleVar(
            ImGuiStyleVar.ScrollbarSize,
            math.max(5.0, 7.0 * (tonumber(hustle_meter.PopupCurrentDpiScale or 1.0) or 1.0))
        )
        pushed = true
    end

    local flags = 0
    if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar then
        flags = flags + ImGuiWindowFlags.AlwaysVerticalScrollbar
    end

    local opened = true
    if ImGui and ImGui.BeginChild then
        opened = ImGui.BeginChild(
            tostring(id),
            0,
            hustle_meter.release_popup_px(height or 355),
            true,
            flags
        ) == true
    end
    return opened, pushed
end

function hustle_meter.release_popup_scroll_end_build046(pushed)
    if ImGui and ImGui.EndChild then ImGui.EndChild() end
    if pushed and ImGui and ImGui.PopStyleVar then ImGui.PopStyleVar(1) end
end

function hustle_meter.render_release_changelog()
    hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "WHAT'S NEW / CHANGELOG")
    hustle_meter.text_colored(0.35, 1.00, 0.45, 1.00, "HUSTLEMETER " .. tostring(hustle_meter.Version))
    hustle_meter.subtle_text("Build 061  •  Production")
    hustle_meter.separator()

    local opened, pushed =
        hustle_meter.release_popup_scroll_begin_build046("##HM046_ChangelogScroll", 405)

    if opened and hustle_meter.first_run_begin_card(
        "##HM046_Changes",
        hustle_meter.release_popup_px(390)
    ) then
        hustle_meter.text_wrapped("• Smart Heists has been removed from HustleMeter.")
        hustle_meter.text_wrapped("• HustleMeter no longer changes Silent Night or Codax player cuts, heist presets, cooldown values, bonuses, or weekly heist multipliers.")
        hustle_meter.text_wrapped("• Earnings history still ignores brief all-zero transition samples and repairs affected imported history once with a backup.")

        hustle_meter.text("")
        hustle_meter.text_colored(0.42, 0.82, 1.00, 1.00, "Focused scope")
        hustle_meter.text_wrapped("• Main / Settings keeps HustleMeter focused on money tracking, history, HUD guidance, diagnostics, and support.")
        hustle_meter.text_wrapped("• Third-party heist configuration stays with the script that provides it.")
        hustle_meter.text_wrapped("• High-frequency diagnostic systems remain disabled during normal use.")

        hustle_meter.text("")
        hustle_meter.text_colored(0.72, 0.42, 1.00, 1.00, "Support")
        hustle_meter.text_wrapped("• Support ZIP keeps HustleMeter scanner, transition, ledger, and Cherax.log evidence without collecting third-party heist presets or Codax settings.")
        hustle_meter.first_run_end_card()
    end

    hustle_meter.release_popup_scroll_end_build046(pushed)
    hustle_meter.text("")
    hustle_meter.render_color_button(
        "CONTINUE",
        "Green",
        hustle_meter.continue_release_changelog,
        -1,
        hustle_meter.release_popup_px(40)
    )
end

function hustle_meter.render_startup_promo()
    hustle_meter.text_colored(0.72, 0.42, 1.00, 1.00, "STARTUP")
    hustle_meter.text_colored(0.42, 0.82, 1.00, 1.00, "From Launch to Lobby.")
    hustle_meter.separator()

    local opened, pushed =
        hustle_meter.release_popup_scroll_begin_build046("##HM046_StartupScroll", 405)

    if opened then
        local width = hustle_meter.credits_content_width()
        local logoSize = hustle_meter.release_popup_px(118)

        if ImGui and ImGui.SetCursorPosX and width > logoSize then
            local currentX = hustle_meter.credits_get_cursor_pos_x()
            ImGui.SetCursorPosX(currentX + math.max(0, (width - logoSize) * 0.5))
        end

        hustle_meter.render_startup_logo_build045(logoSize)
        hustle_meter.text("")

        if hustle_meter.first_run_begin_card(
            "##HM046_Startup",
            hustle_meter.release_popup_px(275)
        ) then
            hustle_meter.text_colored(0.35, 1.00, 0.45, 1.00, "Want to join other Cherax players without Prime?")
            hustle_meter.text_wrapped("Startup Browser lets you browse sessions being hosted by other Startup users and join the community.")

            hustle_meter.text("")
            hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "Hosting a heist but no one's joining?")
            hustle_meter.text_wrapped("Use Startup to post your lobby to other Cherax players instead of waiting alone.")

            hustle_meter.text("")
            hustle_meter.text_colored(0.72, 0.42, 1.00, 1.00, "HustleMeter + Startup")
            hustle_meter.text_wrapped("Set your Smart Heist cuts, host your finale, or browse other Startup lobbies when you want to join.")
            hustle_meter.first_run_end_card()
        end
    end

    hustle_meter.release_popup_scroll_end_build046(pushed)
    hustle_meter.text("")

    hustle_meter.render_color_button(
        "OPEN STARTUP DISCORD",
        "Purple",
        function()
            local openedDiscord = hustle_meter.open_url(hustle_meter.StartupDiscordLink)
            if openedDiscord then
                hustle_meter.toast("Startup Discord opened.", 3000)
            else
                hustle_meter.copy_to_clipboard(hustle_meter.StartupDiscordLink)
                hustle_meter.toast("Startup Discord invite copied.", 3500)
            end
            hustle_meter.finish_release_popup()
        end,
        -1,
        hustle_meter.release_popup_px(40)
    )

    hustle_meter.render_color_button(
        "CONTINUE TO HUSTLEMETER",
        "Green",
        hustle_meter.finish_release_popup,
        -1,
        hustle_meter.release_popup_px(38)
    )
end

function hustle_meter.render_first_run_welcome()
    hustle_meter.prepare_release_popup()
    if hustle_meter.ReleasePopupStage == nil then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    local screenW, screenH = hustle_meter.get_display_size()
    local dpi = tonumber(hustle_meter.ReleasePopupDpiScale or 0.80) or 0.80
    if dpi < 0.50 then dpi = 0.50 end
    if dpi > 1.00 then dpi = 1.00 end

    local baseWidth = math.min(912, math.max(720, screenW - 72))
    local baseHeight = math.min(648, math.max(546, screenH - 66))
    local width = math.max(540, math.floor(baseWidth * 0.90))
    local height = math.max(408, math.floor(baseHeight * 0.90))
    local posX = math.max(18, (screenW - width) * 0.5)
    local posY = math.max(18, (screenH - height) * 0.5)

    if ImGui.SetNextWindowPos then
        ImGui.SetNextWindowPos(posX, posY, ImGuiCond and ImGuiCond.Always or 0)
    end
    if ImGui.SetNextWindowSize then
        ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0)
    end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    hustle_meter.PopupCurrentDpiScale = dpi
    local colors, vars = hustle_meter.push_first_run_style(dpi)
    local visible =
        ImGui.Begin("##HustleMeterReleasePopup", true, hustle_meter.first_run_window_flags())

    if visible then
        if ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(dpi) end

        if hustle_meter.ReleasePopupPreview == true then
            hustle_meter.text_colored(1.00, 0.78, 0.25, 1.00, "PREVIEW")
            hustle_meter.subtle_text("Nothing will be re-acknowledged.")
            hustle_meter.text("")
        end

        if hustle_meter.ReleasePopupStage == "startup" then
            hustle_meter.render_startup_promo()
        else
            hustle_meter.render_release_changelog()
        end

        if ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(1.0) end
    end

    ImGui.End()
    hustle_meter.PopupCurrentDpiScale = 1.0
    hustle_meter.pop_first_run_style(colors, vars)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- tab routing
-- ═══════════════════════════════════════════════════════════════════════════════════

function hustle_meter.render_tab()
    local pushed=hustle_meter.push_tab_style()
    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabBar("HustleMeterTabs") then
        if ImGui.BeginTabItem("Main") then hustle_meter.render_main(); ImGui.EndTabItem() end
        if ImGui.BeginTabItem("Settings") then hustle_meter.render_config(); ImGui.EndTabItem() end
        ImGui.EndTabBar()
    else
        hustle_meter.render_main()
    end
    hustle_meter.pop_tab_style(pushed)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- init / runtime loops
-- note: boot order: storage → config → history → UI → HUD loop → tracker loop.
-- ═══════════════════════════════════════════════════════════════════════════════════

-- =========================================================
-- Init
-- =========================================================

hustle_meter.ensure_dir()
hustle_meter.migrate_legacy_storage()
-- Auto-load the user's last saved config before creating/syncing the UI features.
hustle_meter.load_config(true)
hustle_meter.refresh_runtime_metadata()
hustle_meter.reset_tracker_for_account(hustle_meter.S.currentAccountName or "Detecting...", hustle_meter.S.currentAccountKey or "pending")
hustle_meter.update_tracker(true)
hustle_meter.create_features()
hustle_meter.sync_feature_states()
hustle_meter.install_native_transaction_firewall()
hustle_meter.refresh_named_earn_firewall()
hustle_meter.live_money_boot()
hustle_meter.forensic_boot_session()
pcall(hustle_meter.ensure_startup_logo_file)
hustle_meter.toast("HustleMeter " .. tostring(hustle_meter.Version) .. " Production loaded.", 4500)
hustle_meter.save_diagnostics("script-start")
hustle_meter.debug_event("SCRIPT_START", "HustleMeter " .. tostring(hustle_meter.Version) .. " Production started.",
    "version=" .. tostring(hustle_meter.Version) .. " build=" .. tostring(hustle_meter.Build) .. " edition=" .. tostring(hustle_meter.S.currentGameEdition) .. "/" .. tostring(hustle_meter.S.currentCheraxEdition))

if ClickGUI and ClickGUI.AddTab then
    ClickGUI.AddTab(hustle_meter.TabName, function()
        hustle_meter.render_tab()
    end)
end

if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        hustle_meter.handle_hotkey()
        hustle_meter.render_hud()
    end)
else
    hustle_meter.warn("Script.RegisterLooped unavailable. HUD hotkey/render will not run.")
end

if Script and Script.QueueJob then
    Script.QueueJob(function()
        while true do
            hustle_meter.keep_first_run_welcome_active()
            hustle_meter.process_pending_reset_actions()
            hustle_meter.process_pending_forensic_actions()
            hustle_meter.process_pending_hard_cap_actions()
            hustle_meter.process_pending_hard_cap_payout_test()
            hustle_meter.process_pending_live_money_actions()
            hustle_meter.process_pending_heist_marker()
            hustle_meter.update_tracker(false)
            hustle_meter.update_hard_cap_guard(false)
            hustle_meter.update_transaction_firewall()
            hustle_meter.forensic_periodic_maintenance()
            local scanner = hustle_meter.get_transaction_scanner()
            local delay = math.floor(tonumber(scanner.nextDelayMs or hustle_meter.S.scannerIdleMs or 100) or 100)
            if delay < 25 then delay = 25 end
            if delay > 1000 then delay = 1000 end
            if Script and Script.Yield then Script.Yield(delay) end
        end
    end)
end

-- Dedicated high-frequency Build 033 Live Payout Scanner.
if Script and Script.QueueJob then
    Script.QueueJob(function()
        while true do
            local ok, err = pcall(hustle_meter.live_money_probe_tick)
            if not ok then
                hustle_meter.S.liveMoneyStatus = "Live scanner error: " .. tostring(err)
                hustle_meter.LiveMoney.writeFailures =
                    (tonumber(hustle_meter.LiveMoney.writeFailures or 0) or 0) + 1
            end
            local delay
            if hustle_meter.S.liveMoneyScannerEnabled == true then
                delay = math.max(50, math.min(1000,
                    math.floor(tonumber(hustle_meter.S.liveMoneyPollMs or 1000) or 1000)))
            else
                delay = 1000
            end
            if Script and Script.Yield then Script.Yield(delay) end
        end
    end)
end

-- First-run welcome renders above the normal ClickGUI and can force the menu open once.
if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT then
    pcall(function()
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            hustle_meter.keep_first_run_welcome_active()
            hustle_meter.keep_settings_reset_confirmation_active()
            hustle_meter.keep_money_reset_confirmation_active()
            hustle_meter.render_first_run_welcome()
            hustle_meter.render_settings_reset_confirmation()
            hustle_meter.render_money_reset_confirmation()
        end)
    end)
end

-- Automatic final support snapshot on normal script unload.
if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_UNLOAD then
    pcall(function()
        EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
            pcall(function()
                hustle_meter.restore_hard_cap_cash_pickups("script-unload")
                if type(hustle_meter.LiveMoney.pendingIncident) == "table" then
                    hustle_meter.LiveMoney.pendingIncident.finalizeAfterMs = hustle_meter.now()
                    hustle_meter.heist_incident_maintain(hustle_meter.now())
                end
                if type(hustle_meter.LiveMoney.pendingPredictiveAttempt) == "table" then
                    hustle_meter.predictive_guard_log(
                        "SCRIPT_UNLOAD_WITH_PENDING_ATTEMPT",
                        "attempt=" .. tostring(hustle_meter.LiveMoney.pendingPredictiveAttempt.attemptId or "unknown")
                    )
                end
                hustle_meter.live_money_write_summary("script-unload")
                hustle_meter.restore_native_transaction_firewall()
                if hustle_meter.Forensic and hustle_meter.Forensic.testActive == true then
                    hustle_meter.forensic_mark_test_end("script-unload-auto")
                end
                hustle_meter.forensic_write_summary("script-unload")
                hustle_meter.save_diagnostics("script-unload")
            end)
        end)
    end)
end

